## File 2: `middleware/errors.js`

```javascript
/**
 * Custom Error Classes and Error Handling Middleware
 * 
 * WHY CUSTOM ERROR CLASSES?
 * - They allow us to distinguish between different error types programmatically
 * - Each error can carry specific metadata (status code, message, details)
 * - The global error middleware can respond differently based on error type
 * 
 * WHY MIDDLEWARE PATTERN?
 * - Express middleware provides a clean way to intercept and handle errors
 * - A single error-handling function at the end catches all unhandled errors
 * - This prevents us from needing try/catch blocks in every route handler
 */

/**
 * Base error class for our API
 * Extends JavaScript's built-in Error class with HTTP status code support
 */
class ApiError extends Error {
  /**
   * @param {string} message - Human-readable error description
   * @param {number} statusCode - HTTP status code (default: 500)
   * @param {object} [details] - Additional error metadata
   */
  constructor(message, statusCode = 500, details = null) {
    super(message); // Call parent Error constructor with the message
    this.statusCode = statusCode;
    this.details = details;

    // Capture stack trace for debugging (optional but recommended)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

/**
 * Not Found Error — thrown when a requested resource doesn't exist
 * HTTP 404 is the standard status code for missing resources
 */
class NotFoundError extends ApiError {
  constructor(resource, id) {
    super(
      `${resource} with id ${id} not found`,
      404, // Standard HTTP "Not Found" status
      { resource, id } // Include metadata for debugging/logging
    );
  }
}

/**
 * Validation Error — thrown when input data fails validation
 * HTTP 400 is the standard status code for client errors/bad requests
 */
class ValidationError extends ApiError {
  constructor(message, fieldErrors = null) {
    super(
      message || 'Validation failed',
      400, // Standard HTTP "Bad Request" status
      { fieldErrors } // Include which fields failed validation
    );
  }
}

/**
 * Global Error Handling Middleware
 * 
 * WHY THIS PATTERN?
 * - Express calls this function whenever an error is thrown in any route
 * - The extra `err` parameter distinguishes it from regular middleware
 * - We always return a JSON response for consistency
 * - We log errors to console for debugging but don't expose stack traces in production
 * 
 * @param {Error} err - The error object caught by Express
 * @param {object} req - Express request object
 * @param {object} res - Express response object
 * @param {function} next - Express next middleware function (unused here)
 */
const errorHandler = (err, req, res, next) => {
  // Log the full error for server-side debugging
  console.error(`[ERROR] ${new Date().toISOString()}:`, err);

  // Determine what to send back based on error type
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  // Build the response body with consistent structure
  const responseBody = {
    success: false,
    error: {
      message,
      statusCode,
      ...(err.details && { details: err.details }) // Only include if present
    }
  };

  // Send JSON response with appropriate status code
  res.status(statusCode).json(responseBody);
};

/**
 * Export all error classes and middleware for use in other modules
 */
module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  errorHandler
};
```

