## File 3: `routes/books.js`

```javascript
/**
 * Book Routes Module
 * 
 * WHY SEPARATE ROUTE FILE?
 * - Keeps route definitions organized and maintainable
 * - Allows easy scaling as the API grows (one file per resource)
 * - Makes it clear which endpoints belong to which domain
 * 
 * REST CONVENTIONS USED:
 * - GET /books — List all books (with optional filtering)
 * - GET /books/:id — Get a single book by ID
 * - POST /books — Create a new book
 * - PUT /books/:id — Fully update an existing book
 * - DELETE /books/:id — Delete a book
 * - GET /stats — Return aggregate statistics about books
 */

const express = require('express');
const router = express.Router(); // Creates a standalone route handler

// Import custom error classes for proper error handling
const { NotFoundError, ValidationError } = require('../middleware/errors');

/**
 * IN-MEMORY DATA STORAGE
 * 
 * WHY AN ARRAY?
 * - Simple and intuitive for educational purposes
 * - No external dependencies (databases) required to run
 * - Easy to understand data structure for learning REST concepts
 * 
 * LIMITATIONS (for production awareness):
 * - Data is lost when server restarts (no persistence)
 * - Not thread-safe (concurrent requests could cause race conditions)
 * - Memory usage grows with data size
 * - No querying capabilities beyond JavaScript array methods
 * 
 * In a real application, you would replace this with:
 * - MongoDB (document database, good for flexible schemas)
 * - PostgreSQL/MySQL (relational, good for structured data with relationships)
 * - SQLite (lightweight file-based database)
 */

// Array to store book objects. Each book has a unique ID and properties.
let books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.5
  },
  {
    id: 2,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    genre: 'Fiction',
    publishedYear: 1960,
    rating: 4.8
  },
  {
    id: 3,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    genre: 'Science',
    publishedYear: 1988,
    rating: 4.7
  }
];

// Track the next available ID to ensure uniqueness
let nextId = 4;

/**
 * GET /books
 * 
 * Returns a list of all books with optional filtering by query parameters.
 * 
 * QUERY PARAMETERS (all optional):
 * - genre: Filter by book genre (e.g., ?genre=Fiction)
 * - author: Filter by author name (partial match, case-insensitive)
 * - minRating: Minimum rating filter (0-5)
 * - publishedAfter: Filter books published after this year
 * 
 * WHY QUERY PARAMETERS?
 * - They allow flexible filtering without changing the URL structure
 * - Multiple filters can be combined for more specific queries
 * - This follows REST best practices for resource retrieval with criteria
 * 
 * @param {object} req - Express request object containing query parameters
 * @param {object} res - Express response object
 * @returns {object} JSON response with success flag and books array
 */
router.get('/books', (req, res) => {
  // Start with all books as our base dataset
  let filteredBooks = [...books];

  // Apply genre filter if provided in query string
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    filteredBooks = filteredBooks.filter(
      book => book.genre.toLowerCase() === genreFilter
    );
  }

  // Apply author filter if provided (partial match, case-insensitive)
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    filteredBooks = filteredBooks.filter(
      book => book.author.toLowerCase().includes(authorFilter)
    );
  }

  // Apply minimum rating filter if provided
  if (req.query.minRating) {
    const minRating = parseFloat(req.query.minRating);
    if (!isNaN(minRating)) {
      filteredBooks = filteredBooks.filter(
        book => book.rating >= minRating
      );
    }
  }

  // Apply published year filter if provided
  if (req.query.publishedAfter) {
    const publishedAfter = parseInt(req.query.publishedAfter, 10);
    if (!isNaN(publishedAfter)) {
      filteredBooks = filteredBooks.filter(
        book => book.publishedYear > publishedAfter
      );
    }
  }

  // Return the filtered results with HTTP 200 (OK) status
  res.json({
    success: true,
    count: filteredBooks.length, // Include count for pagination awareness
    data: filteredBooks
  });
});

/**
 * GET /books/:id
 * 
 * Returns a single book by its ID.
 * 
 * WHY USE :id PARAMETER?
 * - RESTful URLs use path parameters to identify specific resources
 * - This is more semantic than query parameters for resource identification
 * - Express automatically extracts :id from the URL and puts it in req.params
 * 
 * @param {object} req - Express request object with params.id
 * @param {object} res - Express response object
 * @throws {NotFoundError} If book with given ID doesn't exist
 */
router.get('/books/:id', (req, res) => {
  // Convert string ID to number for comparison
  const id = parseInt(req.params.id, 10);

  // Find the book in our array using Array.find()
  const book = books.find(b => b.id === id);

  // If not found, throw our custom NotFoundError (caught by error middleware)
  if (!book) {
    throw new NotFoundError('Book', id);
  }

  // Return the found book with HTTP 200 status
  res.json({
    success: true,
    data: book
  });
});

/**
 * POST /books
 * 
 * Creates a new book and returns it with HTTP 201 (Created) status.
 * 
 * WHY HTTP 201?
 * - 201 is the standard status code for successful resource creation
 * - It distinguishes creation from retrieval (which uses 200)
 * - The response body contains the newly created resource
 * 
 * @param {object} req - Express request object with JSON body
 * @param {object} res - Express response object
 * @throws {ValidationError} If required fields are missing or invalid
 */
router.post('/books', (req, res) => {
  // Extract and validate required fields from request body
  const { title, author, genre, publishedYear, rating } = req.body;

  // Validate that all required fields are present
  if (!title || !author || !genre) {
    throw new ValidationError(
      'Title, author, and genre are required fields',
      { field: ['title', 'author', 'genre'] }
    );
  }

  // Validate publishedYear is a valid number
  if (publishedYear === undefined || publishedYear === null) {
    throw new ValidationError('Published year is required');
  }

  const year = parseInt(publishedYear, 10);
  if (isNaN(year)) {
    throw new ValidationError('Published year must be a valid number');
  }

  // Validate rating if provided (should be between 0 and 5)
  let bookRating = rating;
  if (rating !== undefined && rating !== null) {
    const parsedRating = parseFloat(rating);
    if (isNaN(parsedRating) || parsedRating < 0 || parsedRating > 5) {
      throw new ValidationError('Rating must be a number between 0 and 5');
    }
    bookRating = parsedRating;
  }

  // Create the new book object with auto-incremented ID
  const newBook = {
    id: nextId++, // Increment and assign, then increment for next time
    title,
    author,
    genre,
    publishedYear: year,
    rating: bookRating !== undefined ? bookRating : null
  };

  // Add to our in-memory array (in production, this would be a database insert)
  books.push(newBook);

  // Return the created resource with HTTP 201 status
  res.status(201).json({
    success: true,
    message: 'Book created successfully',
    data: newBook
  });
});

/**
 * PUT /books/:id
 * 
 * Fully updates an existing book by ID.
 * 
 * WHY PUT vs PATCH?
 * - PUT replaces the entire resource (all fields must be provided)
 * - PATCH would only update specified fields (partial update)
 * - For this educational example, PUT demonstrates full replacement
 * 
 * @param {object} req - Express request object with params.id and JSON body
 * @param {object} res - Express response object
 * @throws {NotFoundError} If book with given ID doesn't exist
 * @throws {ValidationError} If input data is invalid
 */
router.put('/books/:id', (req, res) => {
  // Convert string ID to number for comparison
  const id = parseInt(req.params.id, 10);

  // Find the book index in our array (we need index for splice/update)
  const bookIndex = books.findIndex(b => b.id === id);

  // If not found, throw NotFoundError
  if (bookIndex === -1) {
    throw new NotFoundError('Book', id);
  }

  // Extract fields from request body
  const { title, author, genre, publishedYear, rating } = req.body;

  // Validate required fields
  if (!title || !author || !genre) {
    throw new ValidationError(
      'Title, author, and genre are required for update',
      { field: ['title', 'author', 'genre'] }
    );
  }

  // Build the updated book object (preserving ID, replacing other fields)
  const updatedBook = {
    id, // Keep the same ID
    title,
    author,
    genre,
    publishedYear: parseInt(publishedYear, 10),
    rating: rating !== undefined ? parseFloat(rating) : null
  };

  // Update the book in our array (in production, this would be a database update)
  books[bookIndex] = updatedBook;

  // Return the updated resource with HTTP 200 status
  res.json({
    success: true,
    message: 'Book updated successfully',
    data: updatedBook
  });
});

/**
 * DELETE /books/:id
 * 
 * Deletes a book by ID.
 * 
 * WHY RETURN 204 NO CONTENT?
 * - 204 indicates successful deletion with no response body
 * - This is the standard REST convention for DELETE operations
 * - Some clients prefer an empty response for delete operations
 * 
 * @param {object} req - Express request object with params.id
 * @param {object} res - Express response object
 * @throws {NotFoundError} If book with given ID doesn't exist
 */
router.delete('/books/:id', (req, res) => {
  // Convert string ID to number for comparison
  const id = parseInt(req.params.id, 10);

  // Find the book index in our array
  const bookIndex = books.findIndex(b => b.id === id);

  // If not found, throw NotFoundError
  if (bookIndex === -1) {
    throw new NotFoundError('Book', id);
  }

  // Remove the book from our array using splice (in production, database delete)
  books.splice(bookIndex, 1);

  // Return HTTP 204 No Content (standard for successful DELETE)
  res.status(204).send();
});

/**
 * GET /stats
 * 
 * Returns aggregate statistics about the book collection.
 * 
 * WHY STATISTICS ENDPOINT?
 * - Demonstrates data aggregation and transformation in REST APIs
 * - Shows how to compute derived values from stored data
 * - Useful for dashboards and monitoring applications
 * 
 * @param {object} req - Express request object (no parameters needed)
 * @param {object} res - Express response object
 */
router.get('/stats', (req, res) => {
  // Calculate total number of books
  const totalBooks = books.length;

  // Calculate average rating (only for books that have ratings)
  const ratedBooks = books.filter(book => book.rating !== null && book.rating !== undefined);
  const averageRating = ratedBooks.length > 0
    ? parseFloat((ratedBooks.reduce((sum, book) => sum + book.rating, 0) / ratedBooks.length).toFixed(2))
    : null;

  // Count books by genre using reduce for aggregation
  const genreCounts = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Find the highest and lowest rated books
  const highestRated = ratedBooks.length > 0
    ? ratedBooks.reduce((max, book) => book.rating > max.rating ? book : max, ratedBooks[0])
    : null;

  const lowestRated = ratedBooks.length > 0
    ? ratedBooks.reduce((min, book) => book.rating < min.rating ? book : min, ratedBooks[0])
    : null;

  // Return statistics with HTTP 200 status
  res.json({
    success: true,
    data: {
      totalBooks,
      averageRating,
      genreCounts,
      highestRated: highestRated ? { title: highestRated.title, rating: highestRated.rating } : null,
      lowestRated: lowestRated ? { title: lowestRated.title, rating: lowestRated.rating } : null
    }
  });
});

// Export the router so it can be used in server.js
module.exports = router;
```

