## File 4: `server.js`

```javascript
/**
 * Main Server Application
 * 
 * WHY THIS STRUCTURE?
 * - Centralized configuration and setup in one place
 * - Middleware is applied globally for consistent behavior
 * - Routes are mounted at specific paths for organization
 * - Error handling middleware catches errors from all routes
 * 
 * EXPRESS MIDDLEWARE ORDER MATTERS:
 * 1. Body parsing (express.json) — must come before route handlers
 * 2. Route mounting — defines our API endpoints
 * 3. Error handling — must be last to catch errors from above
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const { errorHandler } = require('./middleware/errors');

// Create Express application instance
const app = express();

// Set port for the server (use environment variable or default to 3000)
const PORT = process.env.PORT || 3000;

/**
 * MIDDLEWARE CONFIGURATION
 * 
 * WHY express.json()?
 * - Parses incoming JSON request bodies automatically
 * - Makes req.body available in route handlers
 * - Without this, POST/PUT requests with JSON would have undefined body
 */
app.use(express.json());

// Log all incoming requests for debugging (common development practice)
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler
});

/**
 * ROUTE MOUNTING
 * 
 * WHY app.use('/api', bookRoutes)?
 * - Mounts all book routes under the /api prefix
 * - Keeps API versioning clean (e.g., /api/v1/ in future)
 * - Allows multiple route files to be mounted at different paths
 */
app.use('/api', bookRoutes);

/**
 * ROOT ENDPOINT
 * 
 * Provides a simple health check and API documentation
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book REST API is running!',
    endpoints: {
      'GET /api/books': 'List all books with optional filtering',
      'GET /api/books/:id': 'Get a single book by ID',
      'POST /api/books': 'Create a new book',
      'PUT /api/books/:id': 'Update an existing book',
      'DELETE /api/books/:id': 'Delete a book',
      'GET /api/stats': 'Get statistics about the book collection'
    }
  });
});

/**
 * ERROR HANDLING MIDDLEWARE
 * 
 * WHY MUST IT BE LAST?
 * - Express processes middleware in order
 * - If placed before routes, it would intercept normal responses too
 * - The 4-parameter signature (err, req, res, next) identifies it as error handler
 */
app.use(errorHandler);

/**
 * START THE SERVER
 * 
 * WHY CALLBACK FUNCTION?
 * - Ensures server is ready before logging the startup message
 * - Allows us to handle potential startup errors
 */
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
  console.log(`API available at http://localhost:${PORT}/api`);
});

// Export app for testing purposes (common in Express applications)
module.exports = app;
```

