```javascript
/**
 * ============================================================================
 * CLASSE PERSONALIZADA DE ERRO — AppError
 * ============================================================================
 *
 * POR QUE CRIAR UMA CLASSE DE ERRO PRÓPRIA?
 * ------------------------------------------
 * O JavaScript nativo oferece Error, TypeError, RangeError, etc. Porém, em uma
 * API REST precisamos de mais contexto: código HTTP, tipo do erro e se é
 * recuperável pelo cliente. Uma classe personalizada nos permite:
 *
 *   1. Associar automaticamente um status HTTP ao erro (400, 404, 500...).
 *   2. Diferenciar erros de validação (cliente) de erros internos (servidor).
 *   3. Centralizar o tratamento no middleware de erros, evitando repetição.
 *
 * A herança de Error garante compatibilidade com stack traces nativos do Node.js,
 * o que é essencial para depuração em produção.
 */

class AppError extends Error {
  /**
   * Construtor da classe AppError.
   *
   * @param {string} message - Mensagem descritiva do erro (visível ao cliente).
   * @param {number} statusCode - Código HTTP correspondente (ex: 404, 500).
   * @param {boolean} [isOperational=true] - Indica se o erro é esperado no fluxo
   *        normal da API. Erros operacionais não devem ser monitorados como bugs;
   *        erros não-operacionais (ex: banco de dados fora do ar) sim.
   */
  constructor(message, statusCode, isOperational = true) {
    // super() chama o construtor da classe Error nativa, inicializando message
    // e capturando o stack trace no ponto exato onde o erro foi criado.
    super(message);

    // Propriedades personalizadas:
    this.statusCode = statusCode;   // Código HTTP para resposta
    this.isOperational = isOperational; // Flag para middleware de erros
    this.errorType = this.constructor.name; // Nome da classe (ex: "NotFoundError")

    // captureStackTrace garante que o stack trace comece neste ponto,
    // não no construtor de Error, melhorando a legibilidade do log.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * ============================================================================
 * SUBCLASSES DE ERRO — Hierarquia semântica
 * ============================================================================
 *
 * POR QUE SUBCLASSES?
 * --------------------
 * Subclasses permitem que o middleware de erros trate cada tipo de erro de forma
 * específica, além de tornar o código mais legível e auto-documentado. Em vez de
 * verificar strings como "not found", verificamos instanceof NotFoundError.
 */

/**
 * Erro disparado quando um recurso solicitado não é encontrado.
 * Exemplo: GET /books/999 onde o livro 999 não existe.
 * Status HTTP padrão: 404 Not Found.
 */
class NotFoundError extends AppError {
  constructor(resource, id) {
    // Template string para mensagem clara e informativa.
    super(`${resource} com ID ${id} não encontrado`, 404);
  }
}

/**
 * Erro disparado quando a entrada do cliente viola regras de validação.
 * Exemplo: POST /books com título vazio ou ISBN duplicado.
 * Status HTTP padrão: 400 Bad Request.
 */
class ValidationError extends AppError {
  constructor(message, details = null) {
    super(message, 400);
    this.details = details; // Array de campos inválidos e suas razões
  }
}

/**
 * Erro disparado quando o cliente tenta uma operação não permitida.
 * Exemplo: DELETE /books/:id sem autenticação (em APIs com auth).
 * Status HTTP padrão: 403 Forbidden.
 */
class ForbiddenError extends AppError {
  constructor(message = 'Acesso proibido') {
    super(message, 403);
  }
}

/**
 * Erro disparado quando ocorre um problema interno no servidor.
 * Exemplo: falha ao escrever em disco, timeout de conexão externa.
 * Status HTTP padrão: 500 Internal Server Error.
 * isOperational = false indica que isso é um bug, não um fluxo esperado.
 */
class InternalError extends AppError {
  constructor(message = 'Erro interno do servidor') {
    super(message, 500, false); // false = erro não-operacional (bug)
  }
}

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  ForbiddenError,
  InternalError,
};
```

