```javascript
/**
 * ============================================================================
 * MODELO DE DADOS — Livro (Book)
 * ============================================================================
 *
 * POR QUE ARMAZENAMENTO EM ARRAY EM MEMÓRIA?
 * -------------------------------------------
 * Para este exemplo educacional, usamos um array em memória porque:
 *
 *   1. SIMPLICIDADE: Não requer configuração de banco de dados (MongoDB, PostgreSQL).
 *   2. VELOCIDADE: Operações CRUD são instantâneas (O(1) para push, O(n) para busca).
 *   3. FOCO NO CONTEÚDO: Permite concentrar-se nos conceitos de REST, rotas e
 *      middleware sem distrações com infraestrutura.
 *
 * POR QUE UM ARRAY E NÃO UM MAP/Objeto?
 * --------------------------------------
 * Um array é escolhido porque:
 *   - A ordem de inserção pode ser relevante (livros mais recentes primeiro).
 *   - Facilita operações como paginação e filtragem sequencial.
 *   - Em arrays pequenos (< 1000 itens), a diferença de performance para um Map
 *     é insignificante. Para escalabilidade real, substituiríamos por um banco.
 *
 * ESTRUTURA DO LIVRO:
 * --------------------
 * Cada livro possui campos que cobrem os requisitos comuns de uma API bibliográfica:
 *   - id: identificador único (numérico, auto-incremento).
 *   - title: título do livro (obrigatório, string).
 *   - author: autor (obrigatório, string).
 *   - isbn: ISBN-13 (obrigatório, único no sistema).
 *   - publishedYear: ano de publicação (número, 1000-2100).
 *   - genre: gênero literário (string opcional).
 *   - createdAt / updatedAt: timestamps para auditoria.
 */

// Array principal que armazena todos os livros em memória.
// Inicializamos com alguns dados de exemplo para facilitar testes iniciais.
const books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    isbn: '978-0618640157',
    publishedYear: 1954,
    genre: 'Fantasia',
    createdAt: new Date('2024-01-15T10:00:00Z'),
    updatedAt: new Date('2024-01-15T10:00:00Z'),
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    isbn: '978-0451524935',
    publishedYear: 1949,
    genre: 'Distopia',
    createdAt: new Date('2024-01-15T10:00:00Z'),
    updatedAt: new Date('2024-01-15T10:00:00Z'),
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    isbn: '978-8525046845',
    publishedYear: 1899,
    genre: 'Romance',
    createdAt: new Date('2024-01-15T10:00:00Z'),
    updatedAt: new Date('2024-01-15T10:00:00Z'),
  },
];

// Contador para gerar IDs únicos automaticamente.
// Em produção, usaríamos UUID ou um sequence do banco de dados.
let nextId = 4;

/**
 * Retorna todos os livros armazenados.
 * @returns {Array<Object>} Lista completa de livros.
 */
function findAll() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * POR QUE USEMOS find() E NÃO UM MAP?
 * -------------------------------------
 * Para arrays pequenos, Array.find() é legível e suficiente. Se o array tivesse
 * milhares de registros, criaríamos um Map<id, book> paralelo para busca O(1).
 *
 * @param {number} id - ID numérico do livro.
 * @returns {Object|null} Livro encontrado ou null se não existir.
 */
function findById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Busca um livro pelo ISBN (para evitar duplicatas na criação).
 *
 * @param {string} isbn - ISBN-13 do livro.
 * @returns {Object|null} Livro encontrado ou null.
 */
function findByIsbn(isbn) {
  return books.find((book) => book.isbn === isbn) || null;
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * O ID é gerado automaticamente a partir do contador nextId, garantindo unicidade.
 * Os timestamps de criação e atualização são definidos como agora().
 *
 * @param {Object} bookData - Dados do livro (sem id, createdAt, updatedAt).
 * @returns {Object} Livro criado com todos os campos preenchidos.
 */
function create(bookData) {
  const newBook = {
    id: nextId++, // Incrementa e atribui o ID atual, depois incrementa.
    ...bookData,  // Espalha os dados fornecidos pelo cliente.
    createdAt: new Date(),
    updatedAt: new Date(),
  };

  books.push(newBook); // O(1) — adiciona ao final do array.
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * Se o livro não existir, retorna null (o controller tratará como 404).
 * O campo updatedAt é atualizado automaticamente para refletir a modificação.
 *
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Object} updates - Campos a serem atualizados (partial update).
 * @returns {Object|null} Livro atualizado ou null se não encontrado.
 */
function update(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Atualiza apenas os campos fornecidos (partial update / PATCH semantics).
  // Isso permite atualizações parciais: o cliente envia só o que quer mudar.
  books[index] = {
    ...books[index],       // Mantém todos os campos existentes.
    ...updates,            // Sobrescreve com os novos valores.
    updatedAt: new Date(), // Registra o momento da atualização.
  };

  return books[index];
}

/**
 * Remove um livro do array pelo ID.
 *
 * @param {number} id - ID do livro a ser removido.
 * @returns {boolean} true se removido, false se não encontrado.
 */
function remove(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  // splice remove o elemento e realinha os índices subsequentes.
  // Para arrays pequenos, o custo O(n) é aceitável.
  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o acervo de livros.
 *
 * POR QUE ESTA FUNÇÃO AQUI E NÃO NO CONTROLLER?
 * ----------------------------------------------
 * Estatísticas são uma operação de negócio que depende da estrutura de dados.
 * Manter a lógica de cálculo no modelo mantém o controller focado em
 * orquestrar requisição → modelo → resposta, seguindo o padrão MVC.
 *
 * @returns {Object} Estatísticas do acervo.
 */
function getStats() {
  const total = books.length;

  // Agrupamento por gênero usando reduce — padrão funcional para agregação.
  const byGenre = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Ano mais antigo e mais recente publicados.
  const years = books.map((b) => b.publishedYear);
  const oldestYear = total > 0 ? Math.min(...years) : null;
  const newestYear = total > 0 ? Math.max(...years) : null;

  return {
    total,
    byGenre,
    oldestPublication: oldestYear,
    newestPublication: newestYear,
  };
}

module.exports = {
  findAll,
  findById,
  findByIsbn,
  create,
  update,
  remove,
  getStats,
};
