## Arquivo 4: `src/middleware/validation.middleware.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE VALIDAÇÃO — Valida dados de entrada antes do controller
 * ============================================================================
 *
 * POR QUE VALIDAR NO MIDDLEWARE E NÃO NO CONTROLLER?
 * ---------------------------------------------------
 * Separar validação do controller segue o princípio de responsabilidade única:
 *   - O middleware garante que os dados estão no formato correto.
 *   - O controller foca na lógica de negócio (CRUD).
 *
 * Além disso, middlewares podem ser reutilizados entre rotas e aplicados
 * seletivamente usando a composição do Express.
 */

const { ValidationError } = require('../utils/app-error.util');

/**
 * Middleware que valida os dados de criação de um livro (POST /books).
 *
 * Regras de validação:
 *   - title: obrigatório, string não vazia, mínimo 1 caractere, máximo 500.
 *   - author: obrigatório, string não vazia, mínimo 1 caractere, máximo 200.
 *   - isbn: obrigatório, deve seguir o padrão ISBN-13 (13 dígitos numéricos).
 *   - publishedYear: opcional, mas se fornecido deve ser número entre 1000 e 2100.
 *   - genre: opcional, string com máximo 100 caracteres.
 *
 * @param {Object} req - Objeto de requisição do Express.
 * @param {Object} res - Objeto de resposta do Express.
 * @param {Function} next - Função para passar ao próximo middleware.
 * @throws {ValidationError} Se alguma validação falhar.
 */
function validateCreateBook(req, res, next) {
  const { title, author, isbn, publishedYear, genre } = req.body;

  // Array para acumular múltiplos erros de uma vez (bad request com todos os problemas).
  const errors = [];

  // VALIDAÇÃO DO TÍTULO
  if (!title || typeof title !== 'string' || title.trim().length === 0) {
    errors.push({ field: 'title', message: 'Título é obrigatório e deve ser uma string não vazia' });
  } else if (title.length > 500) {
    errors.push({ field: 'title', message: 'Título não pode exceder 500 caracteres' });
  }

  // VALIDAÇÃO DO AUTOR
  if (!author || typeof author !== 'string' || author.trim().length === 0) {
    errors.push({ field: 'author', message: 'Autor é obrigatório e deve ser uma string não vazia' });
  } else if (author.length > 200) {
    errors.push({ field: 'author', message: 'Autor não pode exceder 200 caracteres' });
  }

  // VALIDAÇÃO DO ISBN — padrão ISBN-13: exatamente 13 dígitos numéricos.
  const isbnPattern = /^\d{13}$/;
  if (!isbn || typeof isbn !== 'string' || !isbnPattern.test(isbn)) {
    errors.push({ field: 'isbn', message: 'ISBN é obrigatório e deve conter exatamente 13 dígitos numéricos' });
  }

  // VALIDAÇÃO DO ANO DE PUBLICAÇÃO (opcional)
  if (publishedYear !== undefined && publishedYear !== null) {
    const year = Number(publishedYear);
    if (!Number.isInteger(year) || year < 1000 || year > 2100) {
      errors.push({ field: 'publishedYear', message: 'Ano de publicação deve ser um número entre 1000 e 2100' });
    }
  }

  // VALIDAÇÃO DO GÊNERO (opcional)
  if (genre !== undefined && genre !== null) {
    if (typeof genre !== 'string' || genre.length > 100) {
      errors.push({ field: 'genre', message: 'Gênero deve ser uma string com no máximo 100 caracteres' });
    }
  }

  // Se houver erros, lançamos ValidationError com todos os detalhes.
  // O middleware de erros capturará e retornará status 400 com a lista completa.
  if (errors.length > 0) {
    return next(new ValidationError('Validação falhou', errors));
  }

  // Todos os campos passaram — prossegue para o controller.
  next();
}

/**
 * Middleware que valida o ID na URL (:id).
 *
 * Express passa params como strings; precisamos garantir que seja um número
 * inteiro positivo antes de passar ao controller.
 *
 * @param {Object} req - Objeto de requisição do Express.
 * @param {Object} res - Objeto de resposta do Express.
 * @param {Function} next - Função para passar ao próximo middleware.
 * @throws {ValidationError} Se o ID não for um número inteiro válido.
 */
function validateBookId(req, res, next) {
  const id = parseInt(req.params.id, 10); // Base 10 explícita para evitar interpretações estranhas.

  if (isNaN(id) || id < 1 || !Number.isInteger(id)) {
    return next(new ValidationError('ID inválido', [
      { field: 'id', message: 'O ID deve ser um número inteiro positivo' },
    ]));
  }

  // Armazena o ID como número no req para uso pelo controller.
  req.params.id = id;
  next();
}

module.exports = {
  validateCreateBook,
  validateBookId,
};
