## Arquivo 5: `src/middleware/error.middleware.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS — Centralizador de erros da API
 * ============================================================================
 *
 * POR QUE UM MIDDLEWARE ESPECIALIZADO EM ERROS?
 * ----------------------------------------------
 * O Express permite definir middlewares com 4 parâmetros (err, req, res, next).
 * Quando qualquer middleware ou handler chama next(err), o Express pula todos
 * os middlewares normais e vai direto para este. Isso nos dá:
 *
 *   1. UM ÚNICO PONTO DE CONTROLE para formatar respostas de erro.
 *   2. SEGURANÇA: não expomos stack traces ou detalhes internos ao cliente.
 *   3. LOG CONSISTENTE: todos os erros são registrados no mesmo lugar.
 *
 * A convenção REST pede que erros tenham estrutura consistente, então padronizamos
 * a resposta em { error: { message, statusCode, type } }.
 */

const { AppError } = require('../utils/app-error.util');

/**
 * Middleware de tratamento de erros.
 *
 * @param {Error} err - Erro capturado pelo Express.
 * @param {Object} req - Objeto de requisição (usado para logging).
 * @param {Object} res - Objeto de resposta do Express.
 * @param {Function} next - Não utilizado, mas necessário pela assinatura do Express.
 */
function errorHandler(err, req, res, next) {
  // Determina o tipo de erro e seu status padrão.
  let statusCode = err.statusCode || 500;
  let errorMessage = err.message || 'Erro interno do servidor';
  let errorType = err.errorType || 'Error';

  // Para erros não-operacionais (bugs), logamos o stack trace completo.
  // Para erros operacionais (ex: 404), apenas a mensagem é suficiente.
  if (!err.isOperational) {
    console.error('[ERRO DO SERVIDOR]', {
      type: errorType,
      message: errorMessage,
      stack: err.stack, // Stack trace completo para depuração em produção.
      url: req.originalUrl,
      method: req.method,
      timestamp: new Date().toISOString(),
    });
  } else {
    // Erros operacionais são logados de forma resumida (não expõe detalhes).
    console.log('[ERRO OPERACIONAL]', {
      type: errorType,
      message: errorMessage,
      url: req.originalUrl,
      method: req.method,
    });
  }

  // Formatação da resposta de erro conforme convenção REST.
  const errorResponse = {
    error: {
      message: errorMessage,
      statusCode,
      type: errorType,
      timestamp: new Date().toISOString(),
    },
  };

  // Se houver detalhes de validação (campos específicos com erros), incluímos.
  if (err.details) {
    errorResponse.error.details = err.details;
  }

  // Responde com o status apropriado e o corpo formatado.
  res.status(statusCode).json(errorResponse);
}

/**
 * Middleware para capturar rotas não encontradas (404).
 *
 * Este middleware deve ser registrado DEPOIS de todas as rotas definidas.
 * Se nenhuma rota corresponder à URL, o Express chega aqui com res.statusCode = 404.
 *
 * @param {Object} req - Objeto de requisição.
 * @param {Object} res - Objeto de resposta.
 * @param {Function} next - Função para passar ao próximo middleware.
 */
function notFoundHandler(req, res, next) {
  // Como nenhuma rota corresponde, tratamos como 404 personalizado.
  const err = new AppError(`Rota ${req.method} ${req.originalUrl} não encontrada`, 404);
  next(err);
}

module.exports = {
  errorHandler,
  notFoundHandler,
};
```

