## Arquivo 6: `src/controllers/books.controller.js`

```javascript
/**
 * ============================================================================
 * CONTROLLER — Lógica de negócio para operações CRUD de livros
 * ============================================================================
 *
 * POR QUE SEPARAR CONTROLLER DO MODELO?
 * --------------------------------------
 * O padrão MVC (Model-View-Controller) separa responsabilidades:
 *   - Modelo: manipula dados (array, banco).
 *   - Controller: orquestra a lógica entre requisição e modelo.
 *   - Rota: define URLs e mapeia para handlers.
 *
 * O controller faz a "ponte": recebe dados da requisição, chama o modelo,
 * formata a resposta e lida com exceções específicas do fluxo (ex: ISBN duplicado).
 */

const bookModel = require('../models/book.model');
const { NotFoundError, ValidationError } = require('../utils/app-error.util');

/**
 * GET /books
 * Lista todos os livros com suporte a filtragem opcional.
 *
 * PARÂMETROS DE QUERY (opcionais):
 *   - author: filtra por autor (case-insensitive, substring match).
 *   - genre: filtra por gênero (exato).
 *   - minYear: filtra livros publicados a partir deste ano.
 *   - maxYear: filtra livros publicados até este ano.
 *   - search: busca por título ou autor (substring, case-insensitive).
 *
 * EXEMPLOS DE USO:
 *   GET /books                          → todos os livros
 *   GET /books?author=tolkien           → livros de Tolkien
 *   GET /books?genre=fantasia&minYear=1900  → fantasia pós-1900
 *   GET /books?search=senhor            → busca por "senhor" no título/autor
 *
 * @param {Object} req - Requisição Express com query params.
 * @param {Object} res - Resposta Express.
 */
function getAllBooks(req, res) {
  // Começamos com a lista completa do modelo.
  let result = bookModel.findAll();

  // FILTRO POR AUTOR (substring case-insensitive).
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter((book) =>
      book.author.toLowerCase().includes(authorFilter)
    );
  }

  // FILTRO POR GÊNERO (exato, case-insensitive).
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter((book) =>
      book.genre && book.genre.toLowerCase() === genreFilter
    );
  }

  // FILTRO POR ANO DE PUBLICAÇÃO (faixa).
  if (req.query.minYear) {
    const minYear = parseInt(req.query.minYear, 10);
    result = result.filter((book) => book.publishedYear >= minYear);
  }
  if (req.query.maxYear) {
    const maxYear = parseInt(req.query.maxYear, 10);
    result = result.filter((book) => book.publishedYear <= maxYear);
  }

  // BUSCA POR TÍTULO/AUTOR (substring).
  if (req.query.search) {
    const search = req.query.search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(search) ||
        book.author.toLowerCase().includes(search)
    );
  }

  // Ordenação padrão: mais recentes por updatedAt primeiro.
  result.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));

  // Resposta 200 OK com a lista filtrada.
  res.status(200).json({
    count: result.length,
    data: result,
    message: result.length === 0 ? 'Nenhum livro encontrado' : 'Livros listados com sucesso',
  });
}

/**
 * GET /books/:id
 * Retorna um único livro pelo ID.
 *
 * EXEMPLO DE RESPOSTA (200):
 * {
 *   "data": {
 *     "id": 1,
 *     "title": "O Senhor dos Anéis",
 *     "author": "J.R.R. Tolkien",
 *     ...
 *   }
 * }
 *
 * EXEMPLO DE ERRO (404):
 * {
 *   "error": {
 *     "message": "Livro com ID 999 não encontrado",
 *     "statusCode": 404,
 *     "type": "NotFoundError"
 *   }
 * }
 *
 * @param {Object} req - Requisição com params.id.
 * @param {Object} res - Resposta Express.
 * @param {Function} next - Para propagação de erros.
 */
function getBookById(req, res, next) {
  const book = bookModel.findById(req.params.id);

  if (!book) {
    // Lançamos NotFoundError em vez de retornar manualmente — o middleware
    // de erros formata a resposta consistentemente para todos os 404.
    return next(new NotFoundError('Livro', req.params.id));
  }

  res.status(200).json({ data: book });
}

/**
 * POST /books
 * Cria um novo livro no sistema.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 * {
 *   "title": "Novo Livro",
 *   "author": "Autor Exemplo",
 *   "isbn": "9780000000000",
 *   "publishedYear": 2024,
 *   "genre": "Ficção"
 * }
 *
 * EXEMPLO CURL:
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Hobbit","author":"J.R.R. Tolkien","isbn":"9780547928227","publishedYear":1937,"genre":"Fantasia"}'
 *
 * @param {Object} req - Requisição com body contendo dados do livro.
 * @param {Object} res - Resposta Express.
 * @param {Function} next - Para propagação de erros.
 */
function createBook(req, res, next) {
  try {
    // Verifica duplicidade de ISBN ANTES de criar — regra de negócio crítica.
    const existingByIsbn = bookModel.findByIsbn(req.body.isbn);
    if (existingByIsbn) {
      return next(
        new ValidationError('ISBN duplicado', [
          { field: 'isbn', message: `Já existe um livro com ISBN ${req.body.isbn}` },
        ])
      );
    }

    const newBook = bookModel.create(req.body);

    // 201 Created é o status HTTP semântico para recursos criados.
    // Incluímos o Location header indicando a URL do recurso criado (convenção REST).
    res.status(201).json({
      data: newBook,
      message: 'Livro criado com sucesso',
      headers: {
        Location: `/books/${newBook.id}`,
      },
    });
  } catch (error) {
    next(error);
  }
}

/**
 * PUT /books/:id
 * Atualiza completamente um livro existente.
 *
 * DIFERENÇA ENTRE PUT E PATCH:
 * -----------------------------
 * PUT substitui o recurso inteiro — todos os campos obrigatórios devem ser enviados.
 * PATCH atualizaria apenas campos específicos (partial update).
 * Aqui usamos PUT com spread operator, permitindo atualização parcial mas exigindo
 * que os campos obrigatórios sejam reenviados se quiserem mantê-los.
 *
 * EXEMPLO CURL:
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","isbn":"978-0618640157","publishedYear":1954,"genre":"Fantasia"}'
 *
 * @param {Object} req - Requisição com params.id e body com dados atualizados.
 * @param {Object} res - Resposta Express.
 * @param {Function} next - Para propagação de erros.
 */
function updateBook(req, res, next) {
  try {
    const updatedBook = bookModel.update(req.params.id, req.body);

    if (!updatedBook) {
      return next(new NotFoundError('Livro', req.params.id));
    }

    // Verifica se o ISBN foi alterado para uma value já existente.
    if (req.body.isbn) {
      const existingByIsbn = bookModel.findByIsbn(req.body.isbn);
      if (existingByIsbn && existingByIsbn.id !== req.params.id) {
        return next(
          new ValidationError('ISBN duplicado', [
            { field: 'isbn', message: `Já existe outro livro com ISBN ${req.body.isbn}` },
          ])
        );
      }
    }

    res.status(200).json({
      data: updatedBook,
      message: 'Livro atualizado com sucesso',
    });
  } catch (error) {
    next(error);
  }
}

/**
 * DELETE /books/:id
 * Remove um livro do sistema.
 *
 * EXEMPLO CURL:
 * curl -X DELETE http://localhost:3000/books/1
 *
 * @param {Object} req - Requisição com params.id.
 * @param {Object} res - Resposta Express.
 * @param {Function} next - Para propagação de erros.
 */
function deleteBook(req, res, next) {
  try {
    const removed = bookModel.remove(req.params.id);

    if (!removed) {
      return next(new NotFoundError('Livro', req.params.id));
    }

    // 204 No Content é o status HTTP padrão para deleção bem-sucedida.
    // Não retornamos corpo porque não há recurso para devolver.
    res.status(204).end();
  } catch (error) {
    next(error);
  }
}

/**
 * GET /stats
 * Retorna estatísticas agregadas do acervo de livros.
 *
 * EXEMPLO DE RESPOSTA:
 * {
 *   "data": {
 *     "total": 3,
 *     "byGenre": { "Fantasia": 1, "Distopia": 1, "Romance": 1 },
 *     "oldestPublication": 1899,
 *     "newestPublication": 1954
 *   }
 * }
 *
 * @param {Object} req - Requisição Express.
 * @param {Object} res - Resposta Express.
 */
function getStats(req, res) {
  const stats = bookModel.getStats();
  res.status(200).json({ data: stats });
}

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

