## Arquivo 7: `src/routes/books.routes.js`

```javascript
/**
 * ============================================================================
 * ROTAS — Mapeamento URL → Handler do Controller
 * ============================================================================
 *
 * POR QUE ARQUIVO DE ROTAS SEPARADO?
 * -----------------------------------
 * Separar rotas do controller segue o princípio de separação de concerns:
 *   - Rotas definem a interface externa (URLs, métodos HTTP, middlewares).
 *   - Controllers implementam a lógica de negócio.
 *
 * Isso facilita testes unitários (testamos controller sem Express) e permite
 * reutilizar rotas em diferentes contexts (ex: API v1 vs v2).
 *
 * POR QUE USEMOS async/await?
 * ----------------------------
 * Embora esta API use array em memória (síncrono), estruturamos os handlers
 * como async para estar preparados para migração futura a banco de dados
 * assíncrono sem precisar reescrever as rotas. O Express suporta nativamente
 * funções async — erros são capturados automaticamente e passados ao middleware.
 */

const express = require('express');
const router = express.Router(); // Cria um roteador modular isolado.

const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
} = require('../controllers/books.controller');

const { validateCreateBook, validateBookId } = require('../middleware/validation.middleware');

/**
 * ============================================================================
 * ROTAS PARA /books (coleção)
 * ============================================================================
 */

/**
 * GET /books
 * Lista todos os livros com filtragem opcional via query params.
 *
 * curl http://localhost:3000/books
 * curl "http://localhost:3000/books?author=tolkien"
 * curl "http://localhost:3000/books?genre=fantasia&minYear=1900"
 */
router.get('/books', getAllBooks);

/**
 * POST /books
 * Cria um novo livro. Requer validação de entrada antes do controller.
 *
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"1984","author":"George Orwell","isbn":"978-0451524935","publishedYear":1949,"genre":"Distopia"}'
 */
router.post('/books', validateCreateBook, createBook);

/**
 * ============================================================================
 * ROTAS PARA /books/:id (recurso individual)
 * ============================================================================
 */

/**
 * GET /books/:id
 * Retorna um livro pelo ID. Valida o ID antes de processar.
 *
 * curl http://localhost:3000/books/1
 * curl http://localhost:3000/books/999  → 404
 */
router.get('/books/:id', validateBookId, getBookById);

/**
 * PUT /books/:id
 * Atualiza um livro existente. Valida o ID antes de processar.
 *
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","isbn":"978-0618640157","publishedYear":1954,"genre":"Fantasia"}'
 */
router.put('/books/:id', validateBookId, updateBook);

/**
 * DELETE /books/:id
 * Remove um livro pelo ID. Valida o ID antes de processar.
 *
 * curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/books/:id', validateBookId, deleteBook);

/**
 * ============================================================================
 * ROTA PARA /stats (estatísticas)
 * ============================================================================
 */

/**
 * GET /stats
 * Retorna estatísticas agregadas do acervo.
 *
 * curl http://localhost:3000/stats
 */
router.get('/stats', getStats);

module.exports = router;
```

