## Arquivo 8: `src/app.js`

```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO DA APLICAÇÃO EXPRESS
 * ============================================================================
 *
 * POR QUE SEPARAR app.js DO server.js?
 * --------------------------------------
 * app.js configura a aplicação (middlewares, rotas) sem abrir a porta.
 * server.js apenas inicia o servidor e faz listen(). Isso permite:
 *   - Testar a app sem precisar de um servidor rodando.
 *   - Inserir a app em testes integration com supertest.
 *   - Reutilizar a mesma configuração em diferentes ambientes.
 */

const express = require('express');
const booksRoutes = require('./routes/books.routes');
const { errorHandler, notFoundHandler } = require('./middleware/error.middleware');

const app = express();

/**
 * ============================================================================
 * MIDDLEWARES GLOBAIS
 * ============================================================================
 *
 * ORDEM IMPORTA! O Express executa middlewares na ordem em que são registrados.
 * Middlewares de parsing devem vir antes das rotas; middlewares de erro por último.
 */

// body-parser nativo do Express 4.16+: parseia JSON no corpo da requisição.
// limit: 10mb — suficiente para a maioria dos payloads de livros.
app.use(express.json({ limit: '10mb' }));

// urlencoded: parseia dados de formulários (útil se expandirmos para HTML forms).
app.use(express.urlencoded({ extended: true, limit: '10mb' }));

/**
 * Middleware de logging simples — registra método, URL e timestamp de cada requisição.
 * Em produção, substituiríamos por um logger como Winston ou Pino.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next();
});

/**
 * ============================================================================
 * ROTAS DA API
 * ============================================================================
 * Todas as rotas estão sob o prefixo /api/v1 para facilitar versionamento futuro.
 * Se precisarmos de uma v2, basta adicionar /api/v2/ sem quebrar clientes existentes.
 */
app.use('/api/v1', booksRoutes);

/**
 * Rota raiz informativa — útil para descoberta da API.
 */
app.get('/', (req, res) => {
  res.json({
    name: 'Book API',
    version: '1.0.0',
    description: 'API REST para gerenciamento de livros — exemplo educacional',
    endpoints: {
      books: {
        list: 'GET /api/v1/books',
        create: 'POST /api/v1/books',
        getById: 'GET /api/v1/books/:id',
        update: 'PUT /api/v1/books/:id',
        delete: 'DELETE /api/v1/books/:id',
      },
      stats: 'GET /api/v1/stats',
    },
  });
});

/**
 * ============================================================================
 * MIDDLEWARES DE ERRO — DEVEM SEMPRE VIR POR ÚLTIMO
 * ============================================================================
 *
 * notFoundHandler: captura requisições para rotas inexistentes (404).
 * errorHandler: captura todos os erros lançados via next(err) nas rotas.
 */
app.use(notFoundHandler);
app.use(errorHandler);

module.exports = app;
```

