## Arquivo 9: `src/server.js`

```javascript
/**
 * ============================================================================
 * PONTO DE ENTRADA — Inicialização do Servidor
 * ============================================================================
 *
 * POR QUE ESTE ARQUIVO É TÃO SIMPLES?
 * ------------------------------------
 * Seguir o princípio da responsabilidade única: este arquivo apenas inicia o
 * servidor. Toda a configuração está em app.js. Isso facilita testes e
 * manutenção, além de permitir diferentes estratégias de deploy (ex: usar a
 * mesma app com Fastify ou Koa no futuro).
 */

const app = require('./app');

// Porta configurável via variável de ambiente, com fallback para 3000.
// Isso permite rodar múltiplas instâncias em portas diferentes (ex: testes paralelos).
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book API rodando na porta ${PORT}`);
  console.log(`  Ambiente: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Base URL: http://localhost:${PORT}`);
  console.log(`========================================`);
  console.log(`\nEndpoints disponíveis:`);
  console.log(`  GET    http://localhost:${PORT}/api/v1/books          — Listar livros`);
  console.log(`  POST   http://localhost:${PORT}/api/v1/books          — Criar livro`);
  console.log(`  GET    http://localhost:${PORT}/api/v1/books/:id      — Buscar por ID`);
  console.log(`  PUT    http://localhost:${PORT}/api/v1/books/:id      — Atualizar livro`);
  console.log(`  DELETE http://localhost:${PORT}/api/v1/books/:id      — Excluir livro`);
  console.log(`  GET    http://localhost:${PORT}/api/v1/stats          — Estatísticas`);
  console.log(`\nTeste com: curl http://localhost:${PORT}/api/v1/books\n`);
});

// Tratamento de erros não capturados no nível do processo.
// Isso captura erros como "ReferenceError" ou falhas de parsing que escapam do Express.
process.on('uncaughtException', (error) => {
  console.error('[UNCAUGHT EXCEPTION]', error);
  server.close(() => process.exit(1)); // Fecha o servidor antes de sair.
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('[UNHANDLED REJECTION]', reason);
  // Em produção, poderíamos notificar o Sentry ou similar aqui.
});

module.exports = server;
```

