## File 1: `errors/customErrors.js`

**Why this file exists:** Custom error classes let us distinguish between "the resource wasn't found" (404), "the client sent bad input" (400), and unexpected server failures (500). Express's built-in `Error` middleware can then inspect the error type and return a consistent JSON shape.

```javascript
/**
 * errors/customErrors.js
 *
 * Custom error classes for the Book API.
 * Each class extends Error, sets a descriptive message, and carries an HTTP status code.
 * The errorHandler middleware reads `statusCode` to build the response.
 */

// ─── Base class: APIError ──────────────────────────────────────────────────────
/**
 * APIError — base for all application-specific errors.
 *
 * @param {string} message  Human-readable description (shown in JSON responses).
 * @param {number} statusCode  HTTP status code (default 500 Internal Server Error).
 */
class APIError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.name = 'APIError';
    this.statusCode = statusCode;

    // Capture a clean stack trace (without the Error constructor noise).
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ─── NotFoundError — resource doesn't exist ─────────────────────────────────────
/**
 * NotFoundError — thrown when a requested book ID is not found.
 * Maps to HTTP 404 Not Found.
 */
class NotFoundError extends APIError {
  constructor(resource = 'Resource') {
    super(`${resource} not found`, 404);
    this.name = 'NotFoundError';
  }
}

// ─── ValidationError — client sent invalid input ────────────────────────────────
/**
 * ValidationError — thrown when request body/query params fail validation.
 * Maps to HTTP 400 Bad Request.
 *
 * @param {string|string[]} message  Single string or array of field-specific messages.
 */
class ValidationError extends APIError {
  constructor(message) {
    // If `message` is an array, join with "; " for a readable single-string message.
    const msg = Array.isArray(message) ? message.join('; ') : message;
    super(msg, 400);
    this.name = 'ValidationError';
  }
}

// ─── Export all three classes ───────────────────────────────────────────────────
module.exports = { APIError, NotFoundError, ValidationError };
```

