## File 2: `data/books.js`

**Why in-memory?** An array is the simplest possible data store. It requires zero setup, makes the code readable, and lets you focus on *API patterns* rather than database drivers. The functions below are deliberately pure (no side effects outside the module) so they're easy to test and swap later.

```javascript
/**
 * data/books.js
 *
 * In-memory storage layer for books.
 *
 * Data structure choice:
 *   - `books` is a plain JavaScript array of objects. Arrays give O(1) push/pop,
 *     and O(n) search (fine for educational scale). For production, replace with
 *     a database query layer that exposes the same interface.
 *   - Each book has an auto-incrementing `id` so we never collide with client IDs.
 *   - Timestamps (`createdAt`, `updatedAt`) let us demonstrate derived stats later.
 */

// ─── Module-level state ────────────────────────────────────────────────────────
/** @type {Array<Object>} In-memory book collection. */
let books = [];

/** @type {number} Auto-incrementing ID counter. Starts at 1. */
let nextId = 1;

// ─── Seed data (so the API isn't empty on first start) ────────────────────────
const seedBooks = [
  {
    id: 1,
    title: 'The Pragmatic Programmer',
    author: 'David Thomas & Andrew Hunt',
    genre: 'Technology',
    publishedYear: 1999,
    isbn: '9780135957059',
    createdAt: new Date('1999-10-20T00:00:00.000Z'),
    updatedAt: new Date('1999-10-20T00:00:00.000Z'),
  },
  {
    id: 2,
    title: 'Clean Code',
    author: 'Robert C. Martin',
    genre: 'Technology',
    publishedYear: 2008,
    isbn: '9780132350884',
    createdAt: new Date('2008-08-01T00:00:00.000Z'),
    updatedAt: new Date('2008-08-01T00:00:00.000Z'),
  },
  {
    id: 3,
    title: 'Dune',
    author: 'Frank Herbert',
    genre: 'Science Fiction',
    publishedYear: 1965,
    isbn: '9780441172719',
    createdAt: new Date('1965-08-01T00:00:00.000Z'),
    updatedAt: new Date('1965-08-01T00:00:00.000Z'),
  },
];

// Populate the array on module load (runs once when Node requires this file).
books = seedBooks.map((b) => ({ ...b }));
nextId = Math.max(...books.map((b) => b.id)) + 1;

// ─── CRUD Functions ────────────────────────────────────────────────────────────

/**
 * getAllBooks — return every book, optionally filtered by query params.
 *
 * @param {Object} [filters]  Optional filter object with keys: genre, author, minYear, search.
 * @returns {Array<Object>} Filtered list of book objects.
 *
 * Filtering logic (case-insensitive substring match where applicable):
 *   - `genre`: exact match after lowercasing both sides.
 *   - `author`: substring match against the full author string.
 *   - `minYear`: publishedYear >= minYear.
 *   - `search`: matches title OR author (substring, case-insensitive).
 */
function getAllBooks(filters = {}) {
  let result = [...books]; // Clone so we never mutate the source array.

  const { genre, author, minYear, search } = filters;

  if (genre) {
    const lowerGenre = genre.toLowerCase();
    result = result.filter((b) => b.genre.toLowerCase() === lowerGenre);
  }

  if (author) {
    const lowerAuthor = author.toLowerCase();
    result = result.filter((b) => b.author.toLowerCase().includes(lowerAuthor));
  }

  if (minYear) {
    const year = Number(minYear);
    if (!isNaN(year)) {
      result = result.filter((b) => b.publishedYear >= year);
    }
  }

  if (search) {
    const lowerSearch = search.toLowerCase();
    result = result.filter(
      (b) =>
        b.title.toLowerCase().includes(lowerSearch) ||
        b.author.toLowerCase().includes(lowerSearch),
    );
  }

  return result;
}

/**
 * getBookById — find a single book by its numeric ID.
 *
 * @param {number} id  The book's unique identifier.
 * @returns {Object|null} The book object, or null if not found.
 */
function getBookById(id) {
  return books.find((b) => b.id === id) || null;
}

/**
 * createBook — add a new book to the in-memory store.
 *
 * @param {Object} data  Book fields (title, author, genre, publishedYear, isbn).
 * @returns {Object} The newly created book object with generated id & timestamps.
 */
function createBook(data) {
  const now = new Date();
  const newBook = {
    id: nextId++,
    title: data.title,
    author: data.author,
    genre: data.genre,
    publishedYear: data.publishedYear,
    isbn: data.isbn,
    createdAt: now,
    updatedAt: now,
  };

  books.push(newBook);
  return { ...newBook }; // Return a copy to prevent external mutation.
}

/**
 * updateBook — replace fields of an existing book by ID.
 *
 * @param {number} id       The book's unique identifier.
 * @param {Object} updates  Fields to overwrite (title, author, genre, publishedYear, isbn).
 * @returns {Object|null} The updated book object, or null if not found.
 */
function updateBook(id, updates) {
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return null;

  // Merge: keep existing fields, overwrite only the ones provided.
  books[index] = {
    ...books[index],
    ...updates,
    updatedAt: new Date(), // Always refresh the timestamp on modification.
  };

  return { ...books[index] };
}

/**
 * deleteBook — remove a book from the store by ID.
 *
 * @param {number} id  The book's unique identifier.
 * @returns {boolean} True if a book was deleted, false if not found.
 */
function deleteBook(id) {
  const index = books.findIndex((b) => b.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

// ─── Export the public API ──────────────────────────────────────────────────────
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
};
