## File 3: `routes/books.js`

**Why separate route file?** Keeping routes in their own module makes `server.js` lean and lets you test route logic independently. Each handler follows the same pattern: validate → call data layer → send JSON response or throw error.

```javascript
/**
 * routes/books.js
 *
 * RESTful book endpoints.
 *
 * HTTP conventions used:
 *   - GET    /books          — list (with optional query filters)
 *   - GET    /books/:id      — single resource
 *   - POST   /books          — create new resource
 *   - PUT    /books/:id      — full update of existing resource
 *   - DELETE /books/:id      — remove resource
 *
 * Every handler returns JSON with a consistent shape:
 *   { data, meta?, error? }
 */

const express = require('express');
const router = express.Router();
const booksData = require('../data/books');
const { NotFoundError, ValidationError } = require('../errors/customErrors');

// ─── GET /books — List all books (with optional filtering) ─────────────────────
/**
 * @route   GET /books
 * @desc    Retrieve a list of books. Supports query parameters for filtering.
 * @access  Public
 *
 * Query params:
 *   - genre   (string)  Filter by exact genre match, case-insensitive.
 *   - author  (string)  Substring search in author name.
 *   - minYear (number)  Minimum published year.
 *   - search  (string)  Search title OR author.
 *
 * @example curl "http://localhost:3000/books?genre=Technology"
 * @example curl "http://localhost:3000/books?search=dune"
 */
router.get('/books', (req, res) => {
  // Extract filter params from the query string; default to empty object.
  const filters = {
    genre: req.query.genre,
    author: req.query.author,
    minYear: req.query.minYear,
    search: req.query.search,
  };

  // Remove undefined values so the data layer doesn't process null filters.
  Object.keys(filters).forEach((key) => {
    if (filters[key] === undefined) delete filters[key];
  });

  const result = booksData.getAllBooks(filters);

  res.json({
    data: result,
    meta: {
      total: result.length,
      // Echo back the applied filters so the client knows what was used.
      filters: Object.keys(filters).length > 0 ? filters : null,
    },
  });
});

// ─── GET /books/:id — Get a single book ────────────────────────────────────────
/**
 * @route   GET /books/:id
 * @desc    Retrieve a single book by its numeric ID.
 * @access  Public
 *
 * @param {number} id  Book identifier (URL parameter).
 *
 * @example curl "http://localhost:3000/books/1"
 */
router.get('/books/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  // Guard against non-numeric IDs before hitting the data layer.
  if (isNaN(id)) {
    throw new ValidationError('Invalid book ID: must be a number');
  }

  const book = booksData.getBookById(id);
  if (!book) {
    // Throwing here lets the global error handler format a clean JSON response.
    throw new NotFoundError('Book');
  }

  res.json({ data: book });
});

// ─── POST /books — Create a new book ──────────────────────────────────────────
/**
 * @route   POST /books
 * @desc    Create a new book record.
 * @access  Public
 *
 * Request body (JSON):
 *   - title        (string, required)  Book title.
 *   - author       (string, required)  Author name(s).
 *   - genre        (string, required)  Genre/category.
 *   - publishedYear(number, required)  Year of publication (4-digit number).
 *   - isbn         (string, optional)  ISBN-13 format recommended.
 *
 * @example curl -X POST http://localhost:3000/books \
 *            -H "Content-Type: application/json" \
 *            -d '{"title":"1984","author":"George Orwell","genre":"Dystopian",
 *                  "publishedYear":1949,"isbn":"9780451524935"}'
 */
router.post('/books', (req, res) => {
  const { title, author, genre, publishedYear, isbn } = req.body;

  // ── Validation block ────────────────────────────────────────────────────────
  const errors = [];

  if (!title || typeof title !== 'string' || title.trim() === '') {
    errors.push('title is required and must be a non-empty string');
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    errors.push('author is required and must be a non-empty string');
  }
  if (!genre || typeof genre !== 'string' || genre.trim() === '') {
    errors.push('genre is required and must be a non-empty string');
  }
  const year = Number(publishedYear);
  if (isNaN(year) || !Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
    errors.push('publishedYear is required and must be a valid integer year');
  }
  if (isbn && (!/^\d{13}$/.test(isbn))) {
    // ISBN-13 is the most common standard; we accept it optionally.
    errors.push('isbn, if provided, must be exactly 13 digits');
  }

  if (errors.length > 0) {
    throw new ValidationError(errors);
  }

  // ── Create & respond ────────────────────────────────────────────────────────
  const newBook = booksData.createBook({
    title: title.trim(),
    author: author.trim(),
    genre: genre.trim(),
    publishedYear: year,
    isbn: isbn ? isbn.trim() : undefined,
  });

  // 201 Created is the semantically correct status for resource creation.
  res.status(201).json({ data: newBook });
});

// ─── PUT /books/:id — Full update of an existing book ──────────────────────────
/**
 * @route   PUT /books/:id
 * @desc    Replace all updatable fields of an existing book.
 * @access  Public
 *
 * Request body (JSON) — all fields are optional; only provided ones are updated:
 *   - title, author, genre, publishedYear, isbn
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *            -H "Content-Type: application/json" \
 *            -d '{"title":"The Pragmatic Programmer (2nd Ed.)","publishedYear":2019}'
 */
router.put('/books/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    throw new ValidationError('Invalid book ID: must be a number');
  }

  // Check existence first so we don't silently create on update.
  const existing = booksData.getBookById(id);
  if (!existing) {
    throw new NotFoundError('Book');
  }

  const { title, author, genre, publishedYear, isbn } = req.body;
  const updates = {};
  const errors = [];

  // Only include fields that were actually sent in the request body.
  if (title !== undefined) {
    if (typeof title !== 'string' || title.trim() === '') {
      errors.push('title must be a non-empty string');
    } else {
      updates.title = title.trim();
    }
  }
  if (author !== undefined) {
    if (typeof author !== 'string' || author.trim() === '') {
      errors.push('author must be a non-empty string');
    } else {
      updates.author = author.trim();
    }
  }
  if (genre !== undefined) {
    if (typeof genre !== 'string' || genre.trim() === '') {
      errors.push('genre must be a non-empty string');
    } else {
      updates.genre = genre.trim();
    }
  }
  if (publishedYear !== undefined) {
    const year = Number(publishedYear);
    if (isNaN(year) || !Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      errors.push('publishedYear must be a valid integer year');
    } else {
      updates.publishedYear = year;
    }
  }
  if (isbn !== undefined) {
    if (isbn !== null && !/^\d{13}$/.test(isbn)) {
      errors.push('isbn, if provided, must be exactly 13 digits');
    } else {
      updates.isbn = isbn;
    }
  }

  if (errors.length > 0) {
    throw new ValidationError(errors);
  }

  const updatedBook = booksData.updateBook(id, updates);
  res.json({ data: updatedBook });
});

// ─── DELETE /books/:id — Remove a book ────────────────────────────────────────
/**
 * @route   DELETE /books/:id
 * @desc    Permanently delete a book by its ID.
 * @access  Public
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/books/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    throw new ValidationError('Invalid book ID: must be a number');
  }

  const deleted = booksData.deleteBook(id);
  if (!deleted) {
    throw new NotFoundError('Book');
  }

  // 204 No Content is standard when deleting returns no body.
  res.status(204).end();
});

// ─── Export the router ──────────────────────────────────────────────────────────
module.exports = router;
```

