## File 4: `routes/stats.js`

**Why a separate stats route?** Statistics are *derived* data, not stored records. Keeping them in their own module signals to consumers that this endpoint computes on the fly and may be more expensive than a simple CRUD lookup.

```javascript
/**
 * routes/stats.js
 *
 * GET /stats — Return aggregate statistics about the book collection.
 *
 * Statistics computed:
 *   - totalBooks          Count of all books.
 *   - averagePublishedYear Mean year of publication (rounded to 1 decimal).
 *   - genreDistribution   Object mapping each genre → count.
 *   - topAuthors          Array of { author, bookCount } sorted descending (top 5).
 *   - booksByDecade       Object mapping decade strings ("1960s", "1970s", …) → count.
 */

const express = require('express');
const router = express.Router();
const booksData = require('../data/books');

/**
 * @route   GET /stats
 * @desc    Retrieve aggregate statistics for all books in the collection.
 * @access  Public
 *
 * @example curl "http://localhost:3000/stats"
 */
router.get('/stats', (req, res) => {
  const allBooks = booksData.getAllBooks();

  // ── totalBooks & averagePublishedYear ────────────────────────────────────────
  const totalBooks = allBooks.length;
  const averagePublishedYear =
    totalBooks > 0
      ? parseFloat(
          (allBooks.reduce((sum, b) => sum + b.publishedYear, 0) / totalBooks).toFixed(1),
        )
      : null;

  // ── genreDistribution ────────────────────────────────────────────────────────
  const genreDistribution = allBooks.reduce((acc, b) => {
    acc[b.genre] = (acc[b.genre] || 0) + 1;
    return acc;
  }, {});

  // ── topAuthors — group by author, sort descending, take top 5 ───────────────
  const authorCounts = allBooks.reduce((acc, b) => {
    acc[b.author] = (acc[b.author] || 0) + 1;
    return acc;
  }, {});

  const topAuthors = Object.entries(authorCounts)
    .map(([author, bookCount]) => ({ author, bookCount }))
    .sort((a, b) => b.bookCount - a.bookCount)
    .slice(0, 5);

  // ── booksByDecade — e.g. "1960s": 3 ─────────────────────────────────────────
  const booksByDecade = allBooks.reduce((acc, b) => {
    const decade = Math.floor(b.publishedYear / 10) * 10;
    const label = `${decade}s`;
    acc[label] = (acc[label] || 0) + 1;
    return acc;
  }, {});

  // Sort decades chronologically for a nicer response.
  const sortedByDecade = Object.entries(booksByDecade)
    .sort(([a], [b]) => parseInt(a) - parseInt(b))
    .reduce((acc, [k, v]) => {
      acc[k] = v;
      return acc;
    }, {});

  res.json({
    data: {
      totalBooks,
      averagePublishedYear,
      genreDistribution,
      topAuthors,
      booksByDecade: sortedByDecade,
    },
  });
});

module.exports = router;
```

