## File 6: `server.js`

**Why this is the entry point?** It wires everything together: Express app, body-parser (so `req.body` works), route mounting, and the global error handler. Keeping it minimal makes the architecture easy to follow.

```javascript
/**
 * server.js
 *
 * Application bootstrap.
 *
 * Architecture decisions explained:
 *   - `express.json()` middleware parses incoming JSON request bodies into req.body.
 *     Without this, POST/PUT bodies would be raw strings and validation would fail.
 *   - Routes are mounted at the root (`/`) so the full paths become /books, /stats, etc.
 *   - The error handler is registered LAST (after routes) so it only catches errors
 *     thrown inside route handlers, not middleware errors before routing.
 *   - `NODE_ENV` defaults to 'development' locally; set to 'production' in deployment
 *     to suppress stack traces in error responses.
 */

const express = require('express');
const booksRouter = require('./routes/books');
const statsRouter = require('./routes/stats');
const errorHandler = require('./middleware/errorHandler');

// Create the Express application instance.
const app = express();

// ─── Middleware setup ──────────────────────────────────────────────────────────
/**
 * Parse JSON request bodies (e.g., POST/PUT payloads).
 * Limits payload to 10kb to prevent abuse.
 */
app.use(express.json({ limit: '10kb' }));

// Simple logging middleware so you can see every request in the terminal.
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ─── Route mounting ────────────────────────────────────────────────────────────
/**
 * Mount route modules. The path argument here is prepended to every route in the module.
 * Since we pass '' (empty string), routes keep their original paths: /books, /stats.
 */
app.use('', booksRouter);
app.use('', statsRouter);

// ─── Root endpoint (health check) ──────────────────────────────────────────────
/**
 * @route   GET /
 * @desc    Simple health-check endpoint confirming the server is running.
 */
app.get('/', (req, res) => {
  res.json({
    message: 'Book API is running',
    endpoints: {
      books: ['GET /books', 'GET /books/:id', 'POST /books', 'PUT /books/:id', 'DELETE /books/:id'],
      stats: ['GET /stats'],
    },
  });
});

// ─── Global error handler (MUST be after all routes) ──────────────────────────
app.use(errorHandler);

// ─── Start the server ──────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`📚 Book API listening on http://localhost:${PORT}`);
  console.log(`   Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app; // Export for testing frameworks.
```

