## Arquivo 2: `src/errors/AppError.js`

```javascript
/**
 * AppError.js
 *
 * Classe base personalizada para erros da aplicação.
 *
 * POR QUE UMA CLASSE DE ERRO PERSONALIZADA?
 * ------------------------------------------
 * Em vez de lançar objetos genéricos ({ message: '...' }), criamos uma classe
 * que carrega: código HTTP, tipo de erro e mensagem. Isso permite que o
 * middleware de tratamento de erros responda com o formato correto automaticamente,
 * sem precisar de condicionais manuais em cada rota.
 *
 * Padrão adotado: Error Object Pattern (do ExpressJS docs)
 */

class AppError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro
   * @param {number} statusCode - Código HTTP da resposta (400, 404, etc.)
   * @param {string} [errorCode] - Código interno do erro (ex: 'BOOK_NOT_FOUND')
   */
  constructor(message, statusCode, errorCode = null) {
    super(message);

    // Preservamos o stack trace para debugging
    Error.captureStackTrace(this, this.constructor);

    /** @type {number} Código HTTP da resposta */
    this.statusCode = statusCode;

    /** @type {string|null} Código interno do erro, útil para logging e monitoramento */
    this.errorCode = errorCode;

    /** @type {boolean} Marca este erro como "conhecido" pela aplicação (não é um bug) */
    this.isOperational = true;
  }
}

/**
 * Erro de requisição inválida — dados faltando, mal formatados ou fora do padrão.
 * HTTP 400 Bad Request.
 */
class ValidationError extends AppError {
  constructor(message, details = null) {
    super(message, 400, 'VALIDATION_ERROR');
    /** @type {object|null} Detalhes específicos da validação (ex: campos inválidos) */
    this.details = details;
  }
}

/**
 * Recurso não encontrado — ID inexistente ou caminho incorreto.
 * HTTP 404 Not Found.
 */
class NotFoundError extends AppError {
  constructor(resource, id) {
    super(`${resource} com ID ${id} não encontrado`, 404, 'NOT_FOUND');
    /** @type {string} Nome do recurso (ex: 'Book') */
    this.resource = resource;
    /** @type {string|number} ID que não foi encontrado */
    this.id = id;
  }
}

/**
 * Erro de método não permitido — endpoint existe mas o verbo HTTP é inválido.
 * HTTP 405 Method Not Allowed.
 */
class MethodNotAllowedError extends AppError {
  constructor(allowedMethods) {
    super(`Método ${allowedMethods.join(', ')} não é permitido para este recurso`, 405, 'METHOD_NOT_ALLOWED');
  }
}

module.exports = { AppError, ValidationError, NotFoundError, MethodNotAllowedError };
