## Arquivo 3: `src/middleware/errorMiddleware.js`

```javascript
/**
 * errorMiddleware.js
 *
 * Middleware de tratamento centralizado de erros.
 *
 * POR QUE UM MIDDLEWARE DE ERROS?
 * --------------------------------
 * O Express possui um mecanismo especial para middlewares de erro: funções com
 * 4 parâmetros (err, req, res, next). Quando qualquer rota ou middleware chama
 * next(err), o fluxo pula diretamente para este middleware. Isso evita a
 * repetição de blocos try/catch em cada handler e garante que TODOS os erros
 * sejam respondidos com o mesmo formato JSON consistente.
 *
 * Em produção, NÃO expomos detalhes internos do erro (stack trace) ao cliente.
 */

const { AppError } = require('../errors/AppError');

/**
 * Middleware de tratamento de erros da aplicação.
 *
 * @param {Error} err - O erro lançado por uma rota ou middleware
 * @param {import('express').Request} req - Objeto de requisição Express
 * @param {import('express').Response} res - Objeto de resposta Express
 * @param {import('express').NextFunction} next - Função next do Express
 */
function errorHandler(err, req, res, next) {
  // Se o erro for nossa classe AppError personalizada, usamos seus campos
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      success: false,
      errorCode: err.errorCode || 'UNKNOWN_ERROR',
      message: err.message,
      ...(err.details && { details: err.details }),
      // Em desenvolvimento, incluímos o stack trace para facilitar debugging.
      // Em produção, remova esta linha para não vazar informações sensíveis.
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    });
  }

  // Erros não previstos (bugs) — resposta genérica segura
  console.error('[ERRO NÃO TRATADO]:', err); // Log para o servidor
  return res.status(500).json({
    success: false,
    errorCode: 'INTERNAL_ERROR',
    message: 'Erro interno do servidor. Tente novamente mais tarde.',
    // Stack trace apenas em desenvolvimento
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
}

/**
 * Middleware que captura erros de funções assíncronas.
 *
 * PROBLEMA RESOLVIDO:
 * --------------------
 * Express NÃO captura automaticamente rejeições de Promises em handlers async.
 * Se uma rota async lança um erro, a promise fica "unhandled" e o cliente
 * nunca recebe resposta (timeout). Este middleware envolve cada handler async
 * para capturar erros e encaminhá-los ao middleware errorHandler.
 *
 * Padrão: Async Error Wrapper
 */
function catchAsync(fn) {
  return function(req, res, next) {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

module.exports = { errorHandler, catchAsync };
```

