## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * routes/books.js
 *
 * Rotas para o recurso "livros" seguindo convenções REST.
 *
 * POR QUE ROTAS SEPARADAS?
 * -------------------------
 * Manter as rotas em um arquivo separado promove:
 * 1. Separação de responsabilidades (Single Responsibility Principle)
 * 2. Facilidade de manutenção e escalabilidade
 * 3. Possibilidade de montar múltiplos "routers" no futuro
 *
 * Convenções REST adotadas:
 * - GET    /books          → lista todos os livros
 * - GET    /books/:id      → obtém um livro pelo ID
 * - POST   /books          → cria um novo livro
 * - PUT    /books/:id      → atualiza completamente um livro
 * - DELETE /books/:id      → exclui um livro
 * - GET    /stats          → estatísticas agregadas (recurso derivado)
 */

const { Router } = require('express');
const { AppError, ValidationError, NotFoundError } = require('../errors/AppError');
const { catchAsync } = require('../middleware/errorMiddleware');

// Instância do router que será montada no app principal
const router = Router();

// ============================================================================
// ARMAZENAMENTO EM MEMÓRIA (IN-MEMORY STORE)
// ============================================================================
//
// POR QUE UM ARRAY?
// ------------------
// Para este exemplo educacional, usamos um array simples porque:
// 1. É a estrutura mais intuitiva para demonstrar CRUD
// 2. Operações de busca linear são aceitáveis para conjuntos pequenos
// 3. Facilita o entendimento do código sem abstrações desnecessárias
//
// Em produção, substituiríamos por um banco de dados (MongoDB, PostgreSQL, etc.)
// e o array seria trocado por queries ao DB — a interface das rotas permaneceria
// a mesma graças ao princípio da abstração.
//
// Cada livro é um objeto com campos bem definidos para facilitar validação.
const books = [
  { id: '1', title: 'Dom Casmurro', author: 'Machado de Assis', year: 1899, genre: 'Romance' },
  { id: '2', title: '1984', author: 'George Orwell', year: 1949, genre: 'Distopia' },
  { id: '3', title: 'O Senhor dos Anéis', author: 'J.R.R. Tolkien', year: 1954, genre: 'Fantasia' },
];

// Gerador de IDs únicos simples (em produção, usar UUID ou ObjectId)
let nextId = 4;
function generateId() {
  return String(nextId++);
}

// ============================================================================
// VALIDAÇÃO DE ENTRADA
// ============================================================================
//
// POR QUE VALIDAR ANTES DE PROCESSAR?
// -------------------------------------
// Validação antecipada (fail-fast) evita que dados inválidos entrem no sistema.
// Também melhora a experiência do usuário ao retornar mensagens de erro claras
// e específicas sobre o que está errado.

/**
 * Valida os campos obrigatórios e tipos de um livro.
 *
 * @param {object} data - Dados brutos da requisição
 * @returns {{valid: boolean, errors: object}} Resultado da validação
 */
function validateBook(data) {
  const errors = {};

  // Título é obrigatório e deve ser string não vazia
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    errors.title = 'O título é obrigatório e deve ser uma string não vazia';
  }

  // Autor é obrigatório e deve ser string não vazia
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    errors.author = 'O autor é obrigatório e deve ser uma string não vazia';
  }

  // Ano deve ser um número inteiro válido entre 0 e o ano atual + 1 (para evitar anos no futuro)
  const currentYear = new Date().getFullYear();
  if (data.year === undefined || data.year === null) {
    errors.year = 'O ano de publicação é obrigatório';
  } else if (!Number.isInteger(data.year) || data.year < 0 || data.year > currentYear + 1) {
    errors.year = `O ano deve ser um inteiro entre 0 e ${currentYear + 1}`;
  }

  // Gênero é opcional, mas se fornecido deve ser string
  if (data.genre !== undefined && data.genre !== null && typeof data.genre !== 'string') {
    errors.genre = 'O gênero deve ser uma string';
  }

  return {
    valid: Object.keys(errors).length === 0,
    errors,
  };
}

// ============================================================================
// FILTRAGEM E PAGINAÇÃO
// ============================================================================
//
// POR QUE FILTRAR NOS QUERY PARAMETERS?
// ----------------------------------------
// Query parameters são o padrão REST para filtros. Eles não alteram o recurso
// em si, apenas a forma como ele é apresentado. Usamos parâmetros opcionais:
// - author: filtra por autor (case-insensitive)
// - genre: filtra por gênero
// - minYear / maxYear: faixa de ano de publicação
//
// Isso permite combinações como: GET /books?author=tolkien&minYear=1950

/**
 * Aplica filtros aos livros com base nos parâmetros de query.
 *
 * @param {Array} allBooks - Lista completa de livros
 * @param {object} filters - Filtros a aplicar
 * @returns {Array} Lista filtrada
 */
function applyFilters(allBooks, filters) {
  return allBooks.filter(book => {
    // Filtro por autor (case-insensitive)
    if (filters.author) {
      const authorMatch = book.author.toLowerCase().includes(filters.author.toLowerCase());
      if (!authorMatch) return false;
    }

    // Filtro por gênero
    if (filters.genre) {
      const genreMatch = book.genre.toLowerCase() === filters.genre.toLowerCase();
      if (!genreMatch) return false;
    }

    // Filtro por ano mínimo
    if (filters.minYear !== undefined && filters.minYear !== null) {
      if (book.year < Number(filters.minYear)) return false;
    }

    // Filtro por ano máximo
    if (filters.maxYear !== undefined && filters.maxYear !== null) {
      if (book.year > Number(filters.maxYear)) return false;
    }

    return true;
  });
}

// ============================================================================
// GET /books — Listar todos os livros com filtragem opcional
// ============================================================================
//
// Exemplo de uso:
//   curl http://localhost:3000/books
//   curl "http://localhost:3000/books?author=tolkien"
//   curl "http://localhost:3000/books?genre=fantasia&minYear=1950"
//
// Postman: GET http://localhost:3000/books
//   Headers: Content-Type: application/json

router.get('/', catchAsync(async (req, res) => {
  // Extrai os parâmetros de query para filtragem
  const { author, genre, minYear, maxYear } = req.query;

  // Constrói o objeto de filtros apenas com os parâmetros presentes
  const filters = {};
  if (author) filters.author = author;
  if (genre) filters.genre = genre;
  if (minYear) filters.minYear = minYear;
  if (maxYear) filters.maxYear = maxYear;

  // Aplica os filtros à lista completa
  const filteredBooks = applyFilters(books, filters);

  // Resposta com metadados de paginação (preparado para expansão futura)
  res.json({
    success: true,
    count: filteredBooks.length,
    total: books.length,
    data: filteredBooks,
  });
}));

// ============================================================================
// GET /books/stats — Estatísticas agregadas dos livros
// ============================================================================
//
// Exemplo de uso:
//   curl http://localhost:3000/books/stats
//
// Postman: GET http://localhost:3000/books/stats

router.get('/stats', catchAsync(async (req, res) => {
  // Estatísticas calculadas em tempo real a partir do array
  const totalBooks = books.length;

  // Quantidade de livros por gênero
  const genreCounts = {};
  books.forEach(book => {
    const genre = book.genre || 'Sem gênero';
    genreCounts[genre] = (genreCounts[genre] || 0) + 1;
  });

  // Ano mais antigo e mais recente
  const years = books.map(b => b.year);
  const oldestYear = Math.min(...years);
  const newestYear = Math.max(...years);

  // Média de anos de publicação
  const averageYear = (years.reduce((a, b) => a + b, 0) / years.length).toFixed(1);

  res.json({
    success: true,
    data: {
      totalBooks,
      genreDistribution: genreCounts,
      yearRange: { oldest: oldestYear, newest: newestYear },
      averagePublicationYear: averageYear,
    },
  });
}));

// ============================================================================
// GET /books/:id — Obter um livro pelo ID
// ============================================================================
//
// Exemplo de uso:
//   curl http://localhost:3000/books/1
//
// Postman: GET http://localhost:3000/books/1

router.get('/:id', catchAsync(async (req, res) => {
  // Busca o livro pelo ID convertido para string (garante comparação correta)
  const book = books.find(b => b.id === req.params.id);

  // Se não encontrado, lançamos NotFoundError que será capturado pelo middleware
  if (!book) {
    throw new NotFoundError('Livro', req.params.id);
  }

  res.json({
    success: true,
    data: book,
  });
}));

// ============================================================================
// POST /books — Criar um novo livro
// ============================================================================
//
// Exemplo de uso com curl:
//   curl -X POST http://localhost:3000/books \
//        -H "Content-Type: application/json" \
//        -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","year":1932,"genre":"Distopia"}'
//
// Postman: POST http://localhost:3000/books
//   Body (JSON): { "title": "...", "author": "...", "year": ..., "genre": "..." }

router.post('/', catchAsync(async (req, res) => {
  // Valida os dados de entrada antes de processar
  const validation = validateBook(req.body);

  if (!validation.valid) {
    throw new ValidationError('Dados inválidos na requisição', validation.errors);
  }

  // Cria o novo livro com ID automático e campos normalizados
  const newBook = {
    id: generateId(),
    title: req.body.title.trim(),           // Remove espaços em branco extras
    author: req.body.author.trim(),
    year: Number(req.body.year),            // Garante que seja número
    genre: req.body.genre ? req.body.genre.trim() : null, // Gênero é opcional
  };

  // Adiciona ao array (operação O(1) no final)
  books.push(newBook);

  // HTTP 201 Created — padrão REST para recursos criados com sucesso
  // O Location header aponta para o URI do recurso criado
  res.status(201).json({
    success: true,
    message: 'Livro criado com sucesso',
    data: newBook,
  });
}));

// ============================================================================
// PUT /books/:id — Atualizar completamente um livro existente
// ============================================================================
//
// POR QUE PUT E NÃO PATCH?
// --------------------------
// PUT significa "substituir" — o cliente envia o recurso COMPLETO e ele substitui
// o existente. PATCH seria "atualização parcial". Para este exemplo, usamos PUT
// porque é mais simples de validar (todos os campos obrigatórios devem estar presentes).
//
// Exemplo de uso com curl:
//   curl -X PUT http://localhost:3000/books/1 \
//        -H "Content-Type: application/json" \
//        -d '{"title":"Dom Casmurro (Ed. Definitiva)","author":"Machado de Assis","year":1899,"genre":"Romance Realista"}'
//
// Postman: PUT http://localhost:3000/books/1
//   Body (JSON): { "title": "...", "author": "...", "year": ..., "genre": "..." }

router.put('/:id', catchAsync(async (req, res) => {
  // Encontra o livro existente
  const bookIndex = books.findIndex(b => b.id === req.params.id);

  if (bookIndex === -1) {
    throw new NotFoundError('Livro', req.params.id);
  }

  // Valida os dados de entrada
  const validation = validateBook(req.body);

  if (!validation.valid) {
    throw new ValidationError('Dados inválidos na requisição', validation.errors);
  }

  // Atualiza o livro existente (substituição completa via PUT)
  books[bookIndex] = {
    id: req.params.id,                        // ID não pode ser alterado
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    year: Number(req.body.year),
    genre: req.body.genre ? req.body.genre.trim() : null,
  };

  res.json({
    success: true,
    message: 'Livro atualizado com sucesso',
    data: books[bookIndex],
  });
}));

// ============================================================================
// DELETE /books/:id — Excluir um livro
// ============================================================================
//
// Exemplo de uso com curl:
//   curl -X DELETE http://localhost:3000/books/1
//
// Postman: DELETE http://localhost:3000/books/1

router.delete('/:id', catchAsync(async (req, res) => {
  // Encontra o índice do livro a ser excluído
  const bookIndex = books.findIndex(b => b.id === req.params.id);

  if (bookIndex === -1) {
    throw new NotFoundError('Livro', req.params.id);
  }

  // Remove o livro do array (splice é O(n) mas aceitável para arrays pequenos)
  const [deletedBook] = books.splice(bookIndex, 1);

  // HTTP 200 OK com o recurso excluído retornado (útil para confirmação)
  res.json({
    success: true,
    message: 'Livro excluído com sucesso',
    data: deletedBook,
  });
}));

module.exports = router;
```

