## Arquivo 5: `src/app.js`

```javascript
/**
 * app.js
 *
 * Configuração da aplicação Express.
 *
 * POR QUE SEPARAR app.js DO server.js?
 * --------------------------------------
 * app.js configura a aplicação (middlewares, rotas, CORS).
 * server.js apenas inicia o servidor HTTP e define a porta.
 * Essa separação permite testar a aplicação sem precisar iniciar o servidor.
 */

const express = require('express');
const { errorHandler } = require('./middleware/errorMiddleware');
const bookRoutes = require('./routes/books');

const app = express();

// ============================================================================
// MIDDLEWARES GLOBAIS
// ============================================================================

/**
 * bodyParser.json() — Parseia o corpo de requisições com Content-Type: application/json.
 * Sem este middleware, req.body seria undefined e não poderíamos ler dados POST/PUT.
 */
app.use(express.json());

/**
 * bodyParser.urlencoded() — Parseia formulários HTML (útil para testes com curl -d).
 * extended: true permite objetos aninhados; false limitaria a strings simples.
 */
app.use(express.urlencoded({ extended: true }));

/**
 * Middleware de logging básico — registra método, URL e timestamp de cada requisição.
 * Em produção, substituiríamos por um logger como Winston ou Pino.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// ============================================================================
// ROTAS
// ============================================================================

/**
 * Montagem das rotas de livros.
 * Todas as rotas ficam sob o prefixo /books, conforme convenção REST.
 */
app.use('/books', bookRoutes);

// ============================================================================
// ROTA PARA RAIZ — Health check
// ============================================================================
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — exemplo educacional Node.js + Express',
    endpoints: {
      'GET    /books': 'Listar todos os livros (com filtragem opcional)',
      'GET    /books/stats': 'Estatísticas dos livros',
      'GET    /books/:id': 'Obter livro por ID',
      'POST   /books': 'Criar novo livro',
      'PUT    /books/:id': 'Atualizar livro existente',
      'DELETE /books/:id': 'Excluir livro',
    },
  });
});

// ============================================================================
// ROTA 404 — Recurso não encontrado (rota inexistente)
// ============================================================================
app.use((req, res, next) => {
  const { AppError } = require('./errors/AppError');
  next(new AppError(`Rota ${req.method} ${req.originalUrl} não encontrada`, 404, 'ROUTE_NOT_FOUND'));
});

// ============================================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS — Deve ser o ÚLTIMO middleware
// ============================================================================
app.use(errorHandler);

module.exports = app;
```

