## Arquivo 6: `src/server.js`

```javascript
/**
 * server.js
 *
 * Ponto de entrada da aplicação. Apenas inicia o servidor HTTP na porta configurada.
 */

const app = require('./app');

// Porta padrão: 3000, mas permite sobrescrita via variável de ambiente (boa prática)
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`✅ Servidor rodando em http://localhost:${PORT}`);
  console.log(`📚 API de Livros — exemplo educacional`);
});

// Graceful shutdown — limpa recursos ao receber sinal de interrupção
process.on('SIGTERM', () => {
  console.log('Sinal SIGTERM recebido. Encerrando servidor...');
  server.close(() => {
    console.log('Servidor encerrado com sucesso.');
    process.exit(0);
  });
});

module.exports = server;
```

