```javascript
/**
 * In-memory data store for books.
 * 
 * WHY AN ARRAY? Arrays are ideal here because:
 * - They preserve insertion order (useful for pagination later)
 * - They support efficient iteration with .filter(), .map(), .reduce()
 * - Access by index is O(1), though we use .findIndex() for ID lookup
 * - No schema enforcement needed since this is educational
 * 
 * WHY NOT A MAP? Maps offer O(1) lookups but complicate filtering and
 * serialization. For a small dataset (< 1000 items), array performance
 * is negligible while code simplicity wins.
 */

// Sample data to demonstrate the API immediately upon startup
const books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.5
  },
  {
    id: 2,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    genre: 'Fiction',
    publishedYear: 1960,
    rating: 4.8
  },
  {
    id: 3,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    genre: 'Science',
    publishedYear: 1988,
    rating: 4.7
  }
];

/**
 * Returns all books in the store.
 * @returns {Array<Object>} Array of book objects
 */
const getAllBooks = () => [...books]; // Return copy to prevent external mutation

/**
 * Finds a single book by its numeric ID.
 * @param {number} id - The unique identifier of the book
 * @returns {Object|null} Book object if found, null otherwise
 */
const getBookById = (id) => books.find((book) => book.id === id) || null;

/**
 * Adds a new book to the store with an auto-incremented ID.
 * WHY AUTO-INCREMENT? Simple for educational purposes. Production systems
 * would use UUIDs or database sequences to avoid collisions in distributed
 * environments.
 * @param {Object} bookData - Book properties (without id)
 * @returns {Object} The newly created book with assigned ID
 */
const createBook = (bookData) => {
  const newId = books.length > 0 ? Math.max(...books.map((b) => b.id)) + 1 : 1;
  const newBook = { id: newId, ...bookData };
  books.push(newBook);
  return newBook;
};

/**
 * Updates an existing book by ID. Returns null if not found.
 * @param {number} id - Book ID to update
 * @param {Object} updates - Fields to update (partial update supported)
 * @returns {Object|null} Updated book or null
 */
const updateBook = (id, updates) => {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Merge existing data with updates (partial update pattern)
  books[index] = { ...books[index], ...updates };
  return books[index];
};

/**
 * Deletes a book by ID. Returns true if deleted, false if not found.
 * @param {number} id - Book ID to delete
 * @returns {boolean} Whether deletion was successful
 */
const deleteBook = (id) => {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // O(n) but acceptable for small datasets
  return true;
};

module.exports = { getAllBooks, getBookById, createBook, updateBook, deleteBook };
```

**Explanation:** We export pure functions rather than exposing the raw array. This encapsulation prevents accidental external mutations and makes testing easier. The spread operator (`...`) creates copies to maintain immutability at the API boundary—important because Express might cache responses otherwise. Auto-incrementing IDs use `Math.max()` on existing IDs, which is safer than relying on array length since deletions can create gaps.

