## File 4: `src/middleware/errorHandler.js`

```javascript
/**
 * Global error-handling middleware for Express.
 * 
 * WHY MIDDLEWARE? Express processes requests through a chain of functions.
 * Placing this at the end catches errors from ANY preceding middleware or route,
 * including async errors that bubble up via .catch() or thrown exceptions.
 * 
 * HOW IT WORKS: Express identifies error-handling middleware by its 4-parameter
 * signature (err, req, res, next). All other middleware use 3 parameters.
 */

const { InternalError } = require('../errors/CustomError');

/**
 * Handles all errors in the application.
 * @param {Error} err - The error object caught by Express
 * @param {Object} req - Express request object (unused but required for signature)
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function (unused here)
 */
const errorHandler = (err, req, res, next) => {
  // Default to 500 if statusCode wasn't set (defensive programming)
  const statusCode = err.statusCode || 500;

  // SECURITY: Never expose internal error details to clients
  // Only operational errors (4xx) get detailed messages
  const isClientError = statusCode >= 400 && statusCode < 500;

  // Log full error details server-side for debugging
  console.error(`[ERROR] ${new Date().toISOString()}:`, {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method
  });

  // Format consistent JSON response for all errors
  const errorResponse = {
    success: false,
    timestamp: new Date().toISOString(),
    status: statusCode,
    message: isClientError ? err.message : 'Internal server error',
    // Include stack trace ONLY in development (never in production)
    ...(process.env.NODE_ENV !== 'production' && err.stack 
      ? { stack: err.stack.split('\n').slice(1).join('\n') } 
      : {})
  };

  res.status(statusCode).json(errorResponse);
};

module.exports = errorHandler;
```

**Explanation:** The conditional spread (`...`) adds the stack trace only when not in production—this is a security best practice. We always log the full error server-side because debugging requires visibility into what went wrong. The `NODE_ENV` check allows different behavior between development (verbose) and production (minimal). Express requires exactly 4 parameters for error middleware; omitting any parameter breaks the detection logic.

