## File 5: `src/routes/books.js`

```javascript
/**
 * Book management routes with full CRUD operations.
 * 
 * WHY SEPARATE ROUTE FILE? Keeping routes modular allows:
 * - Independent testing of route logic
 * - Easier scaling (add /authors, /genres routes later)
 * - Clear separation between routing and business logic
 */

const express = require('express');
const router = express.Router(); // Creates a standalone route handler
const { 
  getAllBooks, 
  getBookById, 
  createBook, 
  updateBook, 
  deleteBook 
} = require('../data/books');
const { ValidationError, NotFoundError } = require('../errors/CustomError');

// ============================================================================
// HELPER: Validate book data structure
// WHY SEPARATE FUNCTION? DRY principle—validation logic is reused across POST
// and PUT handlers. Centralizing it prevents inconsistencies.
// ============================================================================

/**
 * Validates required fields and types for book creation/update.
 * @param {Object} data - Book data to validate
 * @throws {ValidationError} If validation fails
 */
const validateBookData = (data) => {
  const errors = [];

  // Check required string fields
  if (!data.title || typeof data.title !== 'string') {
    errors.push('title is required and must be a string');
  }
  if (!data.author || typeof data.author !== 'string') {
    errors.push('author is required and must be a string');
  }

  // Check numeric fields with range validation
  if (typeof data.publishedYear !== 'number' || 
      !Number.isInteger(data.publishedYear) ||
      data.publishedYear < 0 || 
      data.publishedYear > new Date().getFullYear() + 1) {
    errors.push('publishedYear must be a valid year between 0 and current year+1');
  }

  // Check rating range (common constraint in book APIs)
  if (typeof data.rating !== 'number' || data.rating < 0 || data.rating > 5) {
    errors.push('rating must be a number between 0 and 5');
  }

  if (errors.length > 0) {
    throw new ValidationError(errors.join(', '));
  }
};

// ============================================================================
// GET /books - List all books with optional filtering
// 
// QUERY PARAMETERS:
//   ?genre=Fiction      - Filter by genre (case-insensitive)
//   ?author=Hawking     - Filter by author name substring
//   ?minRating=4.0      - Minimum rating threshold
//   ?publishedAfter=1900 - Filter books published after year
// 
// EXAMPLE CURL: curl "http://localhost:3000/books?genre=Fiction&minRating=4.5"
// ============================================================================

/**
 * Retrieves all books with optional filtering.
 * @route GET /books
 * @param {Object} req - Express request with query parameters
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function for error handling
 */
router.get('/books', (req, res, next) => {
  try {
    let result = getAllBooks();

    // Apply filters only if query parameters are provided
    const { genre, author, minRating, publishedAfter } = req.query;

    if (genre) {
      // Case-insensitive substring match for flexibility
      result = result.filter((book) => 
        book.genre.toLowerCase() === genre.toLowerCase()
      );
    }

    if (author) {
      // Substring match allows partial author names
      result = result.filter((book) => 
        book.author.toLowerCase().includes(author.toLowerCase())
      );
    }

    if (minRating) {
      const min = parseFloat(minRating);
      if (isNaN(min)) {
        throw new ValidationError('minRating must be a number');
      }
      result = result.filter((book) => book.rating >= min);
    }

    if (publishedAfter) {
      const year = parseInt(publishedAfter, 10);
      if (isNaN(year)) {
        throw new ValidationError('publishedAfter must be a number');
      }
      result = result.filter((book) => book.publishedYear > year);
    }

    // Return filtered results with count metadata
    res.json({
      success: true,
      count: result.length,
      data: result
    });
  } catch (error) {
    next(error); // Pass to global error handler
  }
});

// ============================================================================
// GET /books/:id - Get single book by ID
// 
// EXAMPLE CURL: curl "http://localhost:3000/books/1"
// ============================================================================

/**
 * Retrieves a single book by its numeric ID.
 * @route GET /books/:id
 * @param {Object} req - Express request with params.id
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function for error handling
 */
router.get('/books/:id', (req, res, next) => {
  try {
    // Parse and validate ID is a positive integer
    const id = parseInt(req.params.id, 10);
    if (isNaN(id) || id < 1) {
      throw new ValidationError('ID must be a positive integer');
    }

    const book = getBookById(id);
    if (!book) {
      // Throw NotFoundError instead of returning 404 manually—
      // this ensures consistent error shape across the API
      throw new NotFoundError('Book');
    }

    res.json({ success: true, data: book });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// POST /books - Create new book
// 
// REQUEST BODY EXAMPLE:
// {
//   "title": "1984",
//   "author": "George Orwell",
//   "genre": "Dystopian",
//   "publishedYear": 1949,
//   "rating": 4.7
// }
// 
// EXAMPLE CURL: curl -X POST http://localhost:3000/books \
//   -H "Content-Type: application/json" \
//   -d '{"title":"1984","author":"George Orwell","genre":"Dystopian","publishedYear":1949,"rating":4.7}'
// ============================================================================

/**
 * Creates a new book after validation.
 * @route POST /books
 * @param {Object} req - Express request with JSON body
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function for error handling
 */
router.post('/books', (req, res, next) => {
  try {
    // Validate all required fields before attempting creation
    validateBookData(req.body);

    const newBook = createBook(req.body);

    // 201 Created is the standard status for resource creation
    // Include Location header to help clients find the new resource
    res.status(201).json({ 
      success: true, 
      data: newBook,
      location: `/books/${newBook.id}`
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// PUT /books/:id - Update existing book (full replacement)
// 
// NOTE: We use PUT for full updates. For partial updates, PATCH would be used.
// This API uses PUT to keep validation simple—clients must send all fields.
// 
// EXAMPLE CURL: curl -X PUT http://localhost:3000/books/1 \
//   -H "Content-Type: application/json" \
//   -d '{"title":"The Great Gatsby","author":"F. Scott Fitzgerald","genre":"Fiction","publishedYear":1925,"rating":4.6}'
// ============================================================================

/**
 * Updates a book by ID with full replacement data.
 * @route PUT /books/:id
 * @param {Object} req - Express request with params.id and JSON body
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function for error handling
 */
router.put('/books/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id) || id < 1) {
      throw new ValidationError('ID must be a positive integer');
    }

    // Validate before attempting update
    validateBookData(req.body);

    const updatedBook = updateBook(id, req.body);
    if (!updatedBook) {
      throw new NotFoundError('Book');
    }

    // 200 OK for successful update (no content created)
    res.json({ success: true, data: updatedBook });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// DELETE /books/:id - Delete book by ID
// 
// EXAMPLE CURL: curl -X DELETE http://localhost:3000/books/1
// ============================================================================

/**
 * Deletes a book by ID.
 * @route DELETE /books/:id
 * @param {Object} req - Express request with params.id
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function for error handling
 */
router.delete('/books/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id) || id < 1) {
      throw new ValidationError('ID must be a positive integer');
    }

    const deleted = deleteBook(id);
    if (!deleted) {
      throw new NotFoundError('Book');
    }

    // 204 No Content is standard for successful deletions with no response body
    res.status(204).send();
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// GET /stats - Return statistics about the book collection
// 
// EXAMPLE CURL: curl "http://localhost:3000/stats"
// ============================================================================

/**
 * Calculates and returns aggregate statistics.
 * @route GET /stats
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object
 * @param {Function} next - Express next function for error handling
 */
router.get('/stats', (req, res, next) => {
  try {
    const allBooks = getAllBooks();

    if (allBooks.length === 0) {
      // Handle empty dataset gracefully
      return res.json({
        success: true,
        data: {
          totalBooks: 0,
          averageRating: 0,
          mostCommonGenre: null,
          booksByAuthor: {}
        }
      });
    }

    // Calculate average rating using reduce() for O(n) efficiency
    const averageRating = allBooks.reduce((sum, book) => sum + book.rating, 0) / allBooks.length;

    // Find most common genre using a frequency map
    const genreCounts = {};
    allBooks.forEach((book) => {
      genreCounts[book.genre] = (genreCounts[book.genre] || 0) + 1;
    });
    const mostCommonGenre = Object.entries(genreCounts)
      .sort((a, b) => b[1] - a[1])[0]?.[0] || null;

    // Count books per author
    const booksByAuthor = {};
    allBooks.forEach((book) => {
      booksByAuthor[book.author] = (booksByAuthor[book.author] || 0) + 1;
    });

    res.json({
      success: true,
      data: {
        totalBooks: allBooks.length,
        averageRating: parseFloat(averageRating.toFixed(2)), // Round to 2 decimals
        mostCommonGenre,
        booksByAuthor
      }
    });
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

**Explanation:** We use `try/catch` in every route handler because Express doesn't automatically catch synchronous errors in route functions. The `next(error)` pattern passes errors to our global middleware instead of handling them inline—this keeps routes focused on business logic. For the stats endpoint, we calculate everything in a single pass where possible (O(n) complexity). The `?.` optional chaining operator safely handles cases where `Object.entries()` might be empty. We return 204 for DELETE because HTTP spec says no response body should accompany successful deletions—this saves bandwidth and follows REST conventions.

