/**
 * Express application configuration.
 * 
 * WHY SEPARATE APP FROM SERVER? This allows:
 * - Testing the app without starting an HTTP server
 * - Clear separation between configuration and deployment
 * - Easier mocking in unit tests
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const errorHandler = require('./middleware/errorHandler');

const app = express();

// ============================================================================
// MIDDLEWARE CONFIGURATION
// 
// ORDER MATTERS: Middleware executes top-to-bottom. Body parsing must come
// BEFORE routes so req.body is available in route handlers.
// ============================================================================

/**
 * Parses JSON request bodies up to 10kb limit.
 * WHY LIMIT? Prevents denial-of-service attacks via massive payloads.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Parses URL-encoded bodies (for form submissions).
 * Not strictly needed for this JSON API but included for completeness.
 */
app.use(express.urlencoded({ extended: true }));

// ============================================================================
// ROUTE MOUNTING
// 
// WHY MOUNT AT '/api'? Namespacing prevents path collisions and makes it
// easy to version later (e.g., /api/v2/books).
// ============================================================================

app.use('/api', bookRoutes); // All book routes are under /api prefix

// ============================================================================
// HEALTH CHECK ENDPOINT
// 
// WHY INCLUDE? Essential for monitoring, load balancers, and Kubernetes probes.
// ============================================================================

/**
 * Simple health check to verify server is running.
 * @route GET /health
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// 
// MUST BE LAST: Placed after all routes so it catches errors from ANY route.
// Express uses the 4-parameter signature to identify error middleware.
// ============================================================================

app.use(errorHandler);

module.exports = app;
```

**Explanation:** The middleware order is critical: body parsers must run before routes access `req.body`. We namespace routes under `/api` because this allows future versioning (`/api/v2`) without breaking existing clients. The health check endpoint uses a simple JSON response because load balancers expect fast, lightweight responses. Error middleware is placed last because Express executes middleware in registration order—placing it earlier would prevent route handlers from running.

