## File 7: `src/server.js`

```javascript
/**
 * Server entry point.
 * 
 * WHY SEPARATE FROM APP? The app configuration (middleware, routes) is distinct
 * from the network listening logic. This separation allows:
 * - Testing the app without opening ports
 * - Graceful shutdown handling
 * - Environment-specific port selection
 */

const app = require('./app');

// Determine port with fallback for different environments
const PORT = process.env.PORT || 3000;

/**
 * Start the HTTP server and log startup information.
 */
const startServer = () => {
  const server = app.listen(PORT, () => {
    console.log(`Book API running on http://localhost:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log('\nTest endpoints:');
    console.log('  GET     http://localhost:${PORT}/api/books');
    console.log('  POST    http://localhost:${PORT}/api/books');
    console.log('  GET     http://localhost:${PORT}/api/stats');
    console.log('  GET     http://localhost:${PORT}/health');
  });

  // Graceful shutdown handling for production deployments
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Shutting down gracefully...`);
    server.close(() => {
      console.log('Server closed. Exiting process.');
      process.exit(0);
    });

    // Force close after 10 seconds to prevent hanging
    setTimeout(() => {
      console.error('Could not close connections in time. Forcing shutdown.');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', gracefulShutdown); // Kubernetes/docker termination signal
  process.on('SIGINT', gracefulShutdown);  // Ctrl+C manual termination
};

startServer();
```

**Explanation:** We use `process.exit()` codes intentionally: `0` for clean shutdown, `1` for forced shutdown after timeout. The graceful shutdown handler ensures in-flight requests complete before the server dies—critical for zero-downtime deployments. Signal handlers (`SIGTERM`, `SIGINT`) are standard across Unix-like systems and container orchestrators like Kubernetes.

