## File 2: `src/errors.js` — Custom Error Classes

```javascript
/**
 * src/errors.js
 *
 * This module defines custom error classes that extend JavaScript's built-in
 * Error class. Each subclass adds two things:
 *   1. A numeric HTTP status code (via the 'statusCode' property).
 *   2. Optional contextual metadata (e.g., which field failed validation).
 *
 * WHY custom errors instead of plain Error objects?
 *   - The error-handling middleware can inspect the error type to decide what
 *     HTTP status to send back without relying on string matching.
 *   - Clients receive structured JSON like { error: "Not Found", statusCode: 404 }
 *     rather than a generic 500 with no context.
 *   - It makes debugging easier: `err instanceof NotFoundError` is far more
 *     readable than checking err.message === 'Resource not found'.
 */

/**
 * Base class for all application-specific errors.
 *
 * Extends Error so that standard properties like .stack and .name are preserved.
 * We override the constructor to accept a message, an HTTP status code, and
 * optional metadata fields.
 */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable description of the error.
   * @param {number} statusCode - HTTP status code (e.g., 400, 404).
   * @param {object} [meta] - Optional extra data (field names, values, etc.).
   */
  constructor(message, statusCode, meta = {}) {
    // Call the parent Error constructor so .stack and .message are set correctly.
    super(message);

    // Capture the class name for debugging (e.g., "NotFoundError").
    this.name = this.constructor.name;

    // Attach the HTTP status code as a public property.
    this.statusCode = statusCode;

    // Attach any additional metadata passed in.
    this.meta = meta;

    // Preserve a clean stack trace by setting the constructor property.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Thrown when a requested resource does not exist.
 * Example: GET /books/999 when only books with IDs 1-5 exist.
 */
class NotFoundError extends AppError {
  /**
   * @param {string} [message] - Custom message; defaults to "Resource not found".
   * @param {object} [meta] - Optional metadata (e.g., { resource: 'book', id: 999 }).
   */
  constructor(message = "Resource not found", meta = {}) {
    // Merge default meta with any caller-provided meta.
    super(message, 404, { ...{ resource: "unknown" }, ...meta });
  }
}

/**
 * Thrown when client input fails validation.
 * Example: POST /books with a missing title or an invalid ISBN format.
 */
class ValidationError extends AppError {
  /**
   * @param {string} message - Description of what went wrong.
   * @param {object} meta - Should include 'field' indicating which input failed.
   */
  constructor(message, meta = {}) {
    super(message, 400, { ...{ field: null }, ...meta });
  }
}

/**
 * Thrown when a client tries to modify or delete a resource it doesn't own
 * (or in our simple case, when the ID is invalid).
 */
class UnauthorizedError extends AppError {
  constructor(message = "Unauthorized", meta = {}) {
    super(message, 401, meta);
  }
}

/**
 * Thrown for unhandled server-side failures.
 * This should rarely be used directly — prefer letting the error propagate
 * and catching it in a top-level middleware.
 */
class InternalError extends AppError {
  constructor(message = "Internal server error", meta = {}) {
    super(message, 500, meta);
  }
}

// Export all error classes so route handlers and middleware can import them.
module.exports = { AppError, NotFoundError, ValidationError, UnauthorizedError, InternalError };
```

