## File 3: `src/middleware/errorHandler.js` — Global Error Handler

```javascript
/**
 * src/middleware/errorHandler.js
 *
 * Express provides a special middleware signature for error handling:
 *   function (err, req, res, next) { ... }
 *
 * Notice the FOUR parameters. Express recognizes this by arity and routes
 * any thrown/called error here instead of treating it as a normal request handler.
 *
 * WHY a single global error handler?
 *   - Without it, every route would need its own try/catch + res.status().send()
 *     boilerplate, leading to duplicated code.
 *   - With it, we can centralize response formatting, logging, and security
 *     (e.g., never leaking stack traces to clients in production).
 *
 * HOW errors reach this middleware:
 *   1. A route handler calls next(err) explicitly.
 *   2. An async route handler throws an error (Express 4.x catches it automatically).
 *   3. Any middleware calls next(err).
 */

const { AppError } = require("../errors");

/**
 * Global error-handling middleware.
 *
 * @param {AppError} err - The error object (should be an instance of AppError or subclass).
 * @param {import('express').Request} req - The Express request object.
 * @param {import('express').Response} res - The Express response object.
 * @param {import('express').NextFunction} next - Unused but required by Express signature.
 */
function errorHandler(err, req, res, next) {
  // Log the full error (including stack) to the server console for debugging.
  // In production you might send this to a logging service instead.
  console.error(`[ERROR] ${err.name}: ${err.message}`);
  if (process.env.NODE_ENV !== "production" && err.stack) {
    console.error(err.stack);
  }

  // Determine the HTTP status code:
  //   - If it's our custom AppError, use its statusCode property.
  //   - Otherwise default to 500 (Internal Server Error).
  const statusCode = err instanceof AppError ? err.statusCode : 500;

  // Build a consistent JSON response body regardless of error type.
  const responseBody = {
    error: err.message,       // Human-readable message for the client.
    statusCode,               // Numeric status for programmatic handling.
  };

  // Only include meta fields in non-production environments so clients don't
  // see internal details (field names, database queries, etc.).
  if (process.env.NODE_ENV !== "production" && err.meta) {
    responseBody.meta = err.meta;
  }

  // Send the JSON response. Using res.json() automatically sets Content-Type: application/json.
  res.status(statusCode).json(responseBody);
}

module.exports = errorHandler;
```

