## File 4: `src/routes/books.js` — Book Route Handlers

```javascript
/**
 * src/routes/books.js
 *
 * This module defines all route handlers for the /books resource.
 *
 * DESIGN DECISIONS:
 *   - Each handler is a standalone async function. No class-based controllers
 *     are used to keep the example simple and focused on Express patterns.
 *   - We use `findById` as a helper rather than repeating `.find()` logic in
 *     every route — this reduces duplication and makes future refactoring easier.
 *   - Validation is done inline (checking required fields) so we can throw
 *     ValidationError with the specific failing field name.
 *
 * REST CONVENTIONS FOLLOWED:
 *   GET    /books          → 200 + array of books
 *   GET    /books/:id      → 200 + single book object
 *   POST   /books          → 201 + created book object (Location header)
 *   PUT    /books/:id      → 200 + updated book object
 *   DELETE /books/:id      → 204 (No Content — success with no body)
 */

const { NotFoundError, ValidationError } = require("../errors");

// ---------------------------------------------------------------------------
// In-Memory Data Store
// ---------------------------------------------------------------------------
//
// WHY an array instead of an object/map?
//   - Arrays preserve insertion order, which is useful for list endpoints.
//   - For a small educational dataset, O(n) linear search is perfectly fine.
//   - A Map would be faster for lookups but adds unnecessary complexity here.
//
// WHY not use a real database in this example?
//   - The route logic (CRUD operations) stays the same regardless of storage.
//   - Swapping `books` for a DB query is a one-line change per handler.
//   - It keeps the project runnable with just `npm install express`.
//
// Each book object has this shape:
//   {
//     id: number,          // Unique identifier (auto-incremented).
//     title: string,       // Book title (required).
//     author: string,      // Author name (required).
//     isbn: string,        // ISBN-10 or ISBN-13 (optional but recommended).
//     publishedYear: number, // Year of publication (optional).
//     genre: string,       // Book genre (optional).
//     createdAt: string,   // ISO timestamp of creation.
//     updatedAt: string    // ISO timestamp of last update.
//   }
const books = [
  {
    id: 1,
    title: "The Great Gatsby",
    author: "F. Scott Fitzgerald",
    isbn: "9780743273565",
    publishedYear: 1925,
    genre: "Fiction",
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z",
  },
  {
    id: 2,
    title: "To Kill a Mockingbird",
    author: "Harper Lee",
    isbn: "9780061120084",
    publishedYear: 1960,
    genre: "Fiction",
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z",
  },
  {
    id: 3,
    title: "1984",
    author: "George Orwell",
    isbn: "9780451524935",
    publishedYear: 1949,
    genre: "Dystopian",
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z",
  },
];

// Auto-incrementing ID counter. In a real app, the database would handle this.
let nextId = 4;

// ---------------------------------------------------------------------------
// Helper Functions
// ---------------------------------------------------------------------------

/**
 * Finds a book by its numeric ID.
 *
 * @param {number} id - The book's unique identifier.
 * @returns {object|null} The book object if found, null otherwise.
 */
function findById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Validates the required fields for creating or updating a book.
 *
 * @param {object} body - The request body to validate.
 * @param {string} operation - Either "create" or "update" (affects error messages).
 * @throws {ValidationError} If validation fails, with the failing field in meta.
 */
function validateBook(body, operation) {
  // Title is always required.
  if (!body.title || typeof body.title !== "string" || body.title.trim() === "") {
    throw new ValidationError(
      `${operation === "create" ? "Title is required" : "Title must be a non-empty string"}`,
      { field: "title" }
    );
  }

  // Author is always required.
  if (!body.author || typeof body.author !== "string" || body.author.trim() === "") {
    throw new ValidationError(
      `${operation === "create" ? "Author is required" : "Author must be a non-empty string"}`,
      { field: "author" }
    );
  }

  // If ISBN is provided, validate it's a string of reasonable length.
  if (body.isbn !== undefined && body.isbn !== null) {
    if (typeof body.isbn !== "string" || body.isbn.trim() === "") {
      throw new ValidationError("ISBN must be a non-empty string", { field: "isbn" });
    }
  }

  // If publishedYear is provided, it should be a positive integer.
  if (body.publishedYear !== undefined && body.publishedYear !== null) {
    const year = Number(body.publishedYear);
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      throw new ValidationError(
        `publishedYear must be a valid year (0-${new Date().getFullYear() + 1})`,
        { field: "publishedYear" }
      );
    }
  }
}

// ---------------------------------------------------------------------------
// Route Handlers
// ---------------------------------------------------------------------------

/**
 * GET /books
 *
 * Returns a JSON array of all books. Supports optional query parameters for
 * filtering by genre, author, or published year.
 *
 * Query parameter examples:
 *   GET /books?genre=Fiction          → only Fiction books
 *   GET /books?author=Orwell          → case-insensitive partial match on author
 *   GET /books?publishedYear=1949     → exact year match
 *   GET /books?genre=Fiction&author=Orwell  → combined filters (AND logic)
 *
 * @param {import('express').Request} req - Express request with query params.
 * @param {import('express').Response} res - Express response.
 */
function getAllBooks(req, res) {
  // Start with the full list — we'll apply filters below if any are present.
  let result = [...books];

  // Extract optional filter parameters from the query string.
  const { genre, author, publishedYear } = req.query;

  // Apply genre filter (case-insensitive exact match).
  if (genre) {
    result = result.filter((book) => book.genre?.toLowerCase() === genre.toLowerCase());
  }

  // Apply author filter (case-insensitive partial match — "orwell" matches "George Orwell").
  if (author) {
    result = result.filter((book) =>
      book.author?.toLowerCase().includes(author.toLowerCase())
    );
  }

  // Apply publishedYear filter (exact numeric match).
  if (publishedYear) {
    const year = Number(publishedYear);
    if (Number.isInteger(year)) {
      result = result.filter((book) => book.publishedYear === year);
    }
  }

  // Send the (possibly filtered) array as JSON with status 200.
  res.json({
    count: result.length,       // Include a count so clients know how many matched.
    data: result,               // Wrap in a 'data' key for consistent response shape.
  });
}

/**
 * GET /books/:id
 *
 * Returns a single book by its numeric ID.
 *
 * @param {import('express').Request} req - Express request with params.id.
 * @param {import('express').Response} res - Express response.
 * @throws {NotFoundError} If no book exists with the given ID.
 */
function getBookById(req, res) {
  // req.params are string values from the URL path; convert to number for comparison.
  const id = Number(req.params.id);

  // Look up the book using our helper.
  const book = findById(id);

  // If not found, throw a NotFoundError so the global error handler sends 404.
  if (!book) {
    throw new NotFoundError(`Book with ID ${id} not found`, { resource: "book", id });
  }

  res.json({ data: book });
}

/**
 * POST /books
 *
 * Creates a new book from the request body and returns it with status 201.
 * The response also includes a Location header pointing to the new resource,
 * which is a REST best practice (see RFC 7231 Section 7.1.2).
 *
 * Request body example:
 *   { "title": "Brave New World", "author": "Aldous Huxley", "genre": "Dystopian" }
 *
 * @param {import('express').Request} req - Express request with JSON body.
 * @param {import('express').Response} res - Express response.
 * @throws {ValidationError} If required fields are missing or invalid.
 */
function createBook(req, res) {
  // Validate the incoming data before touching the store.
  validateBook(req.body, "create");

  // Generate a new unique ID. In production, use a DB sequence or UUID.
  const id = nextId++;

  // Capture timestamps as ISO 8601 strings.
  const now = new Date().toISOString();

  // Build the new book object. We spread req.body to allow optional fields,
  // then override with our computed values (id, timestamps).
  const newBook = {
    id,
    title: req.body.title.trim(),           // Trim whitespace from user input.
    author: req.body.author.trim(),
    isbn: req.body.isbn ? req.body.isbn.trim() : null,
    publishedYear: req.body.publishedYear || null,
    genre: req.body.genre ? req.body.genre.trim() : null,
    createdAt: now,
    updatedAt: now,
  };

  // Add to our in-memory store.
  books.push(newBook);

  // Set the Location header so clients know where to find the new resource.
  res.location(`/books/${id}`);

  // Status 201 Created signals that a new resource was successfully created.
  res.status(201).json({ data: newBook });
}

/**
 * PUT /books/:id
 *
 * Fully replaces an existing book with the provided data. Fields not included
 * in the request body will be set to null (this is the semantics of PUT vs PATCH).
 *
 * Request body example:
 *   { "title": "1984 - Updated Edition", "author": "George Orwell" }
 *
 * @param {import('express').Request} req - Express request with params.id and JSON body.
 * @param {import('express').Response} res - Express response.
 * @throws {NotFoundError} If the book doesn't exist.
 * @throws {ValidationError} If required fields are missing or invalid.
 */
function updateBook(req, res) {
  const id = Number(req.params.id);
  const bookIndex = books.findIndex((book) => book.id === id);

  // Check existence before attempting update.
  if (bookIndex === -1) {
    throw new NotFoundError(`Book with ID ${id} not found`, { resource: "book", id });
  }

  // Validate the incoming data.
  validateBook(req.body, "update");

  // Build the updated book object. We keep existing values for fields not provided,
  // but required fields (title, author) must be present per validation.
  const updatedBook = {
    ...books[bookIndex],                    // Start with all existing fields.
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    isbn: req.body.isbn !== undefined ? (req.body.isbn ? req.body.isbn.trim() : null) : books[bookIndex].isbn,
    publishedYear: req.body.publishedYear !== undefined ? req.body.publishedYear : books[bookIndex].publishedYear,
    genre: req.body.genre !== undefined ? (req.body.genre ? req.body.genre.trim() : null) : books[bookIndex].genre,
    updatedAt: new Date().toISOString(),    // Always update the timestamp.
  };

  // Replace the old book in-place.
  books[bookIndex] = updatedBook;

  res.json({ data: updatedBook });
}

/**
 * DELETE /books/:id
 *
 * Removes a book from the store by its ID. Returns 204 No Content on success
 * (standard REST convention — no body needed for deletion confirmation).
 *
 * @param {import('express').Request} req - Express request with params.id.
 * @param {import('express').Response} res - Express response.
 * @throws {NotFoundError} If the book doesn't exist.
 */
function deleteBook(req, res) {
  const id = Number(req.params.id);
  const bookIndex = books.findIndex((book) => book.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError(`Book with ID ${id} not found`, { resource: "book", id });
  }

  // Remove the book from the array. splice mutates in-place and returns the removed element.
  books.splice(bookIndex, 1);

  // 204 No Content is the standard response for successful DELETE with no body.
  res.status(204).send();
}

// ---------------------------------------------------------------------------
// Export Route Handlers
// ---------------------------------------------------------------------------
module.exports = { getAllBooks, getBookById, createBook, updateBook, deleteBook };
