## File 5: `src/routes/stats.js` — Statistics Endpoint

```javascript
/**
 * src/routes/stats.js
 *
 * Provides aggregate statistics about the book collection. This is a read-only
 * endpoint that doesn't modify state, so it's placed in its own route file
 * for clarity (separation of concerns).
 *
 * GET /stats returns:
 *   - totalBooks: number of books in the store
 *   - genres: count of books per genre
 *   - authors: count of books per author
 *   - averagePublishedYear: mean year of publication (null if no books)
 *   - oldestBook: title and year of the earliest published book
 *   - newestBook: title and year of the most recently published book
 */

/**
 * GET /stats
 *
 * Computes and returns statistics about the current book collection.
 *
 * @param {import('express').Request} req - Express request (no params needed).
 * @param {import('express').Response} res - Express response.
 */
function getStats(req, res) {
  // Import the books array from the books route module.
  // In a larger app, this would come from a shared data service layer.
  const { books } = require("./books");

  // Guard against an empty collection for division-by-zero safety.
  if (books.length === 0) {
    return res.json({
      totalBooks: 0,
      genres: {},
      authors: {},
      averagePublishedYear: null,
      oldestBook: null,
      newestBook: null,
    });
  }

  // Compute genre counts using a reduce accumulator.
  const genres = books.reduce((acc, book) => {
    const genre = book.genre || "Unknown";
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Compute author counts similarly.
  const authors = books.reduce((acc, book) => {
    acc[book.author] = (acc[book.author] || 0) + 1;
    return acc;
  }, {});

  // Compute average published year (only for books that have one).
  const yearsWithData = books.filter((b) => b.publishedYear !== null && b.publishedYear !== undefined);
  const averagePublishedYear =
    yearsWithData.length > 0
      ? yearsWithData.reduce((sum, b) => sum + b.publishedYear, 0) / yearsWithData.length
      : null;

  // Find oldest and newest published books.
  const sortedByYear = [...books].sort((a, b) => {
    // Treat null/undefined years as infinity so they sort to the end.
    const yearA = a.publishedYear ?? Infinity;
    const yearB = b.publishedYear ?? Infinity;
    return yearA - yearB;
  });

  const oldestBook = sortedByYear[0]
    ? { title: sortedByYear[0].title, publishedYear: sortedByYear[0].publishedYear }
    : null;

  const newestBook = sortedByYear[sortedByYear.length - 1]
    ? { title: sortedByYear[sortedByYear.length - 1].title, publishedYear: sortedByYear[sortedByYear.length - 1].publishedYear }
    : null;

  res.json({
    totalBooks: books.length,
    genres,
    authors,
    averagePublishedYear: averagePublishedYear ? Math.round(averagePublishedYear * 100) / 100 : null,
    oldestBook,
    newestBook,
  });
}

module.exports = { getStats };
```

> **Note:** The `require("./books")` at the top of `getStats` creates a circular dependency since `books.js` doesn't require `stats.js`. In this small project it's harmless because Node caches module exports. In a larger codebase, you'd extract the `books` array into a shared `src/data.js` module to avoid this pattern entirely.

