## File 6: `src/app.js` — Express Application Setup

```javascript
/**
 * src/app.js
 *
 * This is where we assemble the Express application. It wires together:
 *   1. Built-in middleware (JSON body parsing).
 *   2. Our route definitions.
 *   3. The global error-handling middleware.
 *
 * WHY separate app.js from server.js?
 *   - app.js creates and configures the Express application object.
 *   - server.js only handles starting the HTTP server (listening on a port).
 *   - This separation makes testing easier: you can `require('./app')` in tests
 *     without triggering a network listener.
 */

const express = require("express");
const { getAllBooks, getBookById, createBook, updateBook, deleteBook } = require("./routes/books");
const { getStats } = require("./routes/stats");
const errorHandler = require("./middleware/errorHandler");

// Create the Express application instance.
const app = express();

// ---------------------------------------------------------------------------
// Middleware Configuration
// ---------------------------------------------------------------------------

/**
 * Built-in express.json() middleware parses incoming request bodies that have
 * Content-Type: application/json. Without this, req.body would be undefined.
 *
 * limit: "10kb" prevents clients from sending extremely large payloads that
 * could exhaust server memory (a simple DoS mitigation).
 */
app.use(express.json({ limit: "10kb" }));

// ---------------------------------------------------------------------------
// Request Logging Middleware (Development Only)
// ---------------------------------------------------------------------------
/**
 * Simple request logger that prints method, URL, and response time to the console.
 * This is useful for debugging but would be replaced by a proper logging library
 * (e.g., winston, pino) in production.
 */
app.use((req, res, next) => {
  const start = Date.now();
  // Attach an 'end' listener to the response so we can measure total time.
  res.on("finish", () => {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl} → ${res.statusCode} (${duration}ms)`);
  });
  next();
});

// ---------------------------------------------------------------------------
// Route Definitions
// ---------------------------------------------------------------------------

/**
 * GET /stats
 * Returns aggregate statistics about the book collection.
 */
app.get("/stats", getStats);

/**
 * GET /books
 * List all books with optional filtering via query parameters.
 *
 * Example: GET /books?genre=Fiction&author=Orwell
 */
app.get("/books", getAllBooks);

/**
 * GET /books/:id
 * Retrieve a single book by its numeric ID.
 *
 * Example: GET /books/1
 */
app.get("/books/:id", getBookById);

/**
 * POST /books
 * Create a new book from the JSON request body.
 *
 * Example body: { "title": "Brave New World", "author": "Aldous Huxley" }
 */
app.post("/books", createBook);

/**
 * PUT /books/:id
 * Fully replace an existing book's data.
 *
 * Example body: { "title": "1984 - Anniversary Edition", "author": "George Orwell" }
 */
app.put("/books/:id", updateBook);

/**
 * DELETE /books/:id
 * Remove a book by its ID. Returns 204 on success.
 */
app.delete("/books/:id", deleteBook);

// ---------------------------------------------------------------------------
// 404 Handler for Undefined Routes
// ---------------------------------------------------------------------------
/**
 * If no route matches the request URL, send a 404 response.
 * This must be defined AFTER all route definitions so Express checks them first.
 */
app.use((req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.originalUrl} not found`,
    statusCode: 404,
  });
});

// ---------------------------------------------------------------------------
// Global Error Handler (MUST be last middleware)
// ---------------------------------------------------------------------------
/**
 * Express only routes errors to middleware with 4 parameters (err, req, res, next).
 * Placing this at the end ensures it catches errors from any route or middleware.
 */
app.use(errorHandler);

module.exports = app;
```

