/**
 * src/server.js
 *
 * Minimal entry point that starts the HTTP server on a configurable port.
 * The default is 3000, but you can override it with the PORT environment variable.
 */

const app = require("./app");

// Determine the port: use PORT env var or fall back to 3000.
const PORT = process.env.PORT || 3000;

// Start listening. The callback logs the URL for easy discovery.
const server = app.listen(PORT, () => {
  console.log(`Book REST API running on http://localhost:${PORT}`);
  console.log(`Try: curl http://localhost:${PORT}/books`);
});

// Graceful shutdown: stop accepting new connections and close existing ones.
process.on("SIGTERM", () => {
  console.log("SIGTERM received. Shutting down gracefully...");
  server.close(() => {
    console.log("Server closed.");
    process.exit(0);
  });
});

module.exports = server;
```

