## Arquivo 2: `src/models/book.js`

```javascript
/**
 * ============================================================
 * MODEL: Livro (Armazenamento em Memória)
 * ============================================================
 *
 * POR QUE USAR UM ARRAY EM MEMÓRIA?
 * ---------------------------------
 * Para este exemplo educacional, optamos por um array em memória
 * ao invés de um banco de dados real. Isso permite que o código
 * se concentre nos conceitos de REST, roteamento e tratamento de
 * erros sem a complexidade adicional de configuração de BD.
 *
 * Em produção, você substituiria este módulo por uma camada de
 * acesso a dados (ORM como Sequelize/Prisma, ou queries SQL
 * diretas). A interface aqui (listar, buscar, criar, atualizar,
 * excluir) espelha operações CRUD comuns que qualquer repositório
 * real também forneceria.
 *
 * ESTRUTURA DO OBJETO LIVRO:
 * - id: número inteiro único, gerado automaticamente
 * - title: string obrigatória (título do livro)
 * - author: string obrigatória (autor)
 * - year: número inteiro opcional (ano de publicação)
 * - genre: string opcional (gênero literário)
 * - createdAt: timestamp ISO da criação
 * - updatedAt: timestamp ISO da última atualização
 */

// Array que armazena todos os livros em memória.
// Escolhemos array ao invés de objeto/map porque:
// 1. A ordem de inserção é preservada (útil para listagem)
// 2. É mais simples de iterar e filtrar para este exemplo
// 3. Em produção, um banco relacional também usa linhas ordenadas
const books = [];

/**
 * Contador interno para gerar IDs únicos sequenciais.
 * Usamos uma variável closure ao invés de Date.now() ou UUIDs
 * porque:
 * - IDs sequenciais são mais legíveis em exemplos educacionais
 * - Evitam colisões sem necessidade de bibliotecas externas
 * - Simulam o comportamento de AUTO_INCREMENT de bancos SQL
 */
let nextId = 1;

/**
 * Classe personalizada para erros de validação.
 * Herda de Error para manter compatibilidade com o stack trace
 * nativo do Node.js, mas adiciona um campo `statusCode` que
 * permite ao middleware de erro retornar o código HTTP correto.
 *
 * Padrão escolhido: Classes de erro customizadas são preferíveis
 * a lançar strings ou objetos genéricos porque:
 * - Dão semântica clara ao tipo de erro
 * - Permitem tratamento diferenciado no middleware
 * - São auto-documentadas pelo nome da classe
 */
class ValidationError extends Error {
  /**
   * @param {string} message - Descrição do erro de validação
   * @param {number} statusCode - Código HTTP a ser retornado (padrão: 400)
   */
  constructor(message, statusCode = 400) {
    super(message);
    this.statusCode = statusCode;
    // Garante que o nome da classe apareça corretamente no stack trace
    Object.setPrototypeOf(this, ValidationError.prototype);
  }
}

/**
 * Classe para erros de recurso não encontrado.
 * Separamos NotFoundError de outros erros porque:
 * - O código HTTP correto é 404 (não 500)
 * - Permite ao middleware retornar resposta consistente
 * - Diferencia "recurso inexistente" de "erro do servidor"
 */
class NotFoundError extends Error {
  constructor(message, statusCode = 404) {
    super(message);
    this.statusCode = statusCode;
    Object.setPrototypeOf(this, NotFoundError.prototype);
  }
}

/**
 * Classe para erros de recurso já existente.
 * Usada quando um cliente tenta criar um livro com ID duplicado.
 * O código 409 (Conflict) é a convenção REST para este cenário.
 */
class ConflictError extends Error {
  constructor(message, statusCode = 409) {
    super(message);
    this.statusCode = statusCode;
    Object.setPrototypeOf(this, ConflictError.prototype);
  }
}

// ============================================================
// FUNÇÕES CRUD (Create, Read, Update, Delete)
// ============================================================

/**
 * Retorna todos os livros armazenados.
 *
 * Em uma implementação real com banco de dados, aqui adicionaríamos
 * suporte a paginação (limit/offset), ordenação e filtragem no nível
 * da query SQL. Para o array em memória, usamos spread operator (...)
 * para retornar uma cópia do array, evitando que chamadores externos
 * modifiquem o estado interno diretamente.
 *
 * @returns {Array<Object>} Lista de todos os livros
 */
function getAllBooks() {
  return [...books];
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * Usamos Array.prototype.find() ao invés de for loop porque:
 * - É mais conciso e expressivo (funcional vs imperativo)
 * - Para arrays pequenos (exemplo educacional), a diferença de
 *   performance é irrelevante
 * - Em produção com BD, esta função seria substituída por uma query
 *   como `SELECT * FROM books WHERE id = ?`
 *
 * @param {number} id - ID numérico do livro
 * @returns {Object|null} O livro encontrado ou null se não existir
 */
function getBookById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Cria um novo livro no array.
 *
 * Padrão async/await escolhido: Embora esta operação seja síncrona
 * (array.push), mantemos a assinatura assíncrona para que o código
 * possa ser facilmente migrado para uma implementação com banco de
 * dados sem alterar as rotas que chamam esta função. Isso segue o
 * princípio de "preparação para evolução" — escreva código que
 * cresce naturalmente de exemplo educacional para produção.
 *
 * @param {Object} bookData - Dados do novo livro
 * @param {string} bookData.title - Título (obrigatório)
 * @param {string} bookData.author - Autor (obrigatório)
 * @param {number} [bookData.year] - Ano de publicação (opcional)
 * @param {string} [bookData.genre] - Gênero literário (opcional)
 * @returns {Promise<Object>} O livro criado com ID e timestamps
 */
async function createBook(bookData) {
  const newBook = {
    id: nextId++, // Incrementa após atribuição (pré-incremento seria errado aqui)
    title: bookData.title,
    author: bookData.author,
    year: bookData.year || null,
    genre: bookData.genre || null,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  books.push(newBook);
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * Usamos Object.assign() para fazer merge parcial dos campos:
 * - Se o cliente enviar apenas `title`, os outros campos são preservados
 * - Isso segue o princípio de PUT semântico (atualização completa) vs
 *   PATCH (parcial). Para este exemplo, tratamos PUT como atualização
 *   parcial para maior flexibilidade educacional.
 *
 * @param {number} id - ID do livro a atualizar
 * @param {Object} updates - Campos a atualizar
 * @returns {Promise<Object>} O livro atualizado
 * @throws {NotFoundError} Se o livro com o ID não existir
 */
async function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    // Lançamos NotFoundError ao invés de retornar null porque:
    // 1. As rotas podem capturar a exceção e formatar a resposta HTTP
    // 2. Mantém o fluxo de erro consistente com outras funções do módulo
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  // Atualiza apenas os campos fornecidos (merge parcial)
  books[index] = {
    ...books[index], // Preserva todos os campos existentes
    ...updates,      // Sobrescreve com os novos valores
    updatedAt: new Date().toISOString(), // Sempre atualiza o timestamp
  };

  return books[index];
}

/**
 * Exclui um livro pelo ID.
 *
 * Usamos splice() ao invés de filter() porque:
 * - splice() modifica o array original in-place (mais eficiente)
 * - Para arrays pequenos, a diferença é insignificante, mas em
 *   produção com BD, seria equivalente a `DELETE FROM books WHERE id = ?`
 *
 * @param {number} id - ID do livro a excluir
 * @returns {Promise<boolean>} true se excluído, false se não encontrado
 * @throws {NotFoundError} Se o livro com o ID não existir
 */
async function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  books.splice(index, 1);
  return true;
}

/**
 * Retorna estatísticas agregadas sobre os livros.
 *
 * Usamos reduce() para calcular múltiplas métricas em uma única
 * iteração (O(n) ao invés de O(n) × k operações separadas).
 * Isso demonstra um padrão útil para aggregações eficientes.
 *
 * @returns {Object} Estatísticas: total, por gênero, média de anos
 */
function getStats() {
  const total = books.length;

  // Agrupa livros por gênero usando reduce — padrão funcional eficiente
  const byGenre = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Calcula média de anos de publicação (ignorando livros sem ano)
  const booksWithYear = books.filter((b) => b.year !== null && b.year !== undefined);
  const avgYear =
    booksWithYear.length > 0
      ? Math.round(
          booksWithYear.reduce((sum, b) => sum + b.year, 0) / booksWithYear.length,
          1
        )
      : null;

  return {
    total,
    byGenre,
    avgPublicationYear: avgYear,
    oldestBook:
      booksWithYear.length > 0
        ? Math.min(...booksWithYear.map((b) => b.year))
        : null,
    newestBook:
      booksWithYear.length > 0
        ? Math.max(...booksWithYear.map((b) => b.year))
        : null,
  };
}

/**
 * Busca livros com filtragem por título, autor e gênero.
 *
 * Esta função demonstra como implementar filtragem em memória:
 * - Cada parâmetro é opcional (se não fornecido, não filtra)
 * - A busca por título/autor é case-insensitive (tolerante a maiúsculas)
 * - Em produção, isso seria substituído por cláusulas WHERE no SQL
 *
 * @param {Object} filters - Filtros de pesquisa
 * @param {string} [filters.title] - Buscar por substring no título
 * @param {string} [filters.author] - Buscar por substring no autor
 * @param {string} [filters.genre] - Filtrar por gênero exato
 * @returns {Array<Object>} Lista de livros filtrados
 */
function searchBooks({ title, author, genre } = {}) {
  return books.filter((book) => {
    // Se nenhum filtro foi fornecido, retorna todos (comportamento padrão)
    const matchesTitle = !title || book.title.toLowerCase().includes(title.toLowerCase());
    const matchesAuthor = !author || book.author.toLowerCase().includes(author.toLowerCase());
    const matchesGenre = !genre || book.genre === genre;
    return matchesTitle && matchesAuthor && matchesGenre;
  });
}

// ============================================================
// EXPORTAÇÃO DOS MÓDULOS
// ============================================================
// Usamos exports nominais ao invés de module.exports = {} porque:
// - Facilita o tree-shaking em bundlers modernos
// - Torna mais claro quais funções estão sendo exportadas
// - É a convenção preferida pela maioria dos projetos Node.js atuais
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
  searchBooks,
  ValidationError,
  NotFoundError,
  ConflictError,
};
```

