## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE: Tratamento Centralizado de Erros
 * ============================================================
 *
 * POR QUE UM MIDDLEWARE DE ERRO?
 * ------------------------------
 * Em vez de tratar erros em cada rota individualmente (o que levaria
 * a código repetido e inconsistente), usamos um middleware de erro
 * centralizado. O Express reconhece middlewares de erro pela assinatura
 * especial: (err, req, res, next) => ...
 *
 * Este middleware captura:
 * 1. Erros lançados explicitamente nas rotas (try/catch + next(err))
 * 2. Erros de validação (ValidationError → 400)
 * 3. Recursos não encontrados (NotFoundError → 404)
 * 4. Conflitos de dados (ConflictError → 409)
 * 5. Erros inesperados do servidor (500 com mensagem genérica)
 *
 * PADRÃO DE RESPOSTA JSON CONSISTENTE:
 * Todas as respostas de erro seguem o formato:
 * { error: { message: "...", statusCode: NNN } }
 * Isso permite que consumidores da API tratem erros de forma uniforme.
 */

/**
 * Middleware de tratamento de erros para a aplicação Express.
 *
 * @param {Error} err - O erro capturado
 * @param {import('express').Request} req - Objeto de requisição Express
 * @param {import('express').Response} res - Objeto de resposta Express
 * @param {import('express').NextFunction} next - Função para passar ao próximo middleware
 */
function errorHandler(err, req, res, next) {
  // Determina o código de status com base no tipo do erro
  const statusCode = err.statusCode || 500;

  // Em produção, NUNCA exponha a mensagem original do erro ao cliente:
  // - Pode vazar informações sensíveis do servidor (stack traces, paths)
  // - Pode revelar detalhes da implementação interna
  // Para este exemplo educacional, mantemos a mensagem para fins didáticos,
  // mas em produção use: message: 'Erro interno do servidor'
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: {
      message: isProduction && statusCode >= 500
        ? 'Erro interno do servidor'
        : err.message,
      statusCode,
      // Em desenvolvimento, incluímos o stack trace para facilitar debugging
      ...( !isProduction && err.stack ? { stack: err.stack } : {}),
    },
  });
}

/**
 * Middleware para capturar erros de rotas assíncronas.
 *
 * PROBLEMA QUE RESOLVE:
 * Express não captura automaticamente rejeições de Promises em handlers
 * assíncronos. Se um async handler lança um erro, a Promise fica
 * "unhandled rejection" e o cliente nunca recebe resposta.
 *
 * SOLUÇÃO: Envolver cada handler com uma função que captura erros
 * e os passa para next(err), permitindo que o middleware de erro
 * centralizado trate tudo uniformemente.
 *
 * @param {Function} fn - Handler assíncrono Express
 * @returns {Function} Handler envolvido com tratamento de erro
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    // Chamamos a função original e capturamos qualquer rejeição
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

module.exports = { errorHandler, asyncHandler };
```

