## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================
 * ROTAS: Gerenciamento de Livros (RESTful)
 * ============================================================
 *
 * CONVENÇÕES REST ESCOLHIDAS:
 * ---------------------------
 * 1. URLs usam substantivos no plural (/books), não verbos
 *    - Correto: GET /books, POST /books
 *    - Errado: GET /getBooks, POST /createBook
 *    Razão: REST trata recursos como entidades nomeáveis; ações são
 *    determinadas pelo método HTTP, não pela URL.
 *
 * 2. Métodos HTTP semânticos:
 *    - GET: leitura (seguro, idempotente)
 *    - POST: criação (não idempotente — criar dois iguais gera dois recursos)
 *    - PUT: atualização completa/substituição (idempotente)
 *    - DELETE: remoção (idempotente — excluir duas vezes é igual a uma)
 *
 * 3. Códigos HTTP apropriados:
 *    - 200 OK: sucesso em GET/PUT
 *    - 201 Created: sucesso em POST (com Location header)
 *    - 204 No Content: sucesso em DELETE (sem corpo de resposta)
 *    - 400 Bad Request: validação falhou
 *    - 404 Not Found: recurso não existe
 *    - 409 Conflict: violação de restrição de negócio
 *    - 500 Internal Server Error: erro inesperado
 *
 * 4. Filtros via query parameters (?title=...&author=...)
 *    - Segue a convenção REST de usar query strings para filtros
 *    - Mantém a URL do recurso limpa (/books)
 */

const express = require('express');
const router = express.Router();

// Importamos o modelo e os middlewares necessários
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
  searchBooks,
  ValidationError,
  NotFoundError,
} = require('../models/book');
const { asyncHandler } = require('../middleware/errorHandler');

// ============================================================
// GET /books — Listar todos os livros (com filtragem opcional)
// ============================================================
/**
 * Lista todos os livros com suporte a filtragem via query parameters.
 *
 * Filtros disponíveis (todos opcionais):
 * - ?title=javascript → busca por substring no título (case-insensitive)
 * - ?author=tolkien  → busca por substring no autor
 * - ?genre=ficção    → filtro exato por gênero
 *
 * Exemplos de uso:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?title=javascript"
 *   curl "http://localhost:3000/books?author=tolkien&genre=ficção"
 *
 * @route GET /books
 * @access Public
 * @query {string} [title] - Substring para buscar no título
 * @query {string} [author] - Substring para buscar no autor
 * @query {string} [genre] - Gênero exato para filtrar
 * @returns {200} Array de livros
 * @returns {400} Erro de validação se parâmetros forem inválidos
 */
router.get(
  '/books',
  asyncHandler(async (req, res) => {
    // Extraímos os filtros dos query parameters
    const { title, author, genre } = req.query;

    // Se nenhum filtro foi fornecido, retornamos todos os livros
    if (!title && !author && !genre) {
      return res.json(getAllBooks());
    }

    // Aplicamos a busca com filtros
    const results = searchBooks({ title, author, genre });
    return res.json(results);
  })
);

// ============================================================
// GET /books/stats — Estatísticas dos livros
// ============================================================
/**
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * Esta rota demonstra um endpoint que não é estritamente CRUD,
 * mas sim uma operação de aggregação/relatório. Em REST, é comum
 * ter sub-recursos como este para operações derivadas.
 *
 * Exemplos de uso:
 *   curl http://localhost:3000/books/stats
 *
 * @route GET /books/stats
 * @access Public
 * @returns {200} Objeto com estatísticas do acervo
 */
router.get(
  '/books/stats',
  asyncHandler(async (req, res) => {
    const stats = getStats();
    return res.json(stats);
  })
);

// ============================================================
// GET /books/:id — Obter um livro pelo ID
// ============================================================
/**
 * Busca um único livro pelo seu identificador numérico.
 *
 * O parâmetro :id é extraído do req.params pelo Express automaticamente.
 * Convertimos para Number() porque params vêm sempre como string.
 *
 * Exemplos de uso:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → 404
 *
 * @route GET /books/:id
 * @access Public
 * @param {number} id - ID numérico do livro (na URL)
 * @returns {200} Objeto do livro encontrado
 * @returns {400} Erro se o ID não for um número válido
 * @returns {404} Erro se o livro não existir
 */
router.get(
  '/books/:id',
  asyncHandler(async (req, res) => {
    // Convertimos para número e validamos
    const id = Number(req.params.id);

    if (isNaN(id)) {
      throw new ValidationError('ID deve ser um número válido');
    }

    const book = getBookById(id);

    if (!book) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado`);
    }

    return res.json(book);
  })
);

// ============================================================
// POST /books — Criar um novo livro
// ============================================================
/**
 * Cria um novo livro no sistema.
 *
 * Padrão async/await nas rotas: Escolhemos esta abordagem porque:
 * - É mais legível que encadeamento de .then() (evita "callback hell")
 * - Permite uso de try/catch tradicional, facilitando o debugging
 * - É o padrão moderno do ecossistema Node.js (recomendado pela docs oficial)
 *
 * O asyncHandler wrapper garante que erros sejam capturados e passados
 * para o middleware de erro centralizado.
 *
 * Exemplos de uso:
 *   curl -X POST http://localhost:3000/books \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
 *
 * @route POST /books
 * @access Public
 * @body {string} title - Título do livro (obrigatório, mínimo 1 caractere)
 * @body {string} author - Autor do livro (obrigatório, mínimo 1 caractere)
 * @body {number} [year] - Ano de publicação (opcional, deve ser positivo)
 * @body {string} [genre] - Gênero literário (opcional)
 * @returns {201} Livro criado com seus dados completos
 * @returns {400} Erro de validação se campos obrigatórios faltarem
 */
router.post(
  '/books',
  asyncHandler(async (req, res) => {
    const { title, author, year, genre } = req.body;

    // Validação dos campos obrigatórios
    if (!title || typeof title !== 'string' || title.trim().length === 0) {
      throw new ValidationError('O campo "title" é obrigatório e deve ser uma string não vazia');
    }

    if (!author || typeof author !== 'string' || author.trim().length === 0) {
      throw new ValidationError('O campo "author" é obrigatório e deve ser uma string não vazia');
    }

    // Validação opcional do ano (se fornecido, deve ser um número positivo)
    if (year !== undefined && year !== null) {
      const yearNum = Number(year);
      if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
        throw new ValidationError('O campo "year" deve ser um número válido entre 0 e o ano atual');
      }
    }

    // Criamos o livro passando apenas os campos válidos
    const newBook = await createBook({
      title: title.trim(),
      author: author.trim(),
      year: year !== undefined ? Number(year) : null,
      genre: genre || null,
    });

    // 201 Created + header Location indica o URI do recurso criado
    // Isso segue a convenção REST para criação de recursos
    res.status(201).header('Location', `/books/${newBook.id}`).json(newBook);
  })
);

// ============================================================
// PUT /books/:id — Atualizar um livro existente
// ============================================================
/**
 * Atualiza os dados de um livro existente.
 *
 * PUT vs PATCH: Tecnicamente, PUT deveria substituir o recurso inteiro,
 * mas para este exemplo educacional tratamos como atualização parcial
 * (mais flexível). Em produção, você poderia implementar ambos:
 * - PUT: requer todos os campos obrigatórios
 * - PATCH: atualiza apenas os campos fornecidos
 *
 * Exemplos de uso:
 *   curl -X PUT http://localhost:3000/books/1 \
 *     -H "Content-Type: application/json" \
 *     -d '{"title":"Novo Título","year":2024}'
 *
 * @route PUT /books/:id
 * @access Public
 * @param {number} id - ID do livro a atualizar
 * @body {string} [title] - Novo título
 * @body {string} [author] - Novo autor
 * @body {number} [year] - Novo ano de publicação
 * @body {string} [genre] - Novo gênero
 * @returns {200} Livro atualizado
 * @returns {400} Erro de validação
 * @returns {404} Erro se o livro não existir
 */
router.put(
  '/books/:id',
  asyncHandler(async (req, res) => {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      throw new ValidationError('ID deve ser um número válido');
    }

    // Verifica se o livro existe antes de atualizar
    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError(`Livro com ID ${id} não encontrado`);
    }

    // Montamos os dados de atualização (apenas campos fornecidos e válidos)
    const updates = {};

    if (req.body.title !== undefined) {
      if (typeof req.body.title !== 'string' || req.body.title.trim().length === 0) {
        throw new ValidationError('O campo "title" deve ser uma string não vazia');
      }
      updates.title = req.body.title.trim();
    }

    if (req.body.author !== undefined) {
      if (typeof req.body.author !== 'string' || req.body.author.trim().length === 0) {
        throw new ValidationError('O campo "author" deve ser uma string não vazia');
      }
      updates.author = req.body.author.trim();
    }

    if (req.body.year !== undefined) {
      const yearNum = Number(req.body.year);
      if (isNaN(yearNum) || yearNum < 0) {
        throw new ValidationError('O campo "year" deve ser um número positivo');
      }
      updates.year = yearNum;
    }

    if (req.body.genre !== undefined) {
      updates.genre = req.body.genre;
    }

    // Se nenhum campo válido foi fornecido, retornamos o livro atual sem alterações
    if (Object.keys(updates).length === 0) {
      return res.json(existingBook);
    }

    const updatedBook = await updateBook(id, updates);
    return res.json(updatedBook);
  })
);

// ============================================================
// DELETE /books/:id — Excluir um livro
// ============================================================
/**
 * Exclui permanentemente um livro pelo ID.
 *
 * Retornamos 204 No Content (sem corpo) porque:
 * - Não há informação útil para retornar após exclusão
 * - Segue a convenção REST para operações DELETE bem-sucedidas
 * - Reduz o tamanho da resposta (melhor performance)
 *
 * Exemplos de uso:
 *   curl -X DELETE http://localhost:3000/books/1
 *   curl -X DELETE http://localhost:3000/books/999  → 404
 *
 * @route DELETE /books/:id
 * @access Public
 * @param {number} id - ID do livro a excluir
 * @returns {204} Sucesso (sem conteúdo)
 * @returns {404} Erro se o livro não existir
 */
router.delete(
  '/books/:id',
  asyncHandler(async (req, res) => {
    const id = Number(req.params.id);

    if (isNaN(id)) {
      throw new ValidationError('ID deve ser um número válido');
    }

    await deleteBook(id);

    // 204 No Content: sucesso sem corpo de resposta
    res.status(204).end();
  })
);

module.exports = router;
```

