```javascript
/**
 * ============================================================
 * APP PRINCIPAL: Configuração e Inicialização do Servidor Express
 * ============================================================
 *
 * ESTRUTURA DE MIDDLEWARE (ordem importa!):
 * -----------------------------------------
 * 1. body-parser → parseia JSON do corpo das requisições
 * 2. Roteadores → encaminha para as rotas corretas
 * 3. Middleware de erro → captura e trata erros (DEVE ser o último)
 *
 * A ordem é crítica porque o Express executa middlewares sequencialmente.
 * O middleware de erro deve sempre vir por último para capturar erros
 * de qualquer middleware anterior.
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');

// Cria a aplicação Express
const app = express();

// ============================================================
// MIDDLEWARE: Parse do corpo das requisições
// ============================================================
/**
 * express.json() parseia o corpo de requisições com Content-Type: application/json.
 * Sem este middleware, req.body seria undefined e não poderíamos acessar
 * os dados enviados pelo cliente em POST/PUT/PATCH.
 *
 * limit: '10kb' previne requisições excessivamente grandes (segurança).
 */
app.use(express.json({ limit: '10kb' }));

// ============================================================
// MIDDLEWARE: Logging básico de requisições
// ============================================================
/**
 * Middleware simples de logging que imprime no console:
 * - Método HTTP (GET, POST, etc.)
 * - URL solicitada
 * - Timestamp da requisição
 *
 * Em produção, substituiríamos por um logger profissional como Winston ou Pino.
 */
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.url}`);
  next(); // Passa para o próximo middleware/rota
});

// ============================================================
// ROTEAMENTO
// ============================================================
/**
 * Aplicamos as rotas de livros no prefixo /books.
 * Isso significa que todas as rotas definidas em books.js
 * serão acessíveis sob /books (ex: GET /books, POST /books/:id).
 *
 * O router é um middleware Express em si, então podemos usá-lo
 * com app.use() para montar a hierarquia de rotas.
 */
app.use('/books', bookRoutes);

// ============================================================
// ROTA DE HEALTH CHECK (Bônus)
// ============================================================
/**
 * Endpoint simples para verificar se o servidor está respondendo.
 * Útil para monitoramento, load balancers e testes de integridade.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ============================================================
// ROTA 404 PARA RECURSOS NÃO ENCONTRADOS
// ============================================================
/**
 * Middleware que captura requisições para rotas não definidas.
 * Retornamos 404 com mensagem clara ao invés de deixar o Express
 * retornar sua resposta padrão (que pode vazar informações).
 */
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: `Rota ${req.method} ${req.url} não encontrada`,
      statusCode: 404,
    },
  });
});

// ============================================================
// MIDDLEWARE DE ERRO (SEMPRE O ÚLTIMO!)
// ============================================================
/**
 * Registramos o middleware de erro por último.
 * Express identifica middlewares de erro pela assinatura de 4 parâmetros.
 * Este middleware captura erros de TODOS os middlewares e rotas anteriores.
 */
app.use(errorHandler);

// ============================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`📚 API de Livros rodando em http://localhost:${PORT}`);
  console.log(`📖 Endpoints disponíveis:`);
  console.log(`   GET    /books          — Listar todos os livros`);
  console.log(`   GET    /books/stats    — Estatísticas do acervo`);
  console.log(`   GET    /books/:id      — Obter livro por ID`);
  console.log(`   POST   /books          — Criar novo livro`);
  console.log(`   PUT    /books/:id      — Atualizar livro`);
  console.log(`   DELETE /books/:id      — Excluir livro`);
  console.log(`   GET    /health         — Health check`);
});

module.exports = app;
```

