## File 2: `src/errors/customErrors.js`

```javascript
/**
 * ============================================================================
 * CUSTOM ERROR CLASSES
 * ============================================================================
 *
 * WHY custom error classes?
 *   JavaScript's built-in Error class is generic — it doesn't carry HTTP status
 *   codes, error codes, or additional metadata. By extending Error and adding
 *   properties like `statusCode`, `isOperational`, and `errorType`, we create
 *   errors that the middleware can interpret automatically. This follows the
 *   "fail fast" principle: every error knows exactly how to respond before it
 *   reaches the client.
 *
 * PATTERN used: Class extension with property augmentation.
 *   We extend Error (so instanceof checks still work) and add our own fields.
 */

/**
 * BaseError — The foundation for all custom errors in this API.
 *
 * @extends {Error}
 */
class BaseError extends Error {
  /**
   * @param {string} message — Human-readable error description.
   * @param {number} statusCode — HTTP status code (e.g., 400, 404).
   * @param {string} errorType — Machine-readable error identifier.
   */
  constructor(message, statusCode, errorType) {
    super(message);

    // Capture the stack trace at the point of instantiation for debugging.
    Error.captureStackTrace(this, this.constructor);

    // Standardize properties across all custom errors.
    this.statusCode = statusCode;
    this.isOperational = true;   // Marks as a known, expected error (not a bug).
    this.errorType = errorType;  // e.g., "NOT_FOUND", "VALIDATION_ERROR"
  }

  /**
   * toJSON — Serializes the error into a clean JSON response shape.
   *
   * WHY override toJSON? Express's JSON.stringify will call this automatically,
   * ensuring every error response has a consistent structure: { message, code }.
   */
  toJSON() {
    return {
      message: this.message,
      code: this.errorType,
    };
  }
}

/**
 * NotFoundError — Returned when a requested resource does not exist.
 *
 * EXAMPLE: GET /books/999 when only books with IDs 1-5 exist.
 */
class NotFoundError extends BaseError {
  /**
