/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE
 * ============================================================================
 *
 * WHY middleware for error handling?
 *   Express provides a special 4-argument middleware signature (err, req, res, next)
 *   that acts as a centralized catch-all. Instead of wrapping every route handler
 *   in try/catch, we let errors bubble up to this single point. This follows the
 *   "single responsibility" principle: routes handle business logic; middleware
 *   handles cross-cutting concerns like error formatting.
 *
 * PATTERN used: Express error-handling middleware with async wrapper.
 */

const { InternalError } = require('../errors/customErrors');

/**
 * errorHandler — Centralized Express error-handling middleware.
 *
 * This function is registered as the LAST middleware in the app, so it catches
 * all errors that weren't handled upstream. It inspects the error type and
 * responds with appropriate status codes and messages.
 *
 * @param {Error} err — The error object (must have `statusCode` property).
 * @param {import('express').Request} req — Express request object.
 * @param {import('express').Response} res — Express response object.
 * @param {import('express').NextFunction} next — Express next function.
 *
 * RESPONSE SHAPES:
 *   - Operational errors (4xx): Return { message, code } directly to client.
 *   - Non-operational errors (5xx): Return generic message; log full stack server-side.
 */
function errorHandler(err, req, res, next) {
  // Log the error for debugging. If it's non-operational, include the full stack.
  const shouldLogStack = !err.isOperational;
  if (shouldLogStack) {
    console.error(`[ERROR] ${err.errorType || 'UNKNOWN'}:`, err.message);
    console.error(err.stack);
  } else {
    // Operational errors are expected — log minimally to avoid noise.
    console.warn(`[WARN] ${err.errorType}: ${err.message}`);
  }

  // Determine the HTTP status code (default to 500 for unknown errors).
  const statusCode = err.statusCode || 500;

  // Build the response body based on error type.
  const responseBody = {
    message: err.message,
    code: err.errorType,
  };

  // Include field-level details for validation errors (helps clients fix input).
  if (err.details && Object.keys(err.details).length > 0) {
    responseBody.details = err.details;
  }

  // For non-operational errors, NEVER expose the real error message to clients.
  // This prevents leaking internal implementation details (stack traces, paths, etc.).
  if (!err.isOperational && statusCode === 500) {
    responseBody.message = 'An unexpected error occurred on the server.';
  }

  // Send the JSON response.
  res.status(statusCode).json(responseBody);
}

/**
 * asyncHandler — Wraps async route handlers to catch promise rejections.
 *
 * WHY? Express does NOT automatically catch rejected promises from async routes.
 * If an async handler throws, the error silently disappears and the client hangs.
 * This wrapper converts promise rejections into calls to next(err), which the
 * errorHandler middleware catches.
 *
 * PATTERN used: Higher-order function (HOF) that returns a wrapped handler.
 *
 * @param {Function} fn — Async route handler function.
 * @returns {Function} Wrapped Express route handler.
 */
function asyncHandler(fn) {
  return function (req, res, next) {
    // Call the original async function and catch any rejected promises.
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

module.exports = {
  errorHandler,
  asyncHandler,
};
```

> **Key design decisions:**
> - `asyncHandler` is critical — without it, every async route would need manual try/catch. This wrapper eliminates that boilerplate.
> - Non-operational errors return a generic message to clients but log the full stack server-side. This is a security best practice (CWE-209: Exposure of Error Message).
> - Validation errors include `details` so clients know exactly which fields need fixing.

