 */
function createBook(bookData) {
  const now = new Date();
  const newBook = {
    id: nextId++, // Auto-increment and advance the counter.
    title: bookData.title,
    author: bookData.author,
    genre: bookData.genre,
    year: bookData.year || null,
    rating: bookData.rating || null,
    isbn: bookData.isbn || null,
    createdAt: now,
    updatedAt: now,
  };

  books.push(newBook); // Add to the end of the array.
  return newBook;
