function updateBook(id, updates) {
  const bookIndex = books.findIndex((b) => b.id === id);
  if (bookIndex === -1) {
    throw new NotFoundError('Book', id);
  }

  // Merge existing data with updates; set updatedAt timestamp.
  const updatedBook = {
    ...books[bookIndex], // Spread existing properties first.
    ...updates,          // Override with new values.
    updatedAt: new Date(), // Always refresh the update timestamp.
  };

  books[bookIndex] = updatedBook; // Replace in-place (array mutation).
  return updatedBook;
}

