 *
 * @param {number} id — The book's unique identifier.
 * @returns {boolean} true if the book was found and deleted.
 * @throws {NotFoundError} If no book with the given ID exists.
 */
function deleteBook(id) {
  const bookIndex = books.findIndex((b) => b.id === id);
  if (bookIndex === -1) {
    throw new NotFoundError('Book', id);
  }

  books.splice(bookIndex, 1); // Remove one element at the found index.
  return true;
}

/**
 * getStats — Compute aggregate statistics across all books.
 *
 * @returns {Object} Statistics object containing counts, averages, and distributions.
 */
function getStats() {
  const totalBooks = books.length;

  // Calculate average rating (excluding null ratings).
  const ratedBooks = books.filter((b) => b.rating !== null);
  const averageRating =
    ratedBooks.length > 0
      ? parseFloat((ratedBooks.reduce((sum, b) => sum + b.rating, 0) / ratedBooks.length).toFixed(2))
      : null;

  // Count books by genre (case-insensitive grouping).
  const genreDistribution = {};
  books.forEach((book) => {
    const genre = book.genre || 'Unknown';
    genreDistribution[genre] = (genreDistribution[genre] || 0) + 1;
  });

  // Find the highest and lowest rated books.
  const highestRated =
    ratedBooks.length > 0
      ? ratedBooks.reduce((max, b) => (b.rating > max.rating ? b : max), ratedBooks[0])
      : null;
  const lowestRated =
    ratedBooks.length > 0
      ? ratedBooks.reduce((min, b) => (b.rating < min.rating ? b : min), ratedBooks[0])
      : null;

  return {
    totalBooks,
    averageRating,
    genreDistribution,
    highestRated: highestRated
      ? { id: highestRated.id, title: highestRated.title, rating: highestRated.rating }
      : null,
    lowestRated: lowestRated
      ? { id: lowestRated.id, title: lowestRated.title, rating: lowestRated.rating }
      : null,
  };
}

