  if (!body.title || typeof body.title !== 'string' || body.title.trim().length === 0) {
    errors.title = 'Title is required and must be a non-empty string.';
  } else if (body.title.length > 200) {
    errors.title = 'Title must not exceed 200 characters.';
  }

  // Author: required, string, between 1 and 100 characters.
  if (!body.author || typeof body.author !== 'string' || body.author.trim().length === 0) {
    errors.author = 'Author is required and must be a non-empty string.';
  } else if (body.author.length > 100) {
    errors.author = 'Author must not exceed 100 characters.';
  }

  // Genre: required, string.
  if (!body.genre || typeof body.genre !== 'string' || body.genre.trim().length === 0) {
    errors.genre = 'Genre is required and must be a non-empty string.';
  }

  // Rating (optional): if provided, must be a number between 0 and 5.
  if (body.rating !== undefined && body.rating !== null) {
    const rating = parseFloat(body.rating);
    if (isNaN(rating) || rating < 0 || rating > 5) {
      errors.rating = 'Rating must be a number between 0 and 5.';
    }
