## File 7: `src/app.js`

```javascript
/**
 * ============================================================================
 * APPLICATION ENTRY POINT
 * ============================================================================
 *
 * WHY this structure? Express apps follow a specific middleware registration
 * order that matters:
 *   1. Body parsing (so req.body is available)
 *   2. Route handlers (the actual API endpoints)
 *   3. Error handler (catches errors from any route)
 *
 * This ordering ensures errors are caught AFTER routes execute but BEFORE
 * the response is sent. If the error handler were registered before routes,
 * it would never see route-generated errors.
 */

const express = require('express');

// Import route modules.
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

// Import error-handling middleware.
const { errorHandler } = require('./middleware/errorHandler');

// Create the Express application instance.
const app = express();

/**
 * ============================================================================
 * MIDDLEWARE CONFIGURATION
 * ============================================================================
 */

// Parse JSON request bodies (e.g., POST/PUT with Content-Type: application/json).
// WHY? Without this, req.body would be undefined for JSON payloads.
app.use(express.json());

// Parse URL-encoded request bodies (for form submissions).
app.use(express.urlencoded({ extended: true }));

/**
 * ============================================================================
 * ROUTE REGISTRATION
 * ============================================================================
 * Mount route handlers at their respective paths. Express will automatically
 * strip the mount path when forwarding to the router's internal handlers.
 */
app.use('/books', bookRoutes); // All /books/* requests go to bookRoutes.
app.use('/stats', statsRoutes); // All /stats/* requests go to statsRoutes.

/**
 * ============================================================================
 * ROOT ENDPOINT
 * ============================================================================
 * A simple health-check endpoint that confirms the server is running.
 */
app.get('/', (req, res) => {
  res.json({
    message: 'Books REST API — Use /books and /stats endpoints.',
    endpoints: {
      books: '/books',
      stats: '/stats',
    },
  });
});

/**
 * ============================================================================
 * ERROR HANDLING (MUST BE LAST)
 * ============================================================================
 * Register the error handler AFTER all routes. Express checks middleware in
 * registration order, so this ensures every route error is caught here.
 * The 4-argument signature (err, req, res, next) marks it as an error handler.
 */
app.use(errorHandler);

/**
 * ============================================================================
 * SERVER STARTUP
 * ============================================================================
 */
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
  console.log(`API Documentation:`);
  console.log(`  GET    http://localhost:${PORT}/books          — List all books`);
  console.log(`  GET    http://localhost:${PORT}/books/:id      — Get single book`);
  console.log(`  POST   http://localhost:${PORT}/books          — Create new book`);
  console.log(`  PUT    http://localhost:${PORT}/books/:id      — Update book`);
  console.log(`  DELETE http://localhost:${PORT}/books/:id      — Delete book`);
  console.log(`  GET    http://localhost:${PORT}/stats          — Get statistics`);
});

module.exports = app;
```

> **Key design decisions:**
> - Middleware order is critical: body parsing → routes → error handler. Swapping this order breaks the API.
> - `app.listen()` uses an environment variable for PORT (allows deployment platforms to inject their own port).
> - The startup log prints all available endpoints for easy reference during development.

