/**
 * @fileoverview Classes de erro personalizadas para a API de livros.
 * 
 * Por que classes de erro personalizadas?
 * - Permitem tratamento específico por tipo de erro no middleware
 * - Facilitam o logging e resposta padronizada ao cliente
 * - Seguem o princípio de responsabilidade única (cada classe representa um erro)
 */

/**
 * Classe base para todos os erros da API.
 * 
 * @class
 * @extends Error
 */
class ApiError extends Error {
  /**
   * Cria uma instância de ApiError.
   * 
   * @param {string} message - Mensagem de erro descritiva
   * @param {number} statusCode - Código HTTP da resposta (padrão: 500)
   * @param {boolean} isOperational - Indica se o erro é esperado (true) ou bug (false)
   */
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;

    // Captura o stack trace para debugging
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro disparado quando um recurso não é encontrado.
 * 
 * @class
 * @extends ApiError
 */
class NotFoundError extends ApiError {
  /**
   * Cria um NotFoundError com status 404.
   * 
   * @param {string} resource - Nome do recurso (ex: "Livro", "Usuário")
   * @param {*} id - ID do recurso não encontrado
   */
  constructor(resource = 'Recurso', id) {
    const message = id 
      ? `${resource} com ID ${id} não encontrado`
      : `${resource} não encontrado`;
    super(message, 404, true);
    this.resource = resource;
    this.id = id;
  }
}

/**
 * Erro disparado quando há dados inválidos na requisição.
 * 
 * @class
 * @extends ApiError
 */
class ValidationError extends ApiError {
  /**
   * Cria um ValidationError com status 400.
   * 
   * @param {string} message - Mensagem de validação
   * @param {Object} [details] - Detalhes dos campos inválidos
   */
  constructor(message = 'Dados inválidos', details = {}) {
    super(message, 400, true);
    this.details = details;
  }
}

/**
 * Erro disparado quando o cliente tenta acessar recurso sem permissão.
 * 
 * @class
 * @extends ApiError
 */
class UnauthorizedError extends ApiError {
  constructor(message = 'Não autorizado') {
    super(message, 401, true);
  }
}

/**
 * Erro disparado quando há conflito de dados (ex: duplicação).
 * 
 * @class
 * @extends ApiError
 */
class ConflictError extends ApiError {
  /**
   * Cria um ConflictError com status 409.
   * 
   * @param {string} message - Mensagem de conflito
   */
  constructor(message = 'Conflito nos dados') {
    super(message, 409, true);
  }
}

module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  UnauthorizedError,
  ConflictError
};
```

> **Explicação:** As classes de erro personalizadas permitem que o middleware de tratamento identifique exatamente qual tipo de erro ocorreu. `NotFoundError` (404) é usado quando um livro não existe; `ValidationError` (400) para campos inválidos; `ConflictError` (409) para duplicações. A propriedade `isOperational` diferencia erros esperados (como "não encontrado") de bugs reais do servidor.

