## Arquivo: `src/middleware/errorHandler.js`

```javascript
/**
 * @fileoverview Middleware centralizado de tratamento de erros.
 * 
 * Por que um middleware de erro?
 * - Centraliza o tratamento em UM lugar (DRY — Don't Repeat Yourself)
 * - Garante respostas consistentes para todos os erros
 * - Evita vazamento de stack traces em produção
 * - Permite logging estruturado para monitoramento
 */

const { ApiError } = require('../classes/errors');

/**
 * Middleware de tratamento de erros.
 * 
 * Express identifica middlewares de erro pela assinatura:
 * (error, req, res, next) => ...
 * 
 * @function
 * @param {Error} error - Objeto de erro capturado
 * @param {import('express').Request} req - Objeto de requisição
 * @param {import('express').Response} res - Objeto de resposta
 * @param {import('express').NextFunction} next - Função next do Express
 */
const errorHandler = (error, req, res, next) => {
  // Se o erro já é nossa classe ApiError, usa seu statusCode
  let statusCode = error.statusCode || 500;
  let message = error.message || 'Erro interno do servidor';
  let details = error.details || {};

  // Em produção, não expor stack trace para o cliente
  const isProduction = process.env.NODE_ENV === 'production';

  // Log estruturado do erro (para monitoramento)
  console.error('[ERROR]', {
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    error: error.name || 'Error',
    message: error.message,
    statusCode: error.statusCode,
    stack: isProduction ? undefined : error.stack
  });

  // Resposta padronizada para erros da API
  const response = {
    success: false,
    error: {
      name: error.name || 'Error',
      message: message
    },
    timestamp: new Date().toISOString()
  };

  // Adiciona detalhes apenas se existirem e não for produção
  if (Object.keys(details).length > 0 && !isProduction) {
    response.error.details = details;
  }

  // Em desenvolvimento, adiciona stack trace para debugging
  if (!isProduction && error.stack) {
    response.error.stack = error.stack;
  }

  res.status(statusCode).json(response);
};

/**
 * Middleware para capturar erros de rotas assíncronas.
 * 
 * Express não captura automaticamente rejeições de Promises em handlers async.
 * Esta função envolve cada handler para converter rejects em calls a next().
 * 
 * @function
 * @param {Function} fn - Handler assíncrono do Express
 * @returns {Function} Handler envolvido com tratamento de erro
 */
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

/**
 * Middleware para validar campos obrigatórios.
 * 
 * @function
 * @param {Object} schema - Esquema de validação: { field: required | { type, min, max } }
 * @returns {Function} Middleware de validação
 */
const validate = (schema) => {
  return (req, res, next) => {
    const errors = {};

    for (const [field, rules] of Object.entries(schema)) {
      const value = req.body[field];

      // Verifica obrigatoriedade
      if (rules.required && (value === undefined || value === null || value === '')) {
        errors[field] = `${field} é obrigatório`;
        continue;
      }

      // Se o campo está vazio e não é obrigatório, pula validações
      if (value === undefined || value === null) continue;

      // Validação de tipo
      if (rules.type && typeof value !== rules.type) {
        errors[field] = `${field} deve ser do tipo ${rules.type}`;
        continue;
      }

      // Validação de número mínimo/máximo
      if (rules.type === 'number') {
        if (rules.min !== undefined && value < rules.min) {
          errors[field] = `${field} deve ser >= ${rules.min}`;
        }
        if (rules.max !== undefined && value > rules.max) {
          errors[field] = `${field} deve ser <= ${rules.max}`;
        }
      }

      // Validação de string mínima/máxima
      if (rules.type === 'string' || (!rules.type && typeof value === 'string')) {
        if (rules.min !== undefined && value.length < rules.min) {
          errors[field] = `${field} deve ter >= ${rules.min} caracteres`;
        }
        if (rules.max !== undefined && value.length > rules.max) {
          errors[field] = `${field} deve ter <= ${rules.max} caracteres`;
        }
      }
    }

    // Se há erros, passa para o middleware de erro com ValidationError
    if (Object.keys(errors).length > 0) {
      const { ValidationError } = require('../classes/errors');
      return next(new ValidationError('Validação falhou', errors));
    }

    next();
  };
};

module.exports = { errorHandler, asyncHandler, validate };
```

> **Explicação:** O `errorHandler` é o coração do tratamento de erros — ele garante que TODOS os erros retornem no mesmo formato JSON, independentemente de onde ocorram. O `asyncHandler` é crucial porque Express não captura automaticamente rejeições em handlers `async`. Sem ele, um `throw new Error()` dentro de uma rota async causaria um crash no servidor. O middleware `validate` permite validação declarativa de campos na requisição.

