 * @example curl "http://localhost:3000/books?genre=fantasia&search=senhor"
 */
router.get('/books', asyncHandler(async (req, res) => {
  // Extrai parâmetros de query da URL
  const { author, genre, search } = req.query;

  // Começa com todos os livros
  let result = [...books];

  // Aplica filtro por autor (busca parcial, case-insensitive)
  if (author) {
    const authorLower = author.toLowerCase();
    result = result.filter(book => 
      book.author.toLowerCase().includes(authorLower)
    );
  }

  // Aplica filtro por gênero (correspondência exata, case-insensitive)
  if (genre) {
    const genreLower = genre.toLowerCase();
    result = result.filter(book => 
      book.genre.toLowerCase() === genreLower
    );
  }

  // Aplica busca no título (parcial, case-insensitive)
  if (search) {
    const searchLower = search.toLowerCase();
    result = result.filter(book => 
      book.title.toLowerCase().includes(searchLower)
    );
  }

  // Resposta com metadados de paginação (para escalabilidade futura)
  res.json({
    success: true,
    data: result,
    meta: {
      total: result.length,
      query: req.query,
      timestamp: new Date().toISOString()
    }
  });
}));

// ============================================================
// ROTAS — GET /books/:id (Obter por ID)
// ============================================================

/**
 * Rota: GET /books/:id
 * 
 * Retorna um único livro pelo seu ID numérico.
 * 
 * @example curl http://localhost:3000/books/1
 * @example curl http://localhost:3000/books/999  // Retorna 404
 */
router.get('/books/:id', asyncHandler(async (req, res) => {
  // Converte ID para número e verifica se é válido
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    throw new ValidationError('ID deve ser um número válido');
  }

  // Encontra o livro pelo ID (O(n) — eficiente para arrays pequenos)
  const book = books.find(b => b.id === id);

  // Se não encontrado, lança NotFoundError (capturado pelo middleware)
  if (!book) {
    throw new NotFoundError('Livro', id);
  }

  // Retorna o livro com sucesso
  res.json({
    success: true,
    data: book,
    timestamp: new Date().toISOString()
  });
}));

// ============================================================
// ROTAS — POST /books (Criar novo livro)
// ============================================================

/**
 * Rota: POST /books
 * 
 * Cria um novo livro no array.
 * 
 * Campos obrigatórios: title, author
 * Campos opcionais: year, genre, isbn
 * 
 * Validações:
 * - year deve ser entre 1000 e 2100
 * - isbn deve ter exatamente 13 dígitos (se fornecido)
 * 
 * @example curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Duna","author":"Frank Herbert","year":1965,"genre":"Ficção Científica"}'
 */
router.post('/books', asyncHandler(async (req, res) => {
  const { title, author, year, genre, isbn } = req.body;

  // Validações básicas
  if (!title || !author) {
    throw new ValidationError('Título e autor são obrigatórios', {
      title: title ? undefined : 'título é obrigatório',
      author: author ? undefined : 'autor é obrigatório'
    });
  }

  // Valida ano se fornecido
  if (year !== undefined) {
    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 1000 || yearNum > 2100) {
      throw new ValidationError('Ano deve ser um número entre 1000 e 2100', {
        year: 'ano inválido'
      });
    }
  }

  // Valida ISBN se fornecido (deve ter 13 dígitos)
  if (isbn !== undefined) {
    const isbnClean = String(isbn).replace(/\D/g, '');
    if (isbnClean.length !== 13) {
      throw new ValidationError('ISBN deve ter exatamente 13 dígitos', {
        isbn: 'ISBN inválido'
      });
    }
  }

  // Gera novo ID único
  const newId = nextId++;

  // Cria o novo livro
  const newBook = {
    id: newId,
    title: String(title).trim(),
    author: String(author).trim(),
    year: year !== undefined ? parseInt(year, 10) : null,
    genre: genre ? String(genre).trim() : null,
    isbn: isbn ? String(isbn).replace(/\D/g, '') : null
  };

  // Adiciona ao array (O(1) — push no final)
  books.push(newBook);

  // Retorna 201 Created com o livro criado
  res.status(201).json({
    success: true,
    data: newBook,
    message: 'Livro criado com sucesso',
    timestamp: new Date().toISOString()
  });
}));

// ============================================================
// ROTAS — PUT /books/:id (Atualizar livro)
// ============================================================

/**
 * Rota: PUT /books/:id
 * 
 * Atualiza completamente um livro existente.
 * Todos os campos devem ser fornecidos.
 * 
 * @example curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia","isbn":"9780618640157"}'
 */
router.put('/books/:id', asyncHandler(async (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    throw new ValidationError('ID deve ser um número válido');
  }

  // Encontra o índice do livro (para poder atualizar)
  const index = books.findIndex(b => b.id === id);

  if (index === -1) {
    throw new NotFoundError('Livro', id);
  }

  const { title, author, year, genre, isbn } = req.body;

  // Validações
  if (!title || !author) {
    throw new ValidationError('Título e autor são obrigatórios');
  }

  if (year !== undefined) {
    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 1000 || yearNum > 2100) {
      throw new ValidationError('Ano deve ser entre 1000 e 2100');
    }
  }

  // Atualiza o livro no array (substituição completa)
  books[index] = {
    id: id,
    title: String(title).trim(),
    author: String(author).trim(),
    year: year !== undefined ? parseInt(year, 10) : null,
    genre: genre ? String(genre).trim() : null,
    isbn: isbn ? String(isbn).replace(/\D/g, '') : null
  };

  res.json({
    success: true,
    data: books[index],
    message: 'Livro atualizado com sucesso',
    timestamp: new Date().toISOString()
  });
}));

// ============================================================
// ROTAS — DELETE /books/:id (Excluir livro)
// ============================================================

/**
 * Rota: DELETE /books/:id
 * 
 * Remove um livro do array pelo ID.
 * Retorna 204 No Content em caso de sucesso.
 * 
 * @example curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/books/:id', asyncHandler(async (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    throw new ValidationError('ID deve ser um número válido');
  }

  // Encontra o índice do livro
  const index = books.findIndex(b => b.id === id);

  if (index === -1) {
    throw new NotFoundError('Livro', id);
  }

  // Remove o livro do array (splice é O(n) mas eficiente para arrays pequenos)
  books.splice(index, 1);

  // Retorna 204 No Content (padrão REST para exclusão bem-sucedida)
  res.status(204).send();
}));

// ============================================================
// ROTAS — GET /stats (Estatísticas)
// ============================================================

/**
 * Rota: GET /stats
 * 
 * Retorna estatísticas agregadas da coleção de livros.
 * 
 * Estatísticas calculadas:
 * - total: número total de livros
 * - porGenero: contagem de livros por gênero
 * - porAno: faixa etária dos livros (mais antigo, mais recente)
 * - autoresUnicos: quantidade de autores distintos
 * 
 * @example curl http://localhost:3000/stats
 */
router.get('/stats', asyncHandler(async (req, res) => {
  // Total de livros
  const total = books.length;

  // Contagem por gênero (usando reduce para agrupamento)
  const porGenero = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Ano mais antigo e mais recente
  const years = books
    .map(b => b.year)
    .filter(y => y !== null);

  const anoMaisAntigo = years.length > 0 ? Math.min(...years) : null;
  const anoMaisRecente = years.length > 0 ? Math.max(...years) : null;

  // Autores únicos (usando Set para eliminar duplicatas)
  const autoresUnicos = new Set(books.map(b => b.author.toLowerCase())).size;

  res.json({
    success: true,
    data: {
      total,
      porGenero,
      anoMaisAntigo,
      anoMaisRecente,
      autoresUnicos
    },
    meta: {
      timestamp: new Date().toISOString(),
      observacao: 'Estatísticas calculadas em tempo real a partir do array em memória'
    }
  });
}));

module.exports = router;
```

> **Explicação detalhada:** Cada rota segue convenções REST rigorosas:
> - `GET /books` → listagem com filtragem via query params
> - `GET /books/:id` → recuperação individual
> - `POST /books` → criação (retorna 201 Created)
> - `PUT /books/:id` → atualização completa (substituição)
> - `DELETE /books/:id` → exclusão (retorna 204 No Content)
> 
> O array `books` é mutável e armazenado em closure — isso significa que os dados persistem durante a execução do servidor, mas são perdidos ao reiniciar (limitação intencional para exemplo educacional). As validações previnem dados inconsistentes.

