## Arquivo: `src/app.js`

```javascript
/**
 * @fileoverview Aplicação principal da API de livros.
 * 
 * Arquitetura escolhida:
 * - Camada de rotas separada (books.js) para organização
 * - Middleware de erro centralizado (errorHandler.js)
 * - Classes de erro personalizadas para tratamento específico
 * 
 * Por que esta estrutura?
 * - Separação de responsabilidades (SRP — Single Responsibility Principle)
 * - Facilita testes unitários por módulo
 * - Escalável: basta adicionar novos arquivos de rota
 */

const express = require('express');
const { errorHandler } = require('./middleware/errorHandler');
const bookRoutes = require('./routes/books');

// Cria a aplicação Express
const app = express();

// ============================================================
// CONFIGURAÇÃO DE MIDDLEWARE
// ============================================================

/**
 * Middleware para parsear JSON no corpo das requisições.
 * 
 * Por que body-parser?
 * - Express 4.x não inclui parser de body nativamente
 * - Permite acessar req.body em rotas POST/PUT
 */
app.use(express.json());

/**
 * Middleware para log de requisições (desenvolvimento).
 * 
 * Registra: método, URL, timestamp e status da resposta.
 */
app.use((req, res, next) => {
  const start = Date.now();

  // Intercepta o envio da resposta para calcular tempo
  const originalEnd = res.end;
  res.end = function(...args) {
    const duration = Date.now() - start;
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} → ${res.statusCode} (${duration}ms)`);
    originalEnd.apply(res, args);
  };

  next();
});

// ============================================================
// ROTAS DA API
// ============================================================

/**
 * Mount das rotas de livros.
 * 
 * Por que usar router?
 * - Agrupa rotas relacionadas sob um prefixo comum (/books)
 * - Facilita a aplicação de middlewares específicos por grupo
 */
app.use('/api', bookRoutes);

// ============================================================
// ROTA RAIZ (Documentação)
// ============================================================

/**
 * Rota: GET /
 * 
 * Retorna informações básicas da API.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    name: 'API de Livros',
    version: '1.0.0',
    description: 'API REST para gerenciamento de livros — exemplo educacional',
    endpoints: {
      list: 'GET /api/books',
      getById: 'GET /api/books/:id',
      create: 'POST /api/books',
      update: 'PUT /api/books/:id',
      delete: 'DELETE /api/books/:id',
      stats: 'GET /api/stats'
    },
    timestamp: new Date().toISOString()
  });
});

// ============================================================
// ROTA 404 (Recurso não encontrado)
// ============================================================

/**
 * Middleware para rotas inexistentes.
 * 
 * Por que tratar 404 separadamente?
 * - Diferencia "recurso não encontrado" de "rota inexistente"
 * - Retorna JSON consistente com o formato da API
 */
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    error: {
      name: 'NotFoundError',
      message: `Rota ${req.method} ${req.path} não encontrada`
    },
    timestamp: new Date().toISOString()
  });
});

// ============================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS (DEVE SER O ÚLTIMO)
// ============================================================

/**
 * Middleware de erro centralizado.
 * 
 * IMPORTANTE: Deve ser o último middleware registrado.
 * Express identifica middlewares de erro pela assinatura de 4 parâmetros.
 */
app.use(errorHandler);

// ============================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════════════════════╗
║           API DE LIVROS — Servidor Iniciado              ║
║                                                          ║
║  Endereço: http://localhost:${PORT}                       ║
║  Documentação: http://localhost:${PORT}/                  ║
║                                                          ║
║  Endpoints disponíveis:                                  ║
║    GET    /api/books          — Listar livros            ║
║    GET    /api/books/:id      — Obter livro por ID       ║
║    POST   /api/books          — Criar novo livro         ║
║    PUT    /api/books/:id      — Atualizar livro          ║
║    DELETE /api/books/:id      — Excluir livro            ║
║    GET    /api/stats          — Estatísticas             ║
╚══════════════════════════════════════════════════════════╝
  `);
});

module.exports = app;
```

> **Explicação:** O `app.js` é o ponto de entrada da aplicação. Ele configura middlewares essenciais (parse JSON, logging), monta as rotas sob `/api`, e trata erros globalmente. A ordem dos middlewares é crítica: o middleware de erro deve ser o último para capturar todos os erros não tratados.

