## File 2: `data/books.js` — In-Memory Data Store

```javascript
/**
 * @fileoverview In-memory data store for books.
 *
 * WHY IN-MEMORY? For an educational example, an array avoids the complexity of
 * setting up a database while still demonstrating all CRUD operations. In a real
 * application, you would replace this module with a database driver (e.g., MongoDB,
 * PostgreSQL). The interface (getBooks, getBookById, etc.) would remain the same,
 * making swapping storage trivial — this is called the Repository Pattern.
 *
 * WHY AN ARRAY? Arrays preserve insertion order and support O(n) iteration for
 * filtering/listing. For a small dataset (hundreds to low thousands of records),
 * an array is perfectly adequate. For larger datasets, you'd use a Map keyed by ID
 * for O(1) lookups.
 */

// ---------------------------------------------------------------------------
// Data Structure
// ---------------------------------------------------------------------------
/**
 * @typedef {Object} Book
 * @property {number} id          - Unique numeric identifier (auto-incremented).
 * @property {string}  title      - The book's title (required, non-empty string).
 * @property {string}  author     - The book's author name (required, non-empty string).
 * @property {number}  year       - Publication year (integer between 0 and current year).
 * @property {string}  [genre]    - Optional genre/category of the book.
 */

/**
 * @type {Book[]}
 *
 * The books array holds all book records in memory.
 * We use `let` instead of `const` because we will mutate this array (push/splice).
 * In production, you'd never expose raw mutable state — you'd wrap it behind a service layer.
 */
let books = [
  { id: 1, title: "To Kill a Mockingbird", author: "Harper Lee", year: 1960, genre: "Fiction" },
  { id: 2, title: "1984",              author: "George Orwell", year: 1949, genre: "Dystopian" },
  { id: 3, title: "Pride and Prejudice",author: "Jane Austen",  year: 1813, genre: "Romance" },
  { id: 4, title: "The Great Gatsby",   author: "F. Scott Fitzgerald", year: 1925, genre: "Fiction" },
  { id: 5, title: "Brave New World",    author: "Aldous Huxley", year: 1932, genre: "Dystopian" }
];

/**
 * Next available ID. We track this separately so new books always get a unique ID.
 * In a real database, the DB would handle auto-incrementing IDs for us.
 */
let nextId = 6;

// ---------------------------------------------------------------------------
// Helper: Generate a unique ID
// ---------------------------------------------------------------------------
/**
 * Returns the next sequential ID and increments the counter.
 * @returns {number} The new unique ID.
 */
function generateId() {
  return nextId++;
}

// ---------------------------------------------------------------------------
// CRUD Operations
// ---------------------------------------------------------------------------

/**
 * Retrieves all books from the in-memory store.
 *
 * WHY RETURN A COPY? We spread `books` into a new array (`[...books]`) so that
 * callers cannot accidentally mutate our internal state. This is called
 * "defensive copying" and prevents subtle bugs where external code modifies
 * data behind our back.
 *
 * @returns {Book[]} A shallow copy of all books.
 */
function getAllBooks() {
  return [...books];
}

/**
 * Finds a single book by its numeric ID.
 *
 * WHY USE `find()`? Array.prototype.find() returns the first element that satisfies
 * the test function, or undefined if none match. It's clean and readable for
 * simple lookups. For large datasets, a Map would be faster (O(1) vs O(n)).
 *
 * @param {number} id - The unique identifier of the book to find.
 * @returns {Book|undefined} The matching book, or undefined if not found.
 */
function getBookById(id) {
  return books.find(book => book.id === id);
}

/**
 * Creates a new book and adds it to the store.
 *
 * WHY SPREAD THE INPUT? We create a new object `{ ...bookData, id: generateId() }`
 * rather than mutating the caller's input object. This ensures our data store
 * owns its copies and prevents side effects.
 *
 * @param {Partial<Book>} bookData - The book data to insert (id is auto-generated).
 * @returns {Book} The newly created book with its assigned ID.
 */
function createBook(bookData) {
  const newBook = { ...bookData, id: generateId() };
  books.push(newBook);
  return newBook;
}

/**
 * Updates an existing book by ID with the provided fields.
 *
 * WHY USE `Object.assign()`? It merges the existing book object with only the
 * fields present in `updates`, leaving unspecified fields untouched. This is
 * the essence of a partial update (as opposed to replacing the entire record).
 *
 * @param {number} id       - The ID of the book to update.
 * @param {Partial<Book>} updates - Fields to overwrite on the existing book.
 * @returns {Book|undefined} The updated book, or undefined if not found.
 */
function updateBook(id, updates) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return undefined;

  // Merge: keep existing fields, overwrite only the ones provided in `updates`
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Deletes a book by its ID.
 *
 * WHY USE `findIndex()` + `splice()`? This is the standard array mutation pattern:
 * findIndex locates the position (O(n)), and splice removes it in-place.
 * Alternative: filter() to create a new array, but that allocates extra memory.
 * For an educational example with small data, either approach is fine.
 *
 * @param {number} id - The ID of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove 1 element at the found index
  return true;
}

// ---------------------------------------------------------------------------
// Statistics
// ---------------------------------------------------------------------------

/**
 * Computes aggregate statistics about the book collection.
 *
 * WHY USE `reduce()`? It's the most expressive way to accumulate values across
 * an array into a single result object. We use it here to compute:
 *   - totalBooks: simple count via length
 *   - averageYear: sum of years divided by count (with division-by-zero guard)
 *   - genreCounts: frequency map of each genre
 *   - authorBookCount: how many books each author has written
 *
 * @returns {Object} Statistics object containing totals, averages, and breakdowns.
 */
function getStats() {
  const totalBooks = books.length;

  // Guard against empty dataset to avoid NaN from division by zero
  const averageYear = totalBooks > 0
    ? Math.round(books.reduce((sum, book) => sum + book.year, 0) / totalBooks)
    : 0;

  // Count occurrences of each genre using reduce as an accumulator pattern
  const genreCounts = books.reduce((counts, book) => {
    const genre = book.genre || "Unknown"; // Treat missing genre as "Unknown"
    counts[genre] = (counts[genre] || 0) + 1;
    return counts;
  }, {});

  // Count books per author — useful for finding prolific writers
  const authorBookCount = books.reduce((counts, book) => {
    counts[book.author] = (counts[book.author] || 0) + 1;
    return counts;
  }, {});

  return {
    totalBooks,
    averageYear,
    genreCounts,
    authorBookCount
  };
}

// ---------------------------------------------------------------------------
// Module Exports
// ---------------------------------------------------------------------------
/**
 * Export all data-layer functions so route handlers can use them.
 *
 * WHY EXPORT INDIVIDUAL FUNCTIONS? This follows the principle of separation of
 * concerns: the data layer knows how to store/retrieve, and the route layer
 * knows how to handle HTTP requests. Keeping them separate makes testing easier
 * (you can test data functions without spinning up an HTTP server).
 */
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats
};
