```javascript
/**
 * @fileoverview Custom error classes and Express error-handling middleware.
 *
 * WHY CUSTOM ERROR CLASSES? JavaScript's built-in Error class is generic. By
 * creating subclasses (NotFoundError, ValidationError, etc.), we can:
 *   1. Distinguish between error types in our middleware.
 *   2. Attach meaningful HTTP status codes to each error type.
 *   3. Provide consistent JSON error responses across all endpoints.
 *
 * WHY EXPRESS ERROR MIDDLEWARE? Express has a special 4-argument middleware
 * signature (err, req, res, next) that acts as a catch-all for any errors
 * thrown in route handlers or middleware. Placing it LAST ensures it intercepts
 * all unhandled errors before any response-sending middleware runs.
 */

// ---------------------------------------------------------------------------
// Custom Error Classes
// ---------------------------------------------------------------------------

/**
 * Base error class that attaches an HTTP status code.
 *
 * WHY EXTEND `Error`? Extending the built-in Error gives us standard properties
 * like `.stack` for debugging, while adding our own `.statusCode` property lets
 * the middleware respond with the correct HTTP status.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (default: 500).
   */
  constructor(message, statusCode = 500) {
    super(message); // Call parent constructor to set .message and capture stack trace
    this.statusCode = statusCode;
    this.isOperational = true; // Marks this as a known/expected error (not a bug)
  }
}

/**
 * 404 Not Found — Resource does not exist.
 */
class NotFoundError extends ApiError {
  constructor(resource, id) {
    super(`${resource} with id ${id} not found`, 404);
  }
}

/**
 * 400 Bad Request — Client sent invalid data.
 */
class ValidationError extends ApiError {
  constructor(message) {
    super(message, 400);
  }
}

// ---------------------------------------------------------------------------
// Error-Handling Middleware
// ---------------------------------------------------------------------------

/**
 * Centralized error handler for all Express routes.
 *
 * HOW IT WORKS: When any route or middleware calls `next(err)`, Express skips
 * all remaining normal middleware and jumps to this error-handling function.
 * We inspect the error type and respond with an appropriate JSON payload.
 *
 * @param {Error} err - The error object (must have .statusCode and .message).
 * @param {import('express').Request} req - The Express request object.
 * @param {import('express').Response} res - The Express response object.
 * @param {import('express').NextFunction} next - Unused but required by Express signature.
 */
function errorHandler(err, req, res, next) {
  // Log the full error (including stack trace) for server-side debugging
  console.error(`[ERROR] ${err.message}`);
  console.error(err.stack);

  // Build a consistent JSON error response
  const response = {
    success: false,
    error: {
      message: err.message,
      statusCode: err.statusCode
    }
  };

  // In development, include the stack trace for easier debugging
  if (process.env.NODE_ENV !== 'production') {
    response.error.stack = err.stack;
  }

  // Send the JSON response with the error's status code
  res.status(err.statusCode).json(response);
}

// ---------------------------------------------------------------------------
// Module Exports
// ---------------------------------------------------------------------------
module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  errorHandler
};
```

