## File 5: `routes/books.js` — Book Route Handlers

```javascript
/**
 * @fileoverview REST route handlers for book resources.
 *
 * WHY SEPARATE ROUTE FILE? As your API grows, keeping all routes in one file
 * becomes unmaintainable. Separating by resource (books, users, orders, etc.)
 * follows the Single Responsibility Principle and makes it easy to find and
 * modify specific endpoints.
 *
 * WHY USE `express.Router()`? Router creates a modular, mountable handler
 * container. It lets us define routes with relative paths (`/books`) and then
 * mount them at any URL prefix in our main app. This is how real Express
 * applications organize their code.
 */

const express = require('express');
const router = express.Router();

// Import data-layer functions (separation of concerns: routes ≠ storage)
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook
} = require('../data/books');

// Import custom error classes for consistent error responses
const { NotFoundError, ValidationError } = require('../middleware/errorHandler');

// ---------------------------------------------------------------------------
// GET /books — List all books with optional filtering
// ---------------------------------------------------------------------------

/**
 * @swagger
 * /books:
 *   get:
 *     summary: Retrieve a list of all books
 *     parameters:
 *       - in: query
 *         name: title
 *         schema: { type: string }
 *         description: Filter by book title (partial match, case-insensitive)
 *       - in: query
 *         name: author
 *         schema: { type: string }
 *         description: Filter by author name (partial match, case-insensitive)
 *       - in: query
 *         name: genre
 *         schema: { type: string }
 *         description: Filter by exact genre match
 *       - in: query
 *         name: minYear
 *         schema: { type: integer }
 *         description: Minimum publication year (inclusive)
 *       - in: query
 *         name: maxYear
 *         schema: { type: integer }
 *         description: Maximum publication year (inclusive)
 *     responses:
 *       200:
 *         description: A list of books matching the filters
 *
 * EXAMPLE CURL:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?genre=Fiction&minYear=1900"
 *   curl "http://localhost:3000/books?author=orwell"
 */
router.get('/', (req, res) => {
  // Start with all books as our base dataset
  let result = getAllBooks();

  // Apply filters only if the query parameter was actually provided.
  // This avoids unnecessary filtering when the user wants everything.
  const { title, author, genre, minYear, maxYear } = req.query;

  if (title) {
    // Case-insensitive partial match: convert both to lowercase for comparison
    result = result.filter(book =>
      book.title.toLowerCase().includes(title.toLowerCase())
    );
  }

  if (author) {
    result = result.filter(book =>
      book.author.toLowerCase().includes(author.toLowerCase())
    );
  }

  if (genre) {
    // Exact match for genre (case-insensitive)
    result = result.filter(book =>
      book.genre && book.genre.toLowerCase() === genre.toLowerCase()
    );
  }

  if (minYear) {
    const min = parseInt(minYear, 10);
    if (!isNaN(min)) {
      result = result.filter(book => book.year >= min);
    }
  }

  if (maxYear) {
    const max = parseInt(maxYear, 10);
    if (!isNaN(max)) {
      result = result.filter(book => book.year <= max);
    }
  }

  // Return the (possibly filtered) list as JSON
  res.json({ success: true, data: result });
});

// ---------------------------------------------------------------------------
// GET /books/:id — Get a single book by ID
// ---------------------------------------------------------------------------

/**
 * @swagger
 * /books/{id}:
 *   get:
 *     summary: Retrieve a single book by its ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema: { type: integer }
 *     responses:
 *       200:
 *         description: The requested book
 *       404:
 *         description: Book not found
 *
 * EXAMPLE CURL:
 *   curl http://localhost:3000/books/1
 */
router.get('/:id', (req, res) => {
  // Convert the URL parameter from string to number for numeric comparison
  const id = parseInt(req.params.id, 10);

  // Validate that the ID is a valid number
  if (isNaN(id)) {
    throw new ValidationError('Invalid book ID: must be a number');
  }

  const book = getBookById(id);

  // If not found, throw our custom NotFoundError (caught by error handler)
  if (!book) {
    throw new NotFoundError('Book', id);
  }

  res.json({ success: true, data: book });
});

// ---------------------------------------------------------------------------
// POST /books — Create a new book
// ---------------------------------------------------------------------------

/**
 * @swagger
 * /books:
 *   post:
 *     summary: Create a new book
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author]
 *             properties:
 *               title:  { type: string }
 *               author: { type: string }
 *               year:   { type: integer }
 *               genre:  { type: string }
 *     responses:
 *       201:
 *         description: The newly created book (with auto-assigned ID)
 *       400:
 *         description: Validation error — missing or invalid fields
 *
 * EXAMPLE CURL:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dune","author":"Frank Herbert","year":1965,"genre":"Sci-Fi"}'
 */
router.post('/', (req, res) => {
  const { title, author, year, genre } = req.body;

  // --- Validation: required fields ---
  if (!title || typeof title !== 'string' || title.trim() === '') {
    throw new ValidationError('Title is required and must be a non-empty string');
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    throw new ValidationError('Author is required and must be a non-empty string');
  }

  // --- Validation: year (optional but must be valid if provided) ---
  let parsedYear = undefined;
  if (year !== undefined && year !== null) {
    parsedYear = parseInt(year, 10);
    if (isNaN(parsedYear) || parsedYear < 0 || parsedYear > new Date().getFullYear()) {
      throw new ValidationError(
        `Year must be a number between 0 and ${new Date().getFullYear()}`
      );
    }
  }

  // Build the book object, including only defined fields
  const bookData = { title: title.trim(), author: author.trim() };
  if (parsedYear !== undefined) bookData.year = parsedYear;
  if (genre !== undefined && genre !== null) bookData.genre = genre.trim();

  // Create the book in our data store
  const newBook = createBook(bookData);

  // 201 Created is the correct status for a newly created resource
  res.status(201).json({ success: true, data: newBook });
});

// ---------------------------------------------------------------------------
// PUT /books/:id — Update an existing book (full replacement)
// ---------------------------------------------------------------------------

/**
 * @swagger
 * /books/{id}:
 *   put:
 *     summary: Replace all fields of an existing book
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema: { type: integer }
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author]
 *             properties:
 *               title:  { type: string }
 *               author: { type: string }
 *               year:   { type: integer }
 *               genre:  { type: string }
 *     responses:
 *       200:
 *         description: The updated book
 *       404:
 *         description: Book not found
 *       400:
 *         description: Validation error
 *
 * EXAMPLE CURL:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"To Kill a Mockingbird (Updated)","author":"Harper Lee","year":1960,"genre":"Classic"}'
 */
router.put('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    throw new ValidationError('Invalid book ID: must be a number');
  }

  // Check the book exists BEFORE validating input — saves work if it doesn't exist
  const existingBook = getBookById(id);
  if (!existingBook) {
    throw new NotFoundError('Book', id);
  }

  const { title, author, year, genre } = req.body;

  // Reuse the same validation logic as POST
  if (!title || typeof title !== 'string' || title.trim() === '') {
    throw new ValidationError('Title is required and must be a non-empty string');
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    throw new ValidationError('Author is required and must be a non-empty string');
  }

  let parsedYear = undefined;
  if (year !== undefined && year !== null) {
    parsedYear = parseInt(year, 10);
    if (isNaN(parsedYear) || parsedYear < 0 || parsedYear > new Date().getFullYear()) {
      throw new ValidationError(
        `Year must be a number between 0 and ${new Date().getFullYear()}`
      );
    }
  }

  const updates = { title: title.trim(), author: author.trim() };
  if (parsedYear !== undefined) updates.year = parsedYear;
  if (genre !== undefined && genre !== null) updates.genre = genre.trim();

  // updateBook merges the new fields with existing ones (partial update behavior)
  const updatedBook = updateBook(id, updates);

  res.json({ success: true, data: updatedBook });
});

// ---------------------------------------------------------------------------
// DELETE /books/:id — Delete a book by ID
// ---------------------------------------------------------------------------

/**
 * @swagger
 * /books/{id}:
 *   delete:
 *     summary: Delete a book by its ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema: { type: integer }
 *     responses:
 *       200:
 *         description: Confirmation of deletion with the removed book's data
 *       404:
 *         description: Book not found
 *
 * EXAMPLE CURL:
 *   curl -X DELETE http://localhost:3000/books/5
 */
router.delete('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    throw new ValidationError('Invalid book ID: must be a number');
  }

  // Check existence before attempting deletion
  const existingBook = getBookById(id);
  if (!existingBook) {
    throw new NotFoundError('Book', id);
  }

  // Perform the deletion
  deleteBook(id);

  // Return 200 with the deleted book's data so the client knows what was removed
  res.json({ success: true, data: existingBook });
});

// ---------------------------------------------------------------------------
// Module Export
// ---------------------------------------------------------------------------
module.exports = router;
```

