## File 7: `server.js` — Application Entry Point

```javascript
/**
 * @fileoverview Main application entry point.
 *
 * WHY THIS FILE IS THE "CONDUCTOR"? This file doesn't contain business logic.
 * Its job is to:
 *   1. Configure the Express application
 *   2. Register middleware in the correct order
 *   3. Mount route modules at their URL prefixes
 *   4. Start listening on a port
 *
 * MIDDLEWARE ORDER MATTERS in Express — it executes top-to-bottom like a chain.
 * We place body-parsing and logging BEFORE routes so every request gets parsed
 * and logged before any route handler runs. The error handler goes LAST because
 * it must catch errors from everything above it.
 */

const express = require('express');
const app = express();

// ---------------------------------------------------------------------------
// Middleware Registration (in execution order)
// ---------------------------------------------------------------------------

/**
 * Parses incoming JSON request bodies into `req.body`.
 *
 * WHY IS THIS NECESSARY? By default, Express does not parse request bodies.
 * Without this middleware, `req.body` would be undefined and POST/PUT requests
 * would have no data. This is one of the most commonly used built-in middlewares.
 */
app.use(express.json());

/**
 * Our custom request logger — runs on every incoming request.
 */
const { requestLogger } = require('./middleware/logger');
app.use(requestLogger);

// ---------------------------------------------------------------------------
// Route Mounting
// ---------------------------------------------------------------------------

/**
 * Mount the books router at /books. All routes in `routes/books.js` will be
 * prefixed with `/books` automatically (e.g., GET /books, POST /books).
 */
const bookRoutes = require('./routes/books');
app.use('/books', bookRoutes);

/**
 * Mount the stats router at /stats.
 */
const statsRoutes = require('./routes/stats');
app.use('/stats', statsRoutes);

// ---------------------------------------------------------------------------
// Root Endpoint (health check)
// ---------------------------------------------------------------------------

/**
 * Simple health-check endpoint to verify the server is running.
 *
 * EXAMPLE CURL:
 *   curl http://localhost:3000/
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book REST API is running',
    endpoints: {
      'GET    /books':       'List all books (with optional filters)',
      'GET    /books/:id':   'Get a single book by ID',
      'POST   /books':       'Create a new book',
      'PUT    /books/:id':   'Update an existing book',
      'DELETE /books/:id':   'Delete a book by ID',
      'GET    /stats':       'Get aggregate statistics'
    }
  });
});

// ---------------------------------------------------------------------------
// Error Handling (MUST be last — catches errors from all routes above)
// ---------------------------------------------------------------------------
const { errorHandler } = require('./middleware/errorHandler');
app.use(errorHandler);

// ---------------------------------------------------------------------------
// Start the Server
// ---------------------------------------------------------------------------

/**
 * The port to listen on. We default to 3000 but allow override via environment
 * variable (useful for deployment platforms like Heroku that set PORT).
 */
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`📚 Book API server running on http://localhost:${PORT}`);
  console.log(`   Environment: ${process.env.NODE_ENV || 'development'}`);
});
```

