## Arquivo 2: `src/middleware/errors.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * CLASSE PERSONALIZADA: AppError
 * ------------------------------
 * Criamos uma classe que estende Error para padronizar respostas de erro.
 * Isso permite que o middleware de erros capture qualquer instância de
 * AppError e responda com o status HTTP correto, sem precisar de try/catch
 * em cada rota — o middleware lida com isso centralizadamente.
 *
 * Padrão adotado: Error Handling Middleware do Express
 * ----------------------------------------------------
 * O Express reconhece funções middleware de erro pelo número de parâmetros:
 *   (err, req, res, next) => { ... }
 * Se tiver 4+ parâmetros, o Express sabe que é um handler de erros.
 */

/**
 * Classe AppError — Erro personalizado com código HTTP e mensagem.
 *
 * @extends Error
 */
class AppError extends Error {
  /**
   * Construtor do erro personalizado.
   *
   * @param {string} message - Mensagem descritiva do erro.
   * @param {number} statusCode - Código HTTP da resposta (padrão: 400).
   */
  constructor(message, statusCode = 400) {
    super(message); // Chama o construtor da classe Error pai
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'error' : 'fail';
    this.isOperational = true; // Indica que é um erro esperado, não um bug

    // Mantém o stack trace correto mesmo com custom class em Node.js
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Middleware de tratamento de erros global do Express.
 *
 * Este middleware deve ser o ÚLTIMO a ser registrado no app (depois de todas
 * as rotas). Ele captura:
 *   1. Erros lançados via next(err) nas rotas
 *   2. Instâncias de AppError
 *   3. Erros não tratados (500 genérico)
 *
 * @param {Error} err - O erro capturado.
 * @param {import('express').Request} req - Objeto Request do Express.
 * @param {import('express').Response} res - Objeto Response do Express.
 * @param {import('express').NextFunction} next - Função next do Express.
 */
const errorHandler = (err, req, res, next) => {
  // Se o erro for uma instância de AppError, usamos seus dados
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      status: err.status,
      message: err.message,
      // Em produção, não expor stack trace para clientes
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
    });
  }

  // Erro não operacional (bug inesperado) — resposta genérica 500
  console.error('❌ ERRO NÃO TRATADO:', err); // Log para o desenvolvedor
  return res.status(500).json({
    status: 'error',
    message: 'Erro interno do servidor. Tente novamente mais tarde.',
  });
};

module.exports = { AppError, errorHandler };
```

