## Arquivo 3: `src/routes/books.js`

```javascript
/**
 * ============================================================================
 * ROTAS DE LIVROS — CRUD COMPLETO + ESTATÍSTICAS
 * ============================================================================
 *
 * PADRÃO REST ADOTADO:
 * ---------------------
 * - GET    /books          → Listar todos (com filtragem opcional)
 * - GET    /books/:id       → Obter um livro pelo ID
 * - POST   /books           → Criar novo livro
 * - PUT    /books/:id       → Atualizar livro existente (substituição total)
 * - DELETE /books/:id       → Excluir livro
 * - GET    /stats           → Estatísticas agregadas
 *
 * POR QUE USAR async/await?
 * --------------------------
 * Express suporta handlers assíncronos nativamente a partir da v4.10.
 * Usar async/await torna o código mais legível que promessas encadeadas,
 * e permite usar try/catch para tratamento de erros estruturado.
 *
 * POR QUE ARRAY EM MEMÓRIA?
 * ---------------------------
 * Para um exemplo educacional, um array é suficiente porque:
 *   - Não requer configuração de banco de dados
 *   - Facilita o entendimento da lógica de CRUD
 *   - Em produção, substituiríamos por MongoDB/PostgreSQL com mínima
 *     alteração nas rotas (padrão Repository)
 *
 * EXEMPLOS DE CURL:
 * -----------------
 * # Listar todos os livros
 * curl http://localhost:3000/books
 *
 * # Listar com filtragem
 * curl "http://localhost:3000/books?author=jk&minPrice=10"
 *
 * # Obter livro por ID
 * curl http://localhost:3000/books/1
 *
 * # Criar novo livro
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","price":45.90,"genre":"fantasia"}'
 *
 * # Atualizar livro (PUT = substituição total)
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis - Edição Ilustrada","author":"J.R.R. Tolkien","price":89.90,"genre":"fantasia"}'
 *
 * # Excluir livro
 * curl -X DELETE http://localhost:3000/books/1
 *
 * # Estatísticas
 * curl http://localhost:3000/stats
 */

const { Router } = require('express');
const { AppError } = require('../middleware/errors');

// --------------------------------------------------------------------------
// ESTRUTURA DE DADOS EM MEMÓRIA
// --------------------------------------------------------------------------
// Usamos um array de objetos para armazenar os livros. Cada livro possui:
//   - id: número inteiro auto-incrementado (simples e eficiente para exemplo)
//   - title: string do título
//   - author: string do autor
//   - price: number (preço em reais)
//   - genre: string (gênero literário)
//   - createdAt: timestamp ISO da criação
//
// Alternativas consideradas:
//   - Map: melhor para buscas por ID O(1), mas array é mais familiar
//   - Objeto aninhado: perderia a ordem de inserção
// Escolha final: Array, pois a API terá no máximo alguns registros neste exemplo.

let books = [
  {
    id: 1,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    price: 29.90,
    genre: 'romance',
    createdAt: new Date('2024-01-15T10:00:00Z').toISOString(),
  },
  {
    id: 2,
    title: 'O Pequeno Príncipe',
    author: 'Antoine de Saint-Exupéry',
    price: 19.90,
    genre: 'infantil',
    createdAt: new Date('2024-02-20T14:30:00Z').toISOString(),
  },
  {
    id: 3,
    title: '1984',
    author: 'George Orwell',
    price: 34.50,
    genre: 'distopia',
    createdAt: new Date('2024-03-10T09:15:00Z').toISOString(),
  },
];

// Contador para gerar IDs únicos (auto-incremento simples)
let nextId = 4;

const router = Router();

// --------------------------------------------------------------------------
// GET /books — Listar todos os livros com filtragem opcional
// --------------------------------------------------------------------------
/**
 * Retorna uma lista de livros, com suporte a filtros opcionais via query string.
 *
 * Filtros disponíveis:
 *   - author    → filtra por autor (case-insensitive, parcial)
 *   - genre     → filtra por gênero (exato)
 *   - minPrice  → preço mínimo (number)
 *   - maxPrice  → preço máximo (number)
 *   - search    → busca por título ou autor (parcial, case-insensitive)
 *
 * @example
 * // curl "http://localhost:3000/books?genre=fantasia&maxPrice=50"
 *
 * @param {import('express').Request} req  — Contém req.query com os filtros.
 * @param {import('express').Response} res — Resposta JSON com a lista.
 */
router.get('/books', (req, res) => {
  let result = books;

  // Filtro por autor (busca parcial e insensível a maiúsculas/minúsculas)
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter((book) =>
      book.author.toLowerCase().includes(authorFilter)
    );
  }

  // Filtro por gênero (comparação exata)
  if (req.query.genre) {
    result = result.filter(
      (book) => book.genre.toLowerCase() === req.query.genre.toLowerCase()
    );
  }

  // Filtro de faixa de preço
  if (req.query.minPrice) {
    const minPrice = parseFloat(req.query.minPrice);
    if (!isNaN(minPrice)) {
      result = result.filter((book) => book.price >= minPrice);
    }
  }

  if (req.query.maxPrice) {
    const maxPrice = parseFloat(req.query.maxPrice);
    if (!isNaN(maxPrice)) {
      result = result.filter((book) => book.price <= maxPrice);
    }
  }

  // Busca livre por título ou autor
  if (req.query.search) {
    const search = req.query.search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(search) ||
        book.author.toLowerCase().includes(search)
    );
  }

  // Resposta com metadados de paginação (preparado para expansão futura)
  res.json({
    status: 'success',
    total: result.length,
    count: result.length,
    data: result,
  });
});

// --------------------------------------------------------------------------
// GET /books/:id — Obter um livro pelo ID
// --------------------------------------------------------------------------
/**
 * Retorna um único livro identificado pelo parâmetro de rota :id.
 *
 * Se o ID não existir, lança NotFoundError (404).
 *
 * @example
 * // curl http://localhost:3000/books/1
 *
 * @param {import('express').Request} req  — Contém req.params.id.
 * @param {import('express').Response} res — Resposta JSON com o livro.
 * @param {import('express').NextFunction} next — Passa erros para o middleware.
 */
router.get('/books/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  // Validação: ID deve ser um número inteiro válido
  if (isNaN(id)) {
    return next(new AppError('ID inválido. Deve ser um número inteiro.', 400));
  }

  const book = books.find((b) => b.id === id);

  if (!book) {
    // Lançamos o erro via next() para que o middleware de erros o capture
    return next(new AppError(`Livro com ID ${id} não encontrado.`, 404));
  }

  res.json({ status: 'success', data: book });
});

// --------------------------------------------------------------------------
// POST /books — Criar um novo livro
// --------------------------------------------------------------------------
/**
 * Cria um novo livro a partir dos dados enviados no corpo da requisição (JSON).
 *
 * Campos obrigatórios: title, author, price, genre
 * O ID e createdAt são gerados automaticamente pelo servidor.
 *
 * @example
 * // curl -X POST http://localhost:3000/books \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"Harry Potter","author":"J.K. Rowling","price":55.00,"genre":"fantasia"}'
 *
 * @param {import('express').Request} req  — Contém req.body com os dados.
 * @param {import('express').Response} res — Resposta JSON com o livro criado.
 * @param {import('express').NextFunction} next — Passa erros para o middleware.
 */
router.post('/books', (req, res, next) => {
  const { title, author, price, genre } = req.body;

  // Validação dos campos obrigatórios
  if (!title || !author || price === undefined || !genre) {
    return next(
      new AppError(
        'Campos obrigatórios ausentes: title, author, price e genre são requeridos.',
        400
      )
    );
  }

  // Validação de tipo: price deve ser um número positivo
  const parsedPrice = parseFloat(price);
  if (isNaN(parsedPrice) || parsedPrice < 0) {
    return next(new AppError('Preço deve ser um número positivo.', 400));
  }

  const newBook = {
    id: nextId++, // Auto-incremento simples
    title,
    author,
    price: parsedPrice,
    genre,
    createdAt: new Date().toISOString(),
  };

  books.push(newBook);

  // Status 201 Created indica recurso criado com sucesso (convenção REST)
  res.status(201).json({ status: 'success', data: newBook });
});

// --------------------------------------------------------------------------
// PUT /books/:id — Atualizar um livro existente (substituição total)
// --------------------------------------------------------------------------
/**
 * Substitui completamente os dados de um livro pelo ID fornecido.
 *
 * Diferença entre PUT e PATCH:
 *   - PUT  → substituição TOTAL (todos os campos devem ser enviados)
 *   - PATCH → atualização PARCIAL (apenas os campos desejados)
 *
 * Escolhemos PUT aqui por ser mais simples de implementar e entender.
 *
 * @example
 * // curl -X PUT http://localhost:3000/books/1 \
 * //   -H "Content-Type: application/json" \
 * //   -d '{"title":"Dom Casmurro - Edição Fac-símile","author":"Machado de Assis","price":49.90,"genre":"romance"}'
 *
 * @param {import('express').Request} req  — Contém req.params.id e req.body.
 * @param {import('express').Response} res — Resposta JSON com o livro atualizado.
 * @param {import('express').NextFunction} next — Passa erros para o middleware.
 */
router.put('/books/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    return next(new AppError('ID inválido. Deve ser um número inteiro.', 400));
  }

  const index = books.findIndex((b) => b.id === id);

  if (index === -1) {
    return next(new AppError(`Livro com ID ${id} não encontrado.`, 404));
  }

  const { title, author, price, genre } = req.body;

  // Validação dos campos obrigatórios na atualização
  if (!title || !author || price === undefined || !genre) {
    return next(
      new AppError(
        'Campos obrigatórios ausentes: title, author, price e genre são requeridos.',
        400
      )
    );
  }

  const parsedPrice = parseFloat(price);
  if (isNaN(parsedPrice) || parsedPrice < 0) {
    return next(new AppError('Preço deve ser um número positivo.', 400));
  }

  // Atualização completa do registro (substituição)
  books[index] = {
    id,
    title,
    author,
    price: parsedPrice,
    genre,
    createdAt: books[index].createdAt, // Preserva a data de criação original
  };

  res.json({ status: 'success', data: books[index] });
});

// --------------------------------------------------------------------------
// DELETE /books/:id — Excluir um livro
// --------------------------------------------------------------------------
/**
 * Remove permanentemente um livro pelo ID fornecido.
 *
 * @example
 * // curl -X DELETE http://localhost:3000/books/1
 *
 * @param {import('express').Request} req  — Contém req.params.id.
 * @param {import('express').Response} res — Resposta JSON de confirmação.
 * @param {import('express').NextFunction} next — Passa erros para o middleware.
 */
router.delete('/books/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    return next(new AppError('ID inválido. Deve ser um número inteiro.', 400));
  }

  const index = books.findIndex((b) => b.id === id);

  if (index === -1) {
    return next(new AppError(`Livro com ID ${id} não encontrado.`, 404));
  }

  // splice remove o elemento do array e retorna um array com o elemento removido
  const [removedBook] = books.splice(index, 1);

  // Status 200 OK com corpo contendo o recurso removido (informação útil)
  res.json({ status: 'success', message: 'Livro excluído com sucesso.', data: removedBook });
});

// --------------------------------------------------------------------------
// GET /stats — Estatísticas agregadas dos livros
// --------------------------------------------------------------------------
/**
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * Métricas calculadas:
 *   - totalBooks      → quantidade total de livros
 *   - averagePrice    → preço médio (arredondado para 2 casas decimais)
 *   - minPrice        → menor preço do acervo
 *   - maxPrice        → maior preço do acervo
 *   - genres          → objeto com contagem por gênero
 *   - authors         → quantidade de autores únicos
 *
 * @example
 * // curl http://localhost:3000/stats
 *
 * @param {import('express').Request} req  — Não utiliza parâmetros.
 * @param {import('express').Response} res — Resposta JSON com as estatísticas.
 */
router.get('/stats', (req, res) => {
  const totalBooks = books.length;

  if (totalBooks === 0) {
    return res.json({
      status: 'success',
      data: {
        totalBooks: 0,
        averagePrice: 0,
        minPrice: null,
        maxPrice: null,
        genres: {},
        uniqueAuthors: 0,
      },
    });
  }

  // Array.prototype.reduce para calcular soma dos preços (padrão funcional)
  const totalPrices = books.reduce((sum, book) => sum + book.price, 0);
  const averagePrice = Math.round((totalPrices / totalBooks) * 100) / 100;

  // Math.min/Math.max com spread operator para encontrar extremos
  const minPrice = Math.min(...books.map((b) => b.price));
  const maxPrice = Math.max(...books.map((b) => b.price));

  // Contagem por gênero usando reduce (padrão funcional para agregação)
  const genres = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Autores únicos via Set (estrutura que elimina duplicatas automaticamente)
  const uniqueAuthors = new Set(books.map((b) => b.author)).size;

  res.json({
    status: 'success',
    data: {
      totalBooks,
      averagePrice,
      minPrice,
      maxPrice,
      genres,
      uniqueAuthors,
    },
  });
});

module.exports = router;
```

