## Arquivo 4: `src/app.js`

```javascript
/**
 * ============================================================================
 * CONFIGURAÇÃO PRINCIPAL DO APP EXPRESS
 * ============================================================================
 *
 * POR QUE SEPARAR app.js DE server.js?
 * --------------------------------------
 * - app.js configura o Express (middlewares, rotas) — lógica de aplicação
 * - server.js inicia o servidor HTTP e define a porta — infraestrutura
 *
 * Essa separação permite testar o app sem precisar iniciar um servidor,
 * facilitando testes unitários com supertest ou jest.
 *
 * ORDEM DOS MIDDLEWARES (IMPORTANTE):
 * ------------------------------------
 * 1. body-parser → parseia JSON do corpo da requisição
 * 2. Rotas        → processa as requisições
 * 3. errorHandler → captura ERROS lançados pelas rotas (DEPOIS das rotas!)
 */

const express = require('express');
const { errorHandler } = require('./middleware/errors');
const booksRouter = require('./routes/books');

const app = express();

// --------------------------------------------------------------------------
// MIDDLEWARE: Parse de JSON no corpo da requisição
// --------------------------------------------------------------------------
/**
 * express.json() converte automaticamente o corpo de requisições com
 * Content-Type: application/json em um objeto JavaScript acessível via req.body.
 * Sem isso, req.body seria undefined e não poderíamos receber dados no POST/PUT.
 */
app.use(express.json());

// --------------------------------------------------------------------------
// MIDDLEWARE: Log básico de requisições (para depuração)
// --------------------------------------------------------------------------
/**
 * Middleware simples que loga método, URL e timestamp de cada requisição.
 * Em produção, substituiríamos por um logger como Winston ou Pino.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Passa para o próximo middleware/rota
});

// --------------------------------------------------------------------------
// REGISTRO DAS ROTAS
// --------------------------------------------------------------------------
/**
 * Todas as rotas de livros são registradas sob o prefixo / (sem namespace)
 * porque este é um projeto pequeno. Em projetos maiores, usaríamos:
 *   app.use('/api/v1/books', booksRouter);
 */
app.use('/', booksRouter);

// --------------------------------------------------------------------------
// ROTA PARA RAÍZES — Documentação da API
// --------------------------------------------------------------------------
/**
 * GET / — Retorna informações básicas sobre a API.
 * Útil para verificar se o servidor está no ar (health check).
 */
app.get('/', (req, res) => {
  res.json({
    status: 'success',
    message: 'API de Livros — Exemplo Educacional',
    endpoints: {
      'GET /books': 'Listar todos os livros (com filtragem opcional)',
      'GET /books/:id': 'Obter livro por ID',
      'POST /books': 'Criar novo livro',
      'PUT /books/:id': 'Atualizar livro existente',
      'DELETE /books/:id': 'Excluir livro',
      'GET /stats': 'Estatísticas do acervo',
    },
  });
});

// --------------------------------------------------------------------------
// ROTA 404 — Tratamento de rotas inexistentes
// --------------------------------------------------------------------------
/**
 * Qualquer rota não definida cai neste middleware, retornando 404.
 * Deve vir ANTES do middleware de erros para que seja capturado corretamente.
 */
app.use((req, res, next) => {
  const { AppError } = require('./middleware/errors');
  next(new AppError(`Rota ${req.method} ${req.url} não encontrada.`, 404));
});

// --------------------------------------------------------------------------
// MIDDLEWARE DE ERROS — SEMPRE O ÚLTIMO
// --------------------------------------------------------------------------
/**
 * Deve ser o último app.use() registrado. Captura todos os erros lançados
 * pelas rotas e middlewares anteriores via next(err).
 */
app.use(errorHandler);

module.exports = app;
```

