  console.log(`🧪 Teste com: curl http://localhost:${PORT}/books`);
});

// Tratamento de erros não capturados no nível do processo
process.on('uncaughtException', (err) => {
  console.error('💥 UNCAUGHT EXCEPTION — encerrando o servidor...');
  console.error(err);
  server.close(() => process.exit(1));
});

process.on('unhandledRejection', (err) => {
  console.error('💥 UNHANDLED REJECTION — encerrando o servidor...');
  console.error(err);
  server.close(() => process.exit(1));
});
