## File 2: `server.js`

```javascript
/**
 * server.js — Main entry point for the Book REST API
 *
 * This file sets up the Express application, configures middleware,
 * mounts route handlers, and starts the HTTP server on port 3000.
 *
 * Why Express? It's lightweight, non-opinionated, and gives us full
 * control over routing and middleware — perfect for learning REST patterns.
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');

// Create an Express application instance.
// Each request to our API will flow through this app's middleware stack.
const app = express();

// ─────────────────────────────────────────────
// Middleware Configuration
// ─────────────────────────────────────────────

/**
 * express.json() — Parses incoming JSON request bodies.
 *
 * Without this, req.body would be undefined for POST/PUT requests.
 * We place it BEFORE route definitions so all routes can access parsed data.
 */
app.use(express.json());

// Optional: Log every request to the console (useful for debugging)
/**
 * Simple logging middleware — runs before every request.
 * Prints method, URL, and timestamp to stdout.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler
});

// ─────────────────────────────────────────────
// Route Mounting
// ─────────────────────────────────────────────

/**
 * Mount book routes under /books prefix.
 * All endpoints in routes/books.js will be accessible as:
 *   GET    /books
 *   GET    /books/:id
 *   POST   /books
 *   PUT    /books/:id
 *   DELETE /books/:id
 */
app.use('/books', bookRoutes);

/**
 * Mount stats route under /stats prefix.
 * Accessible as: GET /stats
 */
app.use('/stats', statsRoutes);

// ─────────────────────────────────────────────
// Error Handling Middleware
// ─────────────────────────────────────────────

/**
 * Express error-handling middleware must have 4 parameters (err, req, res, next).
 * It catches errors thrown by routes or middleware and sends a consistent JSON response.
 *
 * IMPORTANT: This MUST be the last app.use() call so it can intercept all errors.
 */
app.use(errorHandler);

// ─────────────────────────────────────────────
// Server Startup
// ─────────────────────────────────────────────

const PORT = process.env.PORT || 3000;

/**
 * Start the HTTP server and listen on the configured port.
 * The callback logs a confirmation message once the server is ready.
 */
app.listen(PORT, () => {
  console.log(`📚 Book API running at http://localhost:${PORT}`);
  console.log(`   Try: GET http://localhost:${PORT}/books`);
});
```

