## File 4: `middleware/errorHandler.js` — Custom Error Classes & Middleware

```javascript
/**
 * middleware/errorHandler.js — Centralized error handling
 *
 * WHY CUSTOM ERROR CLASSES? They let us distinguish between different
 * failure modes (not found vs validation error) and return appropriate
 * HTTP status codes consistently.
 *
 * WHY MIDDLEWARE? Express lets us define a special 4-argument function
 * that catches ALL unhandled errors — routes, middleware, even async rejections
 * if we wrap them properly. This keeps error logic out of individual routes.
 */

/**
 * Custom error class for "resource not found" situations.
 * Extends built-in Error so it works with instanceof checks.
 */
class NotFoundError extends Error {
  /**
   * @param {string} message — Human-readable description of the error
   */
  constructor(message) {
    super(message);
    this.name = 'NotFoundError';
    this.statusCode = 404; // HTTP 404 Not Found
  }
}

/**
 * Custom error class for invalid input / validation failures.
 * Returns HTTP 422 Unprocessable Entity (semantically correct for bad request bodies).
 */
class ValidationError extends Error {
  /**
   * @param {string} message — Description of what went wrong
   * @param {Array<{field: string, message: string}>} [details] — Optional field-level errors
   */
  constructor(message, details = []) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 422;
    this.details = details;
  }
}

/**
 * Central error-handling middleware.
 * Must be defined with (err, req, res, next) — Express recognizes this signature.
 *
 * @param {Error} err — The error object thrown somewhere in the request pipeline
 * @param {import('express').Request} req — Express request object
 * @param {import('express').Response} res — Express response object
 * @param {import('express').NextFunction} next — Express next middleware function
 */
function errorHandler(err, req, res, next) {
  // Determine status code: use the error's statusCode if set, otherwise default to 500
  const statusCode = err.statusCode || 500;

  // Build a consistent JSON error response shape
  const errorResponse = {
    success: false,
    error: {
      name: err.name,
      message: err.message,
    },
  };

  // Include validation details if present (helps clients fix specific fields)
  if (err.details && err.details.length > 0) {
    errorResponse.error.details = err.details;
  }

  // Log the full error stack in development for debugging
  if (process.env.NODE_ENV !== 'production') {
    console.error(err.stack);
  }

  // Send the JSON response — this ends the request cycle
  res.status(statusCode).json(errorResponse);
}

module.exports = { NotFoundError, ValidationError, errorHandler };
```

**Explanation:**  
- `NotFoundError` → 404; `ValidationError` → 422. These map to real HTTP semantics.  
- The middleware checks `err.statusCode` so custom errors carry their own status.  
- We always return `{ success: false, error: { ... } }` — clients can parse this uniformly.

