## File 5: `routes/books.js` — Book CRUD Routes

```javascript
/**
 * routes/books.js — RESTful routes for book resources
 *
 * Implements the full CRUD cycle:
 *   GET    /          → List all books (with optional filtering)
 *   GET    /:id       → Get a single book by ID
 *   POST   /          → Create a new book
 *   PUT    /:id       → Fully update an existing book
 *   DELETE /:id       → Delete a book by ID
 *
 * WHY SEPARATE ROUTE FILE? Keeps server.js clean and makes it easy to add
 * more resources (authors, genres) later without cluttering the main file.
 */

const express = require('express');
const router = express.Router(); // Creates a standalone route handler
const { books, nextId } = require('../data/books');
const { NotFoundError, ValidationError } = require('../middleware/errorHandler');

// ─────────────────────────────────────────────
// GET /books — List all books with optional filtering
// ─────────────────────────────────────────────

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * Query params supported:
 *   - genre      : Filter by exact genre match (e.g., ?genre=Fiction)
 *   - minRating  : Minimum rating threshold (e.g., ?minRating=4.5)
 *   - search     : Partial match on title or author (case-insensitive)
 *
 * @example GET /books?genre=Fiction&minRating=4.5
 * @example GET /books?search=hawking
 */
router.get('/', (req, res) => {
  // Start with the full list — we'll filter down based on query params
  let result = [...books];

  // Filter by genre if provided
  if (req.query.genre) {
    result = result.filter(book => book.genre.toLowerCase() === req.query.genre.toLowerCase());
  }

  // Filter by minimum rating if provided
  if (req.query.minRating) {
    const minRating = parseFloat(req.query.minRating);
    result = result.filter(book => book.rating >= minRating);
  }

  // Search title or author if provided
  if (req.query.search) {
    const searchLower = req.query.search.toLowerCase();
    result = result.filter(book =>
      book.title.toLowerCase().includes(searchLower) ||
      book.author.toLowerCase().includes(searchLower)
    );
  }

  // Return the (possibly filtered) list with a 200 OK status
  res.json({ success: true, data: result, count: result.length });
});

// ─────────────────────────────────────────────
// GET /books/:id — Get a single book by ID
// ─────────────────────────────────────────────

/**
 * Finds and returns a single book matching the given ID.
 * Throws NotFoundError if no match exists (caught by error middleware).
 *
 * @param {number} id — The numeric ID of the book to retrieve
 */
router.get('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);

  // Find the book in our in-memory array
  const book = books.find(b => b.id === id);

  if (!book) {
    // Throw a custom error — Express error middleware will handle the response
    throw new NotFoundError(`Book with ID ${id} not found`);
  }

  res.json({ success: true, data: book });
});

// ─────────────────────────────────────────────
// POST /books — Create a new book
// ─────────────────────────────────────────────

/**
 * Creates a new book from the request body and adds it to storage.
 * Validates all required fields before insertion.
 *
 * Expected JSON body:
 *   { "title": "...", "author": "...", "genre": "...", "publishedYear": ..., "rating": ... }
 *
 * All fields are required. Rating must be between 0 and 5.
 */
router.post('/', (req, res) => {
  const { title, author, genre, publishedYear, rating } = req.body;

  // ── Validation ──────────────────────────────────────────────
  const details = [];

  if (!title || typeof title !== 'string' || title.trim() === '') {
    details.push({ field: 'title', message: 'Title is required and must be a non-empty string' });
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    details.push({ field: 'author', message: 'Author is required and must be a non-empty string' });
  }
  if (!genre || typeof genre !== 'string' || genre.trim() === '') {
    details.push({ field: 'genre', message: 'Genre is required and must be a non-empty string' });
  }
  if (publishedYear === undefined || publishedYear === null || !Number.isInteger(publishedYear)) {
    details.push({ field: 'publishedYear', message: 'Published year is required and must be an integer' });
  }
  if (rating === undefined || rating === null || typeof rating !== 'number' || rating < 0 || rating > 5) {
    details.push({ field: 'rating', message: 'Rating is required and must be a number between 0 and 5' });
  }

  // If any validation failed, throw a ValidationError with field details
  if (details.length > 0) {
    throw new ValidationError('Invalid book data provided', details);
  }

  // ── Create the new book object ──────────────────────────────
  const newBook = {
    id: nextId++,          // Auto-increment ID from our counter
    title: title.trim(),
    author: author.trim(),
    genre: genre.trim(),
    publishedYear,
    rating,
  };

  // Add to in-memory storage
  books.push(newBook);

  // Return 201 Created with the new book — standard REST convention
  res.status(201).json({ success: true, data: newBook, message: 'Book created successfully' });
});

// ─────────────────────────────────────────────
// PUT /books/:id — Fully update an existing book
// ─────────────────────────────────────────────

/**
 * Replaces all fields of an existing book with the provided values.
 * The ID in the URL determines which book to update.
 *
 * Note: This is a FULL update (not PATCH). All fields must be present.
 */
router.put('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const index = books.findIndex(b => b.id === id);

  // Check if the book exists
  if (index === -1) {
    throw new NotFoundError(`Book with ID ${id} not found`);
  }

  const { title, author, genre, publishedYear, rating } = req.body;

  // Reuse the same validation logic as POST
  const details = [];
  if (!title || typeof title !== 'string' || title.trim() === '') {
    details.push({ field: 'title', message: 'Title is required and must be a non-empty string' });
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    details.push({ field: 'author', message: 'Author is required and must be a non-empty string' });
  }
  if (!genre || typeof genre !== 'string' || genre.trim() === '') {
    details.push({ field: 'genre', message: 'Genre is required and must be a non-empty string' });
  }
  if (publishedYear === undefined || publishedYear === null || !Number.isInteger(publishedYear)) {
    details.push({ field: 'publishedYear', message: 'Published year is required and must be an integer' });
  }
  if (rating === undefined || rating === null || typeof rating !== 'number' || rating < 0 || rating > 5) {
    details.push({ field: 'rating', message: 'Rating is required and must be a number between 0 and 5' });
  }

  if (details.length > 0) {
    throw new ValidationError('Invalid book data provided', details);
  }

  // Replace the entire book object at that index
  books[index] = {
    id,                              // Keep the original ID
    title: title.trim(),
    author: author.trim(),
    genre: genre.trim(),
    publishedYear,
    rating,
  };

  // Return 200 OK with the updated book
  res.json({ success: true, data: books[index], message: 'Book updated successfully' });
});

// ─────────────────────────────────────────────
// DELETE /books/:id — Delete a book by ID
// ─────────────────────────────────────────────

/**
 * Removes a book from storage by its ID.
 * Returns 204 No Content on success (standard for DELETE with no response body).
 */
router.delete('/:id', (req, res) => {
  const id = parseInt(req.params.id, 10);
  const index = books.findIndex(b => b.id === id);

  if (index === -1) {
    throw new NotFoundError(`Book with ID ${id} not found`);
  }

  // Remove the book from the array (splice returns the removed element(s))
  books.splice(index, 1);

  // 204 No Content — success but no body to return
  res.status(204).end();
});

module.exports = router;
```

**Explanation:**  
- Each route handler is a plain function — Express calls it with `(req, res)`.  
- `throw` instead of `res.send()` lets the error middleware handle responses uniformly.  
- Validation happens before any data mutation — fail fast, fail clearly.  
- `splice(index, 1)` removes exactly one element at the given index (efficient for small arrays).

