## File 6: `routes/stats.js` — Statistics Endpoint

```javascript
/**
 * routes/stats.js — Aggregate statistics about the book collection
 *
 * Provides summary metrics that require iterating over all books.
 * This demonstrates a non-CRUD endpoint that still follows REST conventions.
 */

const express = require('express');
const router = express.Router();
const { books } = require('../data/books');

/**
 * GET /stats — Return aggregate statistics about the book collection.
 *
 * Calculates:
 *   - totalBooks       : Total number of books in storage
 *   - averageRating    : Mean rating across all books (rounded to 2 decimals)
 *   - genreDistribution: Count of books per genre
 *   - oldestBook       : Book with the earliest published year
 *   - newestBook       : Book with the latest published year
 *   - topRatedBooks    : Up to 3 highest-rated books
 */
router.get('/', (req, res) => {
  const totalBooks = books.length;

  // Guard against empty collection
  if (totalBooks === 0) {
    return res.json({
      success: true,
      data: {
        totalBooks: 0,
        averageRating: 0,
        genreDistribution: {},
        oldestBook: null,
        newestBook: null,
        topRatedBooks: [],
      },
    });
  }

  // Calculate average rating
  const sumRatings = books.reduce((sum, book) => sum + book.rating, 0);
  const averageRating = Math.round((sumRatings / totalBooks) * 100) / 100;

  // Build genre distribution map
  const genreDistribution = {};
  for (const book of books) {
    genreDistribution[book.genre] = (genreDistribution[book.genre] || 0) + 1;
  }

  // Find oldest and newest books by publishedYear
  const oldestBook = books.reduce((oldest, book) =>
    book.publishedYear < oldest.publishedYear ? book : oldest
  );
  const newestBook = books.reduce((newest, book) =>
    book.publishedYear > newest.publishedYear ? book : newest
  );

  // Get top 3 rated books (sorted descending by rating)
  const topRatedBooks = [...books]
    .sort((a, b) => b.rating - a.rating)
    .slice(0, 3);

  res.json({
    success: true,
    data: {
      totalBooks,
      averageRating,
      genreDistribution,
      oldestBook,
      newestBook,
      topRatedBooks,
    },
  });
});

module.exports = router;
```

**Explanation:**  
- `reduce()` is ideal for aggregating values (sums, min/max) in a single pass.  
- We spread `[...books]` before sorting so we don't mutate the original array order.  
- The empty-collection guard prevents division-by-zero on `averageRating`.

