## Arquivo 2: `src/models/book.js`

```javascript
/**
 * ============================================================
 *  MÓDULO: book.js — Modelo de Dados (Camada de Persistência)
 * ============================================================
 *
 * POR QUE UM ARRAY EM MEMÓRIA?
 * ----------------------------
 * Para fins educacionais, usamos um array em memória porque:
 *   1. Elimina a necessidade de configurar banco de dados externo,
 *      permitindo que o foco permaneça nos conceitos de REST.
 *   2. Arrays oferecem acesso O(1) por índice (para busca por ID),
 *      e operações simples de inserção/remoção.
 *   3. Em produção, este módulo seria substituído por um repositório
 *      que consulta MongoDB, PostgreSQL, etc., mas a interface pública
 *      permaneceria a mesma — princípio da abstração de dados.
 *
 * POR QUE USAR SET PARA IDs?
 * --------------------------
 * Um Set (conjunto) garante unicidade de IDs em O(1), evitando
 * duplicatas sem necessidade de varrer todo o array.
 */

// ─────────────────────────────────────────────────────────────
//  CONFIGURAÇÃO E ESTADO GLOBAL
// ─────────────────────────────────────────────────────────────

/**
 * Array que armazena todos os livros em memória.
 * Cada livro é um objeto com as propriedades: id, title, author, year, genre.
 *
 * Escolha de array vs. objeto/mapa:
 *   - Array: bom para ordenação e iteração sequencial (listar tudo).
 *   - Mapa/Objeto: melhor para busca por chave.
 *   Como precisamos tanto listar quanto buscar por ID, usamos array + Set.
 */
const books = [];

/**
 * Set que armazena todos os IDs já utilizados.
 * Garante que nenhum livro novo receba um ID duplicado.
 * Complexidade: inserção e verificação em O(1).
 */
const usedIds = new Set();

/**
 * Contador sequencial para geração de IDs únicos.
 * Começa em 1 e incrementa a cada novo livro criado.
 * Em produção, usaríamos UUIDs ou um sequence do banco.
 */
let nextId = 1;

// ─────────────────────────────────────────────────────────────
//  DADOS INICIAIS (SEED)
// ─────────────────────────────────────────────────────────────

/**
 * Popula o array com livros de exemplo na inicialização.
 * Isso permite testar a API imediatamente sem precisar criar dados.
 */
const seedData = [
  { id: 1, title: 'Dom Casmurro', author: 'Machado de Assis', year: 1899, genre: 'Romance' },
  { id: 2, title: 'Memórias Póstumas de Brás Cubas', author: 'Machado de Assis', year: 1881, genre: 'Romance' },
  { id: 3, title: 'O Cortiço', author: 'Aluísio Azevedo', year: 1890, genre: 'Realismo' },
  { id: 4, title: 'Capitães da Areia', author: 'Jorge Amado', year: 1937, genre: 'Romance' },
  { id: 5, title: 'Grande Sertão: Veredas', author: 'Guimarães Rosa', year: 1956, genre: 'Romance' },
];

/**
 * Insere os dados iniciais no array e no Set de IDs.
 * Chamada automaticamente ao carregar o módulo.
 */
seedData.forEach((book) => {
  books.push(book);
  usedIds.add(book.id);
});

// Atualiza nextId para o próximo valor disponível
nextId = Math.max(...usedIds) + 1;

// ─────────────────────────────────────────────────────────────
//  FUNÇÕES DO MODELO (Camada de Negócio)
// ─────────────────────────────────────────────────────────────

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array<Object>} Lista completa de livros.
 */
function findAll() {
  return [...books]; // Retorna cópia para evitar mutação externa direta
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - O identificador único do livro.
 * @returns {Object|null} O livro encontrado, ou null se não existir.
 */
function findById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Cria um novo livro com ID autogerado.
 * Valida os campos obrigatórios antes de inserir.
 *
 * @param {Object} data - Dados do novo livro.
 * @param {string} data.title - Título do livro (obrigatório).
 * @param {string} data.author - Autor do livro (obrigatório).
 * @param {number} data.year - Ano de publicação (opcional, mas recomendado).
 * @param {string} data.genre - Gênero literário (opcional).
 * @returns {Object} O livro criado com ID atribuído.
 * @throws {Error} Se o título ou autor estiverem ausentes.
 */
function create(data) {
  // Validação básica dos campos obrigatórios
  if (!data.title || data.title.trim() === '') {
    throw new Error('O campo "title" é obrigatório.');
  }
  if (!data.author || data.author.trim() === '') {
    throw new Error('O campo "author" é obrigatório.');
  }

  const newBook = {
    id: nextId++,
    title: data.title.trim(),
    author: data.author.trim(),
    year: data.year ? Number(data.year) : null,
    genre: data.genre ? data.genre.trim() : null,
  };

  books.push(newBook);
  usedIds.add(newBook.id);
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 * Campos não fornecidos na requisição são mantidos (partial update).
 *
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Object} updates - Campos a serem atualizados.
 * @returns {Object|null} O livro atualizado, ou null se não encontrado.
 */
function update(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Atualiza apenas os campos presentes em updates
  if (updates.title !== undefined) books[index].title = updates.title.trim();
  if (updates.author !== undefined) books[index].author = updates.author.trim();
  if (updates.year !== undefined) books[index].year = Number(updates.year);
  if (updates.genre !== undefined) books[index].genre = updates.genre.trim() || null;

  return { ...books[index] }; // Retorna cópia para imutabilidade
}

/**
 * Remove um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser removido.
 * @returns {boolean} True se foi removido, false caso contrário.
 */
function remove(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1);
  usedIds.delete(id);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o acervo de livros.
 *
 * @returns {Object} Estatísticas com total, média de anos, gêneros e autores.
 */
function getStats() {
  const total = books.length;

  // Filtra apenas livros com ano definido para calcular a média
  const booksWithYear = books.filter((b) => b.year !== null);
  const avgYear =
    booksWithYear.length > 0
      ? Math.round(booksWithYear.reduce((sum, b) => sum + b.year, 0) / booksWithYear.length)
      : null;

  // Conta ocorrências por gênero usando reduce (padrão funcional)
  const genres = {};
  books.forEach((book) => {
    if (book.genre) {
      genres[book.genre] = (genres[book.genre] || 0) + 1;
    }
  });

  // Lista autores únicos
  const authors = [...new Set(books.map((b) => b.author))];

  return { total, avgYear, genres, authors };
}

// ─────────────────────────────────────────────────────────────
//  EXPORTAÇÃO (Padrão CommonJS)
// ─────────────────────────────────────────────────────────────

/**
 * Exporta todas as funções do modelo para uso nas rotas.
 * O padrão module.exports é o padrão do Node.js (CommonJS).
 * Em projetos modernos com ES Modules, usaríamos export default.
 */
module.exports = { findAll, findById, create, update, remove, getStats };
```

