## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 *  MÓDULO: errorHandler.js — Middleware de Tratamento de Erros
 * ============================================================
 *
 * POR QUE UM MIDDLEWARE DE ERROS?
 * --------------------------------
 * No Express, middlewares de erro têm a assinatura especial de
 * 4 parâmetros: (err, req, res, next). Eles capturam erros que
 * escaparam do fluxo normal e padronizam respostas de erro.
 *
 * Isso evita que cada rota precise de try/catch manual para
 * erros conhecidos, mantendo o código das rotas mais limpo.
 */

/**
 * Classe base para erros personalizados da API.
 * Herda de Error e adiciona propriedades específicas:
 *   - statusCode: código HTTP da resposta (padrão 400).
 *   - isOperational: indica se o erro é esperado (true) ou
 *     um bug do servidor (false, para logs internos).
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem de erro legível ao cliente.
   * @param {number} statusCode - Código HTTP da resposta (padrão 400).
   */
  constructor(message, statusCode = 400) {
    super(message); // Chama o construtor da classe Error
    this.statusCode = statusCode;
    this.isOperational = true; // Erro esperado, não um bug do servidor
  }
}

/**
 * Middleware que captura erros e retorna respostas padronizadas.
 * Deve ser registrado POR ÚLTIMO, após todas as rotas.
 *
 * @param {Error} err - O erro capturado.
 * @param {Object} req - Objeto de requisição do Express.
 * @param {Object} res - Objeto de resposta do Express.
 * @param {Function} next - Função next do Express (não usada aqui).
 */
function errorHandler(err, req, res, next) {
  // Se o erro é da nossa classe ApiError, usamos sua mensagem e status
  if (err instanceof ApiError) {
    return res.status(err.statusCode).json({
      success: false,
      error: err.message,
    });
  }

  // Para erros não tratados (bugs do servidor), retornamos 500
  console.error('Erro não tratado:', err); // Log para depuração
  return res.status(500).json({
    success: false,
    error: 'Erro interno do servidor. Tente novamente mais tarde.',
  });
}

module.exports = { ApiError, errorHandler };
```

