## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================
 *  MÓDULO: books.js — Rotas da API de Livros
 * ============================================================
 *
 * POR QUE ROTAS SEPARADAS?
 * -------------------------
 * Separar rotas em módulos distintos permite:
 *   1. Escalabilidade: adicionar novas entidades sem poluir o app principal.
 *   2. Testabilidade: cada módulo de rota pode ser testado isoladamente.
 *   3. Legibilidade: o arquivo app.js permanece limpo e focado na configuração.
 *
 * PADRÃO REST ADOTADO:
 * ---------------------
 *   GET    /books          → Listar todos (com filtragem opcional)
 *   GET    /books/:id      → Obter um livro pelo ID
 *   POST   /books          → Criar novo livro
 *   PUT    /books/:id      → Atualizar livro existente (full update)
 *   DELETE /books/:id      → Excluir livro
 *   GET    /stats          → Estatísticas do acervo
 *
 * EXEMPLOS DE CURL:
 * -----------------
 *   # Listar todos os livros
 *   curl http://localhost:3000/books
 *
 *   # Filtrar por gênero
 *   curl "http://localhost:3000/books?genre=Romance"
 *
 *   # Buscar por ID
 *   curl http://localhost:3000/books/1
 *
 *   # Criar novo livro
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Alienista","author":"Machado de Assis","year":1882,"genre":"Sátira"}'
 *
 *   # Atualizar livro (PUT = substituição completa dos campos enviados)
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dom Casmurro (Ed. Crítica)","author":"Machado de Assis","year":1899,"genre":"Romance"}'
 *
 *   # Excluir livro
 *   curl -X DELETE http://localhost:3000/books/1
 *
 *   # Estatísticas
 *   curl http://localhost:3000/stats
 */

const express = require('express');
const router = express.Router(); // Cria um roteador independente
const { findAll, findById, create, update, remove, getStats } = require('../models/book');
const { ApiError } = require('../middleware/errorHandler');

// ─────────────────────────────────────────────────────────────
//  GET /books — Listar todos os livros (com filtragem opcional)
// ─────────────────────────────────────────────────────────────

/**
 * Endpoint: GET /books
 *
 * Retorna uma lista de todos os livros. Suporta filtragem via query params:
 *   - genre: filtra por gênero literário (ex: ?genre=Romance)
 *   - author: filtra por autor (busca parcial, case-insensitive)
 *   - search: busca por título ou autor (ambos)
 *
 * Exemplos de requisição:
 *   GET /books                          → todos os livros
 *   GET /books?genre=Romance            → apenas romances
 *   GET /books?author=machado           → livros de Machado (parcial)
 *   GET /books?search=cortiço           → busca por título/autor
 */
router.get('/books', (req, res, next) => {
  try {
    // Pega os parâmetros de query string (todos são opcionais)
    const { genre, author, search } = req.query;

    // Começa com a lista completa e aplica filtros sequencialmente
    let result = findAll();

    if (genre) {
      // Filtra por gênero (comparação exata, case-insensitive)
      result = result.filter((book) => book.genre?.toLowerCase() === genre.toLowerCase());
    }

    if (author) {
      // Busca parcial no nome do autor (ex: "machado" encontra "Machado de Assis")
      const authorLower = author.toLowerCase();
      result = result.filter((book) => book.author?.toLowerCase().includes(authorLower));
    }

    if (search) {
      // Busca em título E autor simultaneamente
      const searchLower = search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title?.toLowerCase().includes(searchLower) ||
          book.author?.toLowerCase().includes(searchLower)
      );
    }

    // Resposta padronizada com campo "success" para consistência
    res.json({ success: true, count: result.length, data: result });
  } catch (err) {
    next(err); // Encaminha erro ao middleware de tratamento
  }
});

// ─────────────────────────────────────────────────────────────
//  GET /books/:id — Obter um livro pelo ID
// ─────────────────────────────────────────────────────────────

/**
 * Endpoint: GET /books/:id
 *
 * Retorna os detalhes de um único livro identificado pelo parâmetro de rota :id.
 * O ID deve ser um número inteiro positivo.
 *
 * Exemplo de requisição:
 *   GET /books/1
 */
router.get('/books/:id', (req, res, next) => {
  try {
    // Converte o parâmetro de rota para número e valida
    const id = Number(req.params.id);

    if (isNaN(id) || id < 1) {
      throw new ApiError('O ID deve ser um número inteiro positivo.', 400);
    }

    const book = findById(id);
    if (!book) {
      // Lança erro operacional (não é bug, é dado inexistente)
      throw new ApiError(`Livro com ID ${id} não encontrado.`, 404);
    }

    res.json({ success: true, data: book });
  } catch (err) {
    next(err);
  }
});

// ─────────────────────────────────────────────────────────────
//  POST /books — Criar um novo livro
// ─────────────────────────────────────────────────────────────

/**
 * Endpoint: POST /books
 *
 * Cria um novo livro a partir dos dados enviados no corpo da requisição (JSON).
 * Campos obrigatórios: title, author.
 * Campos opcionais: year, genre.
 *
 * Exemplo de requisição (curl):
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"A Hora da Estrela","author":"Clarice Lispector","year":1977,"genre":"Romance"}'
 *
 * Resposta de sucesso (201 Created):
 *   { "success": true, "data": { "id": 6, "title": "...", ... } }
 */
router.post('/books', (req, res, next) => {
  try {
    // Valida se o corpo da requisição é um objeto JSON válido
    if (!req.body || typeof req.body !== 'object') {
      throw new ApiError('O corpo da requisição deve ser um objeto JSON.', 400);
    }

    const newBook = create(req.body);
    // 201 Created indica que um recurso foi criado com sucesso
    res.status(201).json({ success: true, data: newBook });
  } catch (err) {
    next(err);
  }
});

// ─────────────────────────────────────────────────────────────
//  PUT /books/:id — Atualizar um livro existente
// ─────────────────────────────────────────────────────────────

/**
 * Endpoint: PUT /books/:id
 *
 * Atualiza completamente um livro existente. Todos os campos enviados
 * no corpo substituem os valores atuais. Campos não enviados são mantidos.
 *
 * Diferença entre PUT e PATCH:
 *   - PUT: substituição completa (o que você envia é o que fica).
 *   - PATCH: atualização parcial (apenas os campos enviados mudam).
 *   Aqui usamos PUT com comportamento de partial update para praticidade.
 *
 * Exemplo de requisição (curl):
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Dom Casmurro","author":"Machado de Assis","year":1899,"genre":"Romance"}'
 */
router.put('/books/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id) || id < 1) {
      throw new ApiError('O ID deve ser um número inteiro positivo.', 400);
    }

    // Verifica se o livro existe antes de tentar atualizar
    const existing = findById(id);
    if (!existing) {
      throw new ApiError(`Livro com ID ${id} não encontrado.`, 404);
    }

    const updatedBook = update(id, req.body);
    res.json({ success: true, data: updatedBook });
  } catch (err) {
    next(err);
  }
});

// ─────────────────────────────────────────────────────────────
//  DELETE /books/:id — Excluir um livro
// ─────────────────────────────────────────────────────────────

/**
 * Endpoint: DELETE /books/:id
 *
 * Remove permanentemente um livro pelo seu ID.
 *
 * Exemplo de requisição (curl):
 *   curl -X DELETE http://localhost:3000/books/1
 *
 * Resposta de sucesso (200 OK):
 *   { "success": true, "message": "Livro excluído com sucesso." }
 */
router.delete('/books/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id) || id < 1) {
      throw new ApiError('O ID deve ser um número inteiro positivo.', 400);
    }

    const deleted = remove(id);
    if (!deleted) {
      throw new ApiError(`Livro com ID ${id} não encontrado.`, 404);
    }

    // 200 OK com mensagem de confirmação
    res.json({ success: true, message: 'Livro excluído com sucesso.' });
  } catch (err) {
    next(err);
  }
});

// ─────────────────────────────────────────────────────────────
//  GET /stats — Estatísticas do acervo
// ─────────────────────────────────────────────────────────────

/**
 * Endpoint: GET /stats
 *
 * Retorna estatísticas agregadas sobre o acervo de livros:
 *   - total: quantidade total de livros
 *   - avgYear: ano médio de publicação (arredondado)
 *   - genres: contagem de livros por gênero
 *   - authors: lista de autores únicos
 *
 * Exemplo de requisição:
 *   GET /stats
 *
 * Resposta de exemplo:
 *   {
 *     "success": true,
 *     "data": {
 *       "total": 5,
 *       "avgYear": 1903,
 *       "genres": { "Romance": 4, "Realismo": 1 },
 *       "authors": ["Machado de Assis", "Aluísio Azevedo", "Jorge Amado", "Guimarães Rosa"]
 *     }
 *   }
 */
router.get('/stats', (req, res, next) => {
  try {
    const stats = getStats();
    res.json({ success: true, data: stats });
  } catch (err) {
    next(err);
  }
});

// ─────────────────────────────────────────────────────────────
//  EXPORTAÇÃO DO ROTEADOR
// ─────────────────────────────────────────────────────────────

module.exports = router;
```

