## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================
 *  ARQUIVO: app.js — Ponto de Entrada da Aplicação
 * ============================================================
 *
 * ESTRUTURA DE INICIALIZAÇÃO DO EXPRESS:
 * ---------------------------------------
 * 1. Criar a instância do app Express.
 * 2. Configurar middlewares globais (body-parser, CORS).
 * 3. Registrar as rotas da API.
 * 4. Registrar o middleware de tratamento de erros (SEMPRE por último).
 * 5. Iniciar o servidor em uma porta.
 *
 * POR QUE USAR async/await?
 * --------------------------
 * Embora esta API seja simples e síncrona (array em memória),
 * usamos a estrutura que suporta async/await para que, ao migrar
 * para um banco de dados real, as rotas já estejam preparadas.
 * O Express trata funções assíncronas nas rotas automaticamente,
 * encaminhando erros ao middleware de erro sem necessidade de
 * try/catch explícito em cada handler (embora tenhamos mantido
 * para validações síncronas).
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const { errorHandler } = require('./middleware/errorHandler');

// Cria a instância principal do aplicativo Express
const app = express();

// ─────────────────────────────────────────────────────────────
//  MIDDLEWARES GLOBAIS
// ─────────────────────────────────────────────────────────────

/**
 * Middleware que faz o parse do corpo das requisições JSON.
 * Converte automaticamente o body de requests com Content-Type: application/json
 * em um objeto JavaScript acessível via req.body.
 * limit: '10kb' evita payloads excessivamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware que faz o parse do corpo das requisições com formato x-www-form-urlencoded.
 * Necessário para formulários HTML tradicionais (menos comum em APIs REST).
 */
app.use(express.urlencoded({ extended: true }));

// ─────────────────────────────────────────────────────────────
//  ROTAS DA API
// ─────────────────────────────────────────────────────────────

/**
 * Registra as rotas de livros sob o prefixo /api.
 * Isso permite, no futuro, adicionar outras entidades sem conflito:
 *   /api/books, /api/authors, etc.
 */
app.use('/api', bookRoutes);

// ─────────────────────────────────────────────────────────────
//  ROTA DE HEALTH CHECK (Bônus)
// ─────────────────────────────────────────────────────────────

/**
 * Endpoint simples para verificar se a API está respondendo.
 * Útil para monitoramento e testes de conectividade.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ─────────────────────────────────────────────────────────────
//  ROTA 404 — Tratamento de rotas inexistentes
// ─────────────────────────────────────────────────────────────

/**
 * Middleware que captura requisições para rotas não definidas.
 * Deve ser registrado ANTES do middleware de erro.
 */
app.use((req, res, next) => {
  const { ApiError } = require('./middleware/errorHandler');
  next(new ApiError(`Rota ${req.method} ${req.path} não encontrada.`, 404));
});

// ─────────────────────────────────────────────────────────────
//  MIDDLEWARE DE TRATAMENTO DE ERROS (SEMPRE POR ÚLTIMO)
// ─────────────────────────────────────────────────────────────

/**
 * Middleware de erro do Express.
 * Deve ser o último middleware registrado.
 * Captura erros lançados por rotas e middlewares anteriores.
 */
app.use(errorHandler);

// ─────────────────────────────────────────────────────────────
//  INICIALIZAÇÃO DO SERVIDOR
// ─────────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000; // Porta configurável via variável de ambiente

/**
 * Inicia o servidor e faz log da porta de escuta.
 * O callback é chamado apenas após o servidor começar a ouvir.
 */
app.listen(PORT, () => {
  console.log(`✅ Servidor rodando em http://localhost:${PORT}`);
  console.log(`📚 API de Livros — endpoints disponíveis em http://localhost:${PORT}/api`);
});

module.exports = app; // Exporta para testes unitários
```

