```javascript
/**
 * ============================================================================
 * CUSTOM ERROR CLASSES
 * ============================================================================
 *
 * WHY custom error classes?
 *   JavaScript's built-in Error class is generic — it carries no semantic
 *   meaning about WHAT went wrong. By creating subclasses (NotFoundError,
 *   ValidationError, etc.), we can:
 *     1. Distinguish error types in our middleware without string-matching.
 *     2. Attach additional properties (e.g., missingFields on ValidationError).
 *     3. Return appropriate HTTP status codes automatically.
 *
 * PATTERN used: Each class extends Error and sets a descriptive `name`
 * property so that console output is readable. We also call super(message)
 * to preserve the standard Error stack trace.
 */

/**
 * BaseError — not used directly, but provides a common structure for all
 * custom errors in this application.
 */
class BaseError extends Error {
  /**
   * @param {string} message - Human-readable description of the error.
   * @param {number} statusCode - HTTP status code to return (default: 500).
   */
  constructor(message, statusCode = 500) {
    super(message); // Call parent Error constructor — preserves stack trace.
    this.name = this.constructor.name; // e.g., "NotFoundError" instead of "Error".
    this.statusCode = statusCode;      // Store status code as a property for middleware.
  }
}

/**
 * NotFoundError — thrown when a requested resource does not exist.
 *
 * EXAMPLE: A client requests GET /books/999 but no book with that ID exists.
 * HTTP convention: 404 Not Found.
 */
class NotFoundError extends BaseError {
  constructor(resource, id) {
    // Build a descriptive message: "Book not found with id 999"
    super(`${resource} not found with id ${id}`, 404);
    this.resource = resource; // Store which resource was looked up (e.g., "Book").
    this.id = id;             // Store the ID that wasn't found.
  }
}

/**
 * ValidationError — thrown when client input fails validation checks.
 *
 * EXAMPLE: A POST /books request omits the required "title" field.
 * HTTP convention: 400 Bad Request.
 *
 * ADDITIONAL PROPERTY: `details` is an array of { field, message } objects
 * so the client knows exactly which fields are problematic.
 */
class ValidationError extends BaseError {
  /**
   * @param {string} message - General description of the validation failure.
   * @param {Array<{field: string, message: string}>} details - Specific field-level errors.
   */
  constructor(message, details = []) {
    super(message, 400);
    this.details = details; // Attach detailed per-field error information.
  }
}

/**
 * ConflictError — thrown when a request conflicts with the current state.
 *
 * EXAMPLE: Creating a book with an ID that already exists.
 * HTTP convention: 409 Conflict.
 */
class ConflictError extends BaseError {
  constructor(message) {
    super(message, 409);
  }
}

/**
 * Export all error classes so other modules can import and throw them.
 * Using named exports makes it clear which errors are available.
 */
module.exports = { BaseError, NotFoundError, ValidationError, ConflictError };
```

