## File 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE
 * ============================================================================
 *
 * WHY middleware for error handling?
 *   Express supports a special "error-handling" middleware signature:
 *     function(err, req, res, next) { ... }
 *   By placing this at the END of our middleware stack, it catches ALL errors
 *   — whether thrown synchronously, passed via next(err), or returned from
 *   async handlers. This is far superior to try/catch in every route handler
 *   because:
 *     1. We write error handling ONCE instead of repeating it everywhere.
 *     2. Async errors (unhandled promise rejections) are caught here too.
 *     3. The response format is consistent across all error types.
 *
 * PATTERN: Express middleware runs in order. Normal routes call next() on
 * success; if anything calls next(err), Express skips remaining normal
 * middleware and jumps to this error handler.
 */

const { NotFoundError, ValidationError } = require('../errors/customErrors');

/**
 * errorHandler — Centralized Express error-handling middleware.
 *
 * @param {Error} err - The error object (any type).
 * @param {import('express').Request} req - The HTTP request object.
 * @param {import('express').Response} res - The HTTP response object.
 * @param {import('express').NextFunction} next - Express next function (unused here).
 */
function errorHandler(err, req, res, next) {
  // Log the full error to the server console for debugging.
  // In production, you might send this to a logging service instead.
  console.error(`[ERROR] ${new Date().toISOString()} — ${err.name}: ${err.message}`);

  // Determine the HTTP status code:
  //   - Custom errors carry their own statusCode property (set in constructor).
  //   - Unknown/generic errors default to 500 (Internal Server Error).
  const statusCode = err.statusCode || 500;

  // Build a consistent JSON response shape for ALL errors.
  // This lets clients parse error responses uniformly.
  const responseBody = {
    success: false,           // Standard field indicating the request failed.
    error: {
      type: err.name,         // e.g., "NotFoundError" — helps client identify issue.
      message: err.message,   // Human-readable description.
    },
  };

  // Attach additional details if available (e.g., validation field errors).
  if (err.details && Array.isArray(err.details) && err.details.length > 0) {
    responseBody.error.details = err.details;
  }

  // Send the JSON response with the appropriate status code.
  res.status(statusCode).json(responseBody);
}

/**
 * Export the middleware function so app.js can register it with app.use().
 */
module.exports = errorHandler;
```

