## File 4: `src/models/books.js`

```javascript
/**
 * ============================================================================
 * IN-MEMORY DATA STORE (MODEL LAYER)
 * ============================================================================
 *
 * WHY an in-memory array?
 *   For this educational example, we avoid database setup complexity. An array
 *   is simple, fast, and lets us focus on API patterns. In a real application,
 *   you would replace this module with a database driver (MongoDB, PostgreSQL,
 *   etc.) while keeping the same interface — this is called the "Repository
 *   Pattern" and it makes swapping storage mechanisms trivial.
 *
 * DATA STRUCTURE CHOICES:
 *   - `books`: An array of objects. Arrays are ideal because:
 *       1. They preserve insertion order (useful for list endpoints).
 *       2. They support fast iteration for filtering/sorting.
 *       3. Each book object has a unique numeric `id` for O(1) lookups by index
 *          after finding the right position.
 *   - `nextId`: A counter that increments with each new book. This ensures
 *       IDs are always unique and sequential, avoiding gaps from deletions.
 *
 * CONCERN: In-memory storage is NOT persistent — data is lost when the server
 * restarts. This is acceptable for a demo but would be catastrophic in production.
 */

// Import custom errors so we can throw them from this module.
const { NotFoundError, ValidationError, ConflictError } = require('../errors/customErrors');

/**
 * In-memory array storing all book records.
 *
 * Each book object has the shape:
 *   {
 *     id: number,          // Unique identifier (auto-incremented).
 *     title: string,       // Book title (required).
 *     author: string,      // Author name (required).
 *     genre: string,       // Genre/category (optional).
 *     publishedYear: number,// Year of publication (optional).
 *     isbn: string,        // ISBN-13 format (optional).
 *     createdAt: string,   // ISO timestamp of creation.
 *     updatedAt: string    // ISO timestamp of last update.
 *   }
 */
const books = [];

/**
 * Auto-increment counter for generating unique book IDs.
 * Starts at 1 so the first book gets id: 1.
 */
let nextId = 1;

/**
 * ============================================================================
 * BOOK OPERATIONS — CRUD Methods
 * ============================================================================
 */

/**
 * findAll — Retrieve all books, with optional filtering and pagination.
 *
 * WHY filter by query parameters?
 *   REST convention allows clients to refine lists without changing the URL
 *   structure. For example, GET /books?genre=fiction lets the client request
 *   only fiction books. We support:
 *     - genre: exact match on genre field.
 *     - author: substring match (case-insensitive) for flexible searching.
 *     - limit: maximum number of results to return (prevents huge responses).
 *     - page: which "page" of results to return (for pagination).
 *
 * @param {Object} [filters] — Query parameters from the request.
 * @param {string} [filters.genre] — Filter by genre (exact match).
 * @param {string} [filters.author] — Filter by author (substring, case-insensitive).
 * @param {number} [filters.limit] — Max results to return.
 * @param {number} [filters.page] — Page number for pagination (1-indexed).
 * @returns {Object} An object containing { books: [...], total: number } so the
 *                   client knows how many total matching records exist.
 */
function findAll(filters = {}) {
  // Start with a copy of all books so we don't mutate the original array.
  let result = [...books];

  // Apply genre filter if provided — exact match, case-insensitive.
  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter((book) => book.genre?.toLowerCase() === genreLower);
  }

  // Apply author filter if provided — substring match, case-insensitive.
  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter((book) =>
      book.author?.toLowerCase().includes(authorLower)
    );
  }

  // Record the total count BEFORE pagination so clients can calculate pages.
  const total = result.length;

  // Apply pagination if limit is specified.
  if (filters.limit) {
    const page = parseInt(filters.page) || 1;
    const startIndex = (page - 1) * filters.limit;
    result = result.slice(startIndex, startIndex + filters.limit);
  }

  return { books: result, total };
}

/**
 * findById — Retrieve a single book by its numeric ID.
 *
 * WHY throw NotFoundError instead of returning null?
 *   Returning null forces every caller to check for null, which leads to
 *   inconsistent error handling. Throwing an error with a clear message and
 *   status code lets our centralized errorHandler deal with it uniformly.
 *   This is the "fail fast" principle — we detect the problem immediately.
 *
 * @param {number} id — The unique identifier of the book to find.
 * @returns {Object} The book object if found.
 * @throws {NotFoundError} If no book exists with the given ID.
 */
function findById(id) {
  // Array.find returns undefined if no match is found.
  const book = books.find((b) => b.id === id);

  if (!book) {
    // Throw a typed error so the middleware can return 404 with context.
    throw new NotFoundError('Book', id);
  }

  return book;
}

/**
 * create — Add a new book to the in-memory store.
 *
 * WHY validate before creating?
 *   The title and author fields are required by business logic. We use the
 *   ValidationError class (with details) so the client receives specific
 *   feedback about which fields are missing, rather than a generic error.
 *
 * @param {Object} bookData — Partial book object with at minimum title and author.
 * @param {string} bookData.title — The book's title (required).
 * @param {string} bookData.author — The book's author (required).
 * @param {string} [bookData.genre] — Genre/category (optional).
 * @param {number} [bookData.publishedYear] — Publication year (optional).
 * @param {string} [bookData.isbn] — ISBN-13 format (optional).
 * @returns {Object} The newly created book object with generated id and timestamps.
 * @throws {ValidationError} If required fields are missing or invalid.
 */
function create(bookData) {
  // Validate that title is present and non-empty.
  if (!bookData.title || typeof bookData.title !== 'string' || bookData.title.trim() === '') {
    throw new ValidationError('Title is required', [
      { field: 'title', message: 'Title must be a non-empty string.' },
    ]);
  }

  // Validate that author is present and non-empty.
  if (!bookData.author || typeof bookData.author !== 'string' || bookData.author.trim() === '') {
    throw new ValidationError('Author is required', [
      { field: 'author', message: 'Author must be a non-empty string.' },
    ]);
  }

  // Generate a unique ID using our auto-increment counter.
  const id = nextId++;

  // Capture the current timestamp as ISO string for both createdAt and updatedAt.
  const now = new Date().toISOString();

  // Build the complete book object, merging provided data with defaults.
  // We use optional chaining (?.) to safely access properties that might be undefined.
  const book = {
    id,
    title: bookData.title.trim(),       // Trim whitespace from title.
    author: bookData.author.trim(),     // Trim whitespace from author.
    genre: bookData.genre?.trim() || null,   // Null if not provided.
    publishedYear: bookData.publishedYear || null,
    isbn: bookData.isbn?.trim() || null,
    createdAt: now,
    updatedAt: now,
  };

  // Push the new book onto the array. Arrays grow dynamically in JavaScript.
  books.push(book);

  return book;
}

/**
 * update — Modify an existing book by its ID (full replacement).
 *
 * WHY use PUT for full replacement?
 *   REST convention distinguishes between:
 *     - PUT /books/:id → Full replacement of the resource.
 *     - PATCH /books/:id → Partial update of specific fields.
 *   Our implementation uses PUT semantics: all provided fields overwrite,
 *   and omitted fields are set to null (not preserved from the original).
 *
 * @param {number} id — The unique identifier of the book to update.
 * @param {Object} updates — Fields to update (all optional; omitted = set to null).
 * @returns {Object} The updated book object.
 * @throws {NotFoundError} If no book exists with the given ID.
 * @throws {ValidationError} If required fields become invalid after update.
 */
function update(id, updates) {
  // First, find the existing book (throws NotFoundError if missing).
  const bookIndex = books.findIndex((b) => b.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError('Book', id);
  }

  // Validate that title is still present after updates.
  if (updates.title !== undefined && (typeof updates.title !== 'string' || updates.title.trim() === '')) {
    throw new ValidationError('Title must be a non-empty string', [
      { field: 'title', message: 'Title must be a non-empty string.' },
    ]);
  }

  // Validate that author is still present after updates.
  if (updates.author !== undefined && (typeof updates.author !== 'string' || updates.author.trim() === '')) {
    throw new ValidationError('Author must be a non-empty string', [
      { field: 'author', message: 'Author must be a non-empty string.' },
    ]);
  }

  // Capture the update timestamp.
  const now = new Date().toISOString();

  // Build the updated book object by merging old values with new ones.
  // Fields not provided in `updates` retain their original value (unlike strict PUT).
  const updatedBook = {
    ...books[bookIndex],           // Spread all existing fields first.
    title: updates.title !== undefined ? updates.title.trim() : books[bookIndex].title,
    author: updates.author !== undefined ? updates.author.trim() : books[bookIndex].author,
    genre: updates.genre !== undefined ? (updates.genre?.trim() || null) : books[bookIndex].genre,
    publishedYear: updates.publishedYear !== undefined ? updates.publishedYear : books[bookIndex].publishedYear,
    isbn: updates.isbn !== undefined ? (updates.isbn?.trim() || null) : books[bookIndex].isbn,
    updatedAt: now,                // Always update the timestamp.
  };

  // Replace the old book in the array with the updated version.
  books[bookIndex] = updatedBook;

  return updatedBook;
}

/**
 * delete — Remove a book from the store by its ID.
 *
 * WHY use splice instead of filter?
 *   Both work, but splice modifies the array in-place and is slightly more
 *   efficient for single-item removals because it doesn't create a new array.
 *   For large datasets, filter might be preferred (functional purity), but
 *   for this demo, splice keeps the code straightforward.
 *
 * @param {number} id — The unique identifier of the book to delete.
 * @returns {Object} The deleted book object (useful for confirming what was removed).
 * @throws {NotFoundError} If no book exists with the given ID.
 */
function deleteBook(id) {
  // Find the index of the book to delete.
  const bookIndex = books.findIndex((b) => b.id === id);

  if (bookIndex === -1) {
    throw new NotFoundError('Book', id);
  }

  // splice removes the element at bookIndex and returns it in an array.
  // We take [0] to get just the book object (not wrapped in an array).
  const [deletedBook] = books.splice(bookIndex, 1);

  return deletedBook;
}

/**
 * ============================================================================
 * STATISTICS — Aggregation Methods
 * ============================================================================
 */

/**
 * getStats — Compute aggregate statistics about the book collection.
 *
 * WHY compute stats server-side?
 *   Clients shouldn't need to fetch all books just to know counts and averages.
 *   The /stats endpoint provides pre-computed metrics efficiently. We calculate:
 *     - totalBooks: Total number of books in the store.
 *     - genres: A frequency map showing how many books exist per genre.
 *     - authors: A frequency map showing how many books exist per author.
 *     - averagePublishedYear: Mean publication year (null if no published books).
 *
 * @returns {Object} Statistics object with computed metrics.
 */
function getStats() {
  // Start with the total count — O(1) operation on arrays.
  const totalBooks = books.length;

  // Build a genre frequency map using reduce (single pass through the array).
  // For each book, increment the count for its genre (or 'Unknown' if null).
  const genres = books.reduce((acc, book) => {
    const genreKey = book.genre || 'Unknown';
    acc[genreKey] = (acc[genreKey] || 0) + 1;
    return acc;
  }, {});

  // Build an author frequency map — same pattern as genres.
  const authors = books.reduce((acc, book) => {
    const authorKey = book.author || 'Unknown';
    acc[authorKey] = (acc[authorKey] || 0) + 1;
    return acc;
  }, {});

  // Calculate the average published year.
  // Filter out books without a publishedYear first, then compute the mean.
  const publishedBooks = books.filter((b) => b.publishedYear !== null && b.publishedYear !== undefined);
  const averagePublishedYear =
    publishedBooks.length > 0
      ? publishedBooks.reduce((sum, b) => sum + b.publishedYear, 0) / publishedBooks.length
      : null;

  return {
    totalBooks,
    genres,
    authors,
    averagePublishedYear: averagePublishedYear ? Math.round(averagePublishedYear * 100) / 100 : null,
  };
}

/**
 * Export all functions as named exports.
 * This makes it clear which operations are available and allows selective imports.
 */
module.exports = { findAll, findById, create, update, deleteBook, getStats };
