/**
 * ============================================================================
 * BOOK ROUTES
 * ============================================================================
 *
 * WHY separate route file?
 *   Keeping routes in their own module follows the "single responsibility"
 *   principle. The app.js file only needs to know about route registration,
 *   not the details of each endpoint. This also makes it easy to add new
 *   resources (e.g., /authors, /reviews) by creating additional route files.
 *
 * PATTERN: We use Express's Router() to create a sub-application that
 * handles all book-related routes. This router is then mounted in app.js
 * at the /books path prefix.
 *
 * REST CONVENTIONS followed:
 *   - GET    /books       → List all books (with optional filtering).
 *   - GET    /books/:id   → Get a single book by ID.
 *   - POST   /books       → Create a new book.
 *   - PUT    /books/:id   → Fully update an existing book.
 *   - DELETE /books/:id   → Delete a book by ID.
 */

const express = require('express');
const router = express.Router(); // Create a standalone router instance.

// Import the model functions that perform actual data operations.
const { findAll, findById, create, update, deleteBook } = require('../models/books');

/**
 * ============================================================================
 * GET /books — List all books with optional filtering and pagination.
 * ============================================================================
 *
 * QUERY PARAMETERS (all optional):
 *   - genre: Filter by exact genre match (e.g., ?genre=fiction).
 *   - author: Filter by author name substring (e.g., ?author=tolkien).
 *   - limit: Maximum number of results to return (e.g., ?limit=10).
 *   - page: Page number for pagination, 1-indexed (e.g., ?page=2&limit=10).
 *
 * RESPONSE FORMAT:
 *   {
 *     success: true,
 *     data: {
 *       books: [...],      // Array of book objects.
 *       total: number      // Total matching books (before pagination).
 *     }
 *   }
 *
 * EXAMPLE CURL:
 *   curl http://localhost:3000/books?genre=fiction&limit=5
 *   curl http://localhost:3000/books?author=dune
 */
router.get('/', (req, res) => {
  try {
    // Extract filter parameters from the query string.
    // req.query is an object like { genre: 'fiction', limit: '5' }.
    const filters = {
      genre: req.query.genre,
      author: req.query.author,
      limit: req.query.limit ? parseInt(req.query.limit) : undefined,
      page: req.query.page ? parseInt(req.query.page) : undefined,
    };

    // Call the model to retrieve filtered books.
    const { books, total } = findAll(filters);

    // Send a structured JSON response.
    res.json({
      success: true,
      data: {
        books,
        total,
        // Include pagination metadata if limit was requested.
        ...(filters.limit && {
          page: filters.page || 1,
          limit: filters.limit,
          totalPages: Math.ceil(total / filters.limit),
        }),
      },
    });
  } catch (error) {
    // Pass the error to our centralized error-handling middleware.
    // Express will skip remaining middleware and jump to errorHandler.
    res.status(500).json({ success: false, error: { type: 'InternalServerError', message: error.message } });
  }
});

/**
 * ============================================================================
 * GET /books/:id — Get a single book by its numeric ID.
 * ============================================================================
 *
 * URL PARAMETER:
 *   - id: The unique identifier of the book (e.g., /books/1).
 *
 * RESPONSE FORMAT:
 *   {
 *     success: true,
 *     data: { ...book object ... }
 *   }
 *
 * ERROR RESPONSES:
 *   - 404 Not Found: If no book exists with the given ID.
 *
 * EXAMPLE CURL:
 *   curl http://localhost:3000/books/1
 */
router.get('/:id', (req, res) => {
  try {
    // Parse the ID from the URL parameter as an integer.
    const id = parseInt(req.params.id);

    // Validate that the ID is a valid positive number.
    if (isNaN(id) || id < 1) {
      return res.status(400).json({
        success: false,
        error: { type: 'ValidationError', message: 'Book ID must be a positive integer.' },
      });
    }

    // Call the model to find the book (throws NotFoundError if missing).
    const book = findById(id);

    res.json({ success: true, data: book });
  } catch (error) {
    // Re-throw so our global errorHandler handles it with proper status code.
    throw error;
  }
});

/**
 * ============================================================================
 * POST /books — Create a new book.
 * ============================================================================
 *
 * REQUEST BODY (JSON):
 *   {
 *     "title": "The Great Gatsby",      // Required: string, non-empty.
 *     "author": "F. Scott Fitzgerald",  // Required: string, non-empty.
 *     "genre": "Fiction",               // Optional: string.
 *     "publishedYear": 1925,            // Optional: number.
 *     "isbn": "978-0743273565"          // Optional: string (ISBN-13).
 *   }
 *
 * RESPONSE FORMAT (201 Created):
 *   {
 *     success: true,
 *     data: { ...newly created book object with generated id and timestamps... }
 *   }
 *
 * ERROR RESPONSES:
 *   - 400 Bad Request: If required fields are missing or invalid.
 *
 * EXAMPLE CURL:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","genre":"Dystopian","publishedYear":1949}'
 */
router.post('/', (req, res) => {
  try {
    // req.body contains the parsed JSON from the request body.
    // Express's json() middleware (registered in app.js) handles parsing.
    const bookData = req.body;

    // Call the model to create and validate the new book.
    const newBook = create(bookData);

    // Return 201 Created to indicate a new resource was successfully created.
    // This is the standard HTTP status for POST operations that create resources.
    res.status(201).json({ success: true, data: newBook });
  } catch (error) {
    // Validation errors from the model will have statusCode: 400.
    // Our errorHandler middleware uses err.statusCode to set the response code.
    throw error;
  }
});

/**
 * ============================================================================
 * PUT /books/:id — Fully update an existing book.
 * ============================================================================
 *
 * URL PARAMETER:
 *   - id: The unique identifier of the book to update.
 *
 * REQUEST BODY (JSON) — all fields optional; omitted fields retain current value:
 *   {
 *     "title": "Updated Title",
 *     "author": "Updated Author",
 *     "genre": "New Genre",
 *     "publishedYear": 2024,
 *     "isbn": "978-0000000000"
 *   }
 *
 * RESPONSE FORMAT:
 *   {
 *     success: true,
 *     data: { ...updated book object... }
 *   }
 *
 * ERROR RESPONSES:
 *   - 404 Not Found: If no book exists with the given ID.
 *   - 400 Bad Request: If updated fields fail validation.
 *
 * EXAMPLE CURL:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby (Updated Edition)"}'
 */
router.put('/:id', (req, res) => {
  try {
    const id = parseInt(req.params.id);

    // Validate the ID format.
    if (isNaN(id) || id < 1) {
      return res.status(400).json({
        success: false,
        error: { type: 'ValidationError', message: 'Book ID must be a positive integer.' },
      });
    }

    // Call the model to update the book (throws NotFoundError if missing).
    const updatedBook = update(id, req.body);

    res.json({ success: true, data: updatedBook });
  } catch (error) {
    throw error;
  }
});

/**
