 * RESPONSE FORMAT (200 OK):
 *   {
 *     success: true,
 *     data: { ...deleted book object... }
 *   }
 *
 * ERROR RESPONSES:
 *   - 404 Not Found: If no book exists with the given ID.
 *
 * EXAMPLE CURL:
 *   curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', (req, res) => {
  try {
    const id = parseInt(req.params.id);

    // Validate the ID format.
    if (isNaN(id) || id < 1) {
      return res.status(400).json({
        success: false,
        error: { type: 'ValidationError', message: 'Book ID must be a positive integer.' },
      });
    }

    // Call the model to delete the book (throws NotFoundError if missing).
    const deletedBook = deleteBook(id);

    res.json({ success: true, data: deletedBook });
  } catch (error) {
    throw error;
  }
});

/**
