## File 7: `src/app.js`

```javascript
/**
 * ============================================================================
 * MAIN APPLICATION ENTRY POINT
 * ============================================================================
 *
 * WHY this structure?
 *   Express applications follow a specific middleware registration order:
 *     1. Body parsing middleware (so routes can read req.body).
 *     2. Route handlers (the actual API endpoints).
 *     3. Error-handling middleware (catches errors from any route).
 *
 *   This order is CRITICAL because Express processes middleware top-to-bottom.
 *   If errorHandler were registered before the routes, it would never see
 *   route errors. If body parsing were after the routes, req.body would be undefined.
 *
 * PATTERN: We use app.use() to register each piece of middleware globally.
 * Routes are mounted using app.use('/path', router) which attaches all
 * routes from that router under the given path prefix.
 */

const express = require('express'); // Import Express framework.
const app = express();              // Create an Express application instance.

// ============================================================================
// MIDDLEWARE CONFIGURATION
// ============================================================================

/**
 * express.json() — Built-in middleware that parses incoming JSON request bodies.
 *
 * WHY is this needed?
 *   By default, Express does NOT parse request bodies. Without this middleware,
 *   req.body would be undefined even if the client sends JSON. This middleware:
 *     1. Reads the raw request body bytes.
 *     2. Parses them as JSON (if Content-Type is application/json).
 *     3. Attaches the parsed object to req.body for route handlers to use.
 *
 * LIMITATION: It only handles JSON. For file uploads, you'd need multer or
 * similar middleware instead.
 */
app.use(express.json());

/**
 * express.urlencoded() — Parses URL-encoded request bodies (form submissions).
 *
 * WHY include this?
 *   Even though our API primarily uses JSON, some clients (or testing tools)
 *   may send form-encoded data. This middleware ensures we can handle both formats.
 *   extended: true enables the qs library for richer object parsing.
 */
app.use(express.urlencoded({ extended: true }));

/**
 * ============================================================================
 * ROUTE REGISTRATION
 * ============================================================================
 *
 * WHY mount routers with app.use('/path', router)?
 *   This attaches all routes from the given router under the specified path
 *   prefix. For example, mounting booksRouter at '/books' means:
 *     - router.get('/')       → becomes GET /books
 *     - router.get('/:id')    → becomes GET /books/:id
 *     - router.post('/')      → becomes POST /books
 *
 *   This is cleaner than prefixing every route path manually and makes it
 *   easy to move or rename route groups.
 */

// Import our route modules.
const booksRouter = require('./routes/books');  // All book CRUD routes.
const statsRouter = require('./routes/stats');   // Statistics endpoint.

// Mount the routers at their respective path prefixes.
app.use('/books', booksRouter);  // All /books/* routes are handled by booksRouter.
app.use('/stats', statsRouter);  // The /stats route is handled by statsRouter.

/**
 * ============================================================================
 * ROOT ENDPOINT — Health check
 * ============================================================================
 *
 * WHY include a root endpoint?
 *   A simple GET / that returns status information helps:
 *     1. Verify the server is running (health check).
 *     2. Provide API documentation to clients who visit the base URL.
 *     3. Return useful metadata like available endpoints and version info.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Books REST API — Welcome!',
    version: '1.0.0',
    description: 'A simple REST API for managing books using Node.js and Express.js',
    endpoints: {
      // Document all available endpoints with their HTTP methods.
      // This serves as auto-generated API documentation.
      'List all books': 'GET /books',
      'Get book by ID': 'GET /books/:id',
      'Create a book': 'POST /books',
      'Update a book': 'PUT /books/:id',
      'Delete a book': 'DELETE /books/:id',
      'Get statistics': 'GET /stats',
    },
  });
});

/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE — MUST be registered LAST
 * ============================================================================
 *
 * WHY last?
 *   Express processes middleware in registration order. If we register the
 *   error handler before routes, it would intercept errors but then no route
 *   handlers would ever execute (because next(err) would skip straight to it).
 *   By placing it AFTER all routes, we ensure:
 *     1. All normal requests are handled by their respective route handlers.
 *     2. Any error thrown in a route handler is caught by this middleware.
 *     3. The response format is consistent for ALL errors across the API.
 *
 * NOTE: This is an Express "error-handling" middleware because it has FOUR
 * parameters (err, req, res, next). Express recognizes this signature and
 * only calls it when an error is passed via next(err) or thrown in async code.
 */
const errorHandler = require('./middleware/errorHandler');
app.use(errorHandler); // Register AFTER all routes — catches errors from any route.

/**
 * ============================================================================
 * 404 HANDLER — Catch-all for undefined routes
 * ============================================================================
 *
 * WHY a separate 404 handler?
 *   If a client requests a path that doesn't match any registered route
 *   (e.g., GET /nonexistent), Express won't automatically return a 404.
 *   Instead, it will send an empty response. This handler ensures we always
 *   return a meaningful error for unknown routes.
 *
 * PLACEMENT: This must come AFTER all route registrations but BEFORE the
 * error handler (since it's a normal middleware, not an error handler).
 */
app.use((req, res) => {
  // This handler runs when no previous route matched the request.
  res.status(404).json({
    success: false,
    error: {
      type: 'NotFoundError',
      message: `Route ${req.method} ${req.originalUrl} not found.`,
    },
  });
});

/**
 * ============================================================================
 * SERVER STARTUP
 * ============================================================================
 *
 * WHY use a constant PORT with a fallback?
 *   In production environments (Heroku, AWS, etc.), the port is often provided
 *   via an environment variable (PORT). We default to 3000 for local development.
 *
 * WHY log the startup message?
 *   A clear console message helps developers confirm the server started
 *   successfully and know which URL to use for testing.
 */
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Books REST API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Base URL: http://localhost:${PORT}`);
  console.log(`========================================`);
  console.log(`\nAvailable endpoints:`);
  console.log(`  GET    http://localhost:${PORT}/          — API info & documentation`);
  console.log(`  GET    http://localhost:${PORT}/books     — List all books`);
  console.log(`  GET    http://localhost:${PORT}/books/1   — Get book by ID`);
  console.log(`  POST   http://localhost:${PORT}/books     — Create a new book`);
  console.log(`  PUT    http://localhost:${PORT}/books/1   — Update a book`);
  console.log(`  DELETE http://localhost:${PORT}/books/1   — Delete a book`);
  console.log(`  GET    http://localhost:${PORT}/stats     — Get statistics`);
  console.log(`\nTry: curl http://localhost:${PORT}/books\n`);
});

/**
 * Export the app instance for testing purposes.
 * In production, this file is run directly (node src/app.js).
 * For unit tests, we import the app to make HTTP requests without starting a server.
 */
module.exports = app;
