```
src/
├── app.js                  # Main application entry point
├── errors/
│   └── customErrors.js     # Custom error classes
├── middleware/
│   └── errorHandler.js     # Centralized error-handling middleware
├── models/
│   └── books.js            # In-memory data store and operations
