```javascript
/**
 * ============================================================================
 * ALTERNATIVE ENTRY POINT
 * ============================================================================
 *
 * WHY include this file?
 *   Some deployment platforms and testing frameworks prefer a separate server
 *   file that handles the HTTP server creation. This file imports app.js and
 *   adds graceful shutdown handling — useful for production deployments where
 *   you want to clean up resources on process termination.
 *
 * For this educational project, src/app.js is sufficient. This file exists
 * as a reference for more advanced setups.
 */

const app = require('./app');

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

/**
 * Graceful shutdown — clean up resources before exiting.
 * This prevents data loss and ensures in-flight requests complete.
 */
function gracefulShutdown(signal) {
  console.log(`\n${signal} received. Shutting down gracefully...`);
  server.close(() => {
    console.log('Server closed. Process terminated.');
    process.exit(0);
  });

  // Force exit after 10 seconds if connections are still open.
  setTimeout(() => {
    console.error('Could not close connections in time. Forcing exit.');
    process.exit(1);
  }, 10000);
}

// Listen for termination signals from the OS.
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = server;
```

