## Arquivo 2: `src/errors/AppError.js`

```javascript
/**
 * Classe base para erros personalizados da aplicação.
 *
 * POR QUE criar uma classe de erro personalizada?
 *   - Permite adicionar propriedades específicas (statusCode, isOperational)
 *     que o middleware de erros pode usar para gerar respostas HTTP adequadas.
 *   - Erros "operacionais" são aqueles esperados (ex: recurso não encontrado),
 *     enquanto erros "não operacionais" indicam bugs no código e devem ser
 *     logados internamente sem expor detalhes ao cliente.
 *   - Separação clara entre falhas de entrada do usuário vs. problemas internos.
 */
class AppError extends Error {
  /**
   * @param {string} message — Mensagem descritiva do erro (exposta ao cliente).
   * @param {number} statusCode — Código HTTP correspondente (padrão: 500).
   * @param {boolean} isOperational — Se true, o erro é esperado e seguro expor.
   */
  constructor(message, statusCode = 500, isOperational = true) {
    super(message); // Chama construtor da classe Error nativa

    // Preserva a stack trace correta mesmo após herdar de Error
    Object.setPrototypeOf(this, AppError.prototype);

    this.statusCode = statusCode;
    this.isOperational = isOperational;

    // Marca o nome da classe para logs mais legíveis
    this.name = 'AppError';
  }
}

/**
 * Erro 400 Bad Request — dados de entrada inválidos.
 * Usado quando o cliente envia campos ausentes, mal formatados ou fora do esperado.
 */
class BadRequestError extends AppError {
  constructor(message = 'Requisição inválida') {
    super(message, 400);
    this.name = 'BadRequestError';
  }
}

/**
 * Erro 404 Not Found — recurso solicitado não existe.
 * Usado quando um ID de livro é inválido ou inexistente.
 */
class NotFoundError extends AppError {
  constructor(message = 'Recurso não encontrado') {
    super(message, 404);
    this.name = 'NotFoundError';
  }
}

/**
 * Erro 500 Internal Server Error — problema interno inesperado.
 * isOperational = false indica que é um bug e não deve ser exposto ao cliente.
 */
class InternalError extends AppError {
  constructor(message = 'Erro interno do servidor') {
    super(message, 500, false);
    this.name = 'InternalError';
  }
}

module.exports = { AppError, BadRequestError, NotFoundError, InternalError };
```

**Explicação:** A hierarquia de classes de erro permite que o middleware de erros (ver arquivo 4) inspecione `instanceof` e responda com códigos HTTP corretos. O campo `isOperational` é crucial: erros operacionais (como "livro não encontrado") são respostas normais da API; erros não operacionais (bugs) devem ser logados, mas nunca expostos integralmente ao cliente por segurança.

