## Arquivo 4: `src/routes/books.js`

```javascript
const express = require('express');
const { BadRequestError, NotFoundError } = require('../errors/AppError');

/**
 * Rotas para o recurso /books da API REST.
 *
 * POR QUE separar rotas em arquivos distintos?
 *   - Separação de responsabilidades: cada arquivo gerencia um domínio (livros, stats).
 *   - Facilita testes unitários isolados por domínio.
 *   - Escalabilidade: conforme a API cresce, novas rotas são adicionadas sem poluir o app principal.
 *   - Convenção do Express: router é uma instância mínima de app, reutilizável e testável.
 */
const router = express.Router();

// ============================================================================
// ARMAZENAMENTO EM MEMÓRIA (Array)
// ============================================================================
//
// POR QUE usar um array em memória para este exemplo educacional?
//   1. Simplicidade: elimina a complexidade de configurar banco de dados,
//      tornando o foco no entendimento dos conceitos REST e Express.
//   2. Transparência: cada operação (find, create, update, delete) é visível
//      e compreensível sem abstração de ORM ou driver.
//   3. Estrutura preparada para migração: as funções abaixo são "camadas de
//      adaptação" — basta substituí-las por chamadas a um banco real (MongoDB,
//      PostgreSQL, etc.) sem alterar as rotas.
//
// POR QUE array e não objeto/map?
//   - Arrays preservam ordem de inserção (útil para listagem cronológica).
//   - Operações de busca linear são aceitáveis para datasets pequenos (< 10k itens).
//   - Para produção com milhões de registros, usaríamos um banco com índices.
//
// Cada livro segue o schema:
// {
//   id: number,          // Identificador único autoincremental
//   title: string,       // Título do livro (obrigatório)
//   author: string,      // Autor (obrigatório)
//   year: number,        // Ano de publicação (opcional, mas recomendado)
//   genre: string,       // Gênero literário (opcional)
//   createdAt: string,   // Timestamp ISO da criação (gerado automaticamente)
//   updatedAt: string    // Timestamp ISO da última atualização
// }
// ============================================================================

/** @type {Array<Object>} Lista de livros em memória */
const books = [];

/** @type {number} Contador para IDs autoincrementais únicos */
let nextId = 1;

// --------------------------------------------------------------------------
// FUNÇÕES DE ACESSO AO DADOS (Camada de Adaptação)
// --------------------------------------------------------------------------

/**
 * Encontra um livro pelo ID.
 *
 * @param {number} id — ID do livro a ser buscado.
 * @returns {Object|null} Livro encontrado ou null se não existir.
 */
const findById = (id) => books.find((book) => book.id === id) || null;

/**
 * Cria um novo livro no array e retorna com IDs/timestamps preenchidos.
 *
 * @param {Object} data — Dados do livro a ser criado.
 * @returns {Object} Livro criado com campos adicionais (id, timestamps).
 */
const create = (data) => {
  const newBook = {
    id: nextId++, // Incrementa e atribui ID único
    ...data,      // Espalha os dados fornecidos pelo cliente
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  books.push(newBook);
  return newBook;
};

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id — ID do livro a atualizar.
 * @param {Object} updates — Campos a serem atualizados (partial update).
 * @returns {Object|null} Livro atualizado ou null se não encontrado.
 */
const update = (id, updates) => {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Mescla dados existentes com atualizações (partial update)
  books[index] = { ...books[index], ...updates, updatedAt: new Date().toISOString() };
  return books[index];
};

/**
 * Remove um livro pelo ID.
 *
 * @param {number} id — ID do livro a remover.
 * @returns {boolean} True se removido, false caso contrário.
 */
const remove = (id) => {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove elemento do array
  return true;
};

// ============================================================================
// ENDPOINT: GET /books
// ============================================================================
//
// LISTAR TODOS OS LIVROS COM FILTRAGEM OPCIONAL.
//
// PARÂMETROS DE QUERY (opcionais):
//   - author: filtra por autor (case-insensitive, substring match)
//   - genre:  filtra por gênero (case-insensitive, substring match)
//   - year:   filtra por ano exato de publicação
//   - search: busca por título OU autor (substring match)
//
// EXEMPLOS DE USO:
//   curl http://localhost:3000/books
//   curl "http://localhost:3000/books?author=tolkien"
//   curl "http://localhost:3000/books?genre=ficcao&year=2020"
//   curl "http://localhost:3000/books?search=magic"
//
// RESPOSTA: Array de livros (200 OK) ou array vazio (200 OK se nenhum livro).
// ============================================================================

/**
 * @name GET /books
 * @description Lista todos os livros com filtragem opcional por query params.
 * @access Public
 */
router.get('/', (req, res) => {
  let result = [...books]; // Cria cópia para não mutar o array original durante filtro

  // Filtragem por autor (substring case-insensitive)
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(authorFilter));
  }

  // Filtragem por gênero
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter((book) => book.genre?.toLowerCase().includes(genreFilter));
  }

  // Filtragem por ano exato
  if (req.query.year) {
    const yearNum = parseInt(req.query.year, 10);
    if (!isNaN(yearNum)) {
      result = result.filter((book) => book.year === yearNum);
    }
  }

  // Busca por título ou autor
  if (req.query.search) {
    const searchFilter = req.query.search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(searchFilter) ||
        book.author.toLowerCase().includes(searchFilter),
    );
  }

  // Retorna os livros filtrados com código 200 OK
  return res.status(200).json({
    count: result.length, // Total de livros após filtragem (útil para paginação futura)
    data: result,         // Array de livros
  });
});

// ============================================================================
// ENDPOINT: GET /books/:id
// ============================================================================
//
// OBTER UM LIVRO ESPECÍFICO PELO ID.
//
// PARÂMETROS DE ROTA:
//   - id: número inteiro identificando o livro.
//
// EXEMPLOS DE USO:
//   curl http://localhost:3000/books/1
//   curl http://localhost:3000/books/999  → 404 Not Found
//
// RESPOSTA: Objeto livro (200 OK) ou erro 404 se não encontrado.
// ============================================================================

/**
 * @name GET /books/:id
 * @description Retorna um único livro pelo ID.
 * @access Public
 */
router.get('/:id', (req, res, next) => {
  // Converte id para número e valida se é inteiro válido
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    // Se o ID não for um número válido, retorna erro 400 Bad Request
    return next(new BadRequestError('ID deve ser um número inteiro válido'));
  }

  const book = findById(id);

  if (!book) {
    // Se não encontrado, encadeia erro 404 para o middleware de tratamento
    return next(new NotFoundError(`Livro com ID ${id} não encontrado`));
  }

  return res.status(200).json({ data: book });
});

// ============================================================================
// ENDPOINT: POST /books
// ============================================================================
//
// CRIAR UM NOVO LIVRO.
//
// CORPO DA REQUISIÇÃO (JSON):
//   {
//     "title": "O Senhor dos Anéis",    // Obrigatório — string não vazia
//     "author": "J.R.R. Tolkien",       // Obrigatório — string não vazia
//     "year": 1954,                     // Opcional — número inteiro
//     "genre": "Fantasia"               // Opcional — string
//   }
//
// EXEMPLOS DE USO:
//   curl -X POST http://localhost:3000/books \
//        -H "Content-Type: application/json" \
//        -d '{"title":"1984","author":"George Orwell","year":1949,"genre":"Distopia"}'
//
// RESPOSTA: Livro criado com ID e timestamps (201 Created).
// ============================================================================

/**
 * @name POST /books
 * @description Cria um novo livro no sistema.
 * @access Public
 */
router.post('/', (req, res, next) => {
  const { title, author, year, genre } = req.body;

  // Validação: título e autor são obrigatórios
  if (!title || typeof title !== 'string' || title.trim() === '') {
    return next(new BadRequestError('Campo "title" é obrigatório e deve ser uma string não vazia'));
  }

  if (!author || typeof author !== 'string' || author.trim() === '') {
    return next(new BadRequestError('Campo "author" é obrigatório e deve ser uma string não vazia'));
  }

  // Validação opcional: year deve ser número se fornecido
  let validatedYear = undefined;
  if (year !== undefined && year !== null) {
    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
      return next(new BadRequestError('Campo "year" deve ser um número inteiro válido entre 0 e o ano atual + 1'));
    }
    validatedYear = yearNum;
  }

  // Validação opcional: genre deve ser string se fornecido
  let validatedGenre = undefined;
  if (genre !== undefined && genre !== null) {
    if (typeof genre !== 'string' || genre.trim() === '') {
      return next(new BadRequestError('Campo "genre" deve ser uma string não vazia'));
    }
    validatedGenre = genre.trim();
  }

  // Cria o livro com dados validados
  const newBook = create({
    title: title.trim(),
    author: author.trim(),
    ...(validatedYear !== undefined && { year: validatedYear }),
    ...(validatedGenre !== undefined && { genre: validatedGenre }),
  });

  // Retorna 201 Created com o livro criado no corpo da resposta
  return res.status(201).json({ data: newBook });
});

// ============================================================================
// ENDPOINT: PUT /books/:id
// ============================================================================
//
// ATUALIZAR UM LIVRO EXISTENTE (FULL UPDATE).
//
// CORPO DA REQUISIÇÃO (JSON):
//   Todos os campos são opcionais — apenas os fornecidos serão atualizados.
//   {
//     "title": "Novo Título",
//     "author": "Novo Autor",
//     "year": 2024,
//     "genre": "Ficção Científica"
//   }
//
// EXEMPLOS DE USO:
//   curl -X PUT http://localhost:3000/books/1 \
//        -H "Content-Type: application/json" \
//        -d '{"year":2024,"genre":"Clássico"}'
//
// RESPOSTA: Livro atualizado (200 OK) ou 404 se não encontrado.
// ============================================================================

/**
 * @name PUT /books/:id
 * @description Atualiza completamente um livro existente pelo ID.
 * @access Public
 */
router.put('/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    return next(new BadRequestError('ID deve ser um número inteiro válido'));
  }

  // Verifica se o livro existe antes de atualizar
  const existingBook = findById(id);
  if (!existingBook) {
    return next(new NotFoundError(`Livro com ID ${id} não encontrado`));
  }

  const { title, author, year, genre } = req.body;

  // Validações similares às do POST
  if (title !== undefined && (typeof title !== 'string' || title.trim() === '')) {
    return next(new BadRequestError('Campo "title" deve ser uma string não vazia'));
  }

  if (author !== undefined && (typeof author !== 'string' || author.trim() === '')) {
    return next(new BadRequestError('Campo "author" deve ser uma string não vazia'));
  }

  let validatedYear = undefined;
  if (year !== undefined) {
    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
      return next(new BadRequestError('Campo "year" deve ser um número inteiro válido'));
    }
    validatedYear = yearNum;
  }

  let validatedGenre = undefined;
  if (genre !== undefined) {
    if (typeof genre !== 'string' || genre.trim() === '') {
      return next(new BadRequestError('Campo "genre" deve ser uma string não vazia'));
    }
    validatedGenre = genre.trim();
  }

  // Atualiza o livro com os campos fornecidos
  const updatedBook = update(id, {
    ...(title !== undefined && { title: title.trim() }),
    ...(author !== undefined && { author: author.trim() }),
    ...(validatedYear !== undefined && { year: validatedYear }),
    ...(validatedGenre !== undefined && { genre: validatedGenre }),
  });

  return res.status(200).json({ data: updatedBook });
});

// ============================================================================
// ENDPOINT: DELETE /books/:id
// ============================================================================
//
// EXCLUIR UM LIVRO PELO ID.
//
// EXEMPLOS DE USO:
//   curl -X DELETE http://localhost:3000/books/1
//   curl -X DELETE http://localhost:3000/books/999  → 404 Not Found
//
// RESPOSTA: Mensagem de sucesso (200 OK) ou 404 se não encontrado.
// ============================================================================

/**
 * @name DELETE /books/:id
 * @description Remove um livro pelo ID.
 * @access Public
 */
router.delete('/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id)) {
    return next(new BadRequestError('ID deve ser um número inteiro válido'));
  }

  // Verifica se o livro existe antes de tentar remover
  const existingBook = findById(id);
  if (!existingBook) {
    return next(new NotFoundError(`Livro com ID ${id} não encontrado`));
  }

  remove(id);

  // Retorna 200 OK com mensagem de confirmação
  return res.status(200).json({
    status: 'success',
    message: `Livro com ID ${id} foi removido com sucesso`,
  });
});

module.exports = router;
```

**Explicação detalhada das decisões de design:**

1. **Separador de IDs autoincrementais (`nextId`)** — Evita colisões de ID mesmo se livros forem deletados. Em produção, usaríamos UUIDs ou IDs do banco (MongoDB ObjectId, PostgreSQL SERIAL).

2. **Partial update em PUT** — O método `update` usa spread operator (`{ ...existing, ...updates }`) para mesclar campos. Isso permite atualizações parciais sem sobrescrever campos não fornecidos. Para um update completo (substituição total), o comportamento seria diferente.

3. **Validação em camadas** — Cada endpoint valida seus próprios dados de entrada antes de chamar funções de acesso aos dados. Isso mantém as rotas responsáveis por sua própria integridade, enquanto as funções de dados permanecem genéricas e reutilizáveis.

4. **Uso de `next(err)`** — Em vez de responder diretamente com `res.status().json()`, encadeamos erros para o middleware centralizado. Isso garante consistência nas respostas de erro em toda a API.

5. **Cópia do array antes de filtrar** — `let result = [...books]` evita mutação acidental do array original durante operações de filtro, mantendo a integridade dos dados.

