## Arquivo 5: `src/routes/stats.js`

```javascript
const express = require('express');
const { books } = require('./books'); // Nota: em projeto real, usaríamos um serviço/repositório

/**
 * Rotas para estatísticas da API de livros.
 *
 * POR QUE rotas de stats separadas?
 *   - Estatísticas são dados agregados, não recursos CRUD tradicionais.
 *   - Separação clara entre operações de leitura/escrita e análises.
 *   - Facilita adição futura de métricas avançadas (gráficos, dashboards).
 */
const router = express.Router();

// ============================================================================
// ENDPOINT: GET /stats
// ============================================================================
//
// RETORNAR ESTATÍSTICAS AGREGADAS SOBRE O ACERVO DE LIVROS.
//
// AS ESTATÍSTICAS INCLUÍDAS:
//   - totalBooks: número total de livros cadastrados
//   - totalAuthors: número de autores únicos (considerando normalização)
//   - averageYear: ano médio de publicação (arredondado para 1 casa decimal)
//   - booksByGenre: objeto com contagem de livros por gênero
//   - oldestBook: livro mais antigo publicado (pelo campo year)
//   - newestBook: livro mais recente publicado (pelo campo year)
//
// EXEMPLOS DE USO:
//   curl http://localhost:3000/stats
//
// RESPOSTA: Objeto com estatísticas agregadas (200 OK).
// ============================================================================

/**
 * @name GET /stats
 * @description Retorna estatísticas agregadas sobre o acervo de livros.
 * @access Public
 */
router.get('/', (req, res) => {
  // Se não há livros, retorna estatísticas zeradas
  if (books.length === 0) {
    return res.status(200).json({
      totalBooks: 0,
      totalAuthors: 0,
      averageYear: null,
      booksByGenre: {},
      oldestBook: null,
      newestBook: null,
    });
  }

  // Calcula autores únicos normalizando para lowercase e trim
  const uniqueAuthors = new Set(books.map((book) => book.author.toLowerCase().trim()));

  // Calcula média dos anos de publicação (ignorando livros sem year)
  const booksWithYear = books.filter((book) => book.year !== undefined && book.year !== null);
  const averageYear =
    booksWithYear.length > 0
      ? Math.round((booksWithYear.reduce((sum, book) => sum + book.year, 0) / booksWithYear.length) * 10) / 10
      : null;

  // Agrupa livros por gênero e conta quantos existem em cada
  const booksByGenre = books.reduce((acc, book) => {
    const genre = book.genre ? book.genre.toLowerCase().trim() : 'sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Encontra o livro mais antigo e mais recente pelo campo year
  const sortedByYear = [...books].sort((a, b) => {
    // Livros sem year vão para o final na ordenação de antigos, início nos novos
    if (!a.year && !b.year) return 0;
    if (!a.year) return 1;
    if (!b.year) return -1;
    return a.year - b.year;
  });

  const oldestBook = sortedByYear[0] || null;
  const newestBook = sortedByYear[sortedByYear.length - 1] || null;

  return res.status(200).json({
    totalBooks: books.length,
    totalAuthors: uniqueAuthors.size,
    averageYear,
    booksByGenre,
    oldestBook,
    newestBook,
  });
});

module.exports = router;
```

**Explicação:** As estatísticas são calculadas em tempo real a partir do array de livros. O uso de `Set` para autores únicos garante normalização (case-insensitive). A função `reduce` é eficiente para agregações. Em produção, essas estatísticas seriam pré-calculadas e armazenadas em cache para evitar recálculo a cada requisição.

