const express = require('express');
const booksRouter = require('./routes/books');
const statsRouter = require('./routes/stats');
const errorHandler = require('./middleware/errorHandler');

/**
 * Configuração principal da aplicação Express.
 *
 * POR QUE esta estrutura?
 *   - Middlewares globais (body-parser, JSON) são aplicados antes das rotas.
 *   - Rotas são montadas em caminhos específicos (/books, /stats).
 *   - Middleware de erro é registrado por último para capturar erros de todas as rotas.
 *   - A porta é configurável via variável de ambiente (padrão: 3000).
 */

// Cria a instância do aplicativo Express
const app = express();

// ============================================================================
// MIDDLEWARES GLOBAIS
// ============================================================================

/**
 * Middleware para parsing de JSON no corpo das requisições.
 *
 * POR QUE este middleware?
 *   - Express não faz parsing automático de JSON desde a versão 4.x.
 *   - Sem ele, req.body seria undefined em requisições POST/PUT com JSON.
 *   - limit: '10kb' previne ataques de negação de serviço por payloads gigantes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware para logging básico de todas as requisições.
 *
 * POR QUE logging?
 *   - Facilita debugging e monitoramento em produção.
 *   - Mostra método HTTP, URL, status e tempo de resposta.
 */
app.use((req, res, next) => {
  const start = Date.now(); // Marca o início do processamento
  next(); // Continua para a próxima etapa (rotas ou middleware de erro)
  const duration = Date.now() - start; // Calcula duração em ms
  console.log(`${req.method} ${req.originalUrl} — ${res.statusCode} — ${duration}ms`);
});

// ============================================================================
// MONTAGEM DAS ROTAS
// ============================================================================

/**
 * Monta as rotas do recurso /books.
 * Todas as rotas definidas em src/routes/books.js são prefixadas com /books.
 */
app.use('/books', booksRouter);

/**
 * Monta as rotas de estatísticas.
 * Acessível em GET /stats.
 */
app.use('/stats', statsRouter);

// ============================================================================
// ROTA DE HEALTH CHECK (BÔNUS)
// ============================================================================

/**
 * @name GET /health
 * @description Endpoint de verificação de saúde da API.
 * @access Public
 */
app.get('/health', (req, res) => {
  return res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(), // Tempo que o processo está rodando em segundos
  });
});

// ============================================================================
// ROTA 404 PARA RECURSOS NÃO ENCONTRADOS
// ============================================================================

/**
 * Middleware para capturar requisições a rotas inexistentes.
 * Retorna 404 antes do middleware de erro ser atingido.
 */
app.use((req, res, next) => {
  const { BadRequestError } = require('./errors/AppError');
  next(new BadRequestError(`Rota ${req.method} ${req.originalUrl} não encontrada`));
});

// ============================================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS (SEMPRE POR ÚLTIMO)
// ============================================================================
app.use(errorHandler);

// ============================================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================================

/**
 * Porta do servidor. Usa variável de ambiente ou padrão 3000.
 * process.env.PORT é comum em plataformas de deploy (Heroku, Railway, etc.).
 */
const PORT = process.env.PORT || 3000;

/**
 * Inicia o servidor e lista na porta configurada.
 */
app.listen(PORT, () => {
  console.log(`📚 API de Livros rodando em http://localhost:${PORT}`);
  console.log(`   Endpoints disponíveis:`);
  console.log(`   - GET    /books          → Listar todos os livros`);
  console.log(`   - GET    /books/:id      → Obter livro por ID`);
  console.log(`   - POST   /books          → Criar novo livro`);
  console.log(`   - PUT    /books/:id      → Atualizar livro`);
  console.log(`   - DELETE /books/:id      → Excluir livro`);
  console.log(`   - GET    /stats          → Estatísticas do acervo`);
  console.log(`   - GET    /health         → Verificação de saúde`);
});

module.exports = app;
```

**Explicação:** O `app.js` é o ponto de entrada da aplicação. A ordem dos middlewares é crítica: parsing → logging → rotas → 404 → erro. O middleware de erro deve ser sempre o último, pois ele captura erros de TODOS os middlewares anteriores. O health check é uma prática comum em APIs profissionais para monitoramento por plataformas como Kubernetes e Docker Swarm.

