# File: server.js

```javascript
/**
 * ============================================================================
 * BOOK MANAGEMENT REST API - EDUCATIONAL EXAMPLE
 * ============================================================================
 * 
 * This Express.js application provides a complete RESTful API for managing books.
 * It demonstrates core concepts including:
 *   - In-memory data storage with detailed structure explanations
 *   - RESTful route design following HTTP conventions
 *   - Comprehensive error handling with custom error classes
 *   - Input validation and sanitization
 *   - Query parameter filtering and statistics aggregation
 * 
 * Data Structure Choice Explanation:
 * ---------------------------------
 * We use an array of book objects for in-memory storage. While a Map or object
 * keyed by ID would provide O(1) lookups, arrays offer several educational
 * advantages:
 *   1. Preserves insertion order (predictable iteration)
 *   2. Simple to understand and debug
 *   3. Demonstrates array methods (filter, map, reduce) commonly used in APIs
 *   4. Easy to serialize/deserialize for persistence later
 * 
 * Trade-off: Lookups are O(n) instead of O(1). For production with large datasets,
 * a Map or database would be preferred. Here, we balance simplicity with the
 * educational goal of showing array manipulation patterns.
 * ============================================================================
 */

const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

// Middleware to parse JSON request bodies
app.use(express.json());

/**
 * ============================================================================
 * SECTION 1: DATA STORAGE LAYER
 * ============================================================================
 * 
 * In-memory storage using an array of book objects. Each book contains:
 *   - id: Unique identifier (numeric, auto-incrementing)
 *   - title: Book title string
 *   - author: Author name string  
 *   - genre: Book genre/category string
 *   - publishedYear: Publication year as integer
 *   - rating: Average rating from 1-5 as float
 * 
 * We seed with sample data so the API is immediately testable.
 */

// Array to store all books in memory
let books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.5
  },
  {
    id: 2,
    title: 'To Kill a Mockingbird',
    author: 'Harper Lee',
    genre: 'Fiction',
    publishedYear: 1960,
    rating: 4.8
  },
  {
    id: 3,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    genre: 'Science',
    publishedYear: 1988,
    rating: 4.7
  },
  {
    id: 4,
    title: 'The Art of War',
    author: 'Sun Tzu',
    genre: 'Philosophy',
    publishedYear: -500,
    rating: 4.3
  }
];

// Counter for generating unique IDs (auto-increment)
let nextId = 5;

/**
 * ============================================================================
 * SECTION 2: CUSTOM ERROR CLASSES
 * ============================================================================
 * 
 * We create custom error classes to provide structured, typed errors throughout
 * the application. This enables:
 *   - Consistent error response format
 *   - Easy error type checking in middleware
 *   - Better debugging with stack traces
 *   - Separation of concerns (routes throw, middleware handles)
 * 
 * Using custom classes instead of generic Error allows us to attach additional
 * properties like statusCode and isOperational.
 */

/** Base application error class */
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error message
   * @param {number} statusCode - HTTP status code (default: 500)
   */
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    // Mark as operational error (expected, not a bug)
    this.isOperational = true;

    // Capture stack trace for debugging
    Error.captureStackTrace(this, this.constructor);
  }
}

/** Error thrown when requested resource is not found */
class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
    this.resource = resource;
  }
}

/** Error thrown when request validation fails */
class ValidationError extends AppError {
  constructor(message, details = []) {
    super(message, 400);
    this.details = details;
  }
}

/** Error thrown for unauthorized access */
class UnauthorizedError extends AppError {
  constructor(message = 'Unauthorized') {
    super(message, 401);
  }
}

// Export error classes for use in route handlers
module.exports = { AppError, NotFoundError, ValidationError, UnauthorizedError };

/**
 * ============================================================================
 * SECTION 3: VALIDATION HELPERS
 * ============================================================================
 * 
 * Centralized validation functions ensure consistent input checking across all
 * mutation endpoints (POST, PUT). This DRYs up the code and makes it easy to
 * update validation rules in one place.
 * 
 * Why separate validation from routes?
 *   - Reusability: Same validation logic can be used by multiple routes
 *   - Testability: Validation functions are pure and easy to unit test
 *   - Maintainability: Changes to validation rules don't require touching routes
 */

/**
 * Validates book creation/update data
 * @param {Object} data - Book data to validate
 * @returns {Array<string>} Array of error messages (empty if valid)
 */
function validateBookData(data) {
  const errors = [];

  // Title is required and must be a non-empty string
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    errors.push('Title is required and must be a non-empty string');
  }

  // Author is required and must be a non-empty string
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    errors.push('Author is required and must be a non-empty string');
  }

  // Genre is optional but must be a string if provided
  if (data.genre !== undefined && typeof data.genre !== 'string') {
    errors.push('Genre must be a string');
  }

  // Published year is optional but must be a number if provided
  if (data.publishedYear !== undefined) {
    if (!Number.isInteger(data.publishedYear)) {
      errors.push('Published year must be an integer');
    } else if (data.publishedYear < -3000 || data.publishedYear > new Date().getFullYear() + 1) {
      errors.push(`Published year must be between -3000 and ${new Date().getFullYear() + 1}`);
    }
  }

  // Rating is optional but must be a number between 1 and 5 if provided
  if (data.rating !== undefined) {
    if (typeof data.rating !== 'number' || data.rating < 1 || data.rating > 5) {
      errors.push('Rating must be a number between 1 and 5');
    }
  }

  return errors;
}

/**
 * Validates book ID parameter
 * @param {*} id - ID to validate
 * @returns {boolean} True if valid numeric ID
 */
function isValidId(id) {
  const parsed = parseInt(id, 10);
  return !isNaN(parsed) && isFinite(parsed) && parsed > 0;
}

/**
 * ============================================================================
 * SECTION 4: ROUTE HANDLERS
 * ============================================================================
 * 
 * Each route handler follows the async/await pattern for cleaner error handling.
 * Even though our storage is synchronous, using async functions:
 *   - Makes it easy to swap in database calls later
 *   - Provides consistent error handling with try/catch
 *   - Follows modern JavaScript best practices
 * 
 * REST Convention Notes:
 *   - GET requests should never modify data (idempotent)
 *   - POST creates new resources, returns 201 Created
 *   - PUT replaces entire resource, returns updated object
 *   - DELETE removes resource, returns 204 No Content on success
 */

/**
 * GET /books - List all books with optional filtering
 * 
 * Query Parameters (all optional):
 *   - title: Filter by title substring (case-insensitive)
 *   - author: Filter by author substring (case-insensitive)
 *   - genre: Exact genre match
 *   - minRating: Minimum rating filter (1-5)
 *   - maxRating: Maximum rating filter (1-5)
 * 
 * Example: GET /books?genre=Fiction&minRating=4.0
 */
function getBooks(req, res, next) {
  try {
    // Start with all books
    let result = [...books];

    // Apply filters if query parameters are provided
    const { title, author, genre, minRating, maxRating } = req.query;

    // Filter by title substring (case-insensitive)
    if (title) {
      result = result.filter(book => 
        book.title.toLowerCase().includes(title.toLowerCase())
      );
    }

    // Filter by author substring (case-insensitive)
    if (author) {
      result = result.filter(book => 
        book.author.toLowerCase().includes(author.toLowerCase())
      );
    }

    // Exact genre match
    if (genre) {
      result = result.filter(book => 
        book.genre === genre
      );
    }

    // Minimum rating filter
    if (minRating) {
      const min = parseFloat(minRating);
      if (!isNaN(min)) {
        result = result.filter(book => book.rating >= min);
      }
    }

    // Maximum rating filter
    if (maxRating) {
      const max = parseFloat(maxRating);
      if (!isNaN(max)) {
        result = result.filter(book => book.rating <= max);
      }
    }

    // Return filtered results with metadata
    res.json({
      success: true,
      count: result.length,
      data: result
    });
  } catch (error) {
    next(error);
  }
}

/**
 * GET /books/:id - Get a single book by ID
 */
function getBookById(req, res, next) {
  try {
    const { id } = req.params;

    // Validate ID format
    if (!isValidId(id)) {
      throw new ValidationError('Invalid book ID format', [
        'ID must be a positive integer'
      ]);
    }

    const bookId = parseInt(id, 10);
    const book = books.find(b => b.id === bookId);

    if (!book) {
      throw new NotFoundError('Book');
    }

    res.json({
      success: true,
      data: book
    });
  } catch (error) {
    next(error);
  }
}

/**
 * POST /books - Create a new book
 * 
 * Request Body:
 *   - title (required): String
 *   - author (required): String
 *   - genre (optional): String
 *   - publishedYear (optional): Integer
 *   - rating (optional): Number 1-5
 */
function createBook(req, res, next) {
  try {
    const errors = validateBookData(req.body);

    if (errors.length > 0) {
      throw new ValidationError('Invalid book data', errors);
    }

    // Create new book object with auto-incremented ID
    const newBook = {
      id: nextId++,
      title: req.body.title.trim(),
      author: req.body.author.trim(),
      genre: req.body.genre || null,
      publishedYear: req.body.publishedYear || null,
      rating: req.body.rating || null
    };

    // Add to in-memory storage
    books.push(newBook);

    // Return 201 Created with the new resource
    res.status(201).json({
      success: true,
      data: newBook
    });
  } catch (error) {
    next(error);
  }
}

/**
 * PUT /books/:id - Update an existing book (full replacement)
 */
function updateBook(req, res, next) {
  try {
    const { id } = req.params;

    // Validate ID format
    if (!isValidId(id)) {
      throw new ValidationError('Invalid book ID format', [
        'ID must be a positive integer'
      ]);
    }

    const bookId = parseInt(id, 10);
    const bookIndex = books.findIndex(b => b.id === bookId);

    if (bookIndex === -1) {
      throw new NotFoundError('Book');
    }

    // Validate provided data
    const errors = validateBookData(req.body);
    if (errors.length > 0) {
      throw new ValidationError('Invalid book data', errors);
    }

    // Replace entire book object (PUT semantics: full replacement)
    books[bookIndex] = {
      id: bookId,
      title: req.body.title.trim(),
      author: req.body.author.trim(),
      genre: req.body.genre || null,
      publishedYear: req.body.publishedYear || null,
      rating: req.body.rating || null
    };

    res.json({
      success: true,
      data: books[bookIndex]
    });
  } catch (error) {
    next(error);
  }
}

/**
 * DELETE /books/:id - Delete a book by ID
 */
function deleteBook(req, res, next) {
  try {
    const { id } = req.params;

    // Validate ID format
    if (!isValidId(id)) {
      throw new ValidationError('Invalid book ID format', [
        'ID must be a positive integer'
      ]);
    }

    const bookId = parseInt(id, 10);
    const bookIndex = books.findIndex(b => b.id === bookId);

    if (bookIndex === -1) {
      throw new NotFoundError('Book');
    }

    // Remove book from array
    books.splice(bookIndex, 1);

    // Return 204 No Content on successful deletion
    res.status(204).send();
  } catch (error) {
    next(error);
  }
}

/**
 * GET /stats - Get statistics about the book collection
 * 
 * Returns aggregate data including:
 *   - Total number of books
 *   - Average rating across all books
 *   - Books by genre distribution
 *   - Oldest and newest publications
 */
function getStats(req, res, next) {
  try {
    const totalBooks = books.length;

    if (totalBooks === 0) {
      return res.json({
        success: true,
        data: {
          totalBooks: 0,
          averageRating: null,
          booksByGenre: {},
          oldestPublication: null,
          newestPublication: null
        }
      });
    }

    // Calculate average rating (only for books with ratings)
    const ratedBooks = books.filter(b => b.rating !== null);
    const averageRating = ratedBooks.length > 0
      ? parseFloat((ratedBooks.reduce((sum, b) => sum + b.rating, 0) / ratedBooks.length).toFixed(2))
      : null;

    // Group books by genre
    const booksByGenre = {};
    books.forEach(book => {
      const genre = book.genre || 'Unknown';
      booksByGenre[genre] = (booksByGenre[genre] || 0) + 1;
    });

    // Find oldest and newest publications
    const publishedBooks = books.filter(b => b.publishedYear !== null);
    let oldestPublication = null;
    let newestPublication = null;

    if (publishedBooks.length > 0) {
      oldestPublication = Math.min(...publishedBooks.map(b => b.publishedYear));
      newestPublication = Math.max(...publishedBooks.map(b => b.publishedYear));
    }

    res.json({
      success: true,
      data: {
        totalBooks,
        averageRating,
        booksByGenre,
        oldestPublication,
        newestPublication
      }
    });
  } catch (error) {
    next(error);
  }
}

/**
 * ============================================================================
 * SECTION 5: ROUTE DEFINITIONS
 * ============================================================================
 * 
 * Routes are defined in logical order. Express matches routes top-to-bottom,
 * so more specific routes should come before parameterized ones.
 * 
 * Note: /stats is defined BEFORE /books/:id to prevent the "stats" segment
 * from being interpreted as an ID parameter.
 */

// GET /books - List all books with filtering
app.get('/books', getBooks);

// GET /books/:id - Get single book by ID
app.get('/books/:id', getBookById);

// POST /books - Create new book
app.post('/books', createBook);

// PUT /books/:id - Update existing book
app.put('/books/:id', updateBook);

// DELETE /books/:id - Delete book
app.delete('/books/:id', deleteBook);

// GET /stats - Return statistics (must be before /books/:id)
app.get('/stats', getStats);

/**
 * ============================================================================
 * SECTION 6: ERROR HANDLING MIDDLEWARE
 * ============================================================================
 * 
 * Express error handling middleware has a special signature: (err, req, res, next).
 * This middleware catches all errors thrown in route handlers and returns
 * consistent JSON error responses.
 * 
 * Why this pattern?
 *   - Centralized error formatting ensures API consistency
 *   - Separates error logic from business logic
 *   - Prevents sensitive error details from leaking to clients
 *   - Allows logging for debugging while returning safe messages to users
 */

// Global error handling middleware
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use a proper logging service)
  console.error(`[ERROR] ${err.statusCode || err.status || 500}: ${err.message}`);

  // Determine response status code
  const statusCode = err.statusCode || err.status || 500;

  // Build error response object
  const errorResponse = {
    success: false,
    error: {
      message: err.message,
      statusCode
    }
  };

  // Include validation details if available
  if (err.details) {
    errorResponse.error.details = err.details;
  }

  // Only include stack trace in development
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    errorResponse.error.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  const error = new NotFoundError('Route');
  error.message = `Route ${req.method} ${req.path} not found`;
  next(error);
});

/**
 * ============================================================================
 * SECTION 7: SERVER STARTUP
 * ============================================================================
 * 
 * Start the server and log startup information. We use process.env.PORT to
 * allow configuration via environment variables (important for deployment).
 */

app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`Book Management API running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`========================================`);
  console.log(`\nAvailable endpoints:`);
  console.log(`  GET    /books          - List all books (with optional filters)`);
  console.log(`  GET    /books/:id      - Get single book by ID`);
  console.log(`  POST   /books          - Create new book`);
  console.log(`  PUT    /books/:id      - Update existing book`);
  console.log(`  DELETE /books/:id      - Delete book`);
  console.log(`  GET    /stats          - Get collection statistics`);
  console.log(`\nExample filters for GET /books:`);
  console.log(`  ?title=gatsby         - Filter by title`);
  console.log(`  ?author=hawking       - Filter by author`);
  console.log(`  ?genre=Fiction        - Filter by genre`);
  console.log(`  ?minRating=4.0        - Minimum rating filter`);
  console.log(`  ?maxRating=4.5        - Maximum rating filter`);
});

// Export app for testing
module.exports = app;
```

