## Arquivo 2: `src/models/books.js` — Camada de Dados

```javascript
/**
 * ============================================================
 * CAMADA DE MODELO — Armazenamento em Memória
 * ============================================================
 *
 * POR QUE ARRAY EM MEMÓRIA?
 * -------------------------
 * Para este exemplo educacional, usamos um array em memória porque:
 *   1. Elimina a complexidade de configuração de banco de dados
 *   2. Permite focar nos conceitos de REST, rotas e middleware
 *   3. É rápido e não requer instalação de serviços externos
 *
 * POR QUE NÃO USAR BANCO DE DADOS AQUI?
 * --------------------------------------
 * Um projeto real usaria MongoDB (com Mongoose) ou PostgreSQL.
 * O array em memória é uma abstração simples que simula um repositório,
 * e pode ser substituído por uma camada de dados real sem alterar as rotas.
 *
 * ESTRUTURA DO LIVRO:
 * -------------------
 *   id        — Identificador único (number), gerado automaticamente
 *   title     — Título do livro (string, obrigatório)
 *   author    — Autor do livro (string, obrigatório)
 *   year      — Ano de publicação (number, 1000-2100)
 *   genre     — Gênero literário (string, opcional)
 *   createdAt — Timestamp de criação (ISO string)
 *   updatedAt — Timestamp da última atualização (ISO string)
 */

// ============================================================
// ARRAYS DE DADOS EM MEMÓRIA
// ============================================================
// Usamos dois arrays: 'books' para os dados e 'nextId' como contador
// para gerar IDs únicos sequenciais. Isso evita colisões de ID
// sem precisar de bibliotecas externas como uuid.

/** @type {Array<Object>} Lista de livros em memória */
const books = [];

/** @type {number} Próximo ID a ser atribuído a um novo livro */
let nextId = 1;

// ============================================================
// FUNÇÕES DO REPOSITÓRIO (Camada de Dados)
// ============================================================

/**
 * Retorna todos os livros.
 *
 * @returns {Array<Object>} Lista completa de livros
 */
function findAll() {
  return books;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id — ID do livro a ser encontrado
 * @returns {Object|null} O livro se encontrado, null caso contrário
 */
function findById(id) {
  // .find() retorna o primeiro elemento que satisfaz a condição,
  // ou undefined se nenhum for encontrado. Usamos === para comparação
  // estrita de tipo (number vs string).
  return books.find(book => book.id === id) || null;
}

/**
 * Cria um novo livro no array e retorna o objeto criado.
 *
 * @param {Object} data — Dados do livro a ser criado
 * @param {string} data.title   — Título do livro (obrigatório)
 * @param {string} data.author  — Autor do livro (obrigatório)
 * @param {number} [data.year]  — Ano de publicação (opcional)
 * @param {string} [data.genre] — Gênero literário (opcional)
 * @returns {Object} O livro criado com id e timestamps
 */
function create(data) {
  const book = {
    id: nextId++,                          // ID sequencial único
    title: data.title,
    author: data.author,
    year: data.year ?? null,               // null se não fornecido
    genre: data.genre ?? null,             // null se não fornecido
    createdAt: new Date().toISOString(),   // Timestamp ISO 8601
    updatedAt: new Date().toISOString()
  };

  books.push(book);                        // Adiciona ao array
  return book;                             // Retorna o livro completo
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id   — ID do livro a ser atualizado
 * @param {Object} data — Campos a serem atualizados
 * @returns {Object|null} O livro atualizado ou null se não encontrado
 */
function update(id, data) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return null; // Livro não encontrado
  }

  // Atualiza apenas os campos fornecidos (partial update / PATCH semantics)
  // mas mantemos a estrutura completa no retorno.
  const existing = books[index];

  if (data.title !== undefined) existing.title = data.title;
  if (data.author !== undefined) existing.author = data.author;
  if (data.year !== undefined) existing.year = data.year;
  if (data.genre !== undefined) existing.genre = data.genre;

  // Sempre atualizamos o timestamp de modificação
  existing.updatedAt = new Date().toISOString();

  return { ...existing }; // Retorna cópia para evitar mutação direta
}

/**
 * Exclui um livro pelo ID.
 *
 * @param {number} id — ID do livro a ser excluído
 * @returns {boolean} true se excluído, false se não encontrado
 */
function remove(id) {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return false;
  }

  books.splice(index, 1); // Remove exatamente 1 elemento no índice encontrado
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros.
 *
 * @returns {Object} Estatísticas: total, média de anos, distribuição por gênero
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      total: 0,
      averageYear: null,
      genres: {},
      authorsCount: 0
    };
  }

  // Calcula a média dos anos de publicação
  const sumYears = books.reduce((acc, book) => acc + (book.year || 0), 0);
  const averageYear = Math.round(sumYears / total);

  // Conta livros por gênero (ignorando null/undefined)
  const genres = {};
  books.forEach(book => {
    if (book.genre) {
      genres[book.genre] = (genres[book.genre] || 0) + 1;
    }
  });

  // Conta autores únicos
  const uniqueAuthors = new Set(books.map(book => book.author));

  return {
    total,
    averageYear,
    genres,
    authorsCount: uniqueAuthors.size
  };
}

// ============================================================
// FUNÇÕES DE FILTRAGEM E PAGINAÇÃO
// ============================================================

/**
 * Filtra livros com base em parâmetros de query.
 *
 * @param {Object} params — Parâmetros de filtragem da query string
 * @param {string} [params.author]    — Filtrar por autor (case-insensitive)
 * @param {string} [params.genre]     — Filtrar por gênero
 * @param {number} [params.minYear]   — Ano mínimo de publicação
 * @param {number} [params.maxYear]   — Ano máximo de publicação
 * @param {string} [params.search]    — Busca por título (case-insensitive)
 * @returns {Array<Object>} Lista filtrada de livros
 */
function filter(params = {}) {
  let result = [...books]; // Cria cópia para não mutar o array original

  if (params.author) {
    const authorLower = params.author.toLowerCase();
    result = result.filter(book =>
      book.author.toLowerCase().includes(authorLower)
    );
  }

  if (params.genre) {
    const genreLower = params.genre.toLowerCase();
    result = result.filter(book =>
      book.genre && book.genre.toLowerCase() === genreLower
    );
  }

  if (params.minYear) {
    result = result.filter(book => book.year >= Number(params.minYear));
  }

  if (params.maxYear) {
    result = result.filter(book => book.year <= Number(params.maxYear));
  }

  if (params.search) {
    const searchLower = params.search.toLowerCase();
    result = result.filter(book =>
      book.title.toLowerCase().includes(searchLower)
    );
  }

  return result;
}

// ============================================================
// EXPORTAÇÃO DO MÓDULO
// ============================================================
// Usamos exports nominais em vez de module.exports = {} para permitir
// que o Jest ou outros testadores importem funções específicas.
module.exports = {
  findAll,
  findById,
  create,
  update,
  remove,
  getStats,
  filter
};
```

