## Arquivo 3: `src/middleware/errors.js` — Middleware de Erros Personalizado

```javascript
/**
 * ============================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================
 *
 * POR QUE CLASSES DE ERRO PERSONALIZADAS?
 * ----------------------------------------
 * Classes de erro personalizadas permitem:
 *   1. Diferenciar tipos de erro (NotFound, ValidationError, etc.)
 *   2. Incluir metadados específicos (campo que falhou, valor recebido)
 *   3. Mapear automaticamente para códigos HTTP apropriados
 *   4. Fornecer mensagens de erro claras e acionáveis ao cliente
 *
 * POR QUE UM MIDDLEWARE DE ERROS?
 * --------------------------------
 * No Express, o middleware de erros tem a assinatura (err, req, res, next).
 * Ele captura erros lançados em rotas async/await (que o Express não
 * trata automaticamente antes do Express 5) e erros síncronos.
 * Isso centraliza o tratamento de erros em um único lugar.
 */

// ============================================================
// CLASSES DE ERRO PERSONALIZADAS
// ============================================================

/**
 * Erro base para todos os erros da API.
 * Inclui statusCode, isOperational (erro esperado vs bug), e timestamp.
 */
class ApiError extends Error {
  /**
   * @param {number} statusCode — Código HTTP de status (4xx = cliente, 5xx = servidor)
   * @param {string} message    — Mensagem descritiva do erro
   * @param {Object} [meta]     — Metadados adicionais (ex: campos inválidos)
   */
  constructor(statusCode, message, meta = {}) {
    super(message); // Chama o construtor da classe Error nativa

    this.statusCode = statusCode;
    this.isOperational = true; // Erro esperado, não um bug do servidor
    this.meta = meta;
    this.timestamp = new Date().toISOString();

    // Mantém o stack trace correto mesmo com classes customizadas
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro para recursos não encontrados (HTTP 404).
 */
class NotFoundError extends ApiError {
  /**
   * @param {string} [resource] — Nome do recurso não encontrado (padrão: "Recurso")
   */
  constructor(resource = "Recurso") {
    super(404, `${resource} não encontrado`);
    this.resource = resource;
  }
}

/**
 * Erro para validação de dados inválidos (HTTP 400).
 */
class ValidationError extends ApiError {
  /**
   * @param {string} message — Mensagem do erro de validação
   * @param {Array<Object>} [fields] — Lista de campos com erros
   */
  constructor(message, fields = []) {
    super(400, message, { fields });
    this.fields = fields;
  }
}

/**
 * Erro para métodos HTTP não permitidos (HTTP 405).
 */
class MethodNotAllowedError extends ApiError {
  constructor(allowedMethods) {
    super(405, `Método ${req.method} não permitido. Use: ${allowedMethods.join(", ")}`);
    this.allowedMethods = allowedMethods;
  }
}

// ============================================================
// FUNÇÃO DE VALIDAÇÃO DE LIVRO
// ============================================================

/**
 * Valida os dados de um livro antes de criar ou atualizar.
 *
 * @param {Object} data — Dados a serem validados
 * @param {boolean} isUpdate — Se true, todos os campos são opcionais (partial update)
 * @returns {Array<Object>} Lista de erros de validação (vazia se válido)
 */
function validateBook(data, isUpdate = false) {
  const errors = [];

  if (!isUpdate) {
    // Para criação: title e author são obrigatórios
    if (!data.title || typeof data.title !== "string" || data.title.trim() === "") {
      errors.push({ field: "title", message: "Título é obrigatório e deve ser uma string não vazia" });
    }
    if (!data.author || typeof data.author !== "string" || data.author.trim() === "") {
      errors.push({ field: "author", message: "Autor é obrigatório e deve ser uma string não vazia" });
    }
  } else {
    // Para atualização parcial: pelo menos um campo deve ser fornecido
    const hasAnyField = data.title !== undefined || data.author !== undefined ||
                        data.year !== undefined || data.genre !== undefined;
    if (!hasAnyField) {
      errors.push({ field: "_all", message: "Pelo menos um campo deve ser fornecido para atualização" });
    }
  }

  // Validação do ano (se fornecido)
  if (data.year !== undefined && data.year !== null) {
    const year = Number(data.year);
    if (!Number.isInteger(year) || year < 1000 || year > 2100) {
      errors.push({ field: "year", message: "Ano deve ser um número inteiro entre 1000 e 2100" });
    }
  }

  // Validação do gênero (se fornecido)
  if (data.genre !== undefined && data.genre !== null) {
    if (typeof data.genre !== "string" || data.genre.trim() === "") {
      errors.push({ field: "genre", message: "Gênero deve ser uma string não vazia" });
    }
  }

  return errors;
}

// ============================================================
// MIDDLEWARES
// ============================================================

/**
 * Middleware que captura erros de rotas async/await.
 *
 * Express < 5 não propaga erros de promessas rejeitadas automaticamente.
 * Este wrapper envia cada handler de rota para garantir que erros
 * assíncronos sejam capturados e passados ao middleware de erro.
 *
 * @param {Function} fn — Handler de rota async
 * @returns {Function} Middleware Express
 */
function asyncHandler(fn) {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next); // Passa o erro para next(err)
  };
}

/**
 * Middleware de tratamento de erros principal.
 * Deve ser registrado APÓS todas as rotas.
 *
 * @param {Error} err — Objeto de erro capturado
 * @param {Object} req — Objeto request do Express
 * @param {Object} res — Objeto response do Express
 * @param {Function} next — Função next do Express
 */
function errorHandler(err, req, res, next) {
  // Se não for um ApiError, trata como erro interno do servidor (500)
  const statusCode = err.statusCode || 500;
  const isOperational = err.isOperational !== false;

  // Log do erro no servidor para depuração (não enviamos ao cliente)
  if (!isOperational) {
    console.error("[ERRO DO SERVIDOR]", err);
  }

  // Constrói a resposta de erro padronizada
  const errorResponse = {
    success: false,
    statusCode,
    message: err.message,
    timestamp: err.timestamp || new Date().toISOString(),
    path: req.path,
    method: req.method
  };

  // Inclui metadados específicos se disponíveis
  if (err.meta && Object.keys(err.meta).length > 0) {
    errorResponse.meta = err.meta;
  }

  if (err.fields && err.fields.length > 0) {
    errorResponse.fields = err.fields;
  }

  // Em produção, não expomos detalhes do stack trace ao cliente
  if (!isOperational && process.env.NODE_ENV !== "production") {
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
}

/**
 * Middleware que lida com rotas não encontradas (404).
 * Deve ser registrado APÓS todas as rotas, mas ANTES do errorHandler.
 */
function notFoundHandler(req, res, next) {
  // Se chegamos aqui, nenhuma rota correspondeu ao método + caminho
  next(new NotFoundError(`Rota ${req.method} ${req.path}`));
}

// ============================================================
// EXPORTAÇÕES
// ============================================================
module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  MethodNotAllowedError,
  validateBook,
  asyncHandler,
  errorHandler,
  notFoundHandler
};
