## Arquivo 4: `src/routes/books.js` — Rotas da API

```javascript
/**
 * ============================================================
 * ROTAS DA API DE LIVROS
 * ============================================================
 *
 * POR QUE ARQUIVO DE ROTA SEPARADO?
 * ----------------------------------
 * Separar rotas em arquivos distintos permite:
 *   1. Escalabilidade — novas entidades (autores, empréstimos) têm seus próprios arquivos
 *   2. Testabilidade — cada arquivo de rota pode ser testado isoladamente
 *   3. Legibilidade — código mais curto e focado por arquivo
 *   4. Reutilização — o router pode ser montado em múltiplos apps (ex: v1, v2)
 *
 * POR QUE USAR express.Router()?
 * -------------------------------
 * O Router do Express cria um mini-app de middleware que pode ser
 * montado em qualquer caminho. Isso permite:
 *   - Agrupar middlewares específicos por rota
 *   - Prefixar caminhos automaticamente (app.use('/books', bookRoutes))
 *   - Manter o app principal limpo e organizado
 *
 * POR QUE asyncHandler?
 * ---------------------
 * Express não captura erros de promessas rejeitadas em handlers async.
 * O asyncHandler envolve cada handler para que erros assíncronos
 * sejam propagados corretamente para o middleware de erro.
 */

const express = require("express");
const router = express.Router(); // Cria um roteador independente

// Importa funções do modelo e middleware de erros
const { findAll, findById, create, update, remove, getStats, filter } = require("../models/books");
const { asyncHandler, validateBook, NotFoundError } = require("../middleware/errors");

// ============================================================
// GET /books — Listar todos os livros (com filtragem)
// ============================================================
/**
 * @swagger
 * /books:
 *   get:
 *     summary: Lista todos os livros com filtragem opcional
 *     parameters:
 *       - in: query
 *         name: author
 *         schema: { type: string }
 *         description: Filtra por autor (case-insensitive)
 *       - in: query
 *         name: genre
 *         schema: { type: string }
 *         description: Filtra por gênero
 *       - in: query
 *         name: minYear
 *         schema: { type: integer }
 *         description: Ano mínimo de publicação
 *       - in: query
 *         name: maxYear
 *         schema: { type: integer }
 *         description: Ano máximo de publicação
 *       - in: query
 *         name: search
 *         schema: { type: string }
 *         description: Busca por título
 *     responses:
 *       200:
 *         description: Lista de livros retornada com sucesso
 *         content:
 *           application/json:
 *             schema:
 *               type: array
 *               items: { $ref: '#/components/schemas/Book' }
 */
router.get(
  "/",
  asyncHandler(async (req, res) => {
    // req.query contém todos os parâmetros da query string (?author=...&genre=...)
    const filteredBooks = filter(req.query);

    res.json({
      success: true,
      count: filteredBooks.length,
      data: filteredBooks
    });
  })
);

// Exemplo de uso com curl:
//   curl "http://localhost:3000/books"                          // Todos os livros
//   curl "http://localhost:3000/books?author=Machado"           // Filtra por autor
//   curl "http://localhost:3000/books?genre=Romance"            // Filtra por gênero
//   curl "http://localhost:3000/books?minYear=2000&maxYear=2010" // Faixa de anos
//   curl "http://localhost:3000/books?search=pessoa"            // Busca no título

// ============================================================
// GET /books/stats — Estatísticas dos livros
// ============================================================
/**
 * @swagger
 * /books/stats:
 *   get:
 *     summary: Retorna estatísticas agregadas dos livros
 *     responses:
 *       200:
 *         description: Estatísticas calculadas com sucesso
 */
router.get(
  "/stats",
  asyncHandler(async (req, res) => {
    const stats = getStats();

    res.json({
      success: true,
      data: stats
    });
  })
);

// Exemplo de uso com curl:
//   curl "http://localhost:3000/books/stats"

// ============================================================
// GET /books/:id — Obter um livro pelo ID
// ============================================================
/**
 * @swagger
 * /books/{id}:
 *   get:
 *     summary: Busca um livro específico por ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema: { type: integer }
 *         description: ID numérico do livro
 *     responses:
 *       200:
 *         description: Livro encontrado
 *       404:
 *         description: Livro não encontrado
 */
router.get(
  "/:id",
  asyncHandler(async (req, res, next) => {
    const id = Number(req.params.id); // Converte string da URL para número

    // Validação básica do ID
    if (!Number.isInteger(id) || id < 1) {
      return next(new NotFoundError("Livro"));
    }

    const book = findById(id);

    if (!book) {
      return next(new NotFoundError("Livro"));
    }

    res.json({
      success: true,
      data: book
    });
  })
);

// Exemplo de uso com curl:
//   curl "http://localhost:3000/books/1"
//   curl "http://localhost:3000/books/999"  // Retorna 404

// ============================================================
// POST /books — Criar um novo livro
// ============================================================
/**
 * @swagger
 * /books:
 *   post:
 *     summary: Cria um novo livro
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author]
 *             properties:
 *               title:   { type: string }
 *               author:  { type: string }
 *               year:    { type: integer }
 *               genre:   { type: string }
 *     responses:
 *       201:
 *         description: Livro criado com sucesso
 *       400:
 *         description: Erro de validação nos dados enviados
 */
router.post(
  "/",
  asyncHandler(async (req, res) => {
    // Valida os dados recebidos no corpo da requisição
    const validationErrors = validateBook(req.body, false);

    if (validationErrors.length > 0) {
      // Lança ValidationError com a lista de campos inválidos
      throw new (require("../middleware/errors").ValidationError)(
        "Dados de entrada inválidos",
        validationErrors
      );
    }

    const book = create(req.body);

    // 201 Created é o código HTTP padrão para recursos criados com sucesso.
    // O Location header indica onde o novo recurso pode ser acessado.
    res.status(201).json({
      success: true,
      data: book
    });
  })
);

// Exemplo de uso com curl:
//   curl -X POST http://localhost:3000/books \
//        -H "Content-Type: application/json" \
//        -d '{"title":"Dom Casmurro","author":"Machado de Assis","year":1899,"genre":"Romance"}'
//
//   curl -X POST http://localhost:3000/books \
//        -H "Content-Type: application/json" \
//        -d '{"title":"O Cortiço","author":"Aluísio Azevedo","year":1890}'

// ============================================================
// PUT /books/:id — Atualizar um livro existente
// ============================================================
/**
 * @swagger
 * /books/{id}:
 *   put:
 *     summary: Atualiza completamente um livro existente
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema: { type: integer }
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author]
 *             properties:
 *               title:   { type: string }
 *               author:  { type: string }
 *               year:    { type: integer }
 *               genre:   { type: string }
 *     responses:
 *       200:
 *         description: Livro atualizado com sucesso
 *       404:
 *         description: Livro não encontrado
 *       400:
 *         description: Erro de validação
 */
router.put(
  "/:id",
  asyncHandler(async (req, res, next) => {
    const id = Number(req.params.id);

    // Verifica se o livro existe antes de tentar atualizar
    const existingBook = findById(id);
    if (!existingBook) {
      return next(new NotFoundError("Livro"));
    }

    // Valida os dados de entrada
    const validationErrors = validateBook(req.body, true); // true = partial update

    if (validationErrors.length > 0) {
      throw new (require("../middleware/errors").ValidationError)(
        "Dados de entrada inválidos",
        validationErrors
      );
    }

    const updatedBook = update(id, req.body);

    res.json({
      success: true,
      message: "Livro atualizado com sucesso",
      data: updatedBook
    });
  })
);

// Exemplo de uso com curl:
//   curl -X PUT http://localhost:3000/books/1 \
//        -H "Content-Type: application/json" \
//        -d '{"title":"Dom Casmurro (Ed. Atualizada)","year":1899}'

// ============================================================
// DELETE /books/:id — Excluir um livro
// ============================================================
/**
 * @swagger
 * /books/{id}:
 *   delete:
 *     summary: Exclui um livro pelo ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema: { type: integer }
 *     responses:
 *       200:
 *         description: Livro excluído com sucesso
 *       404:
 *         description: Livro não encontrado
 */
router.delete(
  "/:id",
  asyncHandler(async (req, res, next) => {
    const id = Number(req.params.id);

    const deleted = remove(id);

    if (!deleted) {
      return next(new NotFoundError("Livro"));
    }

    // 200 OK com mensagem de confirmação
    // Alternativamente, poderia usar 204 No Content (sem body)
    res.json({
      success: true,
      message: "Livro excluído com sucesso"
    });
  })
);

// Exemplo de uso com curl:
//   curl -X DELETE http://localhost:3000/books/1

// ============================================================
// EXPORTAÇÃO DO ROTEADOR
// ============================================================
module.exports = router;
```

