## Arquivo 6: `src/server.js` — Ponto de Entrada do Servidor

```javascript
/**
 * ============================================================
 * PONTO DE ENTRADA DO SERVIDOR
 * ============================================================
 *
 * Este arquivo é responsável apenas por:
 *   1. Importar a configuração do app (app.js)
 *   2. Definir a porta de escuta
 *   3. Iniciar o servidor HTTP
 *   4. Lidar com erros de inicialização
 *
 * POR QUE process.env.PORT || 3000?
 * ----------------------------------
 * Em ambientes de produção (Heroku, AWS, etc.), a porta é definida
 * pela variável de ambiente PORT. O valor 3000 serve como fallback
 * para desenvolvimento local.
 */

const app = require("./app");

// Porta: usa variável de ambiente ou padrão 3000
const PORT = process.env.PORT || 3000;

// Cria o servidor HTTP a partir do app Express
const server = app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  API de Livros rodando na porta ${PORT}`);
  console.log(`  Ambiente: ${process.env.NODE_ENV || "development"}`);
  console.log(`  Endpoints disponíveis:`);
  console.log(`    GET    /books          — Listar livros`);
  console.log(`    GET    /books/stats    — Estatísticas`);
  console.log(`    GET    /books/:id      — Buscar livro`);
  console.log(`    POST   /books          — Criar livro`);
  console.log(`    PUT    /books/:id      — Atualizar livro`);
  console.log(`    DELETE /books/:id      — Excluir livro`);
  console.log(`    GET    /health         — Health check`);
  console.log(`========================================`);
});

// Tratamento de erros de inicialização do servidor
server.on("error", (err) => {
  if (err.code === "EADDRINUSE") {
    // Porta já está em uso
    console.error(`ERRO: A porta ${PORT} já está em uso!`);
    console.error("Use outra porta: PORT=3001 npm run dev");
  } else {
    console.error("Erro ao iniciar o servidor:", err);
  }
  process.exit(1); // Sai do processo com código de erro
});

// Tratamento de shutdown gracioso
process.on("SIGTERM", () => {
  console.log("SIGTERM recebido. Encerrando servidor...");
  server.close(() => {
    console.log("Servidor encerrado.");
    process.exit(0);
  });
});
```

