## 3. `routes/books.js` — All Book‑Related Routes & Business Logic

```javascript
/**
 * routes/books.js
 *
 * Contains all REST endpoints for the /books resource:
 *   GET    /books          – List all books (with optional filtering)
 *   GET    /books/:id      – Get a single book by ID
 *   POST   /books          – Create a new book
 *   PUT    /books/:id      – Update an existing book (full replacement)
 *   DELETE /books/:id      – Delete a book
 *   GET    /stats          – Return aggregate statistics
 *
 * Why separate route file?
 *   - Keeps the main app.js clean and focused on configuration.
 *   - Allows independent testing of routes.
 *   - Makes it easy to add versioning later (e.g., /api/v1/books).
 */

const express = require('express');
const router = express.Router(); // Creates a standalone route handler

// ─────────────────────────────────────────────────────────────────────────────
// IN-MEMORY DATA STORAGE
// ─────────────────────────────────────────────────────────────────────────────

/**
 * In-memory array to store book objects.
 *
 * Why an array instead of an object/map?
 *   - Arrays preserve insertion order (useful for pagination later).
 *   - They're simple and intuitive for a small educational dataset.
 *   - For production, you'd replace this with a database (PostgreSQL, MongoDB, etc.).
 *
 * Why not use a class or module-level singleton?
 *   - A plain array is stateless enough for this example.
 *   - In a real app, data access would be abstracted into a repository layer.
 */
const books = [
  { id: 1, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', year: 1925, genre: 'Fiction' },
  { id: 2, title: 'To Kill a Mockingbird', author: 'Harper Lee', year: 1960, genre: 'Fiction' },
  { id: 3, title: '1984', author: 'George Orwell', year: 1949, genre: 'Dystopian' },
];

// Auto-incrementing ID counter. Starts at max existing ID + 1.
let nextId = Math.max(...books.map((b) => b.id), 0) + 1;

// ─────────────────────────────────────────────────────────────────────────────
// CUSTOM ERROR CLASS
// ─────────────────────────────────────────────────────────────────────────────

/**
 * AppError: a custom error class that carries an HTTP status code.
 *
 * Why not just throw new Error('message')?
 *   - Generic errors don't convey whether the problem was client-side (4xx)
 *     or server-side (5xx). A statusCode lets middleware format consistent
 *     JSON responses without guessing.
 *   - isOperational=true marks expected errors (bad input, not found) vs.
 *     unexpected bugs (null pointer, DB down). This distinction helps logging.
 */
class AppError extends Error {
  constructor(message, statusCode) {
    super(message); // Call parent constructor with the message
    this.statusCode = statusCode;
    this.isOperational = true; // Expected error, not a code bug
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPER FUNCTIONS
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Generates the next unique ID for a new book.
 *
 * Why not use UUIDs or timestamps?
 *   - Simple integers are easier to read in examples and sufficient for
 *     an in-memory educational dataset.
 *   - In production, you'd use database auto-increment or UUID v4.
 */
function generateId() {
  return nextId++;
}

/**
 * Validates that a book object has the required fields with correct types.
 *
 * Why validate on every write?
 *   - Prevents malformed data from entering the store.
 *   - Fails fast with clear error messages instead of cryptic runtime errors later.
 *   - Required fields: title (string), author (string). Year and genre are optional.
 */
function validateBook(book) {
  const errors = [];

  if (!book.title || typeof book.title !== 'string') {
    errors.push('title is required and must be a string');
  }
  if (!book.author || typeof book.author !== 'string') {
    errors.push('author is required and must be a string');
  }
  if (book.year !== undefined && (typeof book.year !== 'number' || !Number.isInteger(book.year))) {
    errors.push('year must be an integer if provided');
  }

  if (errors.length > 0) {
    throw new AppError(errors.join('; '), 400); // 400 = Bad Request
  }
}

/**
 * Finds a book by ID and throws a 404 error if not found.
 *
 * Why wrap the lookup in a helper?
 *   - Avoids repeating the same find + throw pattern in every route handler.
 *   - Keeps handlers focused on response formatting, not data access logic.
 */
function findBookById(id) {
  const book = books.find((b) => b.id === id);
  if (!book) {
    throw new AppError(`Book with ID ${id} not found`, 404);
  }
  return book;
}

// ─────────────────────────────────────────────────────────────────────────────
// ROUTE HANDLERS
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GET /books
 *
 * Returns all books, optionally filtered by query parameters:
 *   ?genre=Fiction      – Filter by genre (case-insensitive)
 *   ?author=Orwell      – Filter by author substring match
 *
 * Why use query parameters instead of request body for filtering?
 *   - GET requests should be idempotent and safe; bodies are not standard.
 *   - Query params are cacheable and appear in URLs/history.
 *   - REST convention: filters belong in the URL, not the payload.
 */
router.get('/books', async (req, res) => {
  try {
    const { genre, author } = req.query;

    let result = books;

    // Apply genre filter if provided (case-insensitive substring match)
    if (genre) {
      result = result.filter((b) =>
        b.genre.toLowerCase().includes(genre.toLowerCase())
      );
    }

    // Apply author filter if provided (case-insensitive substring match)
    if (author) {
      result = result.filter((b) =>
        b.author.toLowerCase().includes(author.toLowerCase())
      );
    }

    res.json({
      count: result.length,
      data: result,
    });
  } catch (err) {
    // Re-throw so the global error middleware handles it
    next(err);
  }
});

/**
 * GET /books/:id
 *
 * Returns a single book by its numeric ID.
 *
 * Why validate :id is a number?
 *   - Prevents NaN or string IDs from causing silent failures.
 *   - Returns 400 (Bad Request) instead of 500 for malformed URLs.
 */
router.get('/books/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id)) {
      throw new AppError('Invalid book ID: must be an integer', 400);
    }

    const book = findBookById(id);
    res.json(book);
  } catch (err) {
    next(err); // Pass to global error handler
  }
});

/**
 * POST /books
 *
 * Creates a new book. Expects JSON body with at least title and author.
 * Returns the created book with status 201 (Created).
 *
 * Why return 201 instead of 200?
 *   - 201 explicitly signals that a new resource was created.
 *   - Clients can distinguish between "got existing data" and "created new data".
 */
router.post('/books', async (req, res, next) => {
  try {
    const { title, author, year, genre } = req.body;

    // Validate required fields before creating the object
    validateBook({ title, author, year });

    const newBook = {
      id: generateId(),
      title,
      author,
      year: year || null,   // Allow missing year (e.g., for undated works)
      genre: genre || null,
    };

    books.push(newBook);

    res.status(201).json(newBook);
  } catch (err) {
    next(err);
  }
});

/**
 * PUT /books/:id
 *
 * Fully replaces an existing book with the provided data.
 * Returns the updated book with status 200.
 *
 * Why full replacement instead of partial update?
 *   - PUT is defined by REST as idempotent and complete.
 *   - PATCH would be used for partial updates; we keep this example focused.
 *   - Simpler validation: all required fields must be present in the body.
 */
router.put('/books/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id)) {
      throw new AppError('Invalid book ID: must be an integer', 400);
    }

    // Find and validate before mutating
    const existingBook = findBookById(id);
    validateBook(req.body);

    // Replace the entire object (PUT semantics)
    const updatedBook = {
      id,
      title: req.body.title,
      author: req.body.author,
      year: req.body.year || null,
      genre: req.body.genre || null,
    };

    // Find index and replace in-place to preserve array order
    const index = books.findIndex((b) => b.id === id);
    books[index] = updatedBook;

    res.json(updatedBook);
  } catch (err) {
    next(err);
  }
});

/**
 * DELETE /books/:id
 *
 * Removes a book by ID. Returns 204 No Content on success.
 *
 * Why 204 instead of 200?
 *   - 204 explicitly means "success, but no body to return".
 *   - Saves bandwidth and signals that the resource is gone.
 */
router.delete('/books/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (!Number.isInteger(id)) {
      throw new AppError('Invalid book ID: must be an integer', 400);
    }

    const index = books.findIndex((b) => b.id === id);

    if (index === -1) {
      throw new AppError(`Book with ID ${id} not found`, 404);
    }

    // Remove the book from the array
    books.splice(index, 1);

    res.status(204).send(); // No body for 204
  } catch (err) {
    next(err);
  }
});

/**
 * GET /stats
 *
 * Returns aggregate statistics about the book collection:
 *   - totalBooks: number of books in storage
 *   - averageYear: mean publication year (rounded to nearest integer)
 *   - mostCommonGenre: genre with the highest count
 *   - booksByDecade: distribution of books across decades
 *
 * Why compute stats on every request?
 *   - The dataset is tiny (in-memory), so real-time computation is cheap.
 *   - For large datasets, you'd cache or precompute these values.
 */
router.get('/stats', async (req, res) => {
  const totalBooks = books.length;

  if (totalBooks === 0) {
    return res.json({
      totalBooks: 0,
      averageYear: null,
      mostCommonGenre: null,
      booksByDecade: {},
    });
  }

  // Calculate average year
  const sumYears = books.reduce((sum, b) => sum + (b.year || 0), 0);
  const averageYear = Math.round(sumYears / totalBooks);

  // Find most common genre
  const genreCounts = {};
  books.forEach((b) => {
    if (b.genre) {
      genreCounts[b.genre] = (genreCounts[b.genre] || 0) + 1;
    }
  });
  const mostCommonGenre = Object.entries(genreCounts).sort((a, b) => b[1] - a[1])[0]?.[0] || null;

  // Group by decade
  const booksByDecade = {};
  books.forEach((b) => {
    if (b.year) {
      const decade = Math.floor(b.year / 10) * 10;
      const key = `${decade}s`;
      booksByDecade[key] = (booksByDecade[key] || 0) + 1;
    }
  });

  res.json({
    totalBooks,
    averageYear,
    mostCommonGenre,
    booksByDecade,
  });
});

module.exports = router;
```

**Why async/await if storage is synchronous?**  
- Demonstrates the pattern so you can swap in an async database (MongoDB, PostgreSQL) later without changing route signatures.  
- Keeps error handling consistent: `try/catch` works the same for sync and async code.  
- Modern Express best practice—avoids callback hell and makes reasoning about control flow easier.

**Why throw custom errors instead of returning them?**  
- Throwing lets the global error middleware centralize response formatting.  
- Route handlers stay focused on business logic; they don't need to know how errors are serialized.  
- Prevents accidental `res.json({error: ...})` leaks that bypass status codes.

