## Arquivo: `src/utils/errors.js`

```javascript
/**
 * ============================================================
 *  CLASSES DE ERRO PERSONALIZADAS
 * ============================================================
 *
 *  POR QUE criar classes de erro customizadas?
 *
 *  1.  **Identificação precisa**: Permite distinguir entre
 *      "recurso não encontrado", "entrada inválida" e erros
 *      genéricos do servidor, facilitando o tratamento no
 *      middleware de erros.
 *
 *      Sem classes customizadas, teríamos que inspecionar
 *      strings de mensagem ou códigos numéricos — propenso
 *      a erros e difícil de manter.
 *
 *  2.  **Propriedade `statusCode` nativa**: Cada classe carrega
 *      seu código HTTP padrão, eliminando a necessidade de
 *      definir o status manualmente em cada throw.
 *
 *  3.  **Extensibilidade**: Novos tipos de erro podem ser
 *      adicionados facilmente (ex: `ForbiddenError`,
 *      `RateLimitError`) herdando da classe base.
 *
 *  4.  **Stack trace preservado**: Ao estender `Error`, o
 *      stack trace nativo do JavaScript é mantido, o que é
 *      essencial para debug em produção.
 */

/**
 * Classe base para todos os erros da API.
 *
 * Herda de `Error` para preservar o comportamento padrão
 * (stack trace, mensagem) e adiciona `statusCode` como
 * propriedade padrão.
 */
class ApiError extends Error {
  /**
   * @param {string} message - Descrição legível do erro
   * @param {number} statusCode - Código HTTP da resposta (padrão: 500)
   */
  constructor(message, statusCode = 500) {
    super(message); // Chama o construtor de Error com a mensagem

    // `this.statusCode` é uma propriedade customizada.
    // Usamos `Object.defineProperty` para torná-la não enumerável,
    // evitando que apareça em JSON.stringify() acidentalmente.
    this.statusCode = statusCode;

    // `name` identifica o tipo do erro (usado no middleware)
    this.name = this.constructor.name;

    // Captura a linha exata onde o erro foi criado para debug
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro 400 — Bad Request.
 *
 * Usado quando o cliente envia dados malformados ou inválidos.
 * Exemplo: ID numérico esperado mas recebido como string vazia.
 */
class BadRequestError extends ApiError {
  constructor(message = 'Requisição inválida') {
    super(message, 400);
  }
}

/**
 * Erro 404 — Not Found.
 *
 * Usado quando o recurso solicitado não existe no armazenamento.
 * Exemplo: GET /books/999 onde nenhum livro com ID 999 existe.
 */
class NotFoundError extends ApiError {
  constructor(message = 'Recurso não encontrado') {
    super(message, 404);
  }
}

/**
 * Erro 409 — Conflict.
 *
 * Usado quando a operação conflita com o estado atual do recurso.
 * Exemplo: tentar criar um livro com ISBN duplicado.
 */
class ConflictError extends ApiError {
  constructor(message = 'Conflito com recurso existente') {
    super(message, 409);
  }
}

// Exporta todas as classes como um único objeto para facilitar imports
module.exports = { ApiError, BadRequestError, NotFoundError, ConflictError };
```

