```javascript
/**
 * ============================================================
 *  MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================
 *
 *  POR QUE um middleware dedicado para erros?
 *
 *  No Express, middlewares de erro têm uma assinatura especial
 *  com QUATRO parâmetros: `(err, req, res, next)`. O framework
 *  os identifica automaticamente e os encadeia apenas quando
 *  `next(err)` é chamado. Isso separa a lógica de negócio da
 *  lógica de tratamento de falhas.
 *
 *  Padrão adotado: resposta JSON consistente com campos
 *  `error` (mensagem), `statusCode` (número) e opcionalmente
 *  `message` detalhado. Isso permite que clientes consumam
 *  a API sem precisar fazer parsing de HTML ou strings.
 */

const { ApiError } = require('../utils/errors');

/**
 * Middleware central de tratamento de erros.
 *
 * @param {ApiError} err - Instância de erro lançada por uma rota ou middleware
 * @param {import('express').Request} req - Objeto Request do Express
 * @param {import('express').Response} res - Objeto Response do Express
 * @param {import('express').NextFunction} next - Função para encadear ao próximo middleware
 */
function errorHandler(err, req, res, next) {
  // Determina o statusCode: usa o da classe customizada ou 500 como fallback
  const statusCode = err.statusCode || 500;

  // Em desenvolvimento, incluímos o stack trace para facilitar debug.
  // Em produção, isso seria omitido para não vazar informações internas.
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Estrutura de resposta padronizada para erros da API
  const errorResponse = {
    error: err.message || 'Erro interno do servidor',
    statusCode,
    ...(isDevelopment && { stack: err.stack }), // Condicional: só em dev
  };

  // Log do erro no console (essencial para monitoramento em produção)
  console.error(`[ERROR] ${statusCode} — ${err.message}`);
  if (isDevelopment && err.stack) {
    console.error(err.stack);
  }

  // Envia a resposta JSON padronizada
  res.status(statusCode).json(errorResponse);
}

module.exports = errorHandler;
