/**
 * ============================================================
 *  MIDDLEWARE 404 — ROTA NÃO ENCONTRADA
 * ============================================================
 *
 *  POR QUE um middleware separado para 404?
 *
 *  Se nenhuma rota corresponder à URL solicitada, o Express
 *  não lança erro automaticamente. Precisamos capturar isso
 *  manualmente e encadear um erro para que o `errorHandler`
 *  (definido acima) processe a resposta de forma consistente.
 *
 *  Colocamos este middleware DEPOIS de todas as rotas registradas,
 *  pois ele deve ser o "último recurso" antes do errorHandler.
 */

const { NotFoundError } = require('../utils/errors');

function notFoundHandler(req, res, next) {
  // Lança um NotFoundError que será capturado pelo errorHandler
  next(new NotFoundError(`Rota ${req.method} ${req.path} não encontrada`));
}

module.exports = notFoundHandler;
