## Arquivo: `src/routes/books.js`

```javascript
/**
 * ============================================================
 *  ROTAS DE LIVROS — CRUD COMPLETO + ESTATÍSTICAS
 * ============================================================
 *
 *  POR QUE usar rotas organizadas em módulo separado?
 *
 *  1.  **Separação de responsabilidades**: O arquivo `app.js`
 *      cuida da configuração do Express; este arquivo cuida
 *      apenas da lógica de negócio das rotas. Isso facilita
 *      testes unitários e manutenção.
 *
 *  2.  **Escopo isolado**: Variáveis como `books` (array em
 *      memória) ficam encapsuladas neste módulo, sem poluir
 *      o escopo global ou o arquivo principal.
 *
 *  3.  **Convenção REST**: Cada método HTTP mapeia para uma
 *      operação CRUD padrão:
 *        GET    /books       → Listar (com filtragem)
 *        GET    /books/:id   → Mostrar um
 *        POST   /books       → Criar
 *        PUT    /books/:id   → Atualizar completo
 *        DELETE /books/:id   → Excluir
 *        GET    /stats       → Estatísticas (não-CRUD)
 *
 *  ESTRUTURA DE DADOS — Array em Memória:
 *
 *  Escolhemos um array de objetos porque:
 *  - Simplicidade: não requer configuração de banco de dados.
 *  - Adequado para exemplos educacionais e protótipos.
 *  - Operações básicas (push, find, filter, splice) são
 *    diretas e legíveis.
 *
 *  Limitações conhecidas (para fins educacionais):
 *  - Dados são perdidos ao reiniciar o servidor.
 *  - Busca por ID é O(n) — aceitável para poucos registros.
 *  - Sem concorrência (single-threaded).
 *
 *  Para produção, substituiríamos por um banco com índices
 *  adequados (MongoDB, PostgreSQL, etc.).
 */

const { Router } = require('express');
const {
  BadRequestError,
  NotFoundError,
  ConflictError,
} = require('../utils/errors');

// Instância do roteador Express — padrão recomendado para modularidade
const router = Router();

// ============================================================
//  ARMAZENAMENTO EM MEMÓRIA (Array)
// ============================================================
//
//  Usamos `let` em vez de `const` porque o array será modificado
//  (push, splice). O binding da variável é reatribuído, não o
//  conteúdo do array.
//
//  Cada livro tem a seguinte estrutura:
//    {
//      id: number          — Identificador único autoincrementado
//      title: string       — Título do livro (obrigatório)
//      author: string      — Autor (obrigatório)
//      isbn: string        — ISBN único (obrigatório, sem duplicatas)
//      year: number        — Ano de publicação
//      genre: string       — Gênero literário
//      createdAt: string   — Timestamp ISO da criação
//      updatedAt: string   — Timestamp ISO da última atualização
//    }
let books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    isbn: '978-0618640157',
    year: 1954,
    genre: 'Fantasia',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    isbn: '978-0451524935',
    year: 1949,
    genre: 'Distopia',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    isbn: '978-8525046815',
    year: 1899,
    genre: 'Romance',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
];

// Contador para IDs autoincrementados
let nextId = 4;

// ============================================================
//  FUNÇÕES DE VALIDAÇÃO (helpers privados)
// ============================================================

/**
 * Valida os campos obrigatórios de um livro.
 *
 * @param {object} data - Dados parciais ou completos do livro
 * @returns {string[]} - Lista de erros de validação (vazia se válido)
 */
function validateBook(data) {
  const errors = [];

  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    errors.push('O campo "title" é obrigatório e deve ser uma string não vazia');
  }

  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    errors.push('O campo "author" é obrigatório e deve ser uma string não vazia');
  }

  if (!data.isbn || typeof data.isbn !== 'string' || data.isbn.trim() === '') {
    errors.push('O campo "isbn" é obrigatório e deve ser uma string não vazia');
  }

  if (data.year !== undefined && (isNaN(data.year) || !Number.isInteger(data.year))) {
    errors.push('O campo "year" deve ser um número inteiro');
  }

  return errors;
}

/**
 * Converte parâmetros de query para tipos adequados.
 *
 * @param {object} query - Objeto de query strings do Express
 * @returns {object} - Query com tipos convertidos
 */
function parseQueryParams(query) {
  const parsed = { ...query };

  // Converte `page` e `limit` para números, com valores padrão
  if (parsed.page) {
    parsed.page = Math.max(1, parseInt(parsed.page, 10)) || 1;
  } else {
    parsed.page = 1;
  }

  if (parsed.limit) {
    parsed.limit = Math.min(100, Math.max(1, parseInt(parsed.limit, 10))) || 10;
  } else {
    parsed.limit = 10;
  }

  // Converte `sortBy` para lowercase para comparação case-insensitive
  if (parsed.sortBy) {
    parsed.sortBy = parsed.sortBy.toLowerCase();
  }

  return parsed;
}

// ============================================================
//  GET /books — LISTAR TODOS OS LIVROS COM FILTRAGEM
// ============================================================
/**
 * @route   GET /books
 * @desc    Lista todos os livros com suporte a filtragem, paginação e ordenação
 * @access  Public
 *
 * @query {string} [search]       — Busca por título ou autor (case-insensitive)
 * @query {string} [genre]        — Filtra por gênero literário
 * @query {number} [yearFrom]     — Ano mínimo de publicação
 * @query {number} [yearTo]       — Ano máximo de publicação
 * @query {number} [page=1]       — Número da página (começa em 1)
 * @query {number} [limit=10]     — Itens por página (máx: 100)
 * @query {string} [sortBy=title] — Campo para ordenação (title, author, year)
 * @query {string} [order=asc]    — Direção da ordenação (asc | desc)
 *
 * @example curl "http://localhost:3000/books?genre=Fantasia&page=1&limit=5"
 * @example curl "http://localhost:3000/books?search=tolkien&sortBy=year&order=desc"
 */
router.get('/', (req, res) => {
  // Começamos com uma cópia do array para não mutar a fonte durante o processamento
  let result = [...books];

  const query = parseQueryParams(req.query);

  // --- FILTRO POR TERMOS DE BUSCA (título ou autor) ---
  if (query.search) {
    const term = query.search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(term) ||
        book.author.toLowerCase().includes(term)
    );
  }

  // --- FILTRO POR GÊNERO ---
  if (query.genre) {
    const genreLower = query.genre.toLowerCase();
    result = result.filter((book) => book.genre.toLowerCase() === genreLower);
  }

  // --- FILTRO POR INTERVALO DE ANOS ---
  if (query.yearFrom !== undefined) {
    result = result.filter((book) => book.year >= Number(query.yearFrom));
  }
  if (query.yearTo !== undefined) {
    result = result.filter((book) => book.year <= Number(query.yearTo));
  }

  // --- ORDENAÇÃO ---
  const validSortFields = ['title', 'author', 'year'];
  const sortBy = validSortFields.includes(query.sortBy) ? query.sortBy : 'title';
  const order = query.order === 'desc' ? -1 : 1; // asc = 1, desc = -1

  result.sort((a, b) => {
    if (typeof a[sortBy] === 'string') {
      return a[sortBy].localeCompare(b[sortBy]) * order;
    }
    return (a[sortBy] - b[sortBy]) * order;
  });

  // --- PAGINAÇÃO ---
  const total = result.length;
  const totalPages = Math.ceil(total / query.limit);
  const startIndex = (query.page - 1) * query.limit;
  const paginatedBooks = result.slice(startIndex, startIndex + query.limit);

  // Resposta padronizada com metadados de paginação
  res.json({
    success: true,
    data: paginatedBooks,
    pagination: {
      currentPage: query.page,
      totalPages,
      totalItems: total,
      itemsPerPage: query.limit,
      hasNextPage: query.page < totalPages,
      hasPrevPage: query.page > 1,
    },
  });
});

// ============================================================
//  GET /books/stats — ESTATÍSTICAS
// ============================================================
/**
 * @route   GET /books/stats
 * @desc    Retorna estatísticas agregadas sobre o acervo de livros
 * @access  Public
 *
 * @example curl "http://localhost:3000/books/stats"
 */
router.get('/stats', (req, res) => {
  // Agrupamos por gênero para contar quantos livros existem em cada um
  const genreCounts = {};
  for (const book of books) {
    genreCounts[book.genre] = (genreCounts[book.genre] || 0) + 1;
  }

  // Encontramos o livro mais antigo e o mais recente por ano de publicação
  const sortedByYear = [...books].sort((a, b) => a.year - b.year);
  const oldestBook = sortedByYear[0] || null;
  const newestBook = sortedByYear[sortedByYear.length - 1] || null;

  // Calculamos a média de anos de publicação
  const avgYear =
    books.length > 0
      ? Math.round(books.reduce((sum, b) => sum + b.year, 0) / books.length)
      : 0;

  res.json({
    success: true,
    data: {
      totalBooks: books.length,
      totalGenres: Object.keys(genreCounts).length,
      avgPublicationYear: avgYear,
      oldestBook: oldestBook
        ? { title: oldestBook.title, author: oldestBook.author, year: oldestBook.year }
        : null,
      newestBook: newestBook
        ? { title: newestBook.title, author: newestBook.author, year: newestBook.year }
        : null,
      booksByGenre: genreCounts,
    },
  });
});

// ============================================================
//  GET /books/:id — OBTER LIVRO POR ID
// ============================================================
/**
 * @route   GET /books/:id
 * @desc    Retorna um livro específico pelo seu ID numérico
 * @access  Public
 *
 * @param {number} id - ID do livro (deve ser um número inteiro positivo)
 *
 * @example curl "http://localhost:3000/books/1"
 */
router.get('/:id', (req, res, next) => {
  // --- VALIDAÇÃO DO PARÂMETRO DE ROTA ---
  // Convertimos para número e verificamos se é válido.
  // Isso previne que IDs como "abc" ou "-5" causem comportamentos inesperados.
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1) {
    return next(new BadRequestError('O parâmetro "id" deve ser um número inteiro positivo'));
  }

  // `find` retorna o primeiro elemento que satisfaz a condição, ou undefined.
  // Usamos comparação estrita (===) para evitar coerção de tipos (ex: "1" === 1 é false).
  const book = books.find((b) => b.id === id);

  if (!book) {
    // Encadeamos o erro para o middleware errorHandler, mantendo consistência
    return next(new NotFoundError(`Livro com ID ${id} não encontrado`));
  }

  res.json({ success: true, data: book });
});

// ============================================================
//  POST /books — CRIAR NOVO LIVRO
// ============================================================
/**
 * @route   POST /books
 * @desc    Cria um novo livro no acervo
 * @access  Public
 *
 * @body {string}  title  - Título do livro (obrigatório)
 * @body {string}  author - Autor do livro (obrigatório)
 * @body {string}  isbn   - ISBN único (obrigatório, sem duplicatas)
 * @body {number}  [year]  - Ano de publicação (opcional)
 * @body {string}  [genre] - Gênero literário (opcional, padrão: "Não informado")
 *
 * @example curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","isbn":"978-0060850524","year":1932,"genre":"Distopia"}'
 */
router.post('/', (req, res, next) => {
  const { title, author, isbn, year, genre } = req.body;

  // --- VALIDAÇÃO DOS DADOS DE ENTRADA ---
  const validationErrors = validateBook(req.body);
  if (validationErrors.length > 0) {
    return next(new BadRequestError(validationErrors.join('; ')));
  }

  // --- VERIFICAÇÃO DE DUPLICATA DE ISBN ---
  // ISBN é um identificador único global. Dois livros com o mesmo ISBN
  // seriam o mesmo livro fisicamente, então bloqueamos duplicatas.
  const isbnExists = books.some((b) => b.isbn === isbn.trim());
  if (isbnExists) {
    return next(new ConflictError(`Já existe um livro com ISBN "${isbn}"`));
  }

  // --- CRIAÇÃO DO NOVO LIVRO ---
  const newBook = {
    id: nextId++, // Autoincremento simples — em produção, use UUID ou sequência de DB
    title: title.trim(),
    author: author.trim(),
    isbn: isbn.trim(),
    year: year ? Number(year) : null,
    genre: genre ? genre.trim() : 'Não informado',
    createdAt: new Date().toISOString(), // ISO 8601 para compatibilidade universal
    updatedAt: new Date().toISOString(),
  };

  books.push(newBook);

  // Status 201 = Created (padrão REST para recursos criados com sucesso)
  res.status(201).json({ success: true, data: newBook });
});

// ============================================================
//  PUT /books/:id — ATUALIZAR LIVRO EXISTENTE (completo)
// ============================================================
/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente
 * @access  Public
 *
 * @param {number} id       - ID do livro a atualizar
 * @body {string}  [title]  - Novo título
 * @body {string}  [author] - Novo autor
 * @body {string}  [isbn]   - Novo ISBN (deve ser único)
 * @body {number}  [year]   - Novo ano de publicação
 * @body {string}  [genre]  - Novo gênero
 *
 * @example curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis (Ed. Definitiva)","author":"J.R.R. Tolkien","isbn":"978-0618640157","year":1954,"genre":"Fantasia"}'
 */
router.put('/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1) {
    return next(new BadRequestError('O parâmetro "id" deve ser um número inteiro positivo'));
  }

  // Localiza o livro pelo ID
  const bookIndex = books.findIndex((b) => b.id === id);
  if (bookIndex === -1) {
    return next(new NotFoundError(`Livro com ID ${id} não encontrado`));
  }

  // --- VALIDAÇÃO DOS CAMPOS FORNECIDOS ---
  const validationErrors = validateBook(req.body);
  if (validationErrors.length > 0) {
    return next(new BadRequestError(validationErrors.join('; ')));
  }

  // --- VERIFICAÇÃO DE DUPLICATA DE ISBN (excluindo o próprio livro) ---
  const isbnExists = books.some(
    (b) => b.isbn === req.body.isbn.trim() && b.id !== id
  );
  if (isbnExists) {
    return next(new ConflictError(`Já existe um livro com ISBN "${req.body.isbn}"`));
  }

  // --- ATUALIZAÇÃO COMPLETA DO REGISTRO ---
  // Usamos spread operator para criar um novo objeto imutável,
  // preservando campos que não foram enviados (como createdAt).
  const updatedBook = {
    ...books[bookIndex], // Copia todos os campos existentes
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    isbn: req.body.isbn.trim(),
    year: req.body.year ? Number(req.body.year) : null,
    genre: req.body.genre ? req.body.genre.trim() : 'Não informado',
    updatedAt: new Date().toISOString(), // Atualiza timestamp de modificação
  };

  // Substitui o livro antigo pelo atualizado no array
  books[bookIndex] = updatedBook;

  res.json({ success: true, data: updatedBook });
});

// ============================================================
//  DELETE /books/:id — EXCLUIR LIVRO
// ============================================================
/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro do acervo permanentemente
 * @access  Public
 *
 * @param {number} id - ID do livro a excluir
 *
 * @example curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1) {
    return next(new BadRequestError('O parâmetro "id" deve ser um número inteiro positivo'));
  }

  // `findIndex` retorna -1 se não encontrar — mais eficiente que find + indexOf
  const bookIndex = books.findIndex((b) => b.id === id);
  if (bookIndex === -1) {
    return next(new NotFoundError(`Livro com ID ${id} não encontrado`));
  }

  // `splice` remove o elemento do array e retorna um array com o elemento removido
  const [deletedBook] = books.splice(bookIndex, 1);

  // Status 200 = OK (recurso removido com sucesso)
  res.json({ success: true, data: deletedBook, message: 'Livro excluído com sucesso' });
});

module.exports = router;
```

