## Arquivo: `src/app.js`

```javascript
/**
 * ============================================================
 *  CONFIGURAÇÃO DO SERVIDOR EXPRESS
 * ============================================================
 *
 *  POR QUE separar a configuração do Express do ponto de entrada?
 *
 *  O arquivo `app.js` centraliza toda a configuração do servidor:
 *  middlewares globais, rotas e tratamento de erros. Isso permite
 *  que o `index.js` seja apenas um "wrapper" mínimo que inicia
 *  o servidor na porta correta.
 *
 *  Padrões adotados:
 *  - `express.json()`: Parser nativo para bodies JSON (requerido
 *    para POST/PUT com payload). Sem isso, `req.body` seria undefined.
 *  - Middlewares de segurança e logging em produção.
 *  - Rotas montadas com `app.use('/books', booksRouter)` — o prefixo
 *    é adicionado automaticamente a todas as rotas do módulo.
 */

const express = require('express');
const booksRouter = require('./routes/books');
const errorHandler = require('./middleware/errorHandler');
const notFoundHandler = require('./middleware/notFound');

const app = express();

// ============================================================
//  MIDDLEWARES GLOBAIS
// ============================================================

/**
 * Parser de JSON com limite de 10kb por body.
 *
 * Sem este middleware, o Express não parsearia automaticamente
 * o corpo de requisições POST/PUT. O limite previne ataques de
 * negação de serviço por bodies excessivamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Logger simples de requisições (formato combinado do Apache).
 *
 * Em produção, substituiríamos por um logger profissional como
 * `morgan` ou `pino`. Para este exemplo educacional, mantemos
 * a simplicidade com console.log formatado.
 */
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const method = req.method;
  const path = req.path;
  const status = res.statusCode;
  console.log(`[${timestamp}] ${method} ${path} → ${status}`);
  next();
});

// ============================================================
//  ROTAS
// ============================================================

/**
 * Rota raiz para health check e documentação.
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'API de Livros — Servidor rodando!',
    endpoints: {
      docs: 'GET /',
      listBooks: 'GET /books',
      getBook: 'GET /books/:id',
      createBook: 'POST /books',
      updateBook: 'PUT /books/:id',
      deleteBook: 'DELETE /books/:id',
      stats: 'GET /books/stats',
    },
  });
});

/**
 * Montagem do roteador de livros com prefixo '/books'.
 *
 * Todas as rotas definidas em `routes/books.js` serão acessíveis
 * sob o caminho base `/books` (ex: GET /books, POST /books/:id).
 */
app.use('/books', booksRouter);

// ============================================================
//  MIDDLEWARES DE ERRO (DEPOIS de todas as rotas)
// ============================================================

/**
 * Middleware 404 — capturado após todas as rotas serem testadas.
 */
app.use(notFoundHandler);

/**
 * Middleware central de tratamento de erros — deve ser o último.
 */
app.use(errorHandler);

module.exports = app;
```

