## File 2: `app.js` — Application Entry Point & Middleware

```javascript
/**
 * app.js — Express application entry point
 *
 * This module wires together middleware, routes, and error handling.
 * It is intentionally kept thin — route logic lives in ./routes/.
 *
 * Architecture decisions:
 *   - Middleware order matters: body-parser BEFORE routes so req.body is populated.
 *   - A global error-handling middleware (4-arg signature) catches all errors.
 *   - In-memory storage is a module-level variable for simplicity; in production,
 *     swap this for a database connection pool or ORM.
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

// ──────────────────────────────────────────────
// In-Memory Data Store
// ──────────────────────────────────────────────
/**
 * Why an array? Arrays provide O(1) access by index and are trivial to iterate,
 * filter, map, and reduce — ideal for a small educational dataset.
 * For production, replace with MongoDB (document model), PostgreSQL (relational),
 * or Redis (key-value) depending on query patterns and scale requirements.
 */
let books = [
  { id: 1, title: 'The Great Gatsby', author: 'F. Scott Fitzgerald', genre: 'Fiction', publishedYear: 1925, rating: 4.5 },
  { id: 2, title: 'Clean Code', author: 'Robert C. Martin', genre: 'Technology', publishedYear: 2008, rating: 4.7 },
  { id: 3, title: 'Dune', author: 'Frank Herbert', genre: 'Science Fiction', publishedYear: 1965, rating: 4.8 },
  { id: 4, title: 'The Pragmatic Programmer', author: 'David Thomas', genre: 'Technology', publishedYear: 1999, rating: 4.6 },
  { id: 5, title: '1984', author: 'George Orwell', genre: 'Fiction', publishedYear: 1949, rating: 4.7 },
];

// Auto-incrementing ID counter — prevents collisions when generating new IDs.
let nextId = 6;

// ──────────────────────────────────────────────
// Express App Setup
// ──────────────────────────────────────────────
const app = express();
const PORT = process.env.PORT || 3000;

/**
 * Why JSON body parser? REST APIs typically exchange JSON payloads.
 * express.json() parses incoming request bodies and exposes them on req.body.
 * Without it, POST/PUT bodies would be raw strings — impossible to work with.
 */
app.use(express.json());

// Simple logging middleware for debugging requests in development.
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler.
});

// ──────────────────────────────────────────────
// Register Routes
// ──────────────────────────────────────────────
/**
 * Why separate route modules? Separation of concerns: app.js handles
 * infrastructure (middleware, server startup) while routes handle business logic.
 * This makes the codebase easier to test, extend, and navigate.
 */
app.use('/books', bookRoutes);
app.use('/stats', statsRoutes);

// ──────────────────────────────────────────────
// 404 Fallback — Catch unmatched routes
// ──────────────────────────────────────────────
/**
 * Any request that reaches this point has no matching route.
 * We throw a NotFoundError so the global error handler formats it consistently.
 */
app.use((req, res, next) => {
  const err = new Error(`Route ${req.method} ${req.url} not found`);
  err.statusCode = 404;
  next(err);
});

// ──────────────────────────────────────────────
// Global Error-Handling Middleware
// ──────────────────────────────────────────────
/**
 * Express recognizes error-handling middleware by its 4-parameter signature:
 *   (err, req, res, next) => ...
 * This middleware MUST be registered AFTER all routes. It catches errors thrown
 * or passed via next(err) from any preceding middleware or route handler.
 *
 * Why centralize error handling? It prevents repetitive try/catch blocks in every
 * route and ensures consistent error response shapes for API consumers.
 */
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  console.error('[ERROR]', err.message);

  /**
   * In production, never expose internal stack traces to clients — they leak
   * implementation details and can aid attackers. Log the full error server-side
   * and return a sanitized response.
   */
  res.status(statusCode).json({
    success: false,
    error: err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ──────────────────────────────────────────────
// Start Server
// ──────────────────────────────────────────────
app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   Try: GET http://localhost:${PORT}/books`);
});

module.exports = app;
```

