## File 3: `routes/books.js` — Books CRUD Routes

```javascript
/**
 * routes/books.js — RESTful book management endpoints
 *
 * Implements the full CRUD lifecycle for the /books resource:
 *   GET    /books          — List all books (with optional filtering)
 *   GET    /books/:id      — Retrieve a single book by ID
 *   POST   /books          — Create a new book
 *   PUT    /books/:id      — Fully update an existing book
 *   DELETE /books/:id      — Remove a book by ID
 *
 * REST conventions followed:
 *   - Resource nouns in URLs (/books), not verbs.
 *   - HTTP methods convey the operation (GET=read, POST=create, PUT=update, DELETE=remove).
 *   - Status codes are semantically correct (200 OK, 201 Created, 404 Not Found, etc.).
 *   - IDs are path parameters (:id), not query strings.
 */

const express = require('express');
const router = express.Router();

// Re-export our custom error classes so routes can throw them cleanly.
const { NotFoundError, ValidationError } = require('../errors');

// Reference to the in-memory store (imported from app.js via module scope).
// In a larger app, this would be injected via dependency injection or a service layer.
let books;
let nextId;

/**
 * Bootstrap hook — called once when the route module is first required.
 * We attach the mutable state here so routes can read/write it without circular deps.
 */
function init(store) {
  books = store.books;
  nextId = store.nextId;
}

// ──────────────────────────────────────────────
// GET /books — List all books with optional filtering
// ──────────────────────────────────────────────
/**
 * Query parameters supported:
 *   - genre       : Filter by exact genre match (e.g., ?genre=Fiction)
 *   - minRating   : Minimum rating threshold (e.g., ?minRating=4.5)
 *   - publishedYearAfter : Only books published after this year (e.g., ?publishedYearAfter=2000)
 *
 * Why use query params for filtering instead of separate endpoints?
 *   REST encourages a single resource URI with parameters to refine the result set.
 *   This keeps the API surface small and composable — you can combine filters freely.
 */
router.get('/', (req, res) => {
  let result = [...books]; // Spread to avoid mutating the original array during filtering.

  // Filter by genre if provided — loose equality (==) handles string/number coercion.
  if (req.query.genre) {
    result = result.filter(book => book.genre == req.query.genre);
  }

  // Filter by minimum rating — parseFloat ensures we compare numbers, not strings.
  if (req.query.minRating) {
    const min = parseFloat(req.query.minRating);
    result = result.filter(book => book.rating >= min);
  }

  // Filter by publication year — only include books published AFTER the given year.
  if (req.query.publishedYearAfter) {
    const year = parseInt(req.query.publishedYearAfter, 10);
    result = result.filter(book => book.publishedYear > year);
  }

  /**
   * Why return 200 with an array instead of wrapping in { data: [...] }?
   * Both are valid REST styles. A bare array is simpler and matches the JSON:API
   * spec's top-level structure for collections. We add a `total` field for clarity.
   */
  res.json({
    total: result.length,
    data: result,
  });
});

// ──────────────────────────────────────────────
// GET /books/:id — Get a single book by ID
// ──────────────────────────────────────────────
/**
 * Why use findById instead of array index? Book IDs are business keys (semantic),
 * not database auto-increments. Using .find() makes the intent explicit and is
 * resilient to reordering or deletions in the array.
 */
router.get('/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  // isNaN check: req.params are always strings; parseInt converts them.
  if (isNaN(id)) {
    return next(new ValidationError('Invalid book ID format. Must be a number.'));
  }

  const book = books.find(b => b.id === id);

  if (!book) {
    // Throwing an error here transfers control to the global error handler.
    // This is cleaner than nested if/else response blocks in every route.
    return next(new NotFoundError(`Book with ID ${id} not found`));
  }

  res.json({ success: true, data: book });
});

// ──────────────────────────────────────────────
// POST /books — Create a new book
// ──────────────────────────────────────────────
/**
 * Validation rules enforced:
 *   - title, author, genre are required strings (non-empty after trim).
 *   - publishedYear must be a positive integer.
 *   - rating must be a number between 0 and 5 inclusive.
 *
 * Why validate on the server even if the client is trusted? Defense in depth —
 * malformed or malicious data can reach the API through direct HTTP calls,
 * third-party integrations, or compromised clients.
 */
router.post('/', (req, res, next) => {
  const { title, author, genre, publishedYear, rating } = req.body;

  // Collect validation errors to return all at once instead of failing on the first.
  const errors = [];

  if (!title || typeof title !== 'string' || title.trim() === '') {
    errors.push('title is required and must be a non-empty string');
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    errors.push('author is required and must be a non-empty string');
  }
  if (!genre || typeof genre !== 'string' || genre.trim() === '') {
    errors.push('genre is required and must be a non-empty string');
  }
  if (publishedYear === undefined || publishedYear === null) {
    errors.push('publishedYear is required');
  } else if (!Number.isInteger(publishedYear) || publishedYear < 0) {
    errors.push('publishedYear must be a positive integer');
  }
  if (rating === undefined || rating === null) {
    errors.push('rating is required');
  } else if (typeof rating !== 'number' || rating < 0 || rating > 5) {
    errors.push('rating must be a number between 0 and 5');
  }

  if (errors.length > 0) {
    // Returning 400 Bad Request with all validation messages at once.
    return next(new ValidationError(errors.join('; ')));
  }

  const newBook = {
    id: nextId++,
    title: title.trim(),
    author: author.trim(),
    genre: genre.trim(),
    publishedYear,
    rating,
  };

  books.push(newBook);

  /**
   * Why 201 Created instead of 200 OK? 201 semantically signals that a new
   * resource was successfully created. It also implies the response body may
   * contain the newly created resource (which we do).
   */
  res.status(201).json({ success: true, data: newBook });
});

// ──────────────────────────────────────────────
// PUT /books/:id — Fully update an existing book
// ──────────────────────────────────────────────
/**
 * Why PUT and not PATCH? PUT implies a full replacement of the resource.
 * All required fields must be present in the request body. For partial updates,
 * a separate PATCH endpoint would be appropriate (not implemented here for brevity).
 *
 * Idempotency: Sending the same PUT request multiple times produces the same result.
 * This is a key REST property — safe for retries and caching.
 */
router.put('/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    return next(new ValidationError('Invalid book ID format. Must be a number.'));
  }

  const index = books.findIndex(b => b.id === id);
  if (index === -1) {
    return next(new NotFoundError(`Book with ID ${id} not found`));
  }

  const { title, author, genre, publishedYear, rating } = req.body;

  // Reuse the same validation logic as POST for consistency.
  const errors = [];
  if (!title || typeof title !== 'string' || title.trim() === '') {
    errors.push('title is required and must be a non-empty string');
  }
  if (!author || typeof author !== 'string' || author.trim() === '') {
    errors.push('author is required and must be a non-empty string');
  }
  if (!genre || typeof genre !== 'string' || genre.trim() === '') {
    errors.push('genre is required and must be a non-empty string');
  }
  if (publishedYear === undefined || publishedYear === null) {
    errors.push('publishedYear is required');
  } else if (!Number.isInteger(publishedYear) || publishedYear < 0) {
    errors.push('publishedYear must be a positive integer');
  }
  if (rating === undefined || rating === null) {
    errors.push('rating is required');
  } else if (typeof rating !== 'number' || rating < 0 || rating > 5) {
    errors.push('rating must be a number between 0 and 5');
  }

  if (errors.length > 0) {
    return next(new ValidationError(errors.join('; ')));
  }

  // Replace the entire book object — this is PUT semantics.
  books[index] = {
    id,
    title: title.trim(),
    author: author.trim(),
    genre: genre.trim(),
    publishedYear,
    rating,
  };

  res.json({ success: true, data: books[index] });
});

// ──────────────────────────────────────────────
// DELETE /books/:id — Delete a book by ID
// ──────────────────────────────────────────────
/**
 * Why return 204 No Content instead of 200? A successful DELETE has no body to
 * return. 204 is the semantically correct status code per HTTP/1.1 spec (RFC 7231).
 * Some clients (like fetch) handle 204 better than 200 for delete operations.
 */
router.delete('/:id', (req, res, next) => {
  const id = parseInt(req.params.id, 10);
  if (isNaN(id)) {
    return next(new ValidationError('Invalid book ID format. Must be a number.'));
  }

  const index = books.findIndex(b => b.id === id);
  if (index === -1) {
    return next(new NotFoundError(`Book with ID ${id} not found`));
  }

  // Splice removes the element and shifts subsequent indices — O(n) but fine for small arrays.
  const [deleted] = books.splice(index, 1);

  /**
   * Returning 204 means "success, but no body". We call res.status(204).send()
   * with no arguments. This is the most REST-compliant response for deletions.
   */
  res.status(204).send();
});

// Export the router AND the init function so app.js can wire up state.
module.exports = router;
module.exports.init = init;
```

