## File 4: `routes/stats.js` — Statistics Endpoint

```javascript
/**
 * routes/stats.js — Aggregate statistics about the book collection
 *
 * GET /stats returns computed metrics that give a high-level overview of the data.
 * This demonstrates how to derive read-only analytics from your primary resource
 * without creating a separate "analytics" API surface.
 *
 * Why not put stats in books.js? Separation of concerns — stats are a distinct
 * resource with different semantics (read-only aggregation vs. CRUD). Keeping them
 * on /stats keeps the API intuitive and self-documenting.
 */

const express = require('express');
const router = express.Router();

let books;

function init(store) {
  books = store.books;
}

/**
 * GET /stats — Return aggregate statistics
 *
 * Metrics computed:
 *   - totalBooks       : Count of all books in the collection.
 *   - averageRating    : Mean rating across all books, rounded to 2 decimals.
 *   - genreDistribution: Object mapping each genre to its book count.
 *   - oldestPublication: Earliest publishedYear in the collection.
 *   - newestPublication: Latest publishedYear in the collection.
 *
 * Why compute on every request instead of caching? For an in-memory educational
 * API, the computation is trivial (O(n) over a small array). Caching adds
 * complexity (invalidation logic) that isn't justified at this scale. In production,
 * you'd cache stats and invalidate on mutations.
 */
router.get('/', (req, res) => {
  if (!books || books.length === 0) {
    return res.json({
      totalBooks: 0,
      averageRating: 0,
      genreDistribution: {},
      oldestPublication: null,
      newestPublication: null,
    });
  }

  // Reduce to compute sum of ratings — more efficient than a separate loop.
  const totalRating = books.reduce((sum, book) => sum + book.rating, 0);

  // Reduce to build genre counts in a single pass — O(n) instead of O(n²).
  const genreDistribution = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  // Math.min/max with spread operator — concise way to find extremes across an array.
  const years = books.map(b => b.publishedYear);

  res.json({
    totalBooks: books.length,
    averageRating: parseFloat((totalRating / books.length).toFixed(2)),
    genreDistribution,
    oldestPublication: Math.min(...years),
    newestPublication: Math.max(...years),
  });
});

module.exports = router;
module.exports.init = init;
```

