## File 5: `errors.js` — Custom Error Classes

```javascript
/**
 * errors.js — Custom error classes for the API
 *
 * Why custom error classes instead of plain Error objects?
 *   1. Type safety: We can check `err instanceof NotFoundError` to differentiate
 *      error types in middleware or logging systems.
 *   2. Extra metadata: Each class can carry domain-specific properties (e.g., statusCode).
 *   3. Self-documenting code: Throwing `new ValidationError(...)` is more expressive
 *      than throwing a generic Error with a message string.
 *
 * All classes extend the built-in Error so they work seamlessly with try/catch,
 * stack traces, and Node.js error handling.
 */

/**
 * Base error class — all API errors inherit from this.
 * Sets a default statusCode of 500 (Internal Server Error) as a safe fallback.
 */
class ApiError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    // Preserve the correct prototype chain for instanceof checks.
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

/**
 * 404 Not Found — Resource does not exist.
 * Used when a requested book ID is invalid or a route doesn't match.
 */
class NotFoundError extends ApiError {
  constructor(message) {
    super(message, 404);
  }
}

/**
 * 400 Bad Request — Client sent invalid data.
 * Used for validation failures (missing fields, wrong types, out-of-range values).
 */
class ValidationError extends ApiError {
  constructor(message) {
    super(message, 400);
  }
}

/**
 * 500 Internal Server Error — Unexpected server-side failure.
 * In a real app, you'd log the full error details server-side and return a
 * generic message to the client to avoid leaking sensitive information.
 */
class InternalServerError extends ApiError {
  constructor(message = 'An unexpected error occurred') {
    super(message, 500);
  }
}

module.exports = { ApiError, NotFoundError, ValidationError, InternalServerError };
```

