## Arquivo 5: `src/controllers/bookController.js`

```javascript
/**
 * @fileoverview Controlador responsável pela lógica de negócio dos livros.
 *
 * POR QUE UM CONTROLADOR SEPARADO?
 * ---------------------------------
 * Separar a lógica de negócio (controlador) da definição de rotas (routes)
 * segue o princípio de responsabilidade única:
 *   - Rotas definem QUÊ fazer (URL + método HTTP).
 *   - Controladores definem COMO fazer (lógica, validação, resposta).
 * Isso facilita testes unitários e reutilização de código.
 *
 * ESTRUTURA DE DADOS — POR QUE UM ARRAY?
 * ----------------------------------------
 * Usamos um array em memória (`books`) ao invés de um objeto/mapa porque:
 *   1. Simplicidade educacional: arrays são mais intuitivos para iniciantes.
 *   2. Ordenação natural pela ordem de inserção (útil para listagem).
 *   3. Para uma API demonstrativa, a performance não é crítica.
 *
 * EM PRODUÇÃO, usaríamos um banco de dados (MongoDB, PostgreSQL, etc.) com
 * índices adequados. Este array simula um "banco em memória" temporário.
 */

// ============================================================
// DADOS EM MEMÓRIA — Simula um banco de dados temporário.
// ============================================================

/**
 * Array que armazena todos os livros da API.
 * Cada livro é um objeto com as propriedades: id, title, author, year, genre.
 *
 * NOTA: Em uma aplicação real, este array seria substituído por chamadas
 * a um banco de dados (ex: mongoose.find(), pg.query()).
 */
let books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    year: 1954,
    genre: 'Fantasia',
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    year: 1949,
    genre: 'Distopia',
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    year: 1899,
    genre: 'Romance',
  },
];

/**
 * Contador para gerar IDs únicos automaticamente.
 * Usamos uma variável simples ao invés de UUIDs porque:
 *   - IDs numéricos sequenciais são mais legíveis em exemplos educacionais.
 *   - Evita colisões sem necessidade de bibliotecas externas.
 */
let nextId = 4; // Próximo ID a ser atribuído (começa após o último livro existente).

// ============================================================
// IMPORTAÇÕES
// ============================================================

/**
 * Importa a classe AppError para lançar erros personalizados com status HTTP.
 */
const AppError = require('../errors/AppError');

// ============================================================
// CONTROLE DE ACESSO — GET /books (Listar todos os livros)
// ============================================================

/**
 * Retorna a lista de todos os livros, com filtragem opcional por query params.
 *
 * ENDPOINT: GET /books
 *
 * QUERY PARAMS OPCIONAIS:
 *   - author  : Filtra por autor (busca parcial, case-insensitive).
 *   - genre   : Filtra por gênero (busca exata, case-insensitive).
 *   - year    : Filtra por ano de publicação (igualdade).
 *   - search  : Busca textual no título ou autor.
 *
 * EXEMPLOS DE USO:
 *   GET /books                          → Todos os livros
 *   GET /books?author=tolkien           → Livros de Tolkien
 *   GET /books?genre=fantasia           → Livros de fantasia
 *   GET /books?search=senhor            → Livros com "senhor" no título/autor
 *   GET /books?year=1949&genre=distopia → Combinação de filtros
 *
 * @function getAllBooks
 * @param {import('express').Request} req - Objeto de requisição (contém query params).
 * @param {import('express').Response} res - Objeto de resposta.
 */
const getAllBooks = (req, res) => {
  // Começamos com a lista completa de livros.
  let result = books;

  /**
   * Filtragem por autor: converte para minúsculas e faz busca parcial.
   * Ex: "tolkien" encontra "J.R.R. Tolkien".
   */
  if (req.query.author) {
    const authorFilter = req.query.author.toLowerCase();
    result = result.filter(
      (book) => book.author.toLowerCase().includes(authorFilter)
    );
  }

  /**
   * Filtragem por gênero: comparação exata (case-insensitive).
   * Ex: "fantasia" encontra "Fantasia".
   */
  if (req.query.genre) {
    const genreFilter = req.query.genre.toLowerCase();
    result = result.filter(
      (book) => book.genre.toLowerCase() === genreFilter
    );
  }

  /**
   * Filtragem por ano: conversão para número e igualdade exata.
   */
  if (req.query.year) {
    const yearFilter = parseInt(req.query.year, 10);
    result = result.filter((book) => book.year === yearFilter);
  }

  /**
   * Busca textual: procura o termo no título OU no autor.
   */
  if (req.query.search) {
    const searchFilter = req.query.search.toLowerCase();
    result = result.filter(
      (book) =>
        book.title.toLowerCase().includes(searchFilter) ||
        book.author.toLowerCase().includes(searchFilter)
    );
  }

  /**
   * Resposta padronizada com campo "success" e a lista de livros.
   * O status 200 (OK) indica sucesso na operação.
   */
  res.status(200).json({
    success: true,
    count: result.length, // Número de livros retornados (pode ser < total se houver filtros).
    data: result,
  });
};

// ============================================================
// CONTROLE DE ACESSO — GET /books/:id (Obter livro por ID)
// ============================================================

/**
 * Retorna um único livro pelo seu ID.
 *
 * ENDPOINT: GET /books/:id
 *
 * PARÂMETROS DE ROTA:
 *   - id : ID numérico do livro (ex: /books/1).
 *
 * EXEMPLOS DE USO:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → Retorna 404 se não existir.
 *
 * @function getBookById
 * @param {import('express').Request} req - Objeto de requisição (contém params.id).
 * @param {import('express').Response} res - Objeto de resposta.
 * @param {import('express').NextFunction} next - Função para encadear middlewares (erro).
 */
const getBookById = (req, res, next) => {
  // Converte o ID da URL para número (Express passa params como strings).
  const id = parseInt(req.params.id, 10);

  /**
   * Busca o livro no array usando Array.find().
   * find() retorna o primeiro elemento que satisfaz a condição, ou undefined.
   */
  const book = books.find((b) => b.id === id);

  /**
   * Se o livro não for encontrado, lançamos um AppError com status 404.
   * O middleware errorHandler intercepta e envia a resposta JSON apropriada.
   * Usamos next(err) em vez de res.status().json() para manter a consistência
   * do tratamento de erros em toda a API.
   */
  if (!book) {
    return next(new AppError(`Livro com ID ${id} não encontrado`, 404));
  }

  /**
   * Livro encontrado: respondemos com status 200 e os dados do livro.
   */
  res.status(200).json({
    success: true,
    data: book,
  });
};

// ============================================================
// CONTROLE DE ACESSO — POST /books (Criar novo livro)
// ============================================================

/**
 * Cria um novo livro no sistema.
 *
 * ENDPOINT: POST /books
 *
 * CORPO DA REQUISIÇÃO (JSON):
 *   {
 *     "title": "Nome do Livro",
 *     "author": "Nome do Autor",
 *     "year": 2024,
 *     "genre": "Gênero"
 *   }
 *
 * Todos os campos são obrigatórios. O ID é gerado automaticamente.
 *
 * EXEMPLOS DE USO:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","year":1932,"genre":"Distopia"}'
 *
 * @function createBook
 * @param {import('express').Request} req - Objeto de requisição (contém body).
 * @param {import('express').Response} res - Objeto de resposta.
 * @param {import('express').NextFunction} next - Função para encadear middlewares (erro).
 */
const createBook = (req, res, next) => {
  /**
   * Validação: todos os campos obrigatórios devem estar presentes no corpo.
   * Verificamos cada campo individualmente para dar mensagens de erro claras.
   */
  const { title, author, year, genre } = req.body;

  if (!title || !author || !year || !genre) {
    /**
     * Se algum campo estiver faltando, lançamos um AppError com status 400
     * (Bad Request), indicando quais campos são obrigatórios.
     */
    return next(
      new AppError('Todos os campos são obrigatórios: title, author, year, genre', 400)
    );
  }

  /**
   * Validação adicional: o ano deve ser um número válido e razoável.
   * Livros publicados após 2100 ou antes de 1400 (invenção da imprensa) são inválidos.
   */
  const yearNum = parseInt(year, 10);
  if (isNaN(yearNum) || yearNum < 1400 || yearNum > 2100) {
    return next(new AppError('O campo "year" deve ser um número entre 1400 e 2100', 400));
  }

  /**
   * Gera o próximo ID sequencial.
   * Em produção, usaríamos um gerador de UUID ou uma sequência do banco de dados.
   */
  const newBook = {
    id: nextId++, // Incrementa nextId após atribuir (pré-incremento garante IDs únicos).
    title,
    author,
    year: yearNum,
    genre,
  };

  /**
   * Adiciona o novo livro ao array em memória.
   * Em produção, esta operação seria uma inserção no banco de dados.
   */
  books.push(newBook);

  /**
   * Resposta 201 (Created) indica que um recurso foi criado com sucesso.
   * O corpo inclui o livro criado e seu ID gerado automaticamente.
   */
  res.status(201).json({
    success: true,
    message: 'Livro criado com sucesso',
    data: newBook,
  });
};

// ============================================================
// CONTROLE DE ACESSO — PUT /books/:id (Atualizar livro existente)
// ============================================================

/**
 * Atualiza completamente um livro existente pelo seu ID.
 *
 * ENDPOINT: PUT /books/:id
 *
 * CORPO DA REQUISIÇÃO (JSON):
 *   {
 *     "title": "Novo Título",
 *     "author": "Novo Autor",
 *     "year": 2024,
 *     "genre": "Novo Gênero"
 *   }
 *
 * NOTA: PUT implica atualização COMPLETA. Todos os campos devem ser enviados.
 * Para atualização parcial, usaríamos PATCH (não implementado neste exemplo).
 *
 * EXEMPLOS DE USO:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Senhor dos Anéis - Edição Ilustrada","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
 *
 * @function updateBook
 * @param {import('express').Request} req - Objeto de requisição (contém params.id e body).
 * @param {import('express').Response} res - Objeto de resposta.
 * @param {import('express').NextFunction} next - Função para encadear middlewares (erro).
 */
const updateBook = (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  /**
   * Busca o índice do livro no array (indexOf retorna -1 se não encontrado).
   * Usamos indexOf em vez de find porque precisamos do índice para substituir.
   */
  const bookIndex = books.findIndex((b) => b.id === id);

  if (bookIndex === -1) {
    return next(new AppError(`Livro com ID ${id} não encontrado`, 404));
  }

  /**
   * Validação dos campos obrigatórios no corpo da requisição.
   */
  const { title, author, year, genre } = req.body;

  if (!title || !author || !year || !genre) {
    return next(
      new AppError('Todos os campos são obrigatórios: title, author, year, genre', 400)
    );
  }

  const yearNum = parseInt(year, 10);
  if (isNaN(yearNum) || yearNum < 1400 || yearNum > 2100) {
    return next(new AppError('O campo "year" deve ser um número entre 1400 e 2100', 400));
  }

  /**
   * Cria o objeto atualizado, preservando o ID original (IDs não devem mudar).
   */
  const updatedBook = { id, title, author, year: yearNum, genre };

  /**
   * Substitui o livro no array pelo índice encontrado.
   * Em produção, esta seria uma operação de UPDATE no banco de dados.
   */
  books[bookIndex] = updatedBook;

  /**
   * Resposta 200 (OK) com os dados atualizados do livro.
   */
  res.status(200).json({
    success: true,
    message: 'Livro atualizado com sucesso',
    data: updatedBook,
  });
};

// ============================================================
// CONTROLE DE ACESSO — DELETE /books/:id (Excluir livro)
// ============================================================

/**
 * Exclui um livro do sistema pelo seu ID.
 *
 * ENDPOINT: DELETE /books/:id
 *
 * EXEMPLOS DE USO:
 *   curl -X DELETE http://localhost:3000/books/2
 *   curl -X DELETE http://localhost:3000/books/999  → Retorna 404.
 *
 * @function deleteBook
 * @param {import('express').Request} req - Objeto de requisição (contém params.id).
 * @param {import('express').Response} res - Objeto de resposta.
 * @param {import('express').NextFunction} next - Função para encadear middlewares (erro).
 */
const deleteBook = (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  /**
   * Busca o índice do livro a ser excluído.
   */
  const bookIndex = books.findIndex((b) => b.id === id);

  if (bookIndex === -1) {
    return next(new AppError(`Livro com ID ${id} não encontrado`, 404));
  }

  /**
   * Remove o livro do array usando splice (remove 1 elemento no índice encontrado).
   * Em produção, esta seria uma operação de DELETE no banco de dados.
   */
  books.splice(bookIndex, 1);

  /**
   * Resposta 200 (OK) confirmando a exclusão.
   * Alguns desenvolvedores preferem 204 (No Content) para DELETE — ambas são válidas.
   * Usamos 200 com mensagem para manter clareza educacional.
   */
  res.status(200).json({
    success: true,
    message: `Livro com ID ${id} foi excluído com sucesso`,
  });
};

// ============================================================
// CONTROLE DE ACESSO — GET /stats (Estatísticas dos livros)
// ============================================================

/**
 * Retorna estatísticas agregadas sobre o acervo de livros.
 *
 * ENDPOINT: GET /stats
 *
 * ESTATÍSTICAS RETORNADAS:
 *   - totalBooks      : Número total de livros cadastrados.
 *   - totalAuthors    : Número de autores únicos.
 *   - averageYear     : Ano médio de publicação (arredondado).
 *   - genres          : Objeto com contagem de livros por gênero.
 *   - oldestBook      : Livro mais antigo (menor ano).
 *   - newestBook      : Livro mais recente (maior ano).
 *
 * EXEMPLOS DE USO:
 *   curl http://localhost:3000/stats
 *
 * @function getStats
 * @param {import('express').Request} req - Objeto de requisição.
 * @param {import('express').Response} res - Objeto de resposta.
 */
const getStats = (req, res) => {
  /**
   * totalBooks: tamanho simples do array.
   */
  const totalBooks = books.length;

  /**
   * totalAuthors: usamos Set para contar autores únicos automaticamente.
   * Set é uma estrutura de dados que armazena apenas valores únicos.
   */
  const uniqueAuthors = new Set(books.map((book) => book.author));
  const totalAuthors = uniqueAuthors.size;

  /**
   * averageYear: soma de todos os anos dividida pelo total de livros.
   * toFixed(0) arredonda para inteiro; parseFloat converte de volta a número.
   */
  const averageYear =
    totalBooks > 0
      ? Math.round(books.reduce((sum, book) => sum + book.year, 0) / totalBooks)
      : 0;

  /**
   * genres: objeto que acumula contagem por gênero.
   * Reduzimos o array para construir um mapa de contagem.
   */
  const genres = books.reduce((acc, book) => {
    acc[book.genre] = (acc[book.genre] || 0) + 1;
    return acc;
  }, {});

  /**
   * oldestBook e newestBook: encontramos usando reduce para evitar múltiplas iterações.
   */
  const oldestBook =
    totalBooks > 0
      ? books.reduce((oldest, book) => (book.year < oldest.year ? book : oldest), books[0])
      : null;

  const newestBook =
    totalBooks > 0
      ? books.reduce((newest, book) => (book.year > newest.year ? book : newest), books[0])
      : null;

  /**
   * Resposta com todas as estatísticas calculadas.
   */
  res.status(200).json({
    success: true,
    data: {
      totalBooks,
      totalAuthors,
      averageYear,
      genres,
      oldestBook,
      newestBook,
    },
  });
};

// ============================================================
// EXPORTAÇÕES — Módulos que usam estes controladores.
// ============================================================

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

**Explicação:** O controlador contém toda a lógica de negócio. Cada função segue o padrão Express `(req, res, next)` e usa `AppError` para erros, mantendo a consistência do tratamento. A filtragem em `getAllBooks` suporta múltiplos parâmetros de query combináveis. As estatísticas em `getStats` usam métodos funcionais (`reduce`, `Set`) para eficiência e clareza.

