## Arquivo 2: `src/errors/AppError.js`

```javascript
/**
 * @fileoverview Classe base para erros personalizados da aplicação.
 *
 * POR QUE criar classes de erro personalizadas?
 *   - Permite distinguir entre tipos de erro no middleware de tratamento global.
 *     Sem isso, precisaríamos inspecionar strings de mensagem ou códigos HTTP
 *     soltos, o que é frágil e propenso a erros.
 *   - Facilita a resposta padronizada: cada erro carrega seu próprio status code
 *     e estrutura de resposta, eliminando lógica condicional espalhada pelo código.
 *   - Melhora a manutenibilidade: ao adicionar um novo tipo de erro, basta criar
 *     uma nova subclasse — não precisamos modificar o middleware existente.
 */

/**
 * Classe base para todos os erros da aplicação.
 *
 * Herda de Error nativo do JavaScript para manter compatibilidade com stack traces
 * e ferramentas de debugging. O campo `isOperational` marca erros que fazem parte
 * do fluxo normal da API (ex: recurso não encontrado) versus erros internos do sistema.
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro.
   * @param {number} statusCode - Código HTTP correspondente (padrão: 500).
   * @param {boolean} isOperational - Indica se o erro é esperado na operação da API.
   */
  constructor(message, statusCode = 500, isOperational = true) {
    super(message); // Chama construtor de Error nativo para capturar stack trace

    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';

    // Captura o nome da classe para identificação fácil no middleware
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro 400 — Requisição inválida.
 * Usado quando o cliente envia dados malformados ou parâmetros ausentes.
 */
class BadRequestError extends AppError {
  constructor(message = 'Requisição inválida') {
    super(message, 400);
  }
}

/**
 * Erro 404 — Recurso não encontrado.
 * Usado quando um ID informado não corresponde a nenhum livro no array.
 */
class NotFoundError extends AppError {
  constructor(resource = 'Recurso', id = null) {
    const message = id
      ? `${resource} com ID ${id} não encontrado`
      : `${resource} não encontrado`;
    super(message, 404);
  }
}

/**
 * Erro 409 — Conflito.
 * Usado quando uma operação viola uma restrição de negócio (ex: duplicidade).
 */
class ConflictError extends AppError {
  constructor(message = 'Conflito com recurso existente') {
    super(message, 409);
  }
}

/**
 * Erro 500 — Erro interno do servidor.
 * Usado para exceções não tratadas que indicam bug no código.
 */
class InternalError extends AppError {
  constructor(message = 'Erro interno do servidor') {
    super(message, 500, false); // false = erro operacional NÃO intencional
  }
}

module.exports = {
  AppError,
  BadRequestError,
  NotFoundError,
  ConflictError,
  InternalError,
};
```

