## Arquivo 3: `src/middleware/errorHandler.js`

```javascript
/**
 * @fileoverview Middleware global de tratamento de erros.
 *
 * POR QUE um middleware de erro dedicado?
 *   - O Express permite definir middlewares com 4 parâmetros (err, req, res, next).
 *     Quando qualquer rota ou middleware chama `next(err)`, o fluxo é desviado
 *     para este handler, centralizando a lógica de resposta de erro.
 *   - Sem esse middleware, cada rota precisaria de try/catch individual com
 *     respostas inconsistentes — violando o princípio DRY (Don't Repeat Yourself).
 *   - O campo `isOperational` permite esconder detalhes internos em produção,
 *     expondo apenas informações úteis ao cliente sem vazar stack traces.
 */

const { AppError } = require('../errors/AppError');

/**
 * Middleware de tratamento de erros para rotas assíncronas.
 *
 * Express não captura automaticamente rejeições de Promises em handlers async.
 * Este wrapper envolve cada handler, capturando erros e passando para o next().
 *
 * @param {Function} fn - Handler assíncrono da rota.
 * @returns {Function} Função express que chama fn e trata erros.
 */
const asyncHandler = (fn) => (req, res, next) => {
  fn(req, res, next).catch(next); // .catch(next) é o padrão moderno para async/await
};

/**
 * Middleware principal de tratamento de erros.
 *
 * Responde com JSON padronizado contendo status, mensagem e, em desenvolvimento,
 * stack trace. Em produção, oculta detalhes internos por segurança.
 *
 * @param {Error} err - Instância de AppError ou Error nativo.
 * @param {import('express').Request} req - Objeto request do Express.
 * @param {import('express').Response} res - Objeto response do Express.
 * @param {import('express').NextFunction} next - Função next do Express.
 */
const errorHandler = (err, req, res, next) => {
  // Se o erro não for uma instância de AppError, trata como erro interno genérico
  if (!(err instanceof AppError)) {
    console.error('Erro não tratado:', err); // Log para depuração em produção
    err = new AppError(err.message || 'Erro interno do servidor', 500, false);
  }

  const response = {
    status: err.status,
    statusCode: err.statusCode,
    message: err.message,
  };

  // Em desenvolvimento, inclui stack trace para facilitar debugging
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.stack = err.stack;
  }

  res.status(err.statusCode).json(response);
};

module.exports = { asyncHandler, errorHandler };
```

