## Arquivo 4: `src/middleware/validation.js`

```javascript
/**
 * @fileoverview Middleware de validação de entrada para criação e atualização de livros.
 *
 * POR QUE validar no middleware e não dentro do handler?
 *   - Separação de responsabilidades: o handler foca na lógica de negócio,
 *     enquanto o middleware garante que os dados estejam corretos antes disso.
 *   - Reusabilidade: a mesma validação pode ser aplicada em múltiplas rotas.
 *   - Feedback imediato ao cliente com mensagens claras sobre o que está errado.
 */

const { BadRequestError } = require('../errors/AppError');

/**
 * Valida os campos obrigatórios para criação de um livro.
 *
 * @param {import('express').Request} req - Objeto request do Express.
 * @param {import('express').Response} res - Objeto response do Express.
 * @param {Function} next - Função next do Express.
 */
const validateBookCreation = (req, res, next) => {
  const { title, author, isbn, year } = req.body;

  // Validação de campos obrigatórios
  if (!title || typeof title !== 'string' || title.trim().length === 0) {
    return next(new BadRequestError('O campo "title" é obrigatório e deve ser uma string não vazia'));
  }

  if (!author || typeof author !== 'string' || author.trim().length === 0) {
    return next(new BadRequestError('O campo "author" é obrigatório e deve ser uma string não vazia'));
  }

  // ISBN: formato opcional mas, se fornecido, deve ter 10 ou 13 dígitos
  if (isbn !== undefined && isbn !== null) {
    const isbnClean = String(isbn).replace(/[-\s]/g, '');
    if (!/^\d{10}(\d{3})?$/.test(isbnClean)) {
      return next(new BadRequestError('ISBN inválido. Deve conter 10 ou 13 dígitos numéricos'));
    }
  }

  // Ano: deve ser um número entre 1000 e o ano atual
  if (year !== undefined && year !== null) {
    const currentYear = new Date().getFullYear();
    if (!Number.isInteger(year) || year < 1000 || year > currentYear + 1) {
      return next(new BadRequestError(`O campo "year" deve ser um ano válido entre 1000 e ${currentYear + 1}`));
    }
  }

  next(); // Todos os validations passaram — prossegue para o handler
};

/**
 * Valida o ID da URL para rotas que exigem um parâmetro :id.
 *
 * @param {import('express').Request} req - Objeto request do Express.
 * @param {import('express').Response} res - Objeto response do Express.
 * @param {Function} next - Função next do Express.
 */
const validateIdParam = (req, res, next) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id < 1) {
    return next(new BadRequestError('O parâmetro "id" deve ser um número inteiro positivo'));
  }

  // Passa o ID como número para uso nos handlers
  req.validatedId = id;
  next();
};

module.exports = { validateBookCreation, validateIdParam };
```

