## Arquivo 5: `src/routes/books.js`

```javascript
/**
 * @fileoverview Rotas REST para gerenciamento de livros.
 *
 * ESTRUTURA DE DADOS — Por que usar um array em memória?
 *   Para este exemplo educacional, escolhemos um array simples porque:
 *     1. Elimina dependências externas (banco de dados), tornando o código autocontido.
 *     2. Permite focar nos conceitos de API: verbos HTTP, status codes, filtragem, etc.
 *     3. Facilita a compreensão do fluxo de dados sem abstração de ORM.
 *
 *   Em produção, substituiríamos por:
 *     - PostgreSQL + Prisma/Sequelize para relacionamentos e integridade referencial.
 *     - MongoDB + Mongoose para flexibilidade de schema e alta performance de leitura.
 *
 *   O array é enriquecido com um WeakMap (booksMap) para acesso O(1) por ID,
 *   simulando um índice de banco de dados e demonstrando boas práticas de performance.
 *
 * CONVENÇÕES REST adotadas:
 *   - GET    /books       → Listagem com filtragem via query params
 *   - GET    /books/:id   → Busca por ID
 *   - POST   /books       → Criação (body como JSON)
 *   - PUT    /books/:id   → Atualização total (substituição)
 *   - DELETE /books/:id   → Exclusão
 *   - Cada resposta segue o padrão { data, meta } para consistência.
 */

const express = require('express');
const { asyncHandler } = require('../middleware/errorHandler');
const { validateBookCreation, validateIdParam } = require('../middleware/validation');
const { NotFoundError, BadRequestError, ConflictError } = require('../errors/AppError');

const router = express.Router();

// ============================================================
// ARMAZENAMENTO EM MEMÓRIA
// ============================================================

/**
 * Array principal que armazena todos os livros.
 * Cada livro é um objeto com propriedades bem definidas.
 * Usamos let para permitir reatribuição em testes de integração.
 */
let books = [
  { id: 1, title: 'Dom Casmurro', author: 'Machado de Assis', isbn: '9788594524856', year: 1899 },
  { id: 2, title: 'O Cortiço', author: 'Aluísio Azevedo', isbn: '9788532508209', year: 1890 },
  { id: 3, title: 'Memórias Póstumas de Brás Cubas', author: 'Machado de Assis', isbn: '9788594524849', year: 1881 },
];

/**
 * Contador para geração automática de IDs.
 * Simula um autoincremento de banco de dados relacional.
 */
let nextId = 4;

/**
 * WeakMap para acesso rápido O(1) por ID.
 * Em produção, este seria o índice do banco de dados (primary key index).
 */
const booksMap = new Map();
books.forEach((book) => booksMap.set(book.id, book));

// ============================================================
// GET /books — Listar todos os livros com filtragem
// ============================================================

/**
 * @swagger
 * /books:
 *   get:
 *     summary: Lista todos os livros com filtragem opcional
 *     parameters:
 *       - in: query
 *         name: author
 *         schema:
 *           type: string
 *         description: Filtra por autor (case-insensitive, parcial)
 *       - in: query
 *         name: year
 *         schema:
 *           type: integer
 *         description: Filtra por ano de publicação exato
 *       - in: query
 *         name: search
 *         schema:
 *           type: string
 *         description: Busca por título (case-insensitive, parcial)
 *     responses:
 *       200:
 *         description: Lista de livros retornada com sucesso
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 data:
 *                   type: array
 *                   items:
 *                     $ref: '#/components/schemas/Book'
 *                 meta:
 *                   type: object
 *                   properties:
 *                     total:
 *                       type: integer
 *                     filtered:
 *                       type: integer
 *     examples:
 *       curl: |
 *         # Listar todos os livros
 *         curl http://localhost:3000/books
 *
 *         # Filtrar por autor
 *         curl "http://localhost:3000/books?author=machado"
 *
 *         # Buscar por título
 *         curl "http://localhost:3000/books?search=cortiço"
 *
 *         # Combinar filtros
 *         curl "http://localhost:3000/books?author=machado&year=1899"
 */
router.get(
  '/',
  asyncHandler(async (req, res) => {
    const { author, year, search } = req.query;

    // Começamos com uma cópia do array para não mutar o original durante filtragem
    let result = [...books];

    // Filtragem por autor: case-insensitive e parcial (includes)
    if (author) {
      const authorLower = author.toLowerCase();
      result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
    }

    // Filtragem por ano: comparação exata de número
    if (year) {
      const yearNum = parseInt(year, 10);
      if (isNaN(yearNum)) {
        throw new BadRequestError('O parâmetro "year" deve ser um número inteiro');
      }
      result = result.filter((book) => book.year === yearNum);
    }

    // Busca por título: case-insensitive e parcial
    if (search) {
      const searchLower = search.toLowerCase();
      result = result.filter((book) => book.title.toLowerCase().includes(searchLower));
    }

    // Resposta padronizada com metadados para o cliente saber quantos registros existem
    res.json({
      data: result,
      meta: {
        total: books.length,       // Total de livros no sistema (antes da filtragem)
        filtered: result.length,   // Total após aplicação dos filtros
      },
    });
  })
);

// ============================================================
// GET /books/:id — Obter único livro por ID
// ============================================================

/**
 * @swagger
 * /books/{id}:
 *   get:
 *     summary: Busca um livro específico pelo ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 *         description: ID numérico do livro
 *     responses:
 *       200:
 *         description: Livro encontrado
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 data:
 *                   $ref: '#/components/schemas/Book'
 *       404:
 *         description: Livro não encontrado
 *     examples:
 *       curl: |
 *         # Obter livro com ID 1
 *         curl http://localhost:3000/books/1
 *
 *         # Postman — GET http://localhost:3000/books/2
 */
router.get(
  '/:id',
  validateIdParam, // Middleware valida que :id é um número inteiro positivo
  asyncHandler(async (req, res) => {
    const id = req.validatedId;

    // Busca no Map para O(1) — em produção seria uma query SQL com WHERE id = ?
    const book = booksMap.get(id);

    if (!book) {
      throw new NotFoundError('Livro', id);
    }

    res.json({ data: book });
  })
);

// ============================================================
// POST /books — Criar novo livro
// ============================================================

/**
 * @swagger
 * /books:
 *   post:
 *     summary: Cria um novo livro
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author]
 *             properties:
 *               title:
 *                 type: string
 *                 example: "Grande Sertão: Veredas"
 *               author:
 *                 type: string
 *                 example: "João Guimarães Rosa"
 *               isbn:
 *                 type: string
 *                 example: "9788525415230"
 *               year:
 *                 type: integer
 *                 example: 1956
 *     responses:
 *       201:
 *         description: Livro criado com sucesso (status 201 = Created)
 *         headers:
 *           Location:
 *             description: URI do recurso criado
 *             schema:
 *               type: string
 *               example: "/books/4"
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 data:
 *                   $ref: '#/components/schemas/Book'
 *       400:
 *         description: Dados de entrada inválidos
 *     examples:
 *       curl: |
 *         curl -X POST http://localhost:3000/books \
 *           -H "Content-Type: application/json" \
 *           -d '{"title":"Grande Sertão: Veredas","author":"João Guimarães Rosa","isbn":"9788525415230","year":1956}'
 *
 *         # Postman — POST http://localhost:3000/books
 *         # Body (raw JSON): {"title":"Dom Quixote","author":"Miguel de Cervantes","year":1605}
 */
router.post(
  '/',
  validateBookCreation, // Middleware valida campos obrigatórios antes do handler
  asyncHandler(async (req, res) => {
    const { title, author, isbn, year } = req.body;

    // Gera ID automático sequencial — simula autoincrement de banco relacional
    const id = nextId++;

    const newBook = {
      id,
      title: title.trim(),
      author: author.trim(),
      isbn: isbn ? String(isbn).trim() : null,
      year: year || null,
    };

    // Insere no array e atualiza o Map simultaneamente
    books.push(newBook);
    booksMap.set(id, newBook);

    // 201 Created + header Location indica ao cliente onde encontrar o recurso
    res.status(201).header('Location', `/books/${id}`).json({ data: newBook });
  })
);

// ============================================================
// PUT /books/:id — Atualizar livro existente (atualização total)
// ============================================================

/**
 * @swagger
 * /books/{id}:
 *   put:
 *     summary: Atualiza completamente um livro existente
 *     description: |
 *       PUT é usado para SUBSTITUIÇÃO total. Todos os campos obrigatórios devem
 *       ser enviados. Para atualização parcial, use PATCH (não implementado aqui).
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required: [title, author]
 *             properties:
 *               title:
 *                 type: string
 *               author:
 *                 type: string
 *               isbn:
 *                 type: string
 *               year:
 *                 type: integer
 *     responses:
 *       200:
 *         description: Livro atualizado com sucesso
 *       404:
 *         description: Livro não encontrado
 *       409:
 *         description: Conflito (ISBN duplicado)
 *     examples:
 *       curl: |
 *         curl -X PUT http://localhost:3000/books/1 \
 *           -H "Content-Type: application/json" \
 *           -d '{"title":"Dom Casmurro (Ed. Crítica)","author":"Machado de Assis","isbn":"9788594524856","year":1899}'
 *
 *         # Postman — PUT http://localhost:3000/books/1
 */
router.put(
  '/:id',
  validateIdParam,
  validateBookCreation, // Reutiliza validação de criação (campos obrigatórios)
  asyncHandler(async (req, res) => {
    const id = req.validatedId;
    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError('Livro', id);
    }

    const { title, author, isbn, year } = req.body;

    // Verifica conflito de ISBN: se o novo ISBN for diferente do atual e já existir, rejeita
    if (isbn) {
      const existingBookWithIsbn = books.find(
        (b) => b.isbn === isbn && b.id !== id
      );
      if (existingBookWithIsbn) {
        throw new ConflictError(`Já existe um livro com ISBN ${isbn}`);
      }
    }

    // Atualização total: substitui todas as propriedades
    const updatedBook = {
      id,
      title: title.trim(),
      author: author.trim(),
      isbn: isbn ? String(isbn).trim() : null,
      year: year || null,
    };

    books[bookIndex] = updatedBook; // Atualiza no array
    booksMap.set(id, updatedBook);   // Atualiza no Map

    res.json({ data: updatedBook });
  })
);

// ============================================================
// DELETE /books/:id — Excluir livro
// ============================================================

/**
 * @swagger
 * /books/{id}:
 *   delete:
 *     summary: Exclui um livro pelo ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 *     responses:
 *       200:
 *         description: Livro excluído com sucesso (retorna o livro removido)
 *       404:
 *         description: Livro não encontrado
 *     examples:
 *       curl: |
 *         # Excluir livro com ID 3
 *         curl -X DELETE http://localhost:3000/books/3
 *
 *         # Postman — DELETE http://localhost:3000/books/2
 */
router.delete(
  '/:id',
  validateIdParam,
  asyncHandler(async (req, res) => {
    const id = req.validatedId;
    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError('Livro', id);
    }

    // Splice remove o elemento do array e retorna um array com 1 elemento
    const [removedBook] = books.splice(bookIndex, 1);

    // Remove também do Map para manter consistência
    booksMap.delete(id);

    // Retorna o livro excluído como confirmação — prática REST recomendada
    res.json({ data: removedBook });
  })
);

module.exports = router;
```

