## Arquivo 6: `src/routes/stats.js`

```javascript
/**
 * @fileoverview Rotas de estatísticas da API de livros.
 *
 * POR QUE separar rotas em arquivos diferentes?
 *   - Organização: mantém o arquivo principal (app.js) limpo e focado na configuração.
 *   - Escalabilidade: conforme a API cresce, cada domínio pode ter seu próprio módulo.
 *   - Testabilidade: rotas de estatísticas podem ser testadas isoladamente das rotas CRUD.
 *
 * Padrão asyncHandler é mantido mesmo para operações síncronas para consistência
 * e preparação para futuras consultas assíncronas a banco de dados.
 */

const express = require('express');
const { asyncHandler } = require('../middleware/errorHandler');

const router = express.Router();

// ============================================================
// GET /stats — Retornar estatísticas agregadas dos livros
// ============================================================

/**
 * @swagger
 * /stats:
 *   get:
 *     summary: Retorna estatísticas agregadas sobre o acervo de livros
 *     description: |
 *       Calcula métricas em tempo real a partir do array de livros:
 *         - total: quantidade absoluta de livros cadastrados.
 *         - porAutor: distribuição de livros por autor (ordenado alfabeticamente).
 *         - porDecada: distribuição por década de publicação.
 *         - mediaAno: ano médio de publicação (arredondado).
 *     responses:
 *       200:
 *         description: Estatísticas calculadas com sucesso
 *         content:
 *           application/json:
 *             schema:
 *               type: object
 *               properties:
 *                 data:
 *                   type: object
 *                   properties:
 *                     total: { type: integer }
 *                     porAutor: { type: array }
 *                     porDecada: { type: array }
 *                     mediaAno: { type: integer }
 *     examples:
 *       curl: |
 *         # Obter estatísticas
 *         curl http://localhost:3000/stats
 *
 *         # Postman — GET http://localhost:3000/stats
 */
router.get(
  '/',
  asyncHandler(async (_req, res) => {
    // Total de livros no acervo
    const total = books.length;

    // Agrupamento por autor usando reduce — padrão funcional para agregação
    // Em SQL equivalente seria: SELECT author, COUNT(*) as count GROUP BY author ORDER BY author
    const porAutor = Object.entries(
      books.reduce((acc, book) => {
        acc[book.author] = (acc[book.author] || 0) + 1;
        return acc;
      }, {})
    )
      .sort(([a], [b]) => a.localeCompare(b)) // Ordenação alfabética (localeCompare suporta acentos)
      .map(([author, count]) => ({ author, count }));

    // Agrupamento por década: ano → década (ex: 1899 → "1890s")
    const porDecada = Object.entries(
      books.reduce((acc, book) => {
        if (!book.year) return acc; // Ignora livros sem ano cadastrado
        const decade = Math.floor(book.year / 10) * 10;
        const decadeLabel = `${decade}s`;
        acc[decadeLabel] = (acc[decadeLabel] || 0) + 1;
        return acc;
      }, {})
    )
      .sort(([a], [b]) => a.localeCompare(b)) // Ordenação cronológica
      .map(([decada, count]) => ({ decada, count }));

    // Média de anos de publicação (ignorando livros sem ano)
    const booksWithYear = books.filter((b) => b.year);
    const mediaAno =
      booksWithYear.length > 0
        ? Math.round(booksWithYear.reduce((sum, b) => sum + b.year, 0) / booksWithYear.length)
        : null;

    res.json({
      data: {
        total,
        porAutor,
        porDecada,
        mediaAno,
      },
    });
  })
);

module.exports = router;
```

