## Arquivo 7: `src/app.js`

```javascript
/**
 * @fileoverview Configuração principal da aplicação Express.
 *
 * POR QUE esta estrutura?
 *   - app.js é o ponto de entrada que orquestra middleware, rotas e servidor.
 *   - Separar configuração do Express (app.js) das rotas (routes/) segue o princípio
 *     de responsabilidade única: cada módulo faz uma coisa bem definida.
 *   - O uso de express.json() é essencial para que req.body seja populado corretamente
 *     em requisições POST/PUT com payload JSON — sem isso, req.body seria undefined.
 *
 * ORDEM DOS MIDDLEWARES (importante!):
 *   1. Middleware de parsing (express.json) — processa o corpo da requisição.
 *   2. Rotas — manipulam a lógica de negócio.
 *   3. Middleware de erro (errorHandler) — SEMPRE por último, pois captura erros
 *      lançados pelos middlewares e rotas anteriores.
 */

const express = require('express');
const { errorHandler } = require('./middleware/errorHandler');
const booksRouter = require('./routes/books');
const statsRouter = require('./routes/stats');

const app = express();
const PORT = process.env.PORT || 3000;

// ============================================================
// MIDDLEWARE DE PARSING
// ============================================================

/**
 * express.json() — Parser nativo do Express para bodies JSON.
 *
 * Sem este middleware, requisições POST/PUT com Content-Type: application/json
 * teriam req.body === undefined, causando erros silenciosos ou falhas de validação.
 */
app.use(express.json());

// ============================================================
// MIDDLEWARE DE LOG (DESENVOLVIMENTO)
// ============================================================

/**
 * Logger simples que imprime método, URL e timestamp de cada requisição.
 * Útil para debugging e monitoramento básico em desenvolvimento.
 */
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.url}`);
  next(); // Sempre chama next() para não bloquear o fluxo
});

// ============================================================
// ROTAS DA API
// ============================================================

/**
 * Mount das rotas em seus respectivos paths.
 *
 * Por que usar express.Router()?
 *   - Permite agrupar rotas relacionadas com middleware específico (ex: validação).
 *   - Facilita testes unitários isolando grupos de rotas.
 *   - Mantém o app.js limpo e legível.
 */
app.use('/books', booksRouter); // Todas as rotas de livros ficam sob /books
app.use('/stats', statsRouter); // Rotas de estatísticas sob /stats

// ============================================================
// ROTA RAIZ — Documentação da API
// ============================================================

/**
 * @swagger
 * /:
 *   get:
 *     summary: Página inicial com documentação da API
 *     responses:
 *       200:
 *         description: Informações sobre a API e endpoints disponíveis
 */
app.get('/', (req, res) => {
  res.json({
    name: 'API de Livros',
    version: '1.0.0',
    description: 'API REST para gerenciamento de livros — exemplo educacional',
    endpoints: {
      books: {
        list: 'GET    /books',
        getById: 'GET    /books/:id',
        create: 'POST   /books',
        update: 'PUT    /books/:id',
        delete: 'DELETE /books/:id',
      },
      stats: {
        getStats: 'GET /stats',
      },
    },
  });
});

// ============================================================
// ROTA 404 — Tratamento de rotas inexistentes
// ============================================================

/**
 * Middleware que captura requisições para rotas não definidas.
 *
 * POR QUE tratar 404 separadamente do errorHandler?
 *   - Rotas inexistentes são um caso esperado (cliente erra a URL), não um erro interno.
 *   - Colocamos este middleware ANTES do errorHandler para que ele capture o erro
 *     antes que chegue ao handler genérico de erros.
 */
app.use((req, res, next) => {
  const { InternalError } = require('./errors/AppError');
  // Criamos um erro customizado para rotas não encontradas
  const error = new Error(`Rota ${req.method} ${req.originalUrl} não encontrada`);
  error.statusCode = 404;
  next(error); // Passa o erro para o middleware de tratamento
});

// ============================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS (SEMPRE POR ÚLTIMO)
// ============================================================

/**
 * errorHandler — Middleware global que captura todos os erros.
 *
 * IMPORTANTE: Deve ser o último app.use() registrado.
 * O Express identifica middlewares de erro pelo número de parâmetros (4).
 */
app.use(errorHandler);

// ============================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================

app.listen(PORT, () => {
  console.log(`\n✅ Servidor rodando em http://localhost:${PORT}`);
  console.log(`📚 API de Livros — exemplo educacional\n`);
});

module.exports = app;
```

