## File 4: `src/errors.js` — Custom Error Classes

```javascript
/**
 * src/errors.js — Custom error hierarchy for the API
 *
 * Why custom errors instead of plain Error objects?
 * 1. They carry structured metadata (statusCode, isOperational) that middleware
 *    can use to format consistent JSON responses.
 * 2. They make debugging easier: `err instanceof NotFoundError` is clearer than
 *    parsing error messages.
 * 3. They separate "expected" operational errors (bad input, resource not found)
 *    from unexpected system errors (database down, out of memory).
 *
 * The base AppError class includes:
 * - statusCode: HTTP status code for the response
 * - isOperational: true for business-logic errors, false for bugs
 * - message: human-readable description
 */

class AppError extends Error {
  /**
   * @param {string} message — Human-readable error description
   * @param {number} statusCode — HTTP status code (4xx client, 5xx server)
   */
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true; // Expected error, not a bug

    // Capture the stack trace for debugging.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * NotFoundError — Resource was not found (404)
 * Used when a requested book ID does not exist in the store.
 */
class NotFoundError extends AppError {
  constructor(resource = 'resource') {
    super(`${resource} not found`, 404);
  }
}

/**
 * ValidationError — Input validation failed (400)
 * Used when required fields are missing or values are invalid.
 */
class ValidationError extends AppError {
  /**
   * @param {string} message — General validation message
   * @param {Object} details — Field-specific error details (optional)
   */
  constructor(message, details = null) {
    super(message, 400);
    this.details = details; // e.g., { title: 'is required', author: 'must be string' }
  }
}

/**
 * InternalError — Unexpected server-side failure (500)
 * Used for bugs or infrastructure problems. We never expose raw error messages
 * to clients for security reasons.
 */
class InternalError extends AppError {
  constructor(message = 'Internal server error') {
    super(message, 500);
  }
}

module.exports = { AppError, NotFoundError, ValidationError, InternalError };
```

