## File 5: `src/middleware/errorHandler.js` — Global Error-Handling Middleware

```javascript
/**
 * src/middleware/errorHandler.js — Centralized error-handling middleware
 *
 * Express provides a special middleware signature (err, req, res, next) that
 * catches errors from any previous middleware or route handler. Placing this
 * as the LAST middleware ensures all errors are handled consistently.
 *
 * Why this pattern?
 * - Without it, unhandled errors crash the process or return generic HTML.
 * - It centralizes error formatting so every response follows the same JSON shape.
 * - We log unexpected errors (isOperational === false) for debugging but never
 *   expose internal details to clients.
 */

const { InternalError } = require('../errors');

/**
 * Global error-handling middleware.
 *
 * @param {Error} err — The error object (any type)
 * @param {import('express').Request} req — Express request object
 * @param {import('express').Response} res — Express response object
 * @param {import('express').NextFunction} next — Express next function
 */
const errorHandler = (err, req, res, next) => {
  // If the error doesn't have a statusCode, treat it as an internal server error.
  const statusCode = err.statusCode || 500;
  const isOperational = err.isOperational !== false; // Default true for custom errors

  // Log unexpected errors with full stack trace for debugging.
  if (!isOperational) {
    console.error('[UNHANDLED ERROR]', err);
  }

  // Build a consistent JSON error response.
  const response = {
    success: false,
    error: {
      type: err.constructor.name,
      message: err.message,
      ...(err.details && { details: err.details }), // Include field errors if present
    },
    timestamp: new Date().toISOString(),
  };

  // In production, never send the raw stack trace to clients.
  if (process.env.NODE_ENV === 'production' && !isOperational) {
    response.error.message = 'Something went wrong';
  }

  res.status(statusCode).json(response);
};

module.exports = errorHandler;
```

