## File 6: `src/middleware/validation.js` — Request Validation Middleware

```javascript
/**
 * src/middleware/validation.js — Input validation middleware
 *
 * Why validate at the middleware level?
 * - Keeps route handlers focused on business logic, not input checking.
 * - Reusable across multiple routes (e.g., POST and PUT both need body validation).
 * - Fails fast: invalid requests never reach the data layer.
 *
 * The validateBookBody function checks that required fields exist and have
 * correct types. We return a ValidationError with field-specific details so
 * clients know exactly what to fix.
 */

const { ValidationError } = require('../errors');

/**
 * Validates the request body for POST /books and PUT /books/:id.
 *
 * @param {import('express').Request} req — Express request object
 * @param {import('express').Response} res — Express response object
 * @param {import('express').NextFunction} next — Express next function
 *
 * Required fields: title (string), author (string)
 * Optional fields: genre (string), publishedYear (number), rating (number 0-5)
 */
const validateBookBody = (req, res, next) => {
  const { title, author, genre, publishedYear, rating } = req.body;

  // Collect validation errors in an object for field-level feedback.
  const details = {};

  if (!title || typeof title !== 'string' || title.trim() === '') {
    details.title = 'Title is required and must be a non-empty string';
  }

  if (!author || typeof author !== 'string' || author.trim() === '') {
    details.author = 'Author is required and must be a non-empty string';
  }

  if (genre !== undefined && typeof genre !== 'string') {
    details.genre = 'Genre must be a string';
  }

  if (publishedYear !== undefined && (!Number.isInteger(publishedYear) || publishedYear < 0)) {
    details.publishedYear = 'Published year must be a positive integer';
  }

  if (rating !== undefined && (typeof rating !== 'number' || rating < 0 || rating > 5)) {
    details.rating = 'Rating must be a number between 0 and 5';
  }

  // If any errors were collected, throw a ValidationError with details.
  const errorKeys = Object.keys(details);
  if (errorKeys.length > 0) {
    return next(new ValidationError('Invalid book data', details));
  }

  // Validation passed: proceed to the route handler.
  next();
};

/**
 * Validates query parameters for GET /books filtering.
 *
 * @param {import('express').Request} req — Express request object
 * @param {import('express').Response} res — Express response object
 * @param {import('express').NextFunction} next — Express next function
 */
const validateQueryParams = (req, res, next) => {
  const { page, limit, genre } = req.query;

  const details = {};

  if (page !== undefined) {
    const pageNum = parseInt(page, 10);
    if (!Number.isInteger(pageNum) || pageNum < 1) {
      details.page = 'Page must be a positive integer';
    }
  }

  if (limit !== undefined) {
    const limitNum = parseInt(limit, 10);
    if (!Number.isInteger(limitNum) || limitNum < 1 || limitNum > 100) {
      details.limit = 'Limit must be an integer between 1 and 100';
    }
  }

  if (genre !== undefined && typeof genre !== 'string') {
    details.genre = 'Genre must be a string';
  }

  const errorKeys = Object.keys(details);
  if (errorKeys.length > 0) {
    return next(new ValidationError('Invalid query parameters', details));
  }

  next();
};

module.exports = { validateBookBody, validateQueryParams };
```

