## File 7: `src/data/books.js` — In-Memory Data Store

```javascript
/**
 * src/data/books.js — In-memory data store for books
 *
 * Why use an in-memory array instead of a database?
 * 1. Educational clarity: no ORM, migrations, or connection pooling to explain.
 * 2. Instant startup: no external dependencies to install.
 * 3. Demonstrates CRUD operations on a simple data structure before adding DB complexity.
 *
 * Trade-offs (documented for learners):
 * - Data is lost when the server restarts (no persistence).
 * - Not suitable for production (no concurrency control, memory limits).
 * - No query indexing (linear search for filtering).
 *
 * In a real app, you would replace this module with a database adapter
 * (e.g., MongoDB, PostgreSQL) while keeping the same interface.
 */

const { v4: uuidv4 } = require('uuid'); // Generate unique IDs to prevent enumeration attacks

/**
 * The books array serves as our "database."
 * Each book is an object with:
 * - id: UUID string (immutable, unique)
 * - title: string
 * - author: string
 * - genre: string (optional)
 * - publishedYear: number (optional)
 * - rating: number 0-5 (optional)
 * - createdAt: ISO timestamp
 * - updatedAt: ISO timestamp
 */
const books = [];

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * @param {Object} filters — Query filter object from req.query
 * @param {string} [filters.title] — Substring match on title (case-insensitive)
 * @param {string} [filters.author] — Substring match on author (case-insensitive)
 * @param {string} [filters.genre] — Exact match on genre (case-insensitive)
 * @param {number} [filters.page] — Page number for pagination (1-indexed)
 * @param {number} [filters.limit] — Number of books per page
 * @returns {Object} Paginated result with books array and metadata
 */
const getAllBooks = (filters = {}) => {
  // Start with a copy of the full array to avoid mutating the original.
  let result = [...books];

  // Apply filters if provided. Using Array.filter for declarative filtering.
  if (filters.title) {
    const search = filters.title.toLowerCase();
    result = result.filter((book) => book.title.toLowerCase().includes(search));
  }

  if (filters.author) {
    const search = filters.author.toLowerCase();
    result = result.filter((book) => book.author.toLowerCase().includes(search));
  }

  if (filters.genre) {
    const genreLower = filters.genre.toLowerCase();
    result = result.filter((book) => book.genre?.toLowerCase() === genreLower);
  }

  // Pagination: calculate offset and slice the array.
  const page = parseInt(filters.page, 10) || 1;
  const limit = parseInt(filters.limit, 10) || books.length;
  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;

  const paginatedBooks = result.slice(startIndex, endIndex);

  return {
    data: paginatedBooks,
    metadata: {
      total: result.length,
      page,
      limit,
      totalPages: Math.ceil(result.length / limit),
    },
  };
};

/**
 * Finds a single book by its UUID.
 *
 * @param {string} id — Book UUID
 * @returns {Object|null} The book object or null if not found
 */
const getBookById = (id) => {
  return books.find((book) => book.id === id) || null;
};

/**
 * Creates a new book and adds it to the store.
 *
 * @param {Object} bookData — Book properties from request body
 * @returns {Object} The created book with generated id and timestamps
 */
const createBook = (bookData) => {
  const newBook = {
    id: uuidv4(), // Unique, non-sequential ID prevents ID enumeration attacks.
    title: bookData.title,
    author: bookData.author,
    genre: bookData.genre || null,
    publishedYear: bookData.publishedYear || null,
    rating: bookData.rating !== undefined ? bookData.rating : null,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  books.push(newBook); // O(1) append to array. In a DB, this would be an INSERT.
  return newBook;
};

/**
 * Updates an existing book by ID. Returns null if not found.
 *
 * @param {string} id — Book UUID
 * @param {Object} updates — Fields to update (partial update allowed)
 * @returns {Object|null} The updated book or null
 */
const updateBook = (id, updates) => {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Merge existing data with updates, preserving fields not in the request.
  books[index] = {
    ...books[index],
    ...updates,
    updatedAt: new Date().toISOString(), // Always update the timestamp.
  };

  return books[index];
};

/**
 * Deletes a book by ID. Returns true if deleted, false if not found.
 *
 * @param {string} id — Book UUID
 * @returns {boolean} True if the book was found and removed
 */
const deleteBook = (id) => {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // O(n) removal. In a DB, this would be a DELETE.
  return true;
};

/**
 * Computes aggregate statistics across all books.
 *
 * @returns {Object} Statistics object with counts and averages
 */
const getStats = () => {
  const totalBooks = books.length;

  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      averageRating: null,
      mostCommonGenre: null,
      booksByGenre: {},
    };
  }

  // Calculate average rating (excluding null ratings).
  const ratedBooks = books.filter((book) => book.rating !== null);
  const averageRating =
    ratedBooks.length > 0
      ? parseFloat(
          (ratedBooks.reduce((sum, b) => sum + b.rating, 0) / ratedBooks.length).toFixed(2)
        )
      : null;

  // Count books per genre to find the most common.
  const booksByGenre = {};
  books.forEach((book) => {
    if (book.genre) {
      booksByGenre[book.genre] = (booksByGenre[book.genre] || 0) + 1;
    }
  });

  // Find the genre with the highest count.
  let mostCommonGenre = null;
  let maxCount = 0;
  Object.entries(booksByGenre).forEach(([genre, count]) => {
    if (count > maxCount) {
      maxCount = count;
      mostCommonGenre = genre;
    }
  });

  return {
    totalBooks,
    averageRating,
    mostCommonGenre,
    booksByGenre,
  };
};

module.exports = { getAllBooks, getBookById, createBook, updateBook, deleteBook, getStats };
```

