## File 8: `src/routes/books.js` — Book Route Handlers

```javascript
/**
 * src/routes/books.js — RESTful route handlers for books
 *
 * Why separate routes into their own file?
 * - Keeps app.js clean and focused on middleware configuration.
 * - Makes it easy to add new resources (authors, reviews) as separate route files.
 * - Each route file can have its own validation and business logic.
 *
 * REST conventions followed:
 * - GET /books → list all (with optional filtering/pagination)
 * - GET /books/:id → get one by ID
 * - POST /books → create new
 * - PUT /books/:id → full update
 * - DELETE /books/:id → delete
 * - GET /stats → aggregate statistics (non-resource endpoint)
 *
 * Status codes used:
 * - 200 OK: successful GET/PUT
 * - 201 Created: successful POST
 * - 204 No Content: successful DELETE (no response body)
 * - 400 Bad Request: validation errors
 * - 404 Not Found: resource doesn't exist
 * - 500 Internal Server Error: unexpected failures
 */

const express = require('express');
const router = express.Router(); // Create a standalone router instance

const { NotFoundError, ValidationError } = require('../errors');
const { validateBookBody, validateQueryParams } = require('../middleware/validation');
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
} = require('../data/books');

// ============================================================================
// GET /stats — Return aggregate statistics
// No authentication or validation needed for this read-only endpoint.
// ============================================================================

/**
 * @swagger
 * /stats:
 *   get:
 *     summary: Get book collection statistics
 *     responses:
 *       200:
 *         description: Statistics object
 */
router.get('/stats', (req, res) => {
  const stats = getStats();
  res.json({ success: true, data: stats });
});

// ============================================================================
// GET /books — List all books with optional filtering and pagination
// ============================================================================

/**
 * @swagger
 * /books:
 *   get:
 *     summary: List all books with optional filters
 *     parameters:
 *       - in: query
 *         name: title
 *         schema:
 *           type: string
 *         description: Filter by title substring
 *       - in: query
 *         name: author
 *         schema:
 *           type: string
 *         description: Filter by author substring
 *       - in: query
 *         name: genre
 *         schema:
 *           type: string
 *         description: Filter by exact genre match
 *       - in: query
 *         name: page
 *         schema:
 *           type: integer
 *           default: 1
 *       - in: query
 *         name: limit
 *         schema:
 *           type: integer
 *           default: 20
 *     responses:
 *       200:
 *         description: Paginated list of books
 */
router.get('/books', validateQueryParams, (req, res) => {
  const filters = {
    title: req.query.title,
    author: req.query.author,
    genre: req.query.genre,
    page: req.query.page,
    limit: req.query.limit,
  };

  const result = getAllBooks(filters);
  res.json({ success: true, data: result.data, metadata: result.metadata });
});

// ============================================================================
// GET /books/:id — Get a single book by UUID
// ============================================================================

/**
 * @swagger
 * /books/{id}:
 *   get:
 *     summary: Get a book by ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *     responses:
 *       200:
 *         description: Book object
 *       404:
 *         description: Book not found
 */
router.get('/books/:id', (req, res, next) => {
  const book = getBookById(req.params.id);

  if (!book) {
    return next(new NotFoundError('Book'));
  }

  res.json({ success: true, data: book });
});

// ============================================================================
// POST /books — Create a new book
// ============================================================================

/**
 * @swagger
 * /books:
 *   post:
 *     summary: Create a new book
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             required:
 *               - title
 *               - author
 *             properties:
 *               title:
 *                 type: string
 *               author:
 *                 type: string
 *               genre:
 *                 type: string
 *               publishedYear:
 *                 type: integer
 *               rating:
 *                 type: number
 *                 minimum: 0
 *                 maximum: 5
 *     responses:
 *       201:
 *         description: Created book object
 *       400:
 *         description: Validation error
 */
router.post('/books', validateBookBody, (req, res) => {
  const newBook = createBook(req.body);
  // 201 Created is the standard status for resource creation.
  res.status(201).json({ success: true, data: newBook });
});

// ============================================================================
// PUT /books/:id — Full update of an existing book
// ============================================================================

/**
 * @swagger
 * /books/{id}:
 *   put:
 *     summary: Update a book by ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *     requestBody:
 *       required: true
 *       content:
 *         application/json:
 *           schema:
 *             type: object
 *             properties:
 *               title:
 *                 type: string
 *               author:
 *                 type: string
 *               genre:
 *                 type: string
 *               publishedYear:
 *                 type: integer
 *               rating:
 *                 type: number
 *     responses:
 *       200:
 *         description: Updated book object
 *       404:
 *         description: Book not found
 *       400:
 *         description: Validation error
 */
router.put('/books/:id', validateBookBody, (req, res, next) => {
  const updatedBook = updateBook(req.params.id, req.body);

  if (!updatedBook) {
    return next(new NotFoundError('Book'));
  }

  res.json({ success: true, data: updatedBook });
});

// ============================================================================
// DELETE /books/:id — Delete a book by ID
// ============================================================================

/**
 * @swagger
 * /books/{id}:
 *   delete:
 *     summary: Delete a book by ID
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 *     responses:
 *       204:
 *         description: Book deleted successfully
 *       404:
 *         description: Book not found
 */
router.delete('/books/:id', (req, res, next) => {
  const deleted = deleteBook(req.params.id);

  if (!deleted) {
    return next(new NotFoundError('Book'));
  }

  // 204 No Content is standard for successful DELETE (no body to return).
  res.status(204).send();
});

module.exports = router;
