## File 9: `src/app.js` — Express Application Configuration

```javascript
/**
 * src/app.js — Express application setup
 *
 * Why this structure?
 * - Middleware is configured in a logical order: parsing → routing → error handling.
 * - The router is mounted at /api/v1 to allow future versioning without breaking clients.
 * - JSON body parsing middleware (express.json()) is required before any route that
 *   reads req.body, otherwise body will be undefined.
 * - Error-handling middleware is registered LAST so it can catch errors from all routes.
 *
 * Request flow:
 * 1. Client sends HTTP request
 * 2. express.json() parses JSON body into req.body
 * 3. Route matching occurs (books router handles /api/v1/* paths)
 * 4. Validation middleware runs if attached to the route
 * 5. Route handler executes business logic
 * 6. Response is sent
 * 7. If any step throws, errorHandler catches it and formats the response
 */

const express = require('express');
const config = require('./config');
const errorHandler = require('./middleware/errorHandler');
const bookRoutes = require('./routes/books');

const app = express();

// ============================================================================
// Middleware Configuration
// ============================================================================

/**
 * Parse JSON request bodies.
 * Without this, req.body would be undefined for POST/PUT requests with JSON payloads.
 */
app.use(express.json());

/**
 * Log basic request information (useful for debugging in development).
 * In production, you might replace this with a proper logging library like Winston.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next();
});

// ============================================================================
// Route Registration
// ============================================================================

/**
 * Mount the books router at /api/v1.
 * All book endpoints are now accessible under this prefix:
 *   GET    /api/v1/books
 *   GET    /api/v1/books/:id
 *   POST   /api/v1/books
 *   PUT    /api/v1/books/:id
 *   DELETE /api/v1/books/:id
 *   GET    /api/v1/stats
 */
app.use(`/api/${config.apiVersion}`, bookRoutes);

// ============================================================================
// Root endpoint for health checks
// ============================================================================

/**
 * @swagger
 * /:
 *   get:
 *     summary: API health check
 *     responses:
 *       200:
 *         description: API is running
 */
app.get('/', (req, res) => {
  res.json({
    success: true,
    message: 'Book Management API is running',
    version: config.apiVersion,
    endpoints: {
      books: `/api/${config.apiVersion}/books`,
      stats: `/api/${config.apiVersion}/stats`,
    },
  });
});

// ============================================================================
// 404 Handler for undefined routes
// ============================================================================

/**
 * If no route matches, return a 404 with a helpful JSON message.
 * This must come AFTER all route registrations but BEFORE the error handler.
 */
app.use((req, res, next) => {
  const { NotFoundError } = require('./errors');
  next(new NotFoundError('Endpoint'));
});

// ============================================================================
// Global Error-Handling Middleware (MUST be last)
// ============================================================================

app.use(errorHandler);

module.exports = app;
```

