## Arquivo 4: `src/routes/books.js`

Este é o coração da API. Cada função de rota é documentada com JSDoc completo, incluindo exemplos de requisição e resposta. O armazenamento em memória usa um array simples porque:

1. **Educacional**: mantém o código focado nos conceitos de REST, não em banco de dados.
2. **Simplicidade**: arrays permitem filtragem, ordenação e manipulação com métodos nativos do JS (`filter`, `map`, `findIndex`).
3. **Imutabilidade relativa**: usamos `structuredClone()` para evitar mutações acidentais do estado global durante operações de leitura.

```javascript
/**
 * routes/books.js
 *
 * Rotas RESTful para o recurso "livros".
 *
 * POR QUE usar um array em memória?
 * - Para fins educacionais, elimina a complexidade de configurar um banco de dados
 * - Arrays são ideais para demonstrar operações CRUD completas
 * - Em produção, substituiríamos por um banco (MongoDB, PostgreSQL, etc.)
 *   mantendo a mesma interface de rotas — isso é o princípio da abstração
 *
 * POR QUE async/await em vez de callbacks ou .then()?
 * - Async/await torna o código linear e mais legível
 * - Erros podem ser capturados com try/catch, similar a linguagens como Java/C#
 * - Evita o "callback hell" que tornava o código assíncrono difícil de manter
 *
 * POR QUE usar UUIDs em vez de IDs numéricos?
 * - UUIDs são únicos globalmente, evitando colisões em sistemas distribuídos
 * - Não revelam o tamanho da coleção (segurança por obscuridade)
 * - Em produção com banco relacional, IDs autoincremento seriam mais comuns
 */

import { randomUUID } from 'node:crypto';
import {
  BadRequestError,
  NotFoundError,
  ConflictError,
} from '../errors/customErrors.js';

// ─────────────────────────────────────────────
// Armazenamento em memória
// ─────────────────────────────────────────────

/**
 * Array que armazena todos os livros.
 *
 * Estrutura de cada livro:
 * {
 *   id: string       — UUID v4 gerado automaticamente
 *   title: string    — Título do livro (obrigatório)
 *   author: string   — Autor (obrigatório)
 *   isbn: string     — ISBN único (obrigatório, deve ser único no sistema)
 *   year: number     — Ano de publicação (opcional, 1000-2100)
 *   genre: string    — Gênero literário (opcional)
 *   createdAt: string — Timestamp ISO da criação
 *   updatedAt: string — Timestamp ISO da última atualização
 * }
 *
 * Por que um array e não um Map?
 * - Arrays preservam ordem de inserção, útil para listagem
 * - Métodos como filter/map/findIndex são mais familiares
 * - Para escalabilidade real, um Map ou banco seria preferível
 */
const books = [
  {
    id: 'a1b2c3d4-e5f6-7890-abcd-ef1234567890',
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    isbn: '978-85-10-00001-1',
    year: 1899,
    genre: 'Romance',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
  {
    id: 'b2c3d4e5-f6a7-8901-bcde-f12345678901',
    title: '1984',
    author: 'George Orwell',
    isbn: '978-0-452-28423-4',
    year: 1949,
    genre: 'Distopia',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
  {
    id: 'c3d4e5f6-a7b8-9012-cdef-123456789012',
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    isbn: '978-0-618-12911-5',
    year: 1954,
    genre: 'Fantasia',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
  },
];

// ─────────────────────────────────────────────
// Funções auxiliares (private helpers)
// ─────────────────────────────────────────────

/**
 * Valida os campos obrigatórios de um livro.
 *
 * @param {object} data — Dados parciais ou completos do livro.
 * @returns {string[]} — Lista de erros de validação (vazia se válido).
 */
function validateBook(data) {
  const errors = [];

  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    errors.push('O campo "title" é obrigatório e deve ser uma string não vazia.');
  }

  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    errors.push('O campo "author" é obrigatório e deve ser uma string não vazia.');
  }

  if (!data.isbn || typeof data.isbn !== 'string' || data.isbn.trim() === '') {
    errors.push('O campo "isbn" é obrigatório e deve ser uma string não vazia.');
  }

  if (data.year !== undefined && (typeof data.year !== 'number' || data.year < 1000 || data.year > 2100)) {
    errors.push('O campo "year" deve ser um número entre 1000 e 2100.');
  }

  return errors;
}

/**
 * Busca um livro pelo ID. Lança NotFoundError se não encontrado.
 *
 * @param {string} id — UUID do livro.
 * @returns {object} — Cópia profunda do livro encontrado.
 */
function findBookById(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) {
    throw new NotFoundError(`Livro com ID "${id}" não encontrado.`);
  }
  // structuredClone garante que o cliente receba uma cópia,
  // impedindo mutações acidentais do estado interno.
  return structuredClone(books[index]);
}

// ─────────────────────────────────────────────
// GET /books — Listar todos os livros (com filtragem)
// ─────────────────────────────────────────────

/**
 * @route   GET /books
 * @desc    Lista todos os livros com suporte a filtragem e paginação
 * @access  Public
 *
 * Query parameters opcionais:
 *   - author   : filtra por autor (case-insensitive, parcial)
 *   - genre    : filtra por gênero (exato)
 *   - search   : busca por título ou autor (parcial, case-insensitive)
 *   - page     : número da página (padrão: 1)
 *   - limit    : itens por página (padrão: 10, máximo: 100)
 *
 * @example curl "http://localhost:3000/books"
 * @example curl "http://localhost:3000/books?author=tolkien&genre=fantasia&page=1&limit=5"
 *
 * Resposta de sucesso (200):
 * {
 *   "success": true,
 *   "data": [ ...livros... ],
 *   "pagination": { "page": 1, "limit": 10, "total": 3, "pages": 1 }
 * }
 */
export async function getAllBooks(req, res, next) {
  try {
    // Desestrutura os parâmetros de query com valores padrão.
    const { author, genre, search, page = '1', limit = '10' } = req.query;

    // Começamos com uma cópia profunda para não mutar o array original.
    let result = structuredClone(books);

    // Filtragem por autor (busca parcial e insensível a maiúsculas/minúsculas).
    if (author) {
      const authorLower = author.toLowerCase();
      result = result.filter((book) => book.author.toLowerCase().includes(authorLower));
    }

    // Filtragem exata por gênero.
    if (genre) {
      result = result.filter((book) => book.genre?.toLowerCase() === genre.toLowerCase());
    }

    // Busca textual por título ou autor.
    if (search) {
      const searchLower = search.toLowerCase();
      result = result.filter(
        (book) =>
          book.title.toLowerCase().includes(searchLower) ||
          book.author.toLowerCase().includes(searchLower),
      );
    }

    // Cálculo de paginação.
    const total = result.length;
    const pageNum = Math.max(1, parseInt(page, 10));
    const limitNum = Math.min(Math.max(1, parseInt(limit, 10)), 100);
    const totalPages = Math.ceil(total / limitNum);
    const startIndex = (pageNum - 1) * limitNum;
    const paginatedResult = result.slice(startIndex, startIndex + limitNum);

    res.status(200).json({
      success: true,
      data: paginatedResult,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total,
        pages: totalPages,
      },
    });
  } catch (error) {
    next(error);
  }
}

// ─────────────────────────────────────────────
// GET /books/stats — Estatísticas dos livros
// ─────────────────────────────────────────────

/**
 * @route   GET /books/stats
 * @desc    Retorna estatísticas agregadas sobre a coleção de livros
 * @access  Public
 *
 * @example curl "http://localhost:3000/books/stats"
 *
 * Resposta de sucesso (200):
 * {
 *   "success": true,
 *   "data": {
 *     "totalBooks": 3,
 *     "totalAuthors": 3,
 *     "averageYear": 1967.33,
 *     "booksByGenre": { "Romance": 1, "Distopia": 1, "Fantasia": 1 },
 *     "oldestBook": { "title": "...", "year": 1899 },
 *     "newestBook": { "title": "...", "year": 1954 }
 *   }
 * }
 */
export async function getBookStats(req, res, next) {
  try {
    const totalBooks = books.length;

    // Set garante autores únicos.
    const uniqueAuthors = new Set(books.map((b) => b.author)).size;

    // Cálculo da média dos anos de publicação.
    const averageYear =
      totalBooks > 0
        ? parseFloat((books.reduce((sum, b) => sum + (b.year || 0), 0) / totalBooks).toFixed(2))
        : 0;

    // Agrupamento por gênero usando reduce.
    const booksByGenre = books.reduce((acc, book) => {
      const genre = book.genre || 'Sem gênero';
      acc[genre] = (acc[genre] || 0) + 1;
      return acc;
    }, {});

    // Livros mais antigo e mais recente.
    let oldestBook = null;
    let newestBook = null;
    if (totalBooks > 0) {
      oldestBook = books.reduce(
        (min, b) => (b.year < (min?.year ?? Infinity) ? b : min),
        null,
      );
      newestBook = books.reduce(
        (max, b) => (b.year > (max?.year ?? -Infinity) ? b : max),
        null,
      );
    }

    res.status(200).json({
      success: true,
      data: {
        totalBooks,
        totalAuthors: uniqueAuthors,
        averageYear,
        booksByGenre,
        oldestBook: oldestBook ? { title: oldestBook.title, author: oldestBook.author, year: oldestBook.year } : null,
        newestBook: newestBook ? { title: newestBook.title, author: newestBook.author, year: newestBook.year } : null,
      },
    });
  } catch (error) {
    next(error);
  }
}

// ─────────────────────────────────────────────
// GET /books/:id — Obter livro por ID
// ─────────────────────────────────────────────

/**
 * @route   GET /books/:id
 * @desc    Retorna um único livro pelo seu UUID
 * @access  Public
 *
 * @param {string} params.id — UUID do livro.
 *
 * @example curl "http://localhost:3000/books/a1b2c3d4-e5f6-7890-abcd-ef1234567890"
 *
 * Resposta de sucesso (200):
 * {
 *   "success": true,
 *   "data": {
 *     "id": "...",
 *     "title": "Dom Casmurro",
 *     "author": "Machado de Assis",
 *     ...
 *   }
 * }
 */
export async function getBookById(req, res, next) {
  try {
    const book = findBookById(req.params.id);

    res.status(200).json({
      success: true,
      data: book,
    });
  } catch (error) {
    next(error);
  }
}

// ─────────────────────────────────────────────
// POST /books — Criar novo livro
// ─────────────────────────────────────────────

/**
 * @route   POST /books
 * @desc    Cria um novo livro na coleção
 * @access  Public
 *
 * Body (JSON):
 * {
 *   "title": "O Apanhador no Campo",
 *   "author": "J.D. Salinger",
 *   "isbn": "978-0-316-76948-0",
 *   "year": 1951,
 *   "genre": "Romance"
 * }
 *
 * @example curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Apanhador no Campo","author":"J.D. Salinger","isbn":"978-0-316-76948-0","year":1951,"genre":"Romance"}'
 *
 * Resposta de sucesso (201):
 * {
 *   "success": true,
 *   "data": { ...livro criado... },
 *   "message": "Livro criado com sucesso"
 * }
 */
export async function createBook(req, res, next) {
  try {
    const { title, author, isbn, year, genre } = req.body;

    // Validação dos campos obrigatórios.
    const validationErrors = validateBook(req.body);
    if (validationErrors.length > 0) {
      throw new BadRequestError(validationErrors.join(' '));
    }

    // Verifica se o ISBN já existe (unicidade).
    const isbnExists = books.some((book) => book.isbn === isbn.trim());
    if (isbnExists) {
      throw new ConflictError(`Já existe um livro com o ISBN "${isbn}".`);
    }

    const now = new Date().toISOString();

    const newBook = {
      id: randomUUID(), // UUID v4 garante unicidade global sem depender do banco.
      title: title.trim(),
      author: author.trim(),
      isbn: isbn.trim(),
      year: year ? parseInt(year, 10) : undefined,
      genre: genre || undefined,
      createdAt: now,
      updatedAt: now,
    };

    books.push(newBook);

    // 201 Created é o status HTTP semântico para recursos criados.
    res.status(201).json({
      success: true,
      data: structuredClone(newBook),
      message: 'Livro criado com sucesso',
    });
  } catch (error) {
    next(error);
  }
}

// ─────────────────────────────────────────────
// PUT /books/:id — Atualizar livro existente
// ─────────────────────────────────────────────

/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente (substituição total)
 * @access  Public
 *
 * Body (JSON):
 * {
 *   "title": "Dom Casmurro (Ed. Definitiva)",
 *   "author": "Machado de Assis",
 *   "isbn": "978-85-10-00001-1",
 *   "year": 1899,
 *   "genre": "Romance Psicológico"
 * }
 *
 * @example curl -X PUT http://localhost:3000/books/a1b2c3d4-e5f6-7890-abcd-ef1234567890 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Dom Casmurro","author":"Machado de Assis","isbn":"978-85-10-00001-1","year":1899,"genre":"Romance"}'
 *
 * Resposta de sucesso (200):
 * { "success": true, "data": { ...livro atualizado... } }
 */
export async function updateBook(req, res, next) {
  try {
    const book = findBookById(req.params.id); // Lança 404 se não existir

    const { title, author, isbn, year, genre } = req.body;

    // Validação dos campos fornecidos.
    const validationErrors = validateBook(req.body);
    if (validationErrors.length > 0) {
      throw new BadRequestError(validationErrors.join(' '));
    }

    // Verifica unicidade do ISBN (ignorando o próprio livro).
    const isbnExists = books.some(
      (b) => b.isbn === isbn.trim() && b.id !== book.id,
    );
    if (isbnExists) {
      throw new ConflictError(`Já existe outro livro com o ISBN "${isbn}".`);
    }

    // Cria o objeto atualizado.
    const updatedBook = {
      ...book, // Preserva campos não fornecidos (comportamento de substituição total)
      title: title.trim(),
      author: author.trim(),
      isbn: isbn.trim(),
      year: year !== undefined ? parseInt(year, 10) : book.year,
      genre: genre !== undefined ? genre : book.genre,
      updatedAt: new Date().toISOString(),
    };

    // Atualiza no array pelo índice.
    const index = books.findIndex((b) => b.id === book.id);
    books[index] = updatedBook;

    res.status(200).json({
      success: true,
      data: structuredClone(updatedBook),
      message: 'Livro atualizado com sucesso',
    });
  } catch (error) {
    next(error);
  }
}

// ─────────────────────────────────────────────
// DELETE /books/:id — Excluir livro
// ─────────────────────────────────────────────

/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro da coleção permanentemente
 * @access  Public
 *
 * @param {string} params.id — UUID do livro a ser removido.
 *
 * @example curl -X DELETE http://localhost:3000/books/a1b2c3d4-e5f6-7890-abcd-ef1234567890
 *
 * Resposta de sucesso (200):
 * { "success": true, "data": { ...livro removido... }, "message": "Livro excluído" }
 */
export async function deleteBook(req, res, next) {
  try {
    const book = findBookById(req.params.id); // Lança 404 se não existir

    // Remove do array pelo índice.
    const index = books.findIndex((b) => b.id === book.id);
    books.splice(index, 1);

    res.status(200).json({
      success: true,
      data: structuredClone(book),
      message: 'Livro excluído com sucesso',
    });
  } catch (error) {
    next(error);
  }
}
```

