## Arquivo 5: `src/app.js`

O arquivo principal que configura o servidor Express, registra middlewares e rotas. A ordem de registro dos middlewares é intencional: CORS → JSON parsing → Rotas → ErrorHandler. O Express executa middlewares na ordem em que são registrados, por isso o handler de erro deve ser o **último**.

```javascript
/**
 * app.js
 *
 * Ponto de entrada da aplicação. Configura o servidor Express com:
 *   - Middleware CORS (permite requisições de qualquer origem)
 *   - Parser de JSON (req.body automaticamente disponível)
 *   - Rotas do recurso livros
 *   - Middleware central de tratamento de erros
 *
 * POR QUE usar app.use() em vez de app.get()/app.post()?
 * - app.use() registra middlewares que executam para TODAS as rotas
 * - app.get/post() registram handlers específicos para um método+path
 *
 * POR QUE o handler de erro deve ser o último middleware?
 * - O Express encadeia middlewares sequencialmente
 * - Se o errorHandler viesse antes das rotas, ele capturaria erros
 *   de parsing JSON antes que as rotas tivessem chance de tratá-los
 */

import express from 'express';
import {
  getAllBooks,
  getBookStats,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
} from './routes/books.js';
import errorHandler from './middleware/errorHandler.js';

const app = express();
const PORT = process.env.PORT || 3000;

// ─────────────────────────────────────────────
// Middlewares globais
// ─────────────────────────────────────────────

/**
 * CORS — Cross-Origin Resource Sharing.
 * Permite que front-ends de diferentes origens acessem esta API.
 * Em produção, substitua '*' por domínios específicos para segurança.
 */
app.use((req, res, next) => {
  res.header('Access-Control-Allow-Origin', '*');
  res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept, Authorization');
  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');

  // Responde imediatamente a requisições OPTIONS (preflight do CORS).
  if (req.method === 'OPTIONS') {
    return res.sendStatus(200);
  }
  next();
});

/**
 * Parser de JSON.
 * Transforma o body da requisição (string JSON) em objeto JavaScript.
 * Sem este middleware, req.body seria undefined.
 */
app.use(express.json());

// ─────────────────────────────────────────────
// Rotas do recurso /books
// ─────────────────────────────────────────────

/**
 * GET /books — Lista todos os livros (com filtragem e paginação)
 *
 * curl "http://localhost:3000/books"
 * curl "http://localhost:3000/books?author=orwell&search=1984&page=1&limit=5"
 */
app.get('/books', getAllBooks);

/**
 * GET /books/stats — Estatísticas da coleção
 *
 * curl "http://localhost:3000/books/stats"
 */
app.get('/books/stats', getBookStats);

/**
 * GET /books/:id — Busca livro por UUID
 *
 * curl "http://localhost:3000/books/a1b2c3d4-e5f6-7890-abcd-ef1234567890"
 */
app.get('/books/:id', getBookById);

/**
 * POST /books — Cria novo livro
 *
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Admirável Mundo Novo","author":"Aldous Huxley","isbn":"978-0-06-085052-4","year":1932,"genre":"Distopia"}'
 */
app.post('/books', createBook);

/**
 * PUT /books/:id — Atualiza livro existente (substituição total)
 *
 * curl -X PUT http://localhost:3000/books/a1b2c3d4-e5f6-7890-abcd-ef1234567890 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Dom Casmurro","author":"Machado de Assis","isbn":"978-85-10-00001-1","year":1899,"genre":"Romance"}'
 */
app.put('/books/:id', updateBook);

/**
 * DELETE /books/:id — Exclui livro
 *
 * curl -X DELETE http://localhost:3000/books/a1b2c3d4-e5f6-7890-abcd-ef1234567890
 */
app.delete('/books/:id', deleteBook);

// ─────────────────────────────────────────────
// Rota 404 para caminhos inexistentes
// ─────────────────────────────────────────────

/**
 * Middleware que captura requisições para rotas não definidas.
 * Lança um erro via next() para que o errorHandler central o processe.
 */
app.use((req, res, next) => {
  const error = new Error(`Rota ${req.method} ${req.path} não encontrada`);
  error.statusCode = 404;
  error.isOperational = true;
  next(error);
});

// ─────────────────────────────────────────────
// Middleware de tratamento de erros (SEMPRE por último)
// ─────────────────────────────────────────────
app.use(errorHandler);

// ─────────────────────────────────────────────
// Inicialização do servidor
// ─────────────────────────────────────────────

app.listen(PORT, () => {
  console.log(`📚 API de Livros rodando em http://localhost:${PORT}`);
  console.log(`   Endpoints disponíveis:`);
  console.log(`   GET    /books          — Listar livros (com filtragem)`);
  console.log(`   GET    /books/stats    — Estatísticas`);
  console.log(`   GET    /books/:id      — Buscar por ID`);
  console.log(`   POST   /books          — Criar livro`);
  console.log(`   PUT    /books/:id      — Atualizar livro`);
  console.log(`   DELETE /books/:id      — Excluir livro`);
});

export default app;
```

