## File 2: `server.js` — Application Entry Point

```javascript
/**
 * ============================================================================
 * FILE: server.js
 * PURPOSE: Application entry point — bootstraps Express, registers middleware,
 *          mounts route handlers, and starts the HTTP server on port 3000.
 *
 * DESIGN RATIONALE:
 *   - We separate concerns by keeping route definitions in ./routes/ so that
 *     this file stays focused on wiring (middleware + routing) rather than logic.
 *   - express.json() is registered BEFORE routes so every incoming request body
 *     is parsed into req.body as a JavaScript object. Without it, POST/PUT bodies
 *     would arrive as raw strings and we could not validate them.
 *   - The custom error-handling middleware is registered LAST (after all routes)
 *     because Express executes middleware in registration order; placing it last
 *     ensures it catches errors thrown by any route or preceding middleware.
 * ============================================================================
 */

const express = require('express');          // Core web framework
const bookRoutes = require('./routes/books');  // CRUD routes for /books
const statsRoutes = require('./routes/stats'); // Statistics route for /stats
const { errorHandler } = require('./middleware/errorHandler'); // Global error catcher

// --------------------------------------------------------------------------
// Create the Express application instance.
// This is a singleton that holds all middleware and route registrations.
// --------------------------------------------------------------------------
const app = express();

// ============================================================================
// MIDDLEWARE — executed for EVERY request, in registration order:
//   1. express.json()      → parses JSON request bodies (POST/PUT)
//   2. bookRoutes          → handles all /books/* requests
//   3. statsRoutes         → handles /stats requests
//   4. errorHandler        → catches unhandled errors and formats responses
// ============================================================================

/**
 * Parses incoming JSON payloads into req.body.
 * Required so that POST/PUT handlers can read { title, author, ... }.
 */
app.use(express.json());

/**
 * Mounts the books router at the /books path prefix.
 * All routes defined in ./routes/books.js will be accessible under /books/.
 */
app.use('/books', bookRoutes);

/**
 * Mounts the stats router at the /stats path prefix.
 */
app.use('/stats', statsRoutes);

// ============================================================================
// GLOBAL ERROR HANDLING MIDDLEWARE
//
// Express error-handling middleware has FOUR parameters (err, req, res, next).
// Express automatically routes any thrown/error-passed exception here.
// We return a consistent JSON shape so clients can parse errors uniformly.
// ============================================================================
app.use(errorHandler);

// ============================================================================
// START THE HTTP SERVER
// ============================================================================
const PORT = process.env.PORT || 3000; // Allow port override via environment variable

/**
 * Starts the server and logs a confirmation message.
 * The callback receives the Express app instance (standard Node.js pattern).
 */
app.listen(PORT, () => {
  console.log(`📚 Book REST API is running on http://localhost:${PORT}`);
  console.log(`   Try: GET  http://localhost:${PORT}/books`);
  console.log(`        POST http://localhost:${PORT}/books`);
  console.log(`        GET  http://localhost:${PORT}/stats`);
});
```

