## File 3: `data/books.js` — In-Memory Data Store

```javascript
/**
 * ============================================================================
 * FILE: data/books.js
 * PURPOSE: Provides an in-memory array to persist book records during the
 *          lifetime of the Node.js process. Also exports helper functions for
 *          CRUD operations so route handlers stay thin and focused.
 *
 * WHY AN ARRAY (not an object/map)?
 *   - Arrays preserve insertion order, which is intuitive for a "list" resource.
 *   - Numeric IDs map naturally to array indices; we use splice() for O(n) but
 *     simple deletion. For production with thousands of records, a Map or DB
 *     would be preferred — see the migration note below.
 *
 * MIGRATION NOTE:
 *   To switch to a database (e.g., MongoDB), replace this module with a model
 *   that queries the DB instead of mutating an array. The route handlers in
 *   ./routes/books.js will NOT need changes because they call these helpers.
 * ============================================================================
 */

// --------------------------------------------------------------------------
// In-memory storage: each book is a plain JavaScript object.
// We seed it with three sample records so the API is not empty on startup.
// --------------------------------------------------------------------------
const books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.5,
  },
  {
    id: 2,
    title: 'Clean Code',
    author: 'Robert C. Martin',
    genre: 'Technology',
    publishedYear: 2008,
    rating: 4.7,
  },
  {
    id: 3,
    title: 'Dune',
    author: 'Frank Herbert',
    genre: 'Science Fiction',
    publishedYear: 1965,
    rating: 4.8,
  },
];

// --------------------------------------------------------------------------
// Helper: generate the next sequential ID.
// In a real app, use an auto-incrementing column or UUID from the database.
// --------------------------------------------------------------------------

/**
 * Returns the next available integer ID based on existing books.
 * Uses Math.max over current IDs; if the array is empty, returns 1.
 * @returns {number} The next ID to assign.
 */
function getNextId() {
  if (books.length === 0) return 1;
  const maxId = Math.max(...books.map((book) => book.id));
  return maxId + 1;
}

// --------------------------------------------------------------------------
// CRUD helper functions — each one mutates the `books` array directly.
// Route handlers call these instead of touching the array themselves,
// keeping routes focused on HTTP concerns (validation, status codes).
// --------------------------------------------------------------------------

/**
 * Retrieves every book in the store.
 * @returns {Array<Object>} A shallow copy of the books array.
 */
function getAllBooks() {
  return [...books]; // Return a copy to prevent external mutation
}

/**
 * Finds a single book by its numeric ID.
 * @param {number} id - The unique identifier of the book.
 * @returns {Object|undefined} The book object, or undefined if not found.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Inserts a new book into the store and assigns it the next ID.
 * @param {Object} bookData - The book properties to insert.
 * @returns {Object} The newly created book (with assigned ID).
 */
function createBook(bookData) {
  const newBook = { id: getNextId(), ...bookData };
  books.push(newBook);
  return newBook;
}

/**
 * Replaces an existing book with updated data.
 * @param {number} id - The ID of the book to update.
 * @param {Object} updates - Fields to overwrite (full replacement, not patch).
 * @returns {Object|undefined} The updated book, or undefined if not found.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return undefined;
  // Replace the entire object so partial/missing fields are cleared intentionally.
  // For a PATCH endpoint we would merge instead of replace.
  books[index] = { ...books[index], ...updates };
  return books[index];
}

/**
 * Removes a book from the store by ID.
 * @param {number} id - The ID of the book to delete.
 * @returns {boolean} True if a book was removed, false if not found.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;
  books.splice(index, 1); // O(n) removal — acceptable for small in-memory stores
  return true;
}

// Export all helpers so route files can require this module.
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
};
```

