## File 4: `middleware/errorHandler.js` — Centralized Error Handling

```javascript
/**
 * ============================================================================
 * FILE: middleware/errorHandler.js
 * PURPOSE: Defines custom error classes and a global Express middleware that
 *          catches errors from any route and returns structured JSON responses.
 *
 * WHY CUSTOM ERROR CLASSES?
 *   - They carry semantic meaning (NotFound, Validation, Internal) so the
 *     middleware can map each type to the correct HTTP status code.
 *   - Generic "throw new Error()" would force us to inspect message strings,
 *     which is fragile and unreadable.
 *
 * WHY A SINGLE ERROR MIDDLEWARE?
 *   - Without it, every route handler would need its own try/catch block that
 *     manually sends error responses — leading to duplicated boilerplate.
 *   - Express lets us pass an error to next(err); the first middleware with
 *     four parameters (err, req, res, next) becomes the catch-all handler.
 * ============================================================================
 */

// --------------------------------------------------------------------------
// Custom Error Classes — each extends the built-in Error and sets a default
// HTTP status code via the statusCode property for easy reference in middleware.
// --------------------------------------------------------------------------

/**
 * Thrown when a requested resource (e.g., a book by ID) does not exist.
 * Maps to HTTP 404 Not Found.
 */
class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'NotFoundError';
    this.statusCode = 404;
  }
}

/**
 * Thrown when client-supplied input fails validation (missing fields, bad types).
 * Maps to HTTP 400 Bad Request.
 */
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

/**
 * Thrown for unexpected server-side failures (database down, file I/O error).
 * Maps to HTTP 500 Internal Server Error. Clients should not retry blindly.
 */
class InternalServerError extends Error {
  constructor(message) {
    super(message);
    this.name = 'InternalServerError';
    this.statusCode = 500;
  }
}

// --------------------------------------------------------------------------
// Global Error-Handling Middleware
//
// Signature: (err, req, res, next) => {}
// Express recognizes this by the FOUR parameters and routes all errors here.
// ============================================================================

/**
 * Catches any error thrown in a route or middleware and sends a JSON response.
 *
 * Response shape is intentionally consistent so API consumers can parse errors
 * without inspecting status codes alone:
 *   { error: { message, statusCode, type } }
 *
 * In production you would also log `err.stack` to a logging service (e.g.,
 * Winston, Datadog) before responding — we keep it simple for this example.
 *
 * @param {Error} err - The error object caught by Express.
 * @param {Object} req - The Express request object (not used here).
 * @param {Object} res - The Express response object.
 * @param {Function} next - The next middleware function (unused in error handler).
 */
function errorHandler(err, req, res, next) {
  // Determine the status code: prefer err.statusCode if set by our custom classes,
  // otherwise fall back to 500 for unhandled generic errors.
  const statusCode = err.statusCode || 500;

  // Build a structured error response body.
  const errorResponse = {
    error: {
      message: err.message,
      statusCode,
      type: err.name || 'Error', // e.g., "ValidationError", "NotFoundError"
    },
  };

  // Send the JSON response with the appropriate HTTP status.
  res.status(statusCode).json(errorResponse);
}

// Export the classes and middleware for use in routes and server.js.
module.exports = {
  NotFoundError,
  ValidationError,
  InternalServerError,
  errorHandler,
};
```

