## File 5: `routes/books.js` — Book CRUD Routes

```javascript
/**
 * ============================================================================
 * FILE: routes/books.js
 * PURPOSE: Defines all RESTful endpoints for the /books resource:
 *   GET    /books          → list all books (with optional query filters)
 *   GET    /books/:id      → retrieve a single book by ID
 *   POST   /books          → create a new book
 *   PUT    /books/:id      → fully update an existing book
 *   DELETE /books/:id      → remove a book by ID
 *
 * REST CONVENTIONS FOLLOWED:
 *   - Resource nouns in URLs (/books), not verbs.
 *   - GET for reads (no side effects), POST for creation, PUT for full updates,
 *     DELETE for removal. This matches HTTP semantics and enables caching/proxies.
 *   - Consistent JSON response shape: { data, meta } for success; see errorHandler
 *     for the error shape.
 *
 * ASYNC/AWAIT PATTERN:
 *   We use async/await even though the data store is synchronous (in-memory array).
 *   This is intentional: when you later swap in a database (MongoDB, PostgreSQL),
 *   every helper call becomes an awaitable promise and NO route code needs to change.
 * ============================================================================
 */

const express = require('express');
const router = express.Router(); // Creates a standalone route handler set

// Import data-store helpers and custom error classes.
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
} = require('../data/books');
const { NotFoundError, ValidationError } = require('../middleware/errorHandler');

// ============================================================================
// GET /books
// Query parameters (all optional):
//   genre      → filter by exact genre match (e.g., ?genre=Fiction)
//   author     → filter by author name substring (case-insensitive)
//   minRating  → only books with rating >= this value (number)
// ============================================================================

/**
 * Lists all books, optionally filtered by query parameters.
 *
 * Example requests:
 *   GET /books                          → returns every book
 *   GET /books?genre=Science+Fiction    → filters by genre
 *   GET /books?author=martin&minRating=4.5  → combined filters
 *
 * @param {Object} req - Express request object with req.query containing filters.
 * @param {Object} res - Express response object.
 * @param {Function} next - Passed through on unexpected errors.
 */
router.get('/', async (req, res, next) => {
  try {
    // Destructure optional query parameters; defaults to undefined if absent.
    const { genre, author, minRating } = req.query;

    // Start with the full list, then apply filters sequentially.
    let result = getAllBooks();

    // Filter by genre (exact match, case-sensitive — adjust for your needs).
    if (genre) {
      result = result.filter((book) => book.genre === genre);
    }

    // Filter by author (case-insensitive substring match for usability).
    if (author) {
      const authorLower = author.toLowerCase();
      result = result.filter((book) =>
        book.author.toLowerCase().includes(authorLower)
      );
    }

    // Filter by minimum rating (convert query string to number).
    if (minRating !== undefined) {
      const min = parseFloat(minRating);
      if (isNaN(min)) {
        // Return 400 with a clear message instead of silently ignoring bad input.
        throw new ValidationError('Invalid minRating: must be a number');
      }
      result = result.filter((book) => book.rating >= min);
    }

    // Success response: wrap data in a consistent envelope.
    res.json({
      data: result,
      meta: {
        count: result.length,
        totalInStore: getAllBooks().length,
      },
    });
  } catch (error) {
    next(error); // Pass to global error handler
  }
});

// ============================================================================
// GET /books/:id
// Retrieves a single book. Throws NotFoundError if the ID does not exist.
// ============================================================================

/**
 * Returns a single book by its numeric ID.
 *
 * Example request:
 *   GET /books/1
 *
 * @param {Object} req - Express request with req.params.id.
 * @param {Object} res - Express response object.
 * @param {Function} next - Passed through on errors.
 */
router.get('/:id', async (req, res, next) => {
  try {
    // Validate that :id is actually a number before querying.
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID: must be a number');
    }

    const book = getBookById(id);
    if (!book) {
      // Throw our custom error so the global handler sends 404 JSON.
      throw new NotFoundError(`Book with id ${id} not found`);
    }

    res.json({ data: book });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// POST /books
// Creates a new book. Validates required fields and returns the created record.
// ============================================================================

/**
 * Creates a new book from the request body.
 *
 * Required fields: title, author
 * Optional fields: genre, publishedYear, rating (defaults provided)
 *
 * Example request body:
 *   { "title": "1984", "author": "George Orwell", "genre": "Dystopian" }
 *
 * @param {Object} req - Express request with parsed JSON body in req.body.
 * @param {Object} res - Express response object.
 * @param {Function} next - Passed through on errors.
 */
router.post('/', async (req, res, next) => {
  try {
    const { title, author, genre, publishedYear, rating } = req.body;

    // Validate required fields — return 400 with a descriptive message.
    if (!title || !author) {
      throw new ValidationError('Missing required fields: title and author are required');
    }

    // Build the book object, providing sensible defaults for optional fields.
    const newBook = createBook({
      title,
      author,
      genre: genre || 'Unknown',       // Default genre if not provided
      publishedYear: publishedYear || null,
      rating: rating !== undefined ? rating : 0, // Default rating to 0
    });

    // 201 Created is the correct status for a successful resource creation.
    res.status(201).json({ data: newBook });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// PUT /books/:id
// Fully replaces an existing book. All fields must be present in the body.
// ============================================================================

/**
 * Replaces all properties of an existing book.
 *
 * NOTE: This is a FULL update (not PATCH). Every field in the body will
 * overwrite the corresponding field on the server, even if it was optional
 * in POST. Omitted fields become undefined — validate accordingly.
 *
 * Example request:
 *   PUT /books/1
 *   Body: { "title": "The Great Gatsby (Updated)", "author": "F. Scott Fitzgerald", ... }
 *
 * @param {Object} req - Express request with params.id and JSON body.
 * @param {Object} res - Express response object.
 * @param {Function} next - Passed through on errors.
 */
router.put('/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID: must be a number');
    }

    // Check existence before attempting update.
    const existing = getBookById(id);
    if (!existing) {
      throw new NotFoundError(`Book with id ${id} not found`);
    }

    const updatedBook = updateBook(id, req.body);
    res.json({ data: updatedBook });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// DELETE /books/:id
// Removes a book. Returns 204 No Content on success (no response body).
// ============================================================================

/**
 * Deletes a book by its ID.
 *
 * A 204 status tells the client "the request succeeded but there is nothing
 * to return in the body" — this is the standard HTTP convention for DELETE.
 *
 * Example request:
 *   DELETE /books/2
 *
 * @param {Object} req - Express request with params.id.
 * @param {Object} res - Express response object.
 * @param {Function} next - Passed through on errors.
 */
router.delete('/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (isNaN(id)) {
      throw new ValidationError('Invalid book ID: must be a number');
    }

    const deleted = deleteBook(id);
    if (!deleted) {
      throw new NotFoundError(`Book with id ${id} not found`);
    }

    // 204 No Content — standard for successful DELETE operations.
    res.status(204).send();
  } catch (error) {
    next(error);
  }
});

// Export the router so server.js can mount it at /books.
module.exports = router;
```

