## File 6: `routes/stats.js` — Statistics Endpoint

```javascript
/**
 * ============================================================================
 * FILE: routes/stats.js
 * PURPOSE: Provides aggregate statistics about the book collection.
 *   GET /stats → returns counts, averages, and genre distribution.
 *
 * WHY A SEPARATE ENDPOINT?
 *   - Stats are derived data, not a resource in itself. Keeping them under
 *     /stats (not /books/stats) follows REST best practices: the URL describes
 *     WHAT you're querying, not how it's implemented.
 *   - Separating stats from books keeps the books router focused on CRUD and
 *     makes each file easier to read and test independently.
 * ============================================================================
 */

const express = require('express');
const router = express.Router();
const { getAllBooks } = require('../data/books');

// ============================================================================
// GET /stats
// Computes and returns aggregate metrics from the in-memory book store.
// ============================================================================

/**
 * Returns statistics about all books in the collection.
 *
 * Metrics included:
 *   - totalBooks        : count of all books
 *   - averageRating     : mean rating across all books (rounded to 2 decimals)
 *   - genreDistribution : object mapping each genre to its book count
 *   - oldestBook        : book with the earliest publishedYear
 *   - newestBook        : book with the latest publishedYear
 *
 * Example response:
 *   {
 *     "data": {
 *       "totalBooks": 3,
 *       "averageRating": 4.67,
 *       "genreDistribution": { "Fiction": 1, "Technology": 1, "Science Fiction": 1 },
 *       "oldestBook": { "title": "The Great Gatsby", "publishedYear": 1925 },
 *       "newestBook": { "title": "Clean Code", "publishedYear": 2008 }
 *     }
 *   }
 *
 * @param {Object} req - Express request object (no parameters needed).
 * @param {Object} res - Express response object.
 * @param {Function} next - Passed through on unexpected errors.
 */
router.get('/', async (req, res, next) => {
  try {
    const books = getAllBooks();

    // Guard against empty store — avoid division-by-zero and null references.
    if (books.length === 0) {
      return res.json({
        data: {
          totalBooks: 0,
          averageRating: 0,
          genreDistribution: {},
          oldestBook: null,
          newestBook: null,
        },
      });
    }

    // Compute average rating using reduce; round to 2 decimal places.
    const averageRating = parseFloat(
      (books.reduce((sum, b) => sum + b.rating, 0) / books.length).toFixed(2)
    );

    // Build genre distribution: { "Fiction": 1, "Technology": 2, ... }
    const genreDistribution = books.reduce((acc, book) => {
      const genre = book.genre || 'Unknown';
      acc[genre] = (acc[genre] || 0) + 1;
      return acc;
    }, {});

    // Find oldest and newest by publishedYear (nulls sort to end in numeric compare).
    const oldestBook = books.reduce((oldest, book) =>
      (!oldest || (book.publishedYear && book.publishedYear < oldest.publishedYear))
        ? book
        : oldest
    , null);

    const newestBook = books.reduce((newest, book) =>
      (!newest || (book.publishedYear && book.publishedYear > newest.publishedYear))
        ? book
        : newest
    , null);

    res.json({
      data: {
        totalBooks: books.length,
        averageRating,
        genreDistribution,
        oldestBook: oldestBook ? { title: oldestBook.title, publishedYear: oldestBook.publishedYear } : null,
        newestBook: newestBook ? { title: newestBook.title, publishedYear: newestBook.publishedYear } : null,
      },
    });
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

