## Arquivo 3: `src/models/book.js`

```javascript
/**
 * ============================================================
 * MODELO DE DADOS — LIVRO
 * ============================================================
 *
 * POR QUE USAR UM ARRAY EM MEMÓRIA?
 * ----------------------------------
 * Para este exemplo educacional, um array em memória é suficiente
 * porque:
 *   1. Mantém o código focado nos conceitos de REST e Express
 *   2. Evita dependências externas (banco de dados) que distrairiam
 *   3. Permite testar rapidamente todos os endpoints
 *
 * Em produção, substituiríamos este array por um banco de dados
 * real (MongoDB, PostgreSQL, etc.). A interface permaneceria a mesma:
 * funções de CRUD que operam sobre uma coleção de livros.
 *
 * POR QUE CADA LIVRO TEM UM `id` NUMÉRICO AUTOINCREMENTAL?
 * --------------------------------------------------------
 * IDs numéricos são mais simples de gerar (sem bibliotecas UUID),
 * mais legíveis em URLs (/books/1) e mais eficientes para indexação.
 * Em sistemas reais, UUIDs ou ULIDs seriam preferidos para evitar
 * problemas de previsibilidade e segurança.
 */

/**
 * Array que armazena todos os livros em memória.
 *
 * Escolha: array plano vs. objeto mapeado por ID.
 * Um array é adequado aqui porque:
 *   - O número de registros é pequeno (exemplo educacional)
 *   - Permite iteração simples para listagem e filtragem
 *   - Em produção com muitos registros, um Map ou objeto seria melhor
 *     para buscas O(1) por ID.
 */
const books = [];

/**
 * Contador autoincremental para gerar IDs únicos.
 * Começa em 1 e incrementa a cada novo livro criado.
 *
 * Nota: Em um sistema real com múltiplas instâncias (scale-out),
 * este contador precisaria ser centralizado (ex: banco de dados).
 */
let nextId = 1;

/**
 * ============================================================
 * VALIDAÇÃO DE DADOS
 * ============================================================
 *
 * POR QUE VALIDAR NO MODELO E NÃO APENAS NAS ROTAS?
 * --------------------------------------------------
 * A validação no modelo (camada de dados) garante que nenhum
 * caminho no código possa inserir dados inválidos, mesmo que
 * uma rota seja adicionada no futuro sem a validação adequada.
 * Isso segue o princípio de "defesa em profundidade".
 */

/**
 * Valida os campos obrigatórios e tipos de um livro.
 *
 * @param {Object} bookData - Dados do livro a serem validados
 * @param {string} bookData.title - Título do livro (obrigatório, não vazio)
 * @param {string} bookData.author - Autor do livro (obrigatório, não vazio)
 * @param {number} [bookData.year] - Ano de publicação (opcional, numérico)
 * @param {string} [bookData.genre] - Gênero literário (opcional)
 * @returns {Array<string>} Lista de mensagens de erro (vazia se válido)
 */
function validateBook(bookData) {
  const errors = [];

  // Validação do título: obrigatório e não pode ser apenas espaços
  if (!bookData.title || bookData.title.trim() === '') {
    errors.push('O campo "title" é obrigatório');
  }

  // Validação do autor: obrigatório e não pode ser apenas espaços
  if (!bookData.author || bookData.author.trim() === '') {
    errors.push('O campo "author" é obrigatório');
  }

  // Validação opcional do ano: se fornecido, deve ser um número inteiro positivo
  if (bookData.year !== undefined && bookData.year !== null) {
    const year = Number(bookData.year);
    if (!Number.isInteger(year) || year < 0) {
      errors.push('O campo "year" deve ser um número inteiro não negativo');
    }
  }

  return errors;
}

/**
 * ============================================================
 * OPERAÇÕES CRUD (Create, Read, Update, Delete)
 * ============================================================
 */

/**
 * Cria um novo livro no array em memória.
 *
 * @param {Object} bookData - Dados do livro a ser criado
 * @param {string} bookData.title - Título do livro
 * @param {string} bookData.author - Autor do livro
 * @param {number} [bookData.year] - Ano de publicação (opcional)
 * @param {string} [bookData.genre] - Gênero literário (opcional)
 * @returns {Object} O livro criado com ID atribuído
 * @throws {ValidationError} Se os dados forem inválidos
 */
function createBook(bookData) {
  const validationErrors = validateBook(bookData);
  if (validationErrors.length > 0) {
    // Juntamos todas as mensagens de erro em uma única string
    throw new Error(validationErrors.join('; '));
  }

  const book = {
    id: nextId++,
    title: bookData.title.trim(),
    author: bookData.author.trim(),
    year: bookData.year || null,
    genre: bookData.genre ? bookData.genre.trim() : null,
    createdAt: new Date().toISOString(), // ISO 8601 para consistência de fuso
    updatedAt: new Date().toISOString(),
  };

  books.push(book);
  return book;
}

/**
 * Lista todos os livros com suporte a filtragem opcional.
 *
 * PARÂMETROS DE FILTRAGEM (query string):
 *   - author: filtra por autor (case-insensitive, substring match)
 *   - genre: filtra por gênero (case-insensitive, substring match)
 *   - minYear: filtra livros publicados a partir deste ano
 *   - maxYear: filtra livros publicados até este ano
 *
 * @param {Object} [filters] - Filtros opcionais aplicados à lista
 * @returns {Array<Object>} Lista de livros correspondentes aos filtros
 */
function listBooks(filters = {}) {
  let result = [...books]; // Cria cópia para não mutar o array original

  // Filtragem por autor: busca parcial e insensível a maiúsculas/minúsculas
  if (filters.author) {
    const authorFilter = filters.author.toLowerCase();
    result = result.filter((book) =>
      book.author.toLowerCase().includes(authorFilter)
    );
  }

  // Filtragem por gênero
  if (filters.genre) {
    const genreFilter = filters.genre.toLowerCase();
    result = result.filter((book) =>
      book.genre ? book.genre.toLowerCase().includes(genreFilter) : false
    );
  }

  // Filtragem por faixa de ano de publicação
  if (filters.minYear) {
    const minYear = Number(filters.minYear);
    result = result.filter((book) => book.year >= minYear);
  }

  if (filters.maxYear) {
    const maxYear = Number(filters.maxYear);
    result = result.filter((book) => book.year <= maxYear);
  }

  return result;
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - ID do livro a ser buscado
 * @returns {Object|null} O livro encontrado ou null se não existir
 */
function findBookById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Atualiza os campos de um livro existente.
 * Apenas os campos fornecidos no objeto de atualização são modificados
 * (partial update / PATCH semantics, mesmo usando PUT).
 *
 * @param {number} id - ID do livro a ser atualizado
 * @param {Object} updates - Campos a serem atualizados
 * @returns {Object|null} O livro atualizado ou null se não encontrado
 */
function updateBook(id, updates) {
  const bookIndex = books.findIndex((book) => book.id === id);
  if (bookIndex === -1) return null;

  // Atualiza apenas os campos presentes no objeto de atualização
  if (updates.title !== undefined) {
    books[bookIndex].title = updates.title.trim();
  }
  if (updates.author !== undefined) {
    books[bookIndex].author = updates.author.trim();
  }
  if (updates.year !== undefined) {
    books[bookIndex].year = updates.year;
  }
  if (updates.genre !== undefined) {
    books[bookIndex].genre = updates.genre ? updates.genre.trim() : null;
  }

  // Sempre atualiza o timestamp de modificação
  books[bookIndex].updatedAt = new Date().toISOString();

  return books[bookIndex];
}

/**
 * Remove um livro do array pelo seu ID.
 *
 * @param {number} id - ID do livro a ser removido
 * @returns {boolean} true se o livro foi encontrado e removido, false caso contrário
 */
function deleteBook(id) {
  const bookIndex = books.findIndex((book) => book.id === id);
  if (bookIndex === -1) return false;

  books.splice(bookIndex, 1);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre a coleção de livros.
 *
 * @returns {Object} Estatísticas da coleção
 */
function getStats() {
  if (books.length === 0) {
    return {
      total: 0,
      averageYear: null,
      booksByGenre: {},
      booksByAuthor: {},
    };
  }

  // Reduz o array a um objeto com contagens por gênero e autor
  const { booksByGenre, booksByAuthor, sumYear } = books.reduce(
    (acc, book) => {
      // Contagem por gênero (livros sem gênero vão para "Sem gênero")
      const genre = book.genre || 'Sem gênero';
      acc.booksByGenre[genre] = (acc.booksByGenre[genre] || 0) + 1;

      // Contagem por autor
      acc.booksByAuthor[book.author] = (acc.booksByAuthor[book.author] || 0) + 1;

      // Soma dos anos para cálculo da média
      if (book.year !== null) {
        acc.sumYear += book.year;
      }

      return acc;
    },
    { booksByGenre: {}, booksByAuthor: {}, sumYear: 0 }
  );

  // Filtra livros com ano definido para calcular a média
  const booksWithYear = books.filter((b) => b.year !== null);
  const averageYear =
    booksWithYear.length > 0
      ? Math.round(sumYear / booksWithYear.length)
      : null;

  return {
    total: books.length,
    averageYear,
    booksByGenre,
    booksByAuthor,
  };
}

module.exports = {
  createBook,
  listBooks,
  findBookById,
  updateBook,
  deleteBook,
  getStats,
};
```

> **Explicação sobre `reduce` nas estatísticas:** O método `Array.prototype.reduce` é escolhido porque permite calcular múltiplas agregações (contagem por gênero, contagem por autor, soma dos anos) em uma única passagem pelo array — complexidade O(n) em vez de O(3n) se usássemos três loops separados.

