## Arquivo 4: `src/routes/books.js`

```javascript
/**
 * ============================================================
 * ROTAS DA API DE LIVROS
 * ============================================================
 *
 * POR QUE SEPARAR ROTAS EM ARQUIVOS DIFERENCIADOS?
 * -------------------------------------------------
 * Manter as rotas em um arquivo separado (ou conjunto de arquivos)
 * segue o princípio de responsabilidade única:
 *   - O arquivo da rota se preocupa apenas com mapeamento URL → handler
 *   - A lógica de negócio permanece no modelo
 *   - O middleware de erro permanece nos middlewares
 * Isso facilita a manutenção, testes unitários e escalabilidade.
 *
 * CONVENÇÕES REST ADOTADAS:
 * --------------------------
 *   GET    /books          → listAll()      (coleção)
 *   GET    /books/:id      → getById()      (recurso singular)
 *   POST   /books          → create()       (criar recurso)
 *   PUT    /books/:id      → update()       (substituir recurso completo)
 *   DELETE /books/:id      → remove()       (deletar recurso)
 *   GET    /stats          → getStats()     (recurso derivado)
 *
 * Cada método HTTP tem um significado semântico bem definido:
 *   - GET: seguro e idempotente (não modifica estado)
 *   - POST: cria novo recurso, não é idempotente
 *   - PUT: substitui o recurso inteiro, é idempotente
 *   - DELETE: remove o recurso, é idempotente
 */

const express = require('express');
const router = express.Router(); // Router isolado para as rotas de livros

// Importa o modelo e as classes de erro
const {
  createBook,
  listBooks,
  findBookById,
  updateBook,
  deleteBook,
  getStats,
} = require('../models/book');
const { NotFoundError, ValidationError } = require('../utils/errors');

/**
 * ============================================================
 * GET /books
 * Lista todos os livros com filtragem opcional via query string.
 *
 * EXEMPLOS DE USO:
 * ---------------
 * # Listar todos os livros
 * curl http://localhost:3000/books
 *
 * # Filtrar por autor (busca parcial)
 * curl "http://localhost:3000/books?author=tolkien"
 *
 * # Filtrar por gênero
 * curl "http://localhost:3000/books?genre=ficcao"
 *
 * # Filtrar por faixa de ano
 * curl "http://localhost:3000/books?minYear=2000&maxYear=2010"
 *
 * # Combinar filtros
 * curl "http://localhost:3000/books?author=tolkien&genre=fantasia"
 *
 * RESPOSTA (200 OK):
 * {
 *   "data": [
 *     { "id": 1, "title": "O Senhor dos Anéis", "author": "J.R.R. Tolkien", ... }
 *   ],
 *   "total": 1
 * }
 */
router.get('/books', (req, res) => {
  // Extrai parâmetros de filtragem da query string
  const filters = {
    author: req.query.author,
    genre: req.query.genre,
    minYear: req.query.minYear ? Number(req.query.minYear) : undefined,
    maxYear: req.query.maxYear ? Number(req.query.maxYear) : undefined,
  };

  // Remove undefined para passar apenas filtros válidos ao modelo
  Object.keys(filters).forEach(
    (key) => filters[key] === undefined && delete filters[key]
  );

  const books = listBooks(filters);

  res.json({
    data: books,
    total: books.length, // Campo adicional para facilitar paginação futura
  });
});

/**
 * ============================================================
 * GET /books/:id
 * Busca um livro específico pelo seu ID numérico.
 *
 * EXEMPLOS DE USO:
 * ---------------
 * # Obter livro com ID 1
 * curl http://localhost:3000/books/1
 *
 * # Tentar obter livro inexistente (retorna 404)
 * curl http://localhost:3000/books/999
 *
 * RESPOSTA (200 OK):
 * {
 *   "data": {
 *     "id": 1,
 *     "title": "O Senhor dos Anéis",
 *     "author": "J.R.R. Tolkien",
 *     "year": 1954,
 *     "genre": "Fantasia",
 *     "createdAt": "2024-01-15T10:30:00.000Z",
 *     "updatedAt": "2024-01-15T10:30:00.000Z"
 *   }
 * }
 *
 * RESPOSTA (404 Not Found):
 * {
 *   "error": {
 *     "message": "Livro com ID 999 não encontrado",
 *     "statusCode": 404
 *   }
 * }
 */
router.get('/books/:id', (req, res) => {
  // Converte o parâmetro de rota para número
  const id = Number(req.params.id);

  // Validação básica: o ID deve ser um número inteiro válido
  if (isNaN(id) || !Number.isInteger(id)) {
    throw new ValidationError('O campo "id" deve ser um número inteiro válido');
  }

  const book = findBookById(id);

  if (!book) {
    // Lança NotFoundError para ser capturado pelo middleware de erro
    throw new NotFoundError('Livro', id);
  }

  res.json({ data: book });
});

/**
 * ============================================================
 * POST /books
 * Cria um novo livro a partir dos dados enviados no corpo da requisição.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 * ---------------------------
 * {
 *   "title": "O Senhor dos Anéis",    // obrigatório
 *   "author": "J.R.R. Tolkien",       // obrigatório
 *   "year": 1954,                     // opcional
 *   "genre": "Fantasia"               // opcional
 * }
 *
 * EXEMPLOS DE USO:
 * ---------------
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
 *
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"1984","author":"George Orwell"}'
 *
 * RESPOSTA (201 Created):
 * {
 *   "data": {
 *     "id": 1,
 *     "title": "O Senhor dos Anéis",
 *     ...
 *   }
 * }
 *
 * RESPOSTA (400 Bad Request) - título vazio:
 * {
 *   "error": {
 *     "message": "O campo \"title\" é obrigatório; O campo \"author\" é obrigatório",
 *     "statusCode": 400
 *   }
 * }
 */
router.post('/books', (req, res) => {
  const bookData = req.body;

  // Validação: corpo da requisição deve ser um objeto
  if (!bookData || typeof bookData !== 'object') {
    throw new ValidationError('O corpo da requisição deve ser um objeto JSON');
  }

  const book = createBook(bookData);

  // 201 Created indica que um novo recurso foi criado com sucesso.
  // A localização do novo recurso é indicada no header Location.
  res.status(201).header('Location', `/books/${book.id}`).json({ data: book });
});

/**
 * ============================================================
 * PUT /books/:id
 * Atualiza completamente um livro existente.
 * Todos os campos obrigatórios devem ser fornecidos.
 *
 * CORPO DA REQUISIÇÃO (JSON):
 * ---------------------------
 * {
 *   "title": "O Senhor dos Anéis - A Sociedade do Anel",
 *   "author": "J.R.R. Tolkien",
 *   "year": 1954,
 *   "genre": "Fantasia"
 * }
 *
 * EXEMPLOS DE USO:
 * ---------------
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"O Senhor dos Anéis (edição revisada)","author":"J.R.R. Tolkien","year":1954,"genre":"Fantasia"}'
 *
 * RESPOSTA (200 OK):
 * {
 *   "data": {
 *     "id": 1,
 *     "title": "O Senhor dos Anéis (edição revisada)",
 *     ...
 *   }
 * }
 *
 * RESPOSTA (404 Not Found):
 * {
 *   "error": {
 *     "message": "Livro com ID 999 não encontrado",
 *     "statusCode": 404
 *   }
 * }
 */
router.put('/books/:id', (req, res) => {
  const id = Number(req.params.id);

  if (isNaN(id) || !Number.isInteger(id)) {
    throw new ValidationError('O campo "id" deve ser um número inteiro válido');
  }

  const updates = req.body;

  // Validação: corpo deve ser um objeto
  if (!updates || typeof updates !== 'object') {
    throw new ValidationError('O corpo da requisição deve ser um objeto JSON');
  }

  const book = updateBook(id, updates);

  if (!book) {
    throw new NotFoundError('Livro', id);
  }

  res.json({ data: book });
});

/**
 * ============================================================
 * DELETE /books/:id
 * Remove um livro do repositório pelo seu ID.
 *
 * EXEMPLOS DE USO:
 * ---------------
 * curl -X DELETE http://localhost:3000/books/1
 *
 * RESPOSTA (200 OK):
 * {
 *   "data": {
 *     "message": "Livro com ID 1 removido com sucesso"
 *   }
 * }
 *
 * RESPOSTA (404 Not Found):
 * {
 *   "error": {
 *     "message": "Livro com ID 999 não encontrado",
 *     "statusCode": 404
 *   }
 * }
 */
router.delete('/books/:id', (req, res) => {
  const id = Number(req.params.id);

  if (isNaN(id) || !Number.isInteger(id)) {
    throw new ValidationError('O campo "id" deve ser um número inteiro válido');
  }

  const deleted = deleteBook(id);

  if (!deleted) {
    throw new NotFoundError('Livro', id);
  }

  res.json({
    data: { message: `Livro com ID ${id} removido com sucesso` },
  });
});

/**
 * ============================================================
 * GET /stats
 * Retorna estatísticas agregadas sobre a coleção de livros.
 *
 * EXEMPLOS DE USO:
 * ---------------
 * curl http://localhost:3000/stats
 *
 * RESPOSTA (200 OK):
 * {
 *   "data": {
 *     "total": 5,
 *     "averageYear": 1985,
 *     "booksByGenre": {
 *       "Fantasia": 2,
 *       "Ficção Científica": 1,
 *       "Romance": 1,
 *       "Sem gênero": 1
 *     },
 *     "booksByAuthor": {
 *       "J.R.R. Tolkien": 2,
 *       "George Orwell": 1,
 *       ...
 *     }
 *   }
 * }
 */
router.get('/stats', (req, res) => {
  const stats = getStats();
  res.json({ data: stats });
});

module.exports = router;
```

> **Explicação sobre `res.status(201).header('Location', ...)`:** A convenção HTTP recomenda que respostas de criação (POST/PUT que criam) incluam um header `Location` apontando para o URI do recurso criado. Isso permite que clientes descubram automaticamente onde acessar o novo recurso — um padrão essencial em APIs REST bem projetadas.

