## Arquivo 5: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================
 *
 * POR QUE UM MIDDLEWARE ESPECIALIZADO PARA ERROS?
 * -------------------------------------------------
 * Express identifica middlewares de erro pela assinatura:
 *   (err, req, res, next) => ...  (4 parâmetros)
 *
 * Ao centralizar o tratamento de erros em um único middleware,
 * garantimos que:
 *   1. Todas as respostas de erro tenham formato consistente
 *   2. Erros não capturados não vazem para o cliente como stack traces
 *   3. Logs sejam gerados uniformemente para fins de monitoramento
 *
 * PADRÃO DE RESPOSTA DE ERRO:
 * ----------------------------
 * {
 *   "error": {
 *     "message": "Descrição do erro",
 *     "statusCode": 404,
 *     "isOperational": true
 *   }
 * }
 *
 * Em produção, `isOperational` e a stack trace NÃO devem ser
 * expostos ao cliente (apenas logados internamente).
 */

const { AppError } = require('../utils/errors');

/**
 * Middleware de tratamento de erros global.
 * Deve ser registrado APÓS todas as rotas para capturar erros delas.
 *
 * @param {Error} err - A instância de erro lançada
 * @param {import('express').Request} req - Objeto de requisição Express
 * @param {import('express').Response} res - Objeto de resposta Express
 * @param {import('express').NextFunction} next - Função next do Express
 */
function errorHandler(err, req, res, next) {
  // Log do erro para fins de monitoramento (nunca expor ao cliente)
  console.error(`[ERROR] ${new Date().toISOString()} - ${err.message}`);
  if (process.env.NODE_ENV === 'development' && err.stack) {
    console.error(err.stack);
  }

  // Se for um AppError personalizado, usa seu statusCode
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      error: {
        message: err.message,
        statusCode: err.statusCode,
        isOperational: err.isOperational,
      },
    });
  }

  // Para erros não tratados (bugs do servidor), retorna 500 genérico
  // NUNCA expomos stack trace ou detalhes internos ao cliente em produção
  const statusCode = err.statusCode || 500;
  const message =
    process.env.NODE_ENV === 'development' ? err.message : 'Erro interno do servidor';

  res.status(statusCode).json({
    error: {
      message,
      statusCode,
      isOperational: false,
    },
  });
}

module.exports = errorHandler;
```

> **Explicação sobre a assinatura com 4 parâmetros:** Express usa o número de parâmetros para distinguir middlewares normais (3) de middlewares de erro (4). Se você definir um middleware de erro com apenas 3 parâmetros, o Express o tratará como middleware normal e não o chamará automaticamente quando um erro for passado via `next(err)`.

