```javascript
/**
 * ============================================================
 * MIDDLEWARE 404 — RECURSO NÃO ENCONTRADO
 * ============================================================
 *
 * Este middleware captura requisições para rotas que não foram
 * definidas. Deve ser registrado APÓS todas as rotas, mas ANTES
 * do middleware de tratamento de erros.
 *
 * Se fosse colocado antes das rotas, capturaria TODAS as requisições,
 * impedindo que as rotas funcionais fossem atendidas.
 */

/**
 * Middleware que responde com 404 para qualquer rota não definida.
 *
 * @param {import('express').Request} req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function notFoundHandler(req, res, next) {
  res.status(404).json({
    error: {
      message: `Rota ${req.method} ${req.originalUrl} não encontrada`,
      statusCode: 404,
    },
  });
}

module.exports = notFoundHandler;
```

