## Arquivo 7: `src/app.js`

```javascript
/**
 * ============================================================
 * CONFIGURAÇÃO DA APLICAÇÃO EXPRESS
 * ============================================================
 *
 * POR QUE SEPARAR app.js DO server.js?
 * --------------------------------------
 *   - app.js: configura a aplicação (middlewares, rotas)
 *   - server.js: apenas inicia o servidor HTTP e define a porta
 *
 * Isso permite testar a aplicação sem precisar iniciar um servidor,
 * facilitando testes unitários que importam `app` diretamente.
 */

const express = require('express');

// Importa as rotas e middlewares
const bookRoutes = require('./routes/books');
const errorHandler = require('./middleware/errorHandler');
const notFoundHandler = require('./middleware/notFound');

const app = express();

/**
 * ============================================================
 * MIDDLEWARES GLOBAIS
 * ============================================================
 *
 * ORDEM DE REGISTRO (IMPORTANTE):
 * ---------------------------------
 * 1. Middleware de body parser — deve vir ANTES das rotas
 *    para que req.body esteja disponível nos handlers
 * 2. Rotas — devem vir DEPOIS dos middlewares de parsing
 * 3. Middleware 404 — deve vir DEPOIS de todas as rotas
 * 4. Middleware de erro — deve ser o ÚLTIMO middleware
 */

// Body parser: converte JSON do corpo da requisição em objeto JavaScript
// limit: aumenta o limite padrão de 100KB para 50KB — suficiente para este exemplo
app.use(express.json({ limit: '50kb' }));

// Log básico de cada requisição (útil para debugging)
app.use((req, res, next) => {
  console.log(
    `[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`
  );
  next();
});

// Registra as rotas de livros no caminho /books
app.use('/books', bookRoutes);

// Rota raiz informativa
app.get('/', (req, res) => {
  res.json({
    message: 'API de Livros — Exemplo Educacional',
    endpoints: {
      'GET /books': 'Listar todos os livros (com filtragem opcional)',
      'GET /books/:id': 'Obter livro por ID',
      'POST /books': 'Criar novo livro',
      'PUT /books/:id': 'Atualizar livro existente',
      'DELETE /books/:id': 'Excluir livro',
      'GET /stats': 'Estatísticas da coleção',
    },
  });
});

// Middleware 404 — para rotas não definidas
app.use(notFoundHandler);

// Middleware de tratamento de erros — SEMPRE o último
app.use(errorHandler);

module.exports = app;
```

> **Explicação sobre a ordem dos middlewares:** No Express, os middlewares são executados em ordem sequencial (como uma fila). Se o middleware 404 fosse registrado antes das rotas, ele capturaria todas as requisições e nenhuma rota funcionaria. Da mesma forma, se o errorHandler viesse antes do notFoundHandler, erros de "rota não encontrada" seriam tratados como erros normais em vez de 404s.

