## Arquivo 8: `src/server.js`

```javascript
/**
 * ============================================================
 * PONTO DE ENTRADA DO SERVIDOR
 * ============================================================
 *
 * Este arquivo é o mais simples possível: apenas importa a
 * aplicação e inicia o servidor HTTP na porta configurada.
 * A porta segue a convenção de usar variável de ambiente com fallback.
 */

const app = require('./app');

// Porta padrão 3000, ou usa PORT do ambiente (comum em containers/PaaS)
const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`📚 API de Livros rodando na porta ${PORT}`);
  console.log(`   Ambiente: ${process.env.NODE_ENV || 'development'}`);
  console.log(`   Endpoints disponíveis:`);
  console.log(`     GET    http://localhost:${PORT}/`);
  console.log(`     GET    http://localhost:${PORT}/books`);
  console.log(`     POST   http://localhost:${PORT}/books`);
  console.log(`     PUT    http://localhost:${PORT}/books/:id`);
  console.log(`     DELETE http://localhost:${PORT}/books/:id`);
  console.log(`     GET    http://localhost:${PORT}/stats`);
});

// Tratamento de erros não capturados no nível do processo
process.on('uncaughtException', (err) => {
  console.error('❌ Uncaught Exception:', err.message);
  server.close(() => process.exit(1));
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('❌ Unhandled Rejection at:', promise, 'reason:', reason);
  server.close(() => process.exit(1));
});

module.exports = server;
```

> **Explicação sobre `uncaughtException` e `unhandledRejection`:** Em Node.js, erros não capturados em callbacks ou promessas rejeitadas causam o encerramento do processo. Capturá-los permite fazer cleanup (como fechar conexões) antes de sair, e em desenvolvimento evita que o nodemon reinicie o servidor silenciosamente.

