## src/dataStore.js

```javascript
/**
 * In-memory data store for book management.
 * 
 * WHY IN-MEMORY ARRAY STORAGE:
 * - Simple to understand and debug for educational purposes
 * - No database setup required, runs immediately
 * - Demonstrates CRUD operations without external dependencies
 * - In production, this would be replaced with a database (MongoDB, PostgreSQL, etc.)
 * 
 * DATA STRUCTURE CHOICES:
 * - Array of objects: Preserves insertion order for listing endpoints
 * - Each book has a unique numeric ID generated sequentially
 * - Fields include title, author, genre, year, and rating for meaningful filtering/stats
 */

// In-memory array to store all books. 
// Using an array allows us to maintain insertion order when listing all books.
const books = [];

// Counter for generating unique IDs. Starting at 1 for simplicity.
let nextId = 1;

/**
 * Retrieves all books from the in-memory storage.
 * 
 * @returns {Array} Array of all book objects
 */
function getAllBooks() {
    return [...books]; // Return a copy to prevent external mutation
}

/**
 * Finds a single book by its ID.
 * 
 * @param {number} id - The unique identifier of the book
 * @returns {Object|null} The book object if found, null otherwise
 */
function getBookById(id) {
    return books.find(book => book.id === id) || null;
}

/**
 * Adds a new book to the storage with auto-generated ID.
 * 
 * @param {Object} bookData - Book data without ID (title, author, genre, year, rating)
 * @returns {Object} The created book object with assigned ID
 */
function createBook(bookData) {
    const newBook = {
        id: nextId++, // Auto-incrementing ID
        ...bookData   // Spread the provided data into the book object
    };
    books.push(newBook);
    return newBook;
}

/**
 * Updates an existing book by its ID.
 * 
 * @param {number} id - The unique identifier of the book to update
 * @param {Object} updates - Fields to update (partial or full replacement)
 * @returns {Object|null} The updated book object, or null if not found
 */
function updateBook(id, updates) {
    const index = books.findIndex(book => book.id === id);
    if (index === -1) return null;

    // Create a new object with merged data to avoid mutating the original reference
    books[index] = { ...books[index], ...updates };
    return books[index];
}

/**
 * Deletes a book by its ID.
 * 
 * @param {number} id - The unique identifier of the book to delete
 * @returns {boolean} True if deleted, false if not found
 */
function deleteBook(id) {
    const index = books.findIndex(book => book.id === id);
    if (index === -1) return false;

    books.splice(index, 1); // Remove the book from the array
    return true;
}

/**
 * Calculates statistics about the book collection.
 * 
 * @returns {Object} Statistics including total count, average rating, most common genre, etc.
 */
function getStats() {
    const totalBooks = books.length;

    if (totalBooks === 0) {
        return {
            totalBooks: 0,
            averageRating: 0,
            mostCommonGenre: null,
            booksByDecade: {}
        };
    }

    // Calculate average rating
    const totalRating = books.reduce((sum, book) => sum + (book.rating || 0), 0);
    const averageRating = parseFloat((totalRating / totalBooks).toFixed(2));

    // Find most common genre using frequency map
    const genreCounts = {};
    books.forEach(book => {
        const genre = book.genre || 'Unknown';
        genreCounts[genre] = (genreCounts[genre] || 0) + 1;
    });

    let mostCommonGenre = null;
    let maxCount = 0;
    Object.entries(genreCounts).forEach(([genre, count]) => {
        if (count > maxCount) {
            maxCount = count;
            mostCommonGenre = genre;
        }
    });

    // Group books by decade for additional stats
    const booksByDecade = {};
    books.forEach(book => {
        const year = book.year || 0;
        const decade = Math.floor(year / 10) * 10;
        const decadeLabel = `${decade}s`;
        booksByDecade[decadeLabel] = (booksByDecade[decadeLabel] || 0) + 1;
    });

    return {
        totalBooks,
        averageRating,
        mostCommonGenre,
        booksByDecade
    };
}

// Export all functions using CommonJS module syntax
module.exports = {
    getAllBooks,
    getBookById,
    createBook,
    updateBook,
    deleteBook,
    getStats
};
