/**
 * Custom error classes for the book management API.
 * 
 * WHY CUSTOM ERROR CLASSES:
 * - Provides specific error types for different failure scenarios
 * - Enables better error handling in middleware and route handlers
 * - Makes debugging easier by providing descriptive error messages
 * - Follows the principle of failing fast with clear, actionable errors
 */

/**
 * Base error class that extends the built-in Error.
 * Includes HTTP status code for REST API responses.
 */
class AppError extends Error {
    /**
     * Creates an instance of AppError.
     * 
     * @param {string} message - Human-readable error message
     * @param {number} statusCode - HTTP status code (default: 500)
     */
    constructor(message, statusCode = 500) {
        super(message); // Call the parent Error constructor
        this.statusCode = statusCode;
        this.isOperational = true; // Mark as operational error (not a bug)

        // Capture stack trace for debugging
        Error.captureStackTrace(this, this.constructor);
    }
}

/**
 * Error class for 404 Not Found responses.
 * Used when requested resources don't exist.
 */
class NotFoundError extends AppError {
    /**
     * Creates a NotFoundError instance.
     * 
     * @param {string} resource - Name of the resource not found (e.g., "Book")
     * @param {*} id - The ID that was requested
     */
    constructor(resource = 'Resource', id) {
        const message = id 
            ? `${resource} with id ${id} not found`
            : `${resource} not found`;
        super(message, 404);
    }
}

/**
 * Error class for 400 Bad Request responses.
 * Used when client sends invalid or incomplete data.
 */
class ValidationError extends AppError {
    /**
     * Creates a ValidationError instance.
     * 
     * @param {string} message - Description of the validation error
     * @param {Array} fields - Array of field names that failed validation
     */
    constructor(message, fields = []) {
        super(message, 400);
        this.fields = fields; // Store which fields caused the error
    }
}

/**
 * Error class for 500 Internal Server Error responses.
 * Used for unexpected server-side failures.
 */
class InternalError extends AppError {
    /**
     * Creates an InternalError instance.
     * 
     * @param {string} message - Description of the internal error
     */
    constructor(message = 'Internal server error') {
        super(message, 500);
        this.isOperational = false; // Mark as non-operational (potential bug)
    }
}

// Export all custom error classes
module.exports = {
    AppError,
    NotFoundError,
    ValidationError,
    InternalError
};
