/**
 * Validation middleware for book creation and update requests.
 * 
 * WHY SEPARATE VALIDATION MIDDLEWARE:
 * - Keeps route handlers clean and focused on business logic
 * - Reusable across multiple endpoints (POST /books, PUT /books/:id)
 * - Provides consistent validation rules throughout the API
 * - Makes it easy to add or modify validation rules in one place
 */

const { ValidationError } = require('../errors');

/**
 * Validates book data for creation (POST request).
 * 
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object  
 * @param {Function} next - Express next middleware function
 */
function validateCreateBook(req, res, next) {
    const { title, author, genre, year, rating } = req.body;

    // Array to collect validation errors
    const errors = [];

    // Validate required fields
    if (!title || typeof title !== 'string' || title.trim() === '') {
        errors.push('Title is required and must be a non-empty string');
    }

    if (!author || typeof author !== 'string' || author.trim() === '') {
        errors.push('Author is required and must be a non-empty string');
    }

    if (!genre || typeof genre !== 'string' || genre.trim() === '') {
        errors.push('Genre is required and must be a non-empty string');
    }

    // Validate year (must be a number between 0 and current year)
    const currentYear = new Date().getFullYear();
    if (year === undefined || year === null) {
        errors.push('Year is required');
    } else if (!Number.isInteger(year) || year < 0 || year > currentYear + 1) {
        errors.push(`Year must be an integer between 0 and ${currentYear + 1}`);
    }

    // Validate rating (optional, but if provided must be a number 0-5)
    if (rating !== undefined && rating !== null) {
        if (typeof rating !== 'number' || rating < 0 || rating > 5) {
            errors.push('Rating must be a number between 0 and 5');
        }
    }

    // If there are validation errors, throw ValidationError with details
    if (errors.length > 0) {
        return next(new ValidationError('Invalid book data', errors));
    }

    // Validation passed, continue to route handler
    next();
}

/**
 * Validates book data for updates (PUT request).
 * At least one field must be provided.
 * 
 * @param {Object} req - Express request object
 * @param {Object} res - Express response object  
 * @param {Function} next - Express next middleware function
 */
function validateUpdateBook(req, res, next) {
    const { title, author, genre, year, rating } = req.body;

    // Check that at least one field is provided for update
    const hasAnyField = title !== undefined || author !== undefined || 
                        genre !== undefined || year !== undefined || rating !== undefined;

    if (!hasAnyField) {
        return next(new ValidationError('At least one field must be provided for update'));
    }

    // Validate each provided field (same rules as create, but optional)
    const errors = [];

    if (title !== undefined) {
        if (typeof title !== 'string' || title.trim() === '') {
            errors.push('Title must be a non-empty string');
        }
    }

    if (author !== undefined) {
        if (typeof author !== 'string' || author.trim() === '') {
            errors.push('Author must be a non-empty string');
        }
    }

    if (genre !== undefined) {
        if (typeof genre !== 'string' || genre.trim() === '') {
            errors.push('Genre must be a non-empty string');
        }
    }

    if (year !== undefined) {
        const currentYear = new Date().getFullYear();
        if (!Number.isInteger(year) || year < 0 || year > currentYear + 1) {
            errors.push(`Year must be an integer between 0 and ${currentYear + 1}`);
        }
    }

    if (rating !== undefined) {
        if (typeof rating !== 'number' || rating < 0 || rating > 5) {
            errors.push('Rating must be a number between 0 and 5');
        }
    }

    if (errors.length > 0) {
        return next(new ValidationError('Invalid book data', errors));
    }

    next();
}

// Export validation middleware functions
module.exports = {
    validateCreateBook,
    validateUpdateBook
};
