/**
 * Book route handlers for the REST API.
 * 
 * WHY SEPARATE ROUTE FILE:
 * - Keeps code organized by domain (books vs other resources)
 * - Makes it easy to add more routes in the future
 * - Follows the separation of concerns principle
 * - Allows independent testing of route logic
 */

const express = require('express');
const router = express.Router(); // Create a new router instance

// Import data store functions and error classes
const { 
    getAllBooks, 
    getBookById, 
    createBook, 
    updateBook, 
    deleteBook, 
    getStats 
} = require('../dataStore');
const { NotFoundError } = require('../errors');
const { validateCreateBook, validateUpdateBook } = require('../middleware/validation');

/**
 * GET /books - List all books with optional filtering.
 * 
 * QUERY PARAMETERS:
 * - title: Filter by book title (partial match)
 * - author: Filter by author name (partial match)
 * - genre: Filter by exact genre match
 * - minYear: Filter books published after this year
 * - maxYear: Filter books published before this year
 * - minRating: Filter books with rating >= this value
 * 
 * WHY QUERY PARAMETER FILTERING:
 * - Keeps the API flexible without creating multiple endpoints
 * - Allows clients to compose complex queries
 * - Follows REST conventions for resource filtering
 * 
 * @example GET /books?genre=Fiction&minRating=4
 * @example GET /books?author=tolkien&minYear=1950
 */
router.get('/', (req, res) => {
    try {
        // Start with all books
        let filteredBooks = getAllBooks();

        // Apply filters based on query parameters
        const { title, author, genre, minYear, maxYear, minRating } = req.query;

        if (title) {
            // Case-insensitive partial match for title
            filteredBooks = filteredBooks.filter(book => 
                book.title.toLowerCase().includes(title.toLowerCase())
            );
        }

        if (author) {
            // Case-insensitive partial match for author
            filteredBooks = filteredBooks.filter(book => 
                book.author.toLowerCase().includes(author.toLowerCase())
            );
        }

        if (genre) {
            // Exact match for genre
            filteredBooks = filteredBooks.filter(book => 
                book.genre === genre
            );
        }

        if (minYear) {
            const year = parseInt(minYear, 10);
            filteredBooks = filteredBooks.filter(book => book.year >= year);
        }

        if (maxYear) {
            const year = parseInt(maxYear, 10);
            filteredBooks = filteredBooks.filter(book => book.year <= year);
        }

        if (minRating) {
            const rating = parseFloat(minRating);
            filteredBooks = filteredBooks.filter(book => book.rating >= rating);
        }

        // Return filtered books with 200 OK status
        res.json({
            success: true,
            count: filteredBooks.length,
            data: filteredBooks
        });
    } catch (error) {
        // Let the global error handler deal with this
        next(error);
    }
});

/**
 * GET /books/stats - Return statistics about the book collection.
 * 
 * @example GET /books/stats
 */
router.get('/stats', (req, res) => {
    try {
        const stats = getStats();

        res.json({
            success: true,
            data: stats
        });
    } catch (error) {
        next(error);
    }
});

/**
 * GET /books/:id - Get a single book by its ID.
 * 
 * @param {string} req.params.id - The book ID to retrieve
 * @example GET /books/1
 */
router.get('/:id', (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);

        // Find the book in the data store
        const book = getBookById(id);

        // If not found, throw NotFoundError
        if (!book) {
            throw new NotFoundError('Book', id);
        }

        // Return the book with 200 OK status
        res.json({
            success: true,
            data: book
        });
    } catch (error) {
        next(error);
    }
});

/**
 * POST /books - Create a new book.
 * 
 * REQUEST BODY:
 * {
 *   "title": "The Hobbit",
 *   "author": "J.R.R. Tolkien",
 *   "genre": "Fantasy",
 *   "year": 1937,
 *   "rating": 4.5
 * }
 * 
 * @example POST /books
 */
router.post('/', validateCreateBook, (req, res) => {
    try {
        // Create the book using the data store
        const newBook = createBook(req.body);

        // Return the created book with 201 Created status
        res.status(201).json({
            success: true,
            data: newBook
        });
    } catch (error) {
        next(error);
    }
});

/**
 * PUT /books/:id - Update an existing book.
 * 
 * REQUEST BODY: Any combination of fields to update
 * 
 * @example PUT /books/1
 */
router.put('/:id', validateUpdateBook, (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);

        // Find the book first to check if it exists
        const existingBook = getBookById(id);
        if (!existingBook) {
            throw new NotFoundError('Book', id);
        }

        // Update the book in the data store
        const updatedBook = updateBook(id, req.body);

        // Return the updated book with 200 OK status
        res.json({
            success: true,
            data: updatedBook
        });
    } catch (error) {
        next(error);
    }
});

/**
 * DELETE /books/:id - Delete a book by its ID.
 * 
 * @example DELETE /books/1
 */
router.delete('/:id', (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);

        // Find the book first to check if it exists
        const existingBook = getBookById(id);
        if (!existingBook) {
            throw new NotFoundError('Book', id);
        }

        // Delete the book from the data store
        const deleted = deleteBook(id);

        // Return 204 No Content for successful deletion
        res.status(204).send();
    } catch (error) {
        next(error);
    }
});

// Export the router to be used in the main app
module.exports = router;
