/**
 * Express application configuration.
 * 
 * WHY SEPARATE APP CONFIGURATION:
 * - Keeps server startup logic separate from app setup
 * - Makes it easy to test the app independently
 * - Allows for environment-specific configurations
 */

const express = require('express');
const bookRoutes = require('./routes/books');

// Create Express application instance
const app = express();

/**
 * Middleware configuration.
 * 
 * WHY MIDDLEWARE ORDER MATTERS:
 * - Body parsing must come before route handlers that read req.body
 * - Error handling middleware should be last to catch all errors
 * - Each middleware runs in sequence for every request
 */

// Parse JSON request bodies (required for POST/PUT requests)
app.use(express.json());

// Parse URL-encoded request bodies
app.use(express.urlencoded({ extended: true }));

/**
 * Logging middleware.
 * Prints each request method, URL, and timestamp to console.
 * Useful for debugging and monitoring API usage.
 */
app.use((req, res, next) => {
    const timestamp = new Date().toISOString();
    console.log(`[${timestamp}] ${req.method} ${req.url}`);
    next(); // Continue to the next middleware/route handler
});

/**
 * CORS middleware (simplified for educational purposes).
 * In production, you would use the 'cors' package with specific origins.
 */
app.use((req, res, next) => {
    res.header('Access-Control-Allow-Origin', '*');
    res.header('Access-Control-Allow-Headers', 'Origin, X-Requested-With, Content-Type, Accept');
    res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');

    // Handle preflight requests
    if (req.method === 'OPTIONS') {
        return res.sendStatus(200);
    }
    next();
});

// Mount book routes at /books endpoint
app.use('/books', bookRoutes);

/**
 * 404 handler for undefined routes.
 * Returns a proper JSON response instead of HTML error page.
 */
app.use((req, res, next) => {
    const error = new Error(`Route ${req.method} ${req.url} not found`);
    error.statusCode = 404;
    next(error);
});

/**
 * Global error-handling middleware.
 * Catches all errors and returns consistent JSON responses.
 * 
 * WHY ERROR HANDLING MIDDLEWARE:
 * - Centralized error handling prevents code duplication
 * - Ensures consistent error response format across the API
 * - Prevents sensitive error details from being exposed to clients
 * - Handles both synchronous and asynchronous errors
 */
app.use((error, req, res, next) => {
    const statusCode = error.statusCode || 500;
    const message = error.message || 'Internal server error';

    // Log the full error for debugging (not sent to client)
    console.error('Error:', error);

    // Return consistent JSON error response
    res.status(statusCode).json({
        success: false,
        error: {
            message,
            ...(error.fields && { fields: error.fields }),
            ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
        }
    });
});

// Export the app instance for testing and server startup
module.exports = app;
