```javascript
/**
 * ============================================================
 * MÓDULO: Store (Armazenamento em Memória)
 * ============================================================
 *
 * ESCOLHA DA ESTRUTURA DE DADOS:
 *
 * Por que usar um Array?
 * ----------------------
 * 1. SIMPLICIDADE EDUCACIONAL: Arrays são a estrutura mais
 *    intuitiva para demonstrar operações CRUD sem distrações.
 *
 * 2. ORDENANÇA PRESERVADA: A ordem de inserção é mantida, o que
 *    facilita o entendimento do fluxo de dados.
 *
 * 3. OPERAÇÕES SUFFICIENTES: Para uma API educacional com poucos
 *    registros, arrays oferecem performance aceitável para:
 *    - push() / splice() → O(1) / O(n)
 *    - findIndex()       → O(n) — aceitável para < 1000 itens
 *
 * POR QUE NÃO usar um Map ou objeto?
 * -----------------------------------
 * Um Map seria ideal para buscas por ID (O(1)), mas adiciona
 * complexidade desnecessária para este exemplo. Em produção,
 * substituiríamos por um banco de dados real (PostgreSQL, MongoDB).
 *
 * POR QUE NÃO usar JSON file-based?
 * ----------------------------------
 * Arquivos exigem operações síncronas de I/O ou callbacks extras.
 * Para manter o foco nos conceitos REST, usamos memória pura.
 */

/**
 * Array principal que armazena todos os livros.
 * Cada livro é um objeto com propriedades bem definidas.
 *
 * @type {Array<Object>}
 */
const books = [];

/**
 * Contador para gerar IDs únicos automaticamente.
 *
 * ESCOLHA: Usamos um contador simples em vez de UUIDs porque:
 * 1. IDs numéricos são mais legíveis e fáceis de testar.
 * 2. Evita dependências externas (como `uuid`).
 * 3. Para este exemplo educacional, colisão é impossível.
 *
 * Em produção, usaríamos UUID v4 ou snowflake IDs.
 *
 * @type {number}
 */
let nextId = 1;

/**
 * ============================================================
 * FUNÇÕES DO STORE
 * ============================================================
 */

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array<Object>} Cópia rasa do array de livros
 *   para evitar mutação externa acidental (imutabilidade defensiva).
 */
function getAllBooks() {
  return [...books]; // Spread operator cria uma cópia superficial
}

/**
 * Busca um livro pelo seu ID numérico.
 *
 * @param {number} id - O identificador único do livro.
 * @returns {Object|undefined} O livro encontrado ou undefined se não existir.
 *
 * Padrão adotado: `find()` em vez de `filter()[0]` porque:
 * - find() para no primeiro match (mais eficiente).
 * - Retorna undefined explicitamente quando não há match.
 */
function getBookById(id) {
  return books.find((book) => book.id === id);
}

/**
 * Cria um novo livro e o adiciona ao store.
 *
 * @param {Object} bookData - Dados do livro a ser criado.
 * @param {string} bookData.title - Título do livro (obrigatório).
 * @param {string} bookData.author - Autor do livro (obrigatório).
 * @param {string} [bookData.genre] - Gênero literário (opcional).
 * @param {number} [bookData.year] - Ano de publicação (opcional).
 * @returns {Object} O livro criado com ID atribuído automaticamente.
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++, // Incrementa APÓS a atribuição (pós-incremento)
    title: bookData.title,
    author: bookData.author,
    genre: bookData.genre || null, // Campo opcional com fallback
    year: bookData.year || null,   // Campo opcional com fallback
    createdAt: new Date().toISOString(), // Timestamp de criação (ISO 8601)
    updatedAt: new Date().toISOString(), // Timestamp de atualização
  };

  books.push(newBook); // O(1) — adiciona ao final do array
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a ser atualizado.
 * @param {Object} updates - Campos a serem atualizados (partial update).
 * @returns {Object|undefined} O livro atualizado ou undefined se não encontrado.
 *
 * Padrão adotado: Partial Update (PATCH semântico via PUT) porque:
 * - O cliente envia apenas os campos que deseja alterar.
 * - Usamos Object.assign para mesclar com os dados existentes.
 * - Em REST puro, PUT deveria substituir o recurso inteiro, mas
 *   partial updates são amplamente aceitos na prática.
 */
function updateBook(id, updates) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return undefined; // Livro não encontrado
  }

  // Mescla os dados existentes com as atualizações
  books[index] = {
    ...books[index], // Espalha campos existentes (imutabilidade parcial)
    ...updates,      // Sobrescreve com novos valores
    id: books[index].id, // Garante que o ID não seja sobrescrito
    createdAt: books[index].createdAt, // Preserva timestamp de criação
    updatedAt: new Date().toISOString(), // Atualiza timestamp
  };

  return books[index];
}

/**
 * Remove um livro do store pelo ID.
 *
 * @param {number} id - ID do livro a ser removido.
 * @returns {boolean} true se removido com sucesso, false caso contrário.
 *
 * Padrão adotado: splice() em vez de filter() porque:
 * - splice() modifica o array in-place (O(n) mas sem alocação extra).
 * - filter() criaria um novo array inteiro a cada remoção.
 * - Para arrays pequenos, a diferença é imperceptível.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === id);

  if (index === -1) {
    return false; // Livro não encontrado
  }

  books.splice(index, 1); // Remove 1 elemento na posição index
  return true;
}

/**
 * Calcula estatísticas agregadas sobre o catálogo de livros.
 *
 * @returns {Object} Estatísticas do catálogo.
 *
 * Estatísticas incluídas:
 * - totalBooks: quantidade total de livros.
 * - totalAuthors: quantidade de autores únicos (Set para deduplicação).
 * - avgYear: ano médio de publicação (null se sem livros).
 * - genres: contagem por gênero (Map convertido para objeto).
 */
function getStats() {
  const totalBooks = books.length;

  // Set para contar autores únicos — O(n) mas com deduplicação automática
  const uniqueAuthors = new Set(books.map((book) => book.author));

  // Ano médio: filtra livros com year definido antes de calcular
  const yearsWithData = books.filter((book) => book.year !== null);
  const avgYear =
    yearsWithData.length > 0
      ? yearsWithData.reduce((sum, book) => sum + book.year, 0) /
        yearsWithData.length
      : null;

  // Contagem por gênero usando reduce — O(n) single pass
  const genreCounts = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  return {
    totalBooks,
    totalAuthors: uniqueAuthors.size,
    avgYear: avgYear ? Math.round(avgYear * 100) / 100 : null, // 2 casas decimais
    genres: genreCounts,
  };
}

/**
 * ============================================================
 * EXPORTAÇÃO DE MÓDULO (CommonJS)
 * ============================================================
 *
 * Por que CommonJS (require/module.exports) em vez de ES Modules?
 * ---------------------------------------------------------------
 * 1. Express.js e a maioria das bibliotecas Node.js tradicionais
 *    usam CommonJS nativamente.
 * 2. Não requer configuração de babel ou flag --experimental-modules.
 * 3. Para este exemplo, a simplicidade do CommonJS é preferível.
 *
 * Em projetos modernos, ES Modules (import/export) são cada vez mais
 * comuns, mas CommonJS permanece como padrão da indústria para APIs
 * Express.js tradicionais.
 */
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
