```javascript
/**
 * ============================================================
 * MIDDLEWARE: Tratamento Centralizado de Erros
 * ============================================================
 *
 * CONCEITO DE MIDDLEWARE NO EXPRESS:
 * -----------------------------------
 * Middleware são funções que têm acesso ao objeto request,
 * response e ao próximo middleware da pilha (next). Eles podem:
 * 1. Executar código arbitrário.
 * 2. Modificar request/response.
 * 3. Encerrar o ciclo request-response.
 * 4. Chamar next() para passar a execução ao próximo middleware.
 *
 * POR QUE um middleware dedicado para erros?
 * -------------------------------------------
 * 1. CENTRALIZAÇÃO: Todo erro passa por um único ponto, facilitando
 *    logging, formatatação de resposta e manutenção.
 *
 * 2. SEPARAÇÃO DE RESPONSABILIDADES: Rotas não precisam lidar com
 *    formatação de erros — apenas lançam erros e o middleware trata.
 *
 * 3. PADRÃO EXPRESS: O Express identifica middlewares de erro pelo
 *    signature especial (err, req, res, next) — 4 parâmetros.
 *
 * CLASSES DE ERRO PERSONALIZADAS:
 * -------------------------------
 * Estendemos Error para criar subclasses que carregam informações
 * adicionais (statusCode, isOperational). Isso permite que o
 * middleware de erro tome decisões diferentes baseado no tipo.
 */

/**
 * Classe base para erros operacionais da aplicação.
 *
 * ERROS OPERACIONAIS vs ERROS NÃO-OPERACIONAIS:
 * ---------------------------------------------
 * - Operacionais: Erros esperados (recurso não encontrado, validação falha).
 *   Devem retornar 4xx e NÃO devem ser logados como bugs.
 *
 * - Não-operacionais: Bugs do servidor (variável indefinida, erro de banco).
 *   Devem retornar 500 e SER logados para investigação.
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro.
   * @param {number} statusCode - Código HTTP da resposta (padrão: 400).
   */
  constructor(message, statusCode = 400) {
    super(message); // Chama construtor da classe Error pai

    // Propriedades customizadas para o middleware de erro
    this.statusCode = statusCode;
    this.isOperational = true; // Indica que é um erro esperado

    // Mantém stack trace correto com class fields (Node.js >= 12)
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro para quando um recurso não é encontrado.
 * Mapeia para HTTP 404 Not Found.
 */
class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} não encontrado`, 404);
  }
}

/**
 * Erro para quando a entrada do cliente é inválida.
 * Mapeia para HTTP 400 Bad Request.
 */
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
  }
}

/**
 * Middleware de tratamento de erros.
 *
 * IMPORTANTE: Este middleware DEVE ser o último registrado no Express.
 * Ele captura erros lançados por middlewares e rotas anteriores.
 *
 * O Express diferencia middlewares de erro pela quantidade de parâmetros:
 * - Normal: (req, res, next) → 3 parâmetros
 * - Erro:   (err, req, res, next) → 4 parâmetros
 *
 * @param {Error} err - O objeto de erro lançado.
 * @param {Object} req - Objeto request do Express.
 * @param {Object} res - Objeto response do Express.
 * @param {Function} next - Função para o próximo middleware.
 */
function errorHandler(err, req, res, next) {
  // Define valores padrão caso propriedades não estejam presentes
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Erro interno do servidor';

  // Log apenas erros operacionais para depuração (não expor ao cliente)
  if (err.isOperational) {
    console.log(`[Operacional] ${statusCode} - ${message}`);
  } else {
    // Erros não-operacionais são bugs — log completo com stack trace
    console.error(`[BUG] ${statusCode} - ${message}`);
    console.error(err.stack);
  }

  // Resposta padronizada em JSON para todos os erros
  res.status(statusCode).json({
    success: false,
    error: {
      message,
      // Em produção, nunca exponha stack trace ao cliente (segurança)
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
    },
    // Timestamp para rastreamento
    timestamp: new Date().toISOString(),
  });
}

/**
 * Middleware de validação de campos obrigatórios.
 *
 * VERIFICAÇÃO DEFENSIVA: Em vez de confiar que o cliente enviará
 * todos os campos, validamos explicitamente antes de processar.
 *
 * @param {...string} fields - Nomes dos campos obrigatórios.
 * @returns {Function} Middleware Express.
 */
function validateRequired(...fields) {
  return (req, res, next) => {
    // Verifica se todos os campos obrigatórios estão presentes e não vazios
    const missing = fields.filter((field) => !req.body[field]);

    if (missing.length > 0) {
      // Lança ValidationError em vez de retornar diretamente — mantém o padrão
      return next(new ValidationError(`Campos obrigatórios ausentes: ${missing.join(', ')}`));
    }

    next(); // Campo válido — prossegue para a próxima função
  };
}

/**
 * Middleware para validar se o ID é um número inteiro positivo.
 *
 * PARÂMETROS DE ROTA: req.params são sempre strings no Express.
 * Precisamos converter e validar explicitamente.
 *
 * @returns {Function} Middleware Express.
 */
function validateIdParam(req, res, next) {
  const id = parseInt(req.params.id, 10); // Base 10 explícita para clareza

  if (isNaN(id) || id < 1) {
    return next(new ValidationError('ID deve ser um número inteiro positivo'));
  }

  // Anexa o ID convertido ao request para uso nas rotas
  req.validatedId = id;
  next();
}

/**
 * ============================================================
 * EXPORTAÇÕES
 * ============================================================
 */
module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  errorHandler,
  validateRequired,
  validateIdParam,
};
