/**
 * ============================================================
 * ROTA: Gerenciamento de Livros (CRUD Completo)
 * ============================================================
 *
 * PADRÕES REST ADOPTADOS:
 * -----------------------
 * 1. NOMENCLATURA DE ENDPOINTS: Usamos substantivos no plural (/books)
 *    em vez de verbos (/getBooks, /createBook). Isso segue a convenção
 *    HTTP de que o método (GET/POST/PUT/DELETE) já indica a ação.
 *
 * 2. SEMÂNTICA HTTP:
 *    - GET     → Busca/leitura (side-effect free)
 *    - POST    → Criação (retorna 201 + Location header)
 *    - PUT     → Atualização completa ou parcial
 *    - DELETE  → Remoção (retorna 204 sem body)
 *
 * 3. CODES DE STATUS:
 *    - 200 OK      → Sucesso em leitura/atualização
 *    - 201 Created → Recurso criado com sucesso
 *    - 204 No Content → Sucesso sem conteúdo de resposta (deleção)
 *    - 400 Bad Request   → Entrada inválida
 *    - 404 Not Found     → Recurso inexistente
 *    - 500 Internal Error → Erro inesperado do servidor
 *
 * 4. FORMATO DE RESPOSTA: JSON com campo "success" para consistência.
 *
 * ASSINCRONIA (async/await):
 * --------------------------
 * Embora o store atual seja síncrono, definimos as rotas como async
 * porque em produção substituiremos o store por chamadas a banco de
 * dados que são assíncronas. Manter async desde o início evita refatoração.
 */

const express = require('express');
const router = express.Router(); // Cria um roteador independente

// Importa funções do store (camada de dados)
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
} = require('../data/store');

// Importa classes e middlewares de erro
const { NotFoundError, ValidationError, validateIdParam } = require('../middleware/error-handler');

/**
 * ============================================================
 * GET /books
 * ============================================================
 * Lista todos os livros com suporte a filtragem opcional.
 *
 * PARÂMETROS DE QUERY (req.query):
 * ---------------------------------
 * - author: Filtra por autor (case-insensitive parcial)
 * - genre:  Filtra por gênero
 * - minYear: Ano mínimo de publicação
 * - maxYear: Ano máximo de publicação
 *
 * EXEMPLOS DE USO:
 * ----------------
 * # Listar todos os livros
 * curl http://localhost:3000/books
 *
 * # Filtrar por autor
 * curl "http://localhost:3000/books?author=tolkien"
 *
 * # Filtrar por gênero e faixa de ano
 * curl "http://localhost:3000/books?genre=ficcao&minYear=1950&maxYear=2000"
 *
 * RESPOSTA: 200 OK com array de livros
 */
router.get('/books', async (req, res, next) => {
  try {
    let result = getAllBooks();

    // Filtragem por autor (busca parcial, case-insensitive)
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter((book) =>
        book.author.toLowerCase().includes(authorFilter)
      );
    }

    // Filtragem exata por gênero
    if (req.query.genre) {
      const genreFilter = req.query.genre.toLowerCase();
      result = result.filter(
        (book) => book.genre && book.genre.toLowerCase() === genreFilter
      );
    }

    // Filtragem por faixa de ano
    if (req.query.minYear) {
      const minYear = parseInt(req.query.minYear, 10);
      result = result.filter((book) => book.year >= minYear);
    }

    if (req.query.maxYear) {
      const maxYear = parseInt(req.query.maxYear, 10);
      result = result.filter((book) => book.year <= maxYear);
    }

    // Resposta padronizada com metadados de paginação (preparação para futuro)
    res.status(200).json({
      success: true,
      count: result.length,
      data: result,
      // Metadados de filtragem aplicada (útil para debugging)
      filters: req.query.author ? { author: req.query.author } : {},
    });
  } catch (error) {
    next(error); // Passa erro ao middleware de tratamento
  }
});

/**
 * ============================================================
 * GET /books/:id
 * ============================================================
 * Busca um livro específico pelo ID.
 *
 * PARÂMETROS DE ROTA (req.params):
 * ---------------------------------
 * - id: Identificador numérico do livro
 *
 * EXEMPLOS DE USO:
 * ----------------
 * # Obter livro com ID 1
 * curl http://localhost:3000/books/1
 *
 * # Tentar obter livro inexistente (retorna 404)
 * curl http://localhost:3000/books/999
 *
 * RESPOSTA: 200 OK com objeto do livro
 */
router.get('/books/:id', validateIdParam, async (req, res, next) => {
  try {
    const book = getBookById(req.validatedId);

    if (!book) {
      // Lança NotFoundError em vez de retornar diretamente — mantém o padrão
      return next(new NotFoundError('Livro'));
    }

    res.status(200).json({
      success: true,
      data: book,
    });
  } catch (error) {
    next(error);
  }
});

/**
 * ============================================================
 * POST /books
 * ============================================================
 * Cria um novo livro no catálogo.
 *
 * CORPO DA REQUISIÇÃO (req.body):
 * --------------------------------
 * {
 *   "title": "O Senhor dos Anéis",    // obrigatório
 *   "author": "J.R.R. Tolkien",       // obrigatório
 *   "genre": "fantasia",              // opcional
 *   "year": 1954                      // opcional
 * }
 *
 * EXEMPLOS DE USO:
 * ----------------
 * # Criar livro com todos os campos
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"1984","author":"George Orwell","genre":"ficcao","year":1949}'
 *
 * # Criar livro com campos mínimos (apenas título e autor)
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Dom Casmurro","author":"Machado de Assis"}'
 *
 * RESPOSTA: 201 Created com o livro criado + header Location
 */
router.post('/books', validateRequired('title', 'author'), async (req, res, next) => {
  try {
    const newBook = createBook(req.body);

    // 201 Created indica que um novo recurso foi criado
    // Location header aponta para o URI do recurso criado (convenção REST)
    res.status(201).json({
      success: true,
      data: newBook,
      message: 'Livro criado com sucesso',
    });
  } catch (error) {
    next(error);
  }
});

/**
 * ============================================================
 * PUT /books/:id
 * ============================================================
 * Atualiza um livro existente. Suporta atualização parcial.
 *
 * CORPO DA REQUISIÇÃO:
 * --------------------
 * Campos opcionais para atualizar: title, author, genre, year
 *
 * EXEMPLOS DE USO:
 * ----------------
 * # Atualizar todos os campos
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Novo Título","author":"Novo Autor"}'
 *
 * # Atualizar apenas o gênero (partial update)
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"genre":"romance"}'
 *
 * RESPOSTA: 200 OK com o livro atualizado
 */
router.put('/books/:id', validateIdParam, async (req, res, next) => {
  try {
    const updatedBook = updateBook(req.validatedId, req.body);

    if (!updatedBook) {
      return next(new NotFoundError('Livro'));
    }

    res.status(200).json({
      success: true,
      data: updatedBook,
      message: 'Livro atualizado com sucesso',
    });
  } catch (error) {
    next(error);
  }
});

/**
 * ============================================================
 * DELETE /books/:id
 * ============================================================
 * Remove um livro do catálogo.
 *
 * EXEMPLOS DE USO:
 * ----------------
 * # Deletar livro com ID 1
 * curl -X DELETE http://localhost:3000/books/1
 *
 * # Tentar deletar livro inexistente (retorna 404)
 * curl -X DELETE http://localhost:3000/books/999
 *
 * RESPOSTA: 204 No Content (padrão REST para deleção bem-sucedida)
 */
router.delete('/books/:id', validateIdParam, async (req, res, next) => {
  try {
    const deleted = deleteBook(req.validatedId);

    if (!deleted) {
      return next(new NotFoundError('Livro'));
    }

    // 204 No Content: sucesso sem corpo de resposta
    // Isso é mais eficiente (sem bytes desnecessários) e segue a convenção REST
    res.status(204).send();
  } catch (error) {
    next(error);
  }
});

/**
 * ============================================================
 * GET /stats
 * ============================================================
 * Retorna estatísticas agregadas do catálogo de livros.
 *
 * EXEMPLOS DE USO:
 * ----------------
 * curl http://localhost:3000/stats
 *
 * RESPOSTA: 200 OK com objeto de estatísticas
 */
router.get('/stats', async (req, res, next) => {
  try {
    const stats = getStats();

    res.status(200).json({
      success: true,
      data: stats,
    });
  } catch (error) {
    next(error);
  }
});

/**
 * ============================================================
 * EXPORTAÇÃO DO ROTEADOR
 * ============================================================
 *
 * Por que exportamos o router e não as rotas diretamente?
 * -------------------------------------------------------
 * O Express Router é um middleware encapsulado. Ao exportá-lo,
 * podemos registrá-lo em app.js com um prefixo opcional:
 *   app.use('/api', bookRoutes);
 *
 * Isso permite montar APIs compostas (várias routers) sem
 * duplicação de lógica de prefixo.
 */
module.exports = router;
