## Arquivo 5: `src/app.js`

```javascript
/**
 * ============================================================
 * CONFIGURAÇÃO DA APLICAÇÃO EXPRESS
 * ============================================================
 *
 * POR QUE separar app.js do index.js?
 * ------------------------------------
 * - app.js configura o Express (middlewares, rotas, error handling).
 * - index.js apenas inicia o servidor na porta.
 *
 * Essa separação permite:
 * 1. Testes unitários do app sem precisar iniciar o servidor.
 * 2. Reutilização da configuração em diferentes ambientes.
 * 3. Código mais organizado e manutenível.
 */

const express = require('express');

// Middleware para parsear JSON no corpo das requisições
// Sem isso, req.body seria undefined em POST/PUT
const bodyParser = require('express').json();

// Importa o roteador de livros
const bookRoutes = require('./routes/books');

// Importa middleware de tratamento de erros
const { errorHandler } = require('./middleware/error-handler');

/**
 * Cria e configura a instância do aplicativo Express.
 *
 * @returns {Object} Instância configurada do Express app.
 */
function createApp() {
  const app = express();

  /**
   * ============================================================
   * MIDDLEWARE GLOBAL
   * ============================================================
   */

  // Log de cada requisição (padrão comum em desenvolvimento)
  app.use((req, res, next) => {
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
    next();
  });

  // Parseia JSON do corpo — necessário para POST/PUT com body
  app.use(bodyParser);

  /**
   * ============================================================
   * ROTAS
   * ============================================================
   *
   * POR QUE registrar rotas ANTES do middleware de erro?
   * ---------------------------------------------------
   * O Express executa middlewares na ordem em que são registrados.
   * Se o errorHandler fosse registrado antes das rotas, ele capturaria
   * erros de "rota não encontrada" antes que o Express pudesse
   * gerar sua própria resposta 404.
   */

  // Registra as rotas de livros no caminho base /
  // Em produção, usaríamos: app.use('/api/v1', bookRoutes)
  app.use('/', bookRoutes);

  /**
   * ============================================================
   * ROTA 404 PARA RECURSOS NÃO ENCONTRADOS
   * ============================================================
   *
   * Esta rota captura qualquer requisição que não corresponda
   * a nenhuma rota definida acima. É um "catch-all" para URLs
   * inválidas ou métodos não permitidos.
   */
  app.use((req, res, next) => {
    const { AppError } = require('./middleware/error-handler');
    next(new AppError(`Rota ${req.method} ${req.url} não encontrada`, 404));
  });

  /**
   * ============================================================
   * MIDDLEWARE DE TRATAMENTO DE ERROS (SEMPRE POR ÚLTIMO)
   * ============================================================
   *
   * IMPORTANTE: Deve ser o ÚLTIMO middleware registrado.
   * O Express só encaminha erros para middlewares de erro se
   * houver 4 parâmetros na função (err, req, res, next).
   */
  app.use(errorHandler);

  return app;
}

module.exports = createApp;
```

