## File 2: `src/models/book.js`

```javascript
/**
 * ============================================================================
 * BOOK MODEL — Data Structure Definition
 * ============================================================================
 *
 * WHY AN IN-MEMORY ARRAY?
 * -----------------------
 * For an educational example, an in-memory array is ideal because:
 *   1. Zero setup — no database installation required.
 *   2. Instant feedback — changes are visible immediately on next request.
 *   3. Easy to inspect — you can log the entire state at any time.
 *
 * WHY NOT A SINGLE OBJECT PER BOOK?
 * ---------------------------------
 * Each book is a plain JavaScript object with clearly typed fields:
 *   - id (number): Unique identifier, auto-incremented.
 *   - title (string): The book's title. Required.
 *   - author (string): The book's author. Required.
 *   - genre (string): Category like "Fiction", "Science", etc. Optional.
 *   - publishedYear (number): Year the book was published. Optional.
 *   - createdAt (string): ISO timestamp of creation. Set automatically.
 *   - updatedAt (string): ISO timestamp of last modification. Updated on PUT.
 *
 * WHY AUTO-INCREMENTING IDs?
 * --------------------------
 * Simple and predictable for a demo. In production, you'd use UUIDs or
 * database-generated IDs to avoid collisions across distributed systems.
 */

// ---------------------------------------------------------------------------
// State: The in-memory "database" — an array of book objects.
// We use 'let' so we can reassign it (e.g., for reset operations).
// ---------------------------------------------------------------------------
let books = [
  {
    id: 1,
    title: "To Kill a Mockingbird",
    author: "Harper Lee",
    genre: "Fiction",
    publishedYear: 1960,
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z"
  },
  {
    id: 2,
    title: "A Brief History of Time",
    author: "Stephen Hawking",
    genre: "Science",
    publishedYear: 1988,
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z"
  },
  {
    id: 3,
    title: "The Great Gatsby",
    author: "F. Scott Fitzgerald",
    genre: "Fiction",
    publishedYear: 1925,
    createdAt: "2024-01-01T00:00:00.000Z",
    updatedAt: "2024-01-01T00:00:00.000Z"
  }
];

// ---------------------------------------------------------------------------
// Next ID tracker — keeps incrementing so deleted IDs never get reused.
// This prevents accidental collisions if two books happen to share an ID.
// ---------------------------------------------------------------------------
let nextId = 4;

/**
 * Returns a copy of the entire books array.
 * We return a shallow copy (slice) to prevent external code from mutating
 * the internal state directly — a form of encapsulation.
 *
 * @returns {Array<Object>} A shallow copy of all books.
 */
function getAllBooks() {
  return books.slice(); // slice() without args returns a shallow copy
}

/**
 * Finds a single book by its numeric ID.
 *
 * @param {number} id - The unique identifier of the book.
 * @returns {Object|undefined} The book object if found, otherwise undefined.
 */
function getBookById(id) {
  return books.find(book => book.id === id);
}

/**
 * Inserts a new book into the array and assigns it the next available ID.
 *
 * @param {Object} bookData - The book data to insert (without id, createdAt, updatedAt).
 * @returns {Object} The newly created book with generated fields.
 */
function createBook(bookData) {
  const newBook = {
    id: nextId++,                    // Assign and increment in one step
    ...bookData,                     // Spread the provided data
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
  books.push(newBook);               // Add to the end of the array
  return newBook;
}

/**
 * Updates an existing book by ID with the provided fields.
 * Only the fields present in updateData will be changed (partial update).
 * The updatedAt timestamp is always refreshed.
 *
 * @param {number} id - The ID of the book to update.
 * @param {Object} updateData - Fields to update (title, author, genre, publishedYear).
 * @returns {Object|undefined} The updated book, or undefined if not found.
 */
function updateBook(id, updateData) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return undefined; // Book not found

  // Merge: keep existing fields, override with provided ones
  books[index] = {
    ...books[index],                   // Start with current state
    ...updateData,                     // Overlay new values
    id,                                // Ensure ID never changes
    updatedAt: new Date().toISOString() // Refresh the timestamp
  };

  return books[index];
}

/**
 * Deletes a book by its ID.
 *
 * @param {number} id - The ID of the book to delete.
 * @returns {boolean} True if the book was found and deleted, false otherwise.
 */
function deleteBook(id) {
  const index = books.findIndex(book => book.id === id);
  if (index === -1) return false;

  books.splice(index, 1); // Remove exactly one element at the given index
  return true;
}

/**
 * Resets the entire books array to an empty state and resets nextId.
 * Useful for testing — call this between test suites.
 */
function resetBooks() {
  books = [];
  nextId = 1;
}

// ---------------------------------------------------------------------------
// Export all functions as a module.
// We use named exports so consumers can pick exactly what they need.
// ---------------------------------------------------------------------------
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  resetBooks
};
```

> **Key design decisions:**
> - `slice()` for copying prevents callers from mutating the internal array directly.
> - `nextId` is a module-level variable — it persists across requests but resets when the server restarts (acceptable for an in-memory demo).
> - `updateBook` does a *partial* update: only fields you send get changed, everything else stays intact.

