## File 3: `src/middleware/errorHandler.js`

```javascript
/**
 * ============================================================================
 * ERROR HANDLING MIDDLEWARE
 * ============================================================================
 *
 * WHY CUSTOM ERROR CLASSES?
 * -------------------------
 * Custom error classes let us attach extra properties (like statusCode) and
 * distinguish between different error types in our middleware. This is cleaner
 * than checking error messages as strings.
 *
 * WHY A CENTRAL ERROR HANDLER?
 * ----------------------------
 * Express supports a special 4-argument middleware function:
 *   (err, req, res, next) => { ... }
 * When ANY route or middleware calls `next(err)`, Express skips all remaining
 * normal middleware and jumps to this handler. This means we never need to
 * repeat error-response logic in every route.
 *
 * WHY RETURN JSON FOR ALL ERRORS?
 * -------------------------------
 * Consistent error responses make the API predictable for consumers:
 *   { "error": "message", "statusCode": 400 }
 */

// ---------------------------------------------------------------------------
// Custom Error Class: AppError
// Extends the built-in Error so we get a proper stack trace, but adds a
// statusCode property that our middleware reads to set the HTTP response code.
// ---------------------------------------------------------------------------
class AppError extends Error {
  /**
   * @param {string} message - Human-readable error description.
   * @param {number} statusCode - HTTP status code (default: 400 Bad Request).
   */
  constructor(message, statusCode = 400) {
    super(message); // Call the parent Error constructor with our message
    this.statusCode = statusCode; // Attach the HTTP status code

    // Capture a clean stack trace (without the constructor frames)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }
}

// ---------------------------------------------------------------------------
// Validation Error — thrown when client input fails validation.
// Inherits from AppError with a default 400 status.
// ---------------------------------------------------------------------------
class ValidationError extends AppError {
  constructor(message) {
    super(message, 400); // 400 = Bad Request (client sent invalid data)
  }
}

// ---------------------------------------------------------------------------
// Not Found Error — thrown when a requested resource doesn't exist.
// Inherits from AppError with a default 404 status.
// ---------------------------------------------------------------------------
class NotFoundError extends AppError {
  constructor(message) {
    super(message, 404); // 404 = Not Found
  }
}

// ---------------------------------------------------------------------------
// Central Error-Handling Middleware
// This is the "catch-all" for any error that calls next(err).
// It must have exactly 4 parameters (err, req, res, next) — Express detects
// this signature automatically and routes errors here.
// ---------------------------------------------------------------------------
function errorHandler(err, req, res, next) {
  // Log the full error details to the server console for debugging.
  // In production, you'd send this to a logging service (e.g., Winston, Datadog).
  console.error(`[ERROR] ${new Date().toISOString()} —`, err.message);
  console.error(err.stack); // Print the stack trace for debugging

  // Determine the status code: use err.statusCode if set, otherwise default to 500.
  const statusCode = err.statusCode || 500;

  // Build a consistent JSON error response body.
  const responseBody = {
    error: err.message,           // What went wrong
    statusCode                      // The HTTP status code for programmatic handling
  };

  // Send the JSON response with the appropriate status code.
  res.status(statusCode).json(responseBody);
}

// ---------------------------------------------------------------------------
// 404 Fallback Middleware
// If a request hits a route that doesn't exist, Express won't call next(err)
// automatically. This middleware catches unmatched routes and returns a 404.
// It must be registered AFTER all route definitions.
// ---------------------------------------------------------------------------
function notFoundHandler(req, res, next) {
  // Create a NotFoundError and pass it to next() so the errorHandler handles it.
  next(new NotFoundError(`Route ${req.method} ${req.originalUrl} not found`));
}

// ---------------------------------------------------------------------------
// Export everything for use in app.js
// ---------------------------------------------------------------------------
module.exports = {
  AppError,
  ValidationError,
  NotFoundError,
  errorHandler,
  notFoundHandler
};
```

> **Why this pattern?** The `next(err)` convention is Express's built-in error propagation mechanism. By throwing/calling `next` with an error object instead of calling `res.send()` directly in every route, we keep our routes clean and our error handling centralized. The 404 fallback middleware is essential because unmatched routes don't trigger errors on their own — they just fall through to the end of the middleware chain silently.

