## File 4: `src/services/bookService.js`

```javascript
/**
 * ============================================================================
 * BOOK SERVICE — Business Logic Layer
 * ============================================================================
 *
 * WHY A SEPARATE SERVICE LAYER?
 * ------------------------------
 * Separating business logic from route handlers gives us several benefits:
 *   1. Routes stay thin and focused on HTTP concerns (parsing, responding).
 *   2. Services can be unit-tested independently of Express/HTTP.
 *   3. If we swap the data layer (e.g., in-memory → PostgreSQL), only this
 *      file and the model need to change — routes stay the same.
 *
 * WHY VALIDATE IN THE SERVICE, NOT THE ROUTE?
 * --------------------------------------------
 * Validation is business logic, not HTTP logic. By putting it here, we ensure
 * that validation runs regardless of how the data enters the system (API,
 * background job, admin panel, etc.).
 */

const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook
} = require('../models/book');

// ---------------------------------------------------------------------------
// GET /books — List all books with optional filtering
//
// Query parameters supported:
//   - genre    : Filter by exact genre match (e.g., ?genre=Fiction)
//   - author   : Filter by author name substring (case-insensitive)
//   - minYear  : Minimum published year (inclusive)
//   - maxYear  : Maximum published year (inclusive)
// ---------------------------------------------------------------------------

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * @param {Object} filters - Optional filter criteria from req.query.
 * @param {string} [filters.genre] - Exact genre match.
 * @param {string} [filters.author] - Substring match on author name (case-insensitive).
 * @param {number} [filters.minYear] - Minimum published year (inclusive).
 * @param {number} [filters.maxYear] - Maximum published year (inclusive).
 * @returns {Array<Object>} Filtered list of books.
 */
function getBooks(filters = {}) {
  let result = getAllBooks(); // Start with the full dataset

  // Apply genre filter if provided — exact match, case-sensitive.
  if (filters.genre) {
    result = result.filter(book => book.genre === filters.genre);
  }

  // Apply author filter if provided — substring match, case-insensitive.
  // This lets users search "hawking" and find "Stephen Hawking".
  if (filters.author) {
    const authorLower = filters.author.toLowerCase();
    result = result.filter(book =>
      book.author.toLowerCase().includes(authorLower)
    );
  }

  // Apply minimum year filter if provided.
  if (filters.minYear !== undefined) {
    result = result.filter(book => book.publishedYear >= Number(filters.minYear));
  }

  // Apply maximum year filter if provided.
  if (filters.maxYear !== undefined) {
    result = result.filter(book => book.publishedYear <= Number(filters.maxYear));
  }

  return result;
}

// ---------------------------------------------------------------------------
// GET /books/:id — Get a single book by ID
// ---------------------------------------------------------------------------

/**
 * Retrieves a single book by its numeric ID.
 *
 * @param {number} id - The unique identifier of the book.
 * @returns {Object} The book object.
 * @throws {NotFoundError} If no book with the given ID exists.
 */
function getBook(id) {
  const book = getBookById(id);
  if (!book) {
    // Throw a NotFoundError so Express routes can catch it and return 404.
    throw new (require('../middleware/errorHandler').NotFoundError)(
      `Book with id ${id} not found`
    );
  }
  return book;
}

// ---------------------------------------------------------------------------
// POST /books — Create a new book
// ---------------------------------------------------------------------------

/**
 * Creates a new book after validating the required fields.
 *
 * @param {Object} bookData - The book data from the request body.
 * @param {string} bookData.title - The title of the book (required, non-empty).
 * @param {string} bookData.author - The author of the book (required, non-empty).
 * @param {string} [bookData.genre] - The genre/category of the book.
 * @param {number} [bookData.publishedYear] - The year the book was published.
 * @returns {Object} The newly created book with generated id and timestamps.
 * @throws {ValidationError} If title or author is missing or empty.
 */
function createNewBook(bookData) {
  // Validate that title is present and not just whitespace.
  if (!bookData.title || bookData.title.trim() === '') {
    throw new (require('../middleware/errorHandler').ValidationError)(
      'Title is required'
    );
  }

  // Validate that author is present and not just whitespace.
  if (!bookData.author || bookData.author.trim() === '') {
    throw new (require('../middleware/errorHandler').ValidationError)(
      'Author is required'
    );
  }

  // publishedYear, if provided, must be a positive integer.
  if (bookData.publishedYear !== undefined) {
    const year = Number(bookData.publishedYear);
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      throw new (require('../middleware/errorHandler').ValidationError)(
        'publishedYear must be a valid year between 0 and the current year'
      );
    }
  }

  // Delegate to the model layer — the service handles validation,
  // the model handles persistence. This separation is key to testability.
  return createBook({
    title: bookData.title.trim(),       // Trim whitespace from inputs
    author: bookData.author.trim(),
    genre: bookData.genre ? bookData.genre.trim() : undefined,
    publishedYear: bookData.publishedYear
  });
}

// ---------------------------------------------------------------------------
// PUT /books/:id — Update an existing book
// ---------------------------------------------------------------------------

/**
 * Updates an existing book by ID with partial data.
 * Only provided fields are updated; missing fields retain their current values.
 *
 * @param {number} id - The unique identifier of the book to update.
 * @param {Object} updateData - Fields to update (any subset of title, author, genre, publishedYear).
 * @returns {Object} The updated book object.
 * @throws {NotFoundError} If no book with the given ID exists.
 * @throws {ValidationError} If validation fails on provided fields.
 */
function updateExistingBook(id, updateData) {
  // First, verify the book exists — we need its current data for merging.
  const existingBook = getBookById(id);
  if (!existingBook) {
    throw new (require('../middleware/errorHandler').NotFoundError)(
      `Book with id ${id} not found`
    );
  }

  // Validate title if it's being updated.
  if (updateData.title !== undefined) {
    if (typeof updateData.title !== 'string' || updateData.title.trim() === '') {
      throw new (require('../middleware/errorHandler').ValidationError)(
        'Title must be a non-empty string'
      );
    }
  }

  // Validate author if it's being updated.
  if (updateData.author !== undefined) {
    if (typeof updateData.author !== 'string' || updateData.author.trim() === '') {
      throw new (require('../middleware/errorHandler').ValidationError)(
        'Author must be a non-empty string'
      );
    }
  }

  // Validate publishedYear if it's being updated.
  if (updateData.publishedYear !== undefined) {
    const year = Number(updateData.publishedYear);
    if (!Number.isInteger(year) || year < 0 || year > new Date().getFullYear() + 1) {
      throw new (require('../middleware/errorHandler').ValidationError)(
        'publishedYear must be a valid year between 0 and the current year'
      );
    }
  }

  // Delegate to the model layer for the actual update.
  return updateBook(id, updateData);
}

// ---------------------------------------------------------------------------
// DELETE /books/:id — Delete a book
// ---------------------------------------------------------------------------

/**
 * Deletes a book by its ID.
 *
 * @param {number} id - The unique identifier of the book to delete.
 * @returns {boolean} True if the book was deleted, false otherwise.
 * @throws {NotFoundError} If no book with the given ID exists.
 */
function deleteExistingBook(id) {
  const existingBook = getBookById(id);
  if (!existingBook) {
    throw new (require('../middleware/errorHandler').NotFoundError)(
      `Book with id ${id} not found`
    );
  }

  return deleteBook(id);
}

// ---------------------------------------------------------------------------
// GET /stats — Return statistics about the book collection
// ---------------------------------------------------------------------------

/**
 * Computes and returns aggregate statistics about the book collection.
 *
 * Statistics include:
 *   - totalBooks: Total number of books in the collection.
 *   - averagePublishedYear: Mean publication year (rounded to 2 decimals).
 *   - genres: An object mapping each genre to its book count.
 *   - authors: A sorted array of unique author names.
 *
 * @returns {Object} Statistics object with aggregate data.
 */
function getStats() {
  const allBooks = getAllBooks();

  // Compute total number of books.
  const totalBooks = allBooks.length;

  // Compute average published year, or null if there are no books.
  let averagePublishedYear = null;
  if (totalBooks > 0) {
    const sumOfYears = allBooks.reduce(
      (sum, book) => sum + (book.publishedYear || 0),
      0
    );
    averagePublishedYear = Math.round((sumOfYears / totalBooks) * 100) / 100;
  }

  // Count books per genre using a reduce accumulator.
  const genres = allBooks.reduce((acc, book) => {
    const genre = book.genre || 'Unknown'; // Treat missing genre as "Unknown"
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Extract unique author names and sort alphabetically.
  const authors = [...new Set(allBooks.map(book => book.author))].sort();

  return {
    totalBooks,
    averagePublishedYear,
    genres,
    authors
  };
}

// ---------------------------------------------------------------------------
// Export all service functions for use in route handlers.
// ---------------------------------------------------------------------------
module.exports = {
  getBooks,
  getBook,
  createNewBook,
  updateExistingBook,
  deleteExistingBook,
  getStats
};
```

> **Why separate validation from persistence?** The service layer is where business rules live. If we validated inside the route handler, we'd duplicate that logic every time we called `createBook` from elsewhere (e.g., a background job). By keeping validation in the service, we guarantee it runs consistently no matter the entry point.

