/**
 * ============================================================================
 * BOOK ROUTES — HTTP Layer for Book CRUD Operations
 * ============================================================================
 *
 * WHY SEPARATE ROUTE FILES?
 * -------------------------
 * As the API grows, keeping all routes in one file becomes unwieldy.
 * Splitting by resource (books.js, stats.js) makes it easy to find and
 * modify individual endpoints without scrolling through hundreds of lines.
 *
 * WHY USE express.Router()?
 * -------------------------
 * Router instances let us:
 *   1. Group related routes together.
 *   2. Apply route-specific middleware (e.g., auth checks for certain paths).
 *   3. Mount the router at a path prefix (app.use('/books', bookRoutes)).
 * This is cleaner than repeating '/books' on every route definition.
 *
 * WHY ASYNC/AWAIT?
 * ----------------
 * While our current operations are synchronous (in-memory), we write routes
 * with async/await so they're ready for when we swap in an async database.
 * The try/catch pattern also ensures any thrown errors are caught and passed
 * to Express's error handler via next(err).
 */

const express = require('express');
const router = express.Router(); // Create a standalone router instance

// Import the service layer — routes delegate to services, not models directly.
const {
  getBooks,
  getBook,
  createNewBook,
  updateExistingBook,
  deleteExistingBook
} = require('../services/bookService');

// ---------------------------------------------------------------------------
// GET /books
// List all books with optional filtering via query parameters.
//
// Examples:
//   GET /books                          → All books
//   GET /books?genre=Fiction            → Only Fiction books
//   GET /books?author=hawking           → Books by authors containing "hawking"
//   GET /books?minYear=1950&maxYear=2000 → Books published between 1950-2000
//   GET /books?genre=Fiction&minYear=1900 → Combined filters (AND logic)
// ---------------------------------------------------------------------------

/**
 * @route   GET /books
 * @desc    Retrieve all books with optional filtering
 * @access  Public
 * @query   {string} [genre]     - Filter by exact genre match
 * @query   {string} [author]    - Filter by author name substring (case-insensitive)
 * @query   {number} [minYear]   - Minimum published year (inclusive)
 * @query   {number} [maxYear]   - Maximum published year (inclusive)
 * @returns {Array<Object>} Array of book objects
 */
router.get('/', (req, res, next) => {
  try {
    // Extract filter parameters from the query string.
    // req.query is an object like { genre: 'Fiction', minYear: '1950' }.
    const filters = {
      genre: req.query.genre,
      author: req.query.author,
      minYear: req.query.minYear ? Number(req.query.minYear) : undefined,
      maxYear: req.query.maxYear ? Number(req.query.maxYear) : undefined
    };

    // Call the service layer to handle filtering logic.
    const books = getBooks(filters);

    // Send a 200 OK with the JSON response.
    res.json({
      success: true,
      count: books.length,           // Include count for easy pagination later
      data: books
    });
  } catch (error) {
    // Pass any errors to Express's centralized error handler.
    next(error);
  }
});

// ---------------------------------------------------------------------------
// GET /books/:id
// Retrieve a single book by its numeric ID.
//
// Examples:
//   GET /books/1        → Book with id 1
//   GET /books/999      → 404 Not Found (if id 999 doesn't exist)
// ---------------------------------------------------------------------------

/**
 * @route   GET /books/:id
 * @desc    Retrieve a single book by ID
 * @access  Public
 * @param   {number} id - Book ID
 * @returns {Object} Single book object
 */
router.get('/:id', (req, res, next) => {
  try {
    // Convert the URL parameter to a number.
    // Express gives us strings from :params, so we must parse.
    const id = Number(req.params.id);

    // Validate that the ID is actually a valid number.
    if (isNaN(id)) {
      throw new Error('Invalid book ID');
    }

    // Delegate to the service layer — it handles existence checks and validation.
    const book = getBook(id);

    res.json({
      success: true,
      data: book
    });
  } catch (error) {
    next(error); // Pass to centralized error handler
  }
});

// ---------------------------------------------------------------------------
// POST /books
// Create a new book. The request body must contain at minimum `title` and `author`.
//
// Example request body:
//   { "title": "1984", "author": "George Orwell", "genre": "Dystopian", "publishedYear": 1949 }
//
// curl example:
//   curl -X POST http://localhost:3000/books \
//        -H "Content-Type: application/json" \
//        -d '{"title":"1984","author":"George Orwell","genre":"Dystopian","publishedYear":1949}'
// ---------------------------------------------------------------------------

/**
 * @route   POST /books
 * @desc    Create a new book
 * @access  Public
 * @body    {string} title        - Book title (required)
 * @body    {string} author       - Book author (required)
 * @body    {string} [genre]      - Book genre/category
 * @body    {number} [publishedYear] - Year published
 * @returns {Object} The newly created book
 */
router.post('/', (req, res, next) => {
  try {
    // Express's built-in json middleware parses the request body into req.body.
    // If Content-Type is not application/json, req.body will be undefined.
    const bookData = req.body;

    // Basic sanity check: ensure the body exists and is an object.
    if (!bookData || typeof bookData !== 'object') {
      throw new Error('Request body must be a JSON object');
    }

    // Delegate to the service layer — it handles all validation.
    const newBook = createNewBook(bookData);

    // 201 Created is the standard status for successful resource creation.
    // We also set Location header so clients know where to find the new resource.
    res.status(201).json({
      success: true,
      data: newBook
    });
  } catch (error) {
    next(error);
  }
});

// ---------------------------------------------------------------------------
// PUT /books/:id
// Update an existing book with partial or full data.
// Only provided fields are updated; missing fields retain their values.
//
// Example request body:
//   { "title": "1984 (Updated Edition)" }
//
// curl example:
//   curl -X PUT http://localhost:3000/books/1 \
//        -H "Content-Type: application/json" \
//        -d '{"title":"To Kill a Mockingbird (Special Edition)"}'
// ---------------------------------------------------------------------------

/**
 * @route   PUT /books/:id
 * @desc    Update an existing book
 * @access  Public
 * @param   {number} id          - Book ID
 * @body    {string} [title]     - New title
 * @body    {string} [author]    - New author
 * @body    {string} [genre]     - New genre
 * @body    {number} [publishedYear] - New published year
 * @returns {Object} The updated book
 */
router.put('/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      throw new Error('Invalid book ID');
    }

    // Delegate to the service layer for validation and update.
    const updatedBook = updateExistingBook(id, req.body);

    res.json({
      success: true,
      data: updatedBook
    });
  } catch (error) {
    next(error);
  }
});

// ---------------------------------------------------------------------------
// DELETE /books/:id
// Delete a book by its ID. Returns the deleted book in the response body.
//
// curl example:
//   curl -X DELETE http://localhost:3000/books/3
// ---------------------------------------------------------------------------

/**
 * @route   DELETE /books/:id
 * @desc    Delete a book by ID
 * @access  Public
 * @param   {number} id - Book ID
 * @returns {Object} Confirmation of deletion with the deleted book data
 */
router.delete('/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);
    if (isNaN(id)) {
      throw new Error('Invalid book ID');
    }

    // First, fetch the book so we can return it in the response.
    // This lets clients confirm what was deleted.
    const bookToDelete = getBook(id);

    // Delete the book via the service layer.
    deleteExistingBook(id);

    // 200 OK with the deleted resource is a common pattern.
    // Some APIs return 204 No Content instead (no body).
    res.json({
      success: true,
      message: `Book with id ${id} has been deleted`,
      data: bookToDelete
    });
  } catch (error) {
    next(error);
  }
});

// ---------------------------------------------------------------------------
// Export the router so app.js can mount it at /books.
// ---------------------------------------------------------------------------
module.exports = router;
```

> **REST convention notes:**
> - `GET` is idempotent and safe — no side effects.
> - `POST` returns `201 Created` with the new resource (standard REST).
> - `PUT` is idempotent — calling it twice with the same data produces the same result.
> - `DELETE` returns the deleted resource so the client can confirm what was removed. Some APIs use `204 No Content` instead; we chose `200` for better debugging in this educational example.

