```javascript
/**
 * ============================================================================
 * MAIN APPLICATION — Express App Setup
 * ============================================================================
 *
 * WHY THIS ORDER MATTERS:
 * -----------------------
 * Express middleware executes in the order it's registered. The typical order is:
 *   1. Body parsing (so routes can read req.body)
 *   2. Core middleware (helmet, CORS — security)
 *   3. Route handlers (the actual API endpoints)
 *   4. Error handling middleware (catches errors from routes)
 *   5. 404 fallback (catches unmatched routes)
 *
 * If we put the error handler before routes, it would never see route errors.
 * If we put the 404 handler before routes, it would intercept every request.
 * Order is critical — this is a common source of bugs in Express apps.
 *
 * WHY app.use() vs app.get()/app.post()?
 * ---------------------------------------
 * app.use() registers middleware that runs on EVERY request (matching all paths).
 * app.get()/app.post() registers handlers for specific HTTP methods and paths.
 * We use app.use() for body parsing and error handling, and app.use() with a
 * path prefix to mount our route routers.
 */

const express = require('express');
const app = express(); // Create the Express application instance

// ---------------------------------------------------------------------------
// Middleware: Body Parser
// ---------------------------------------------------------------------------
// Express 4.x does NOT include body parsing by default (unlike older versions).
// We need this middleware to parse JSON request bodies into req.body.
// Without it, POST/PUT requests would have an empty req.body.
app.use(express.json());

// ---------------------------------------------------------------------------
// Middleware: Basic Logging (optional but helpful for debugging)
// ---------------------------------------------------------------------------
// This logs every incoming request with its method, URL, and timestamp.
// In production, you'd replace this with a proper logging library.
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next(); // MUST call next() to continue the middleware chain
});

// ---------------------------------------------------------------------------
// Mount Route Routers
// ---------------------------------------------------------------------------
// We mount our route modules at specific path prefixes.
// All routes in books.js will be accessible under /books.
// All routes in stats.js will be accessible under /stats.
const bookRoutes = require('./routes/books');
const statsRoutes = require('./routes/stats');

app.use('/books', bookRoutes);
app.use('/stats', statsRoutes);

// ---------------------------------------------------------------------------
// Root endpoint — simple health check
// ---------------------------------------------------------------------------
app.get('/', (req, res) => {
  res.json({
    message: 'Book REST API is running!',
    endpoints: {
      books: '/books',
      stats: '/stats'
    }
  });
});

// ---------------------------------------------------------------------------
// Error Handling Middleware (MUST be after all routes)
// ---------------------------------------------------------------------------
// This catches errors thrown by routes and formats them consistently.
// See middleware/errorHandler.js for the full implementation.
const { errorHandler, notFoundHandler } = require('./middleware/errorHandler');

app.use(notFoundHandler);   // 404 fallback — must be before errorHandler
app.use(errorHandler);      // Central error handler — must be last

// ---------------------------------------------------------------------------
// Export the app for testing and for server.js to listen.
// ---------------------------------------------------------------------------
module.exports = app;
```

> **Critical ordering reminder:** The error handler and 404 handler MUST come after all route definitions. Express processes middleware in registration order, so if `errorHandler` were registered before `/books`, it would never see errors thrown inside book routes.

