## Arquivo 3: `src/middleware/errorMiddleware.js`

```javascript
/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * POR QUE UM MIDDLEWARE CENTRALIZADO?
 * ------------------------------------
 * Em vez de lidar com erros em cada controller individualmente, criamos um
 * middleware "catch-all" que intercepta erros não tratados e os transforma em
 * respostas HTTP padronizadas. Isso garante consistência na estrutura de erro
 * retornada ao cliente (ex: sempre { error, message, statusCode }).
 *
 * O Express identifica middlewares de erro pela assinatura de 4 parâmetros:
 *   (err, req, res, next)
 * Se um middleware tiver apenas 3 parâmetros, o Express o trata como normal.
 *
 * PADRÃO DE RESPOSTA DE ERRO:
 *   {
 *     success: false,
 *     statusCode: <código HTTP>,
 *     message: "<mensagem legível>",
 *     error: <detalhes do erro — apenas em desenvolvimento>
 *   }
 */

/**
 * Classe base para erros personalizados da API.
 * Herdar dela permite adicionar campos extras (ex: campo que falhou na validação).
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem de erro legível pelo usuário final.
   * @param {number} statusCode - Código HTTP correspondente (400, 404, etc.).
   */
  constructor(message, statusCode) {
    super(message); // Chama o construtor da classe Error nativa

    this.statusCode = statusCode;
    this.isOperational = true; // Marca como erro "esperado" da API (não bug do servidor)

    // Captura o stack trace no momento da criação para debugging.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Erro para quando um recurso não é encontrado.
 * Ex: GET /books/999 quando o ID 999 não existe.
 */
class NotFoundError extends AppError {
  constructor(resource, id) {
    // resource = "livro", id = "999" → mensagem: "Livro com ID 999 não encontrado."
    super(`${resource} com ID ${id} não encontrado.`, 404);
  }
}

/**
 * Erro para quando a requisição é malformada ou contém dados inválidos.
 * Ex: POST /books com título vazio.
 */
class ValidationError extends AppError {
  constructor(message, details = null) {
    super(message, 400);
    this.details = details; // Campo opcional para mais contexto (ex: quais campos falharam)
  }
}

/**
 * Erro para quando o cliente tenta fazer algo não autorizado.
 * Ex: PUT /books/:id sem estar autenticado (futuro, com auth).
 */
class UnauthorizedError extends AppError {
  constructor(message = 'Acesso não autorizado.') {
    super(message, 401);
  }
}

/**
 * ============================================================================
 * MIDDLEWARE PRINCIPAL DE TRATAMENTO DE ERROS
 * ============================================================================
 *
 * Este middleware deve ser o ÚLTIMO a ser registrado no app Express.
 * Ele captura erros lançados por controllers, rotas e outros middlewares.
 *
 * POR QUE USAR async/await AQUI?
 * ------------------------------
 * Embora este middleware não seja assíncrono por natureza, mantemos a assinatura
 * compatível com o padrão do Express para futuros cenários onde o tratamento
 * de erro possa envolver operações assíncronas (ex: log em banco de dados).
 */
const errorHandler = (err, req, res, next) => {
  // Determina se estamos em desenvolvimento para exibir detalhes extras.
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Se o erro já é uma instância de AppError, usamos seus campos definidos.
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      success: false,
      statusCode: err.statusCode,
      message: err.message,
      // Em desenvolvimento, mostramos o stack trace para facilitar debugging.
      // Em produção, ocultamos para não vazar informações internas do servidor.
      ...(isDevelopment && { error: err.stack }),
    });
  }

  // Erros não mapeados (bugs inesperados): retornamos 500 genérico.
  console.error('[ERRO NÃO TRATADO]:', err); // Log no terminal para o desenvolvedor

  return res.status(500).json({
    success: false,
    statusCode: 500,
    message: 'Erro interno do servidor. Tente novamente mais tarde.',
    ...(isDevelopment && { error: err.message }),
  });
};

module.exports = {
  AppError,
  NotFoundError,
  ValidationError,
  UnauthorizedError,
  errorHandler,
};
```

