## Arquivo 4: `src/controllers/booksController.js`

```javascript
/**
 * ============================================================================
 * CONTROLADOR DE LIVROS
 * ============================================================================
 *
 * POR QUE UM CONTROLADOR SEPARADO?
 * ---------------------------------
 * Separamos a lógica de negócio (controlador) da configuração do servidor (app.js).
 * Isso permite testar o controlador isoladamente e reutilizá-lo em diferentes contextos.
 *
 * ESTRUTURA DE DADOS — POR QUE ARRAY EM MEMÓRIA?
 * -----------------------------------------------
 * Usamos um array de objetos para armazenar os livros porque:
 *   1. É simples e fácil de entender para fins educacionais.
 *   2. Operações de busca linear são aceitáveis para conjuntos pequenos (< 1000 itens).
 *   3. Evita a complexidade de configurar um banco de dados real neste exemplo.
 *
 * Em produção, substituiríamos este array por um banco de dados (MongoDB, PostgreSQL, etc.).
 * A interface do controlador permaneceria a mesma — apenas o "repositório" mudaria.
 *
 * PADRÃO async/await:
 * ------------------
 * Mesmo que as operações com array sejam síncronas, mantemos a assinatura assíncrona
 * para facilitar a futura migração para um repositório assíncrono (ex: MongoDB).
 * Isso evita refatoração massiva depois.
 */

// Importamos os erros personalizados para uso consistente em todo o controlador.
const { AppError, NotFoundError, ValidationError } = require('../middleware/errorMiddleware');

/**
 * ============================================================================
 * ARMAZENAMENTO EM MEMÓRIA (SIMULA UM BANCO DE DADOS)
 * ============================================================================
 */

// Array que armazena todos os livros. Cada livro é um objeto com campos padronizados.
let books = [
  {
    id: 1,
    title: 'O Senhor dos Anéis',
    author: 'J.R.R. Tolkien',
    year: 1954,
    genre: 'Fantasia',
    createdAt: new Date('2024-01-15T10:00:00Z'),
  },
  {
    id: 2,
    title: '1984',
    author: 'George Orwell',
    year: 1949,
    genre: 'Distopia',
    createdAt: new Date('2024-01-16T14:30:00Z'),
  },
  {
    id: 3,
    title: 'Dom Casmurro',
    author: 'Machado de Assis',
    year: 1899,
    genre: 'Romance',
    createdAt: new Date('2024-01-17T09:15:00Z'),
  },
];

// Contador para gerar IDs únicos automaticamente.
// Em um banco real, isso seria feito pelo próprio DB (auto-increment / UUID).
let nextId = 4;

/**
 * ============================================================================
 * VALIDAÇÃO DE DADOS
 * ============================================================================
 *
 * POR QUE VALIDAR NO CONTROLADOR?
 * --------------------------------
 * A validação garante que dados malformados nunca cheguem ao armazenamento.
 * Retornamos erros 400 (Bad Request) com mensagens claras sobre o que está errado.
 */

/**
 * Valida os campos obrigatórios de um livro.
 * @param {Object} data - Dados do livro a serem validados.
 * @returns {string[]} - Lista de erros de validação (vazia se tudo estiver correto).
 */
function validateBook(data) {
  const errors = [];

  // title: obrigatório, string não vazia, mínimo 1 caractere.
  if (!data.title || typeof data.title !== 'string' || data.title.trim() === '') {
    errors.push('O campo "title" é obrigatório e deve ser uma string não vazia.');
  }

  // author: obrigatório, string não vazia.
  if (!data.author || typeof data.author !== 'string' || data.author.trim() === '') {
    errors.push('O campo "author" é obrigatório e deve ser uma string não vazia.');
  }

  // year: opcional, mas se fornecido, deve ser um número inteiro entre 0 e o ano atual.
  if (data.year !== undefined && data.year !== null) {
    const currentYear = new Date().getFullYear();
    if (!Number.isInteger(data.year) || data.year < 0 || data.year > currentYear) {
      errors.push(`O campo "year" deve ser um número inteiro entre 0 e ${currentYear}.`);
    }
  }

  // genre: opcional, mas se fornecido, deve ser string não vazia.
  if (data.genre !== undefined && data.genre !== null) {
    if (typeof data.genre !== 'string' || data.genre.trim() === '') {
      errors.push('O campo "genre" deve ser uma string não vazia.');
    }
  }

  return errors;
}

/**
 * ============================================================================
 * GET /books — LISTAR TODOS OS LIVROS COM FILTRAGEM
 * ============================================================================
 *
 * PARÂMETROS DE QUERY (opcionais):
 *   - author: filtra por autor (case-insensitive, parcial)
 *   - genre:  filtra por gênero (case-insensitive, parcial)
 *   - search: busca por título OU autor (case-insensitive, parcial)
 *
 * EXEMPLOS DE USO:
 *   GET /books                          → todos os livros
 *   GET /books?author=tolkien           → livros de Tolkien
 *   GET /books?genre=fantasia           → livros de fantasia
 *   GET /books?search=senhor            → livros com "senhor" no título ou autor
 *
 * COMANDO CURL:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?author=tolkien&genre=fantasia"
 */
async function getAllBooks(req, res, next) {
  try {
    // Extrai os parâmetros de query da URL (ex: ?author=Tolkien)
    const { author, genre, search } = req.query;

    let filteredBooks = books; // Começa com todos os livros

    // Filtro por autor: converte para minúsculas e verifica se o termo está contido.
    if (author) {
      const authorLower = author.toLowerCase();
      filteredBooks = filteredBooks.filter(
        (book) => book.author.toLowerCase().includes(authorLower)
      );
    }

    // Filtro por gênero: mesma lógica de case-insensitive e parcial.
    if (genre) {
      const genreLower = genre.toLowerCase();
      filteredBooks = filteredBooks.filter(
        (book) => book.genre && book.genre.toLowerCase().includes(genreLower)
      );
    }

    // Busca geral: procura no título OU no autor.
    if (search) {
      const searchLower = search.toLowerCase();
      filteredBooks = filteredBooks.filter(
        (book) =>
          book.title.toLowerCase().includes(searchLower) ||
          (book.author && book.author.toLowerCase().includes(searchLower))
      );
    }

    // Retorna os livros filtrados com metadados de paginação.
    return res.status(200).json({
      success: true,
      count: filteredBooks.length, // Quantidade de livros na resposta (pode diferir do total)
      total: books.length,         // Total de livros no sistema
      data: filteredBooks,
      ...(author && { filter: { author } }),
      ...(genre && { filter: { ...((author && { author }) || {}), genre } }),
      ...(search && { filter: { search } }),
    });
  } catch (error) {
    // Encaminha o erro para o middleware de tratamento de erros.
    next(error);
  }
}

/**
 * ============================================================================
 * GET /books/:id — OBTER UM LIVRO POR ID
 * ============================================================================
 *
 * EXEMPLO DE USO:
 *   GET /books/1
 *
 * COMANDO CURL:
 *   curl http://localhost:3000/books/1
 */
async function getBookById(req, res, next) {
  try {
    const id = parseInt(req.params.id, 10); // Converte ID de string para número.

    if (isNaN(id)) {
      // Se o ID não for um número válido, retornamos erro 400.
      throw new ValidationError('O parâmetro "id" deve ser um número inteiro válido.');
    }

    // find() retorna o PRIMEIRO elemento que satisfaz a condição, ou undefined.
    const book = books.find((b) => b.id === id);

    if (!book) {
      // Se não encontrado, lançamos NotFoundError (tratado pelo middleware).
      throw new NotFoundError('Livro', id);
    }

    return res.status(200).json({
      success: true,
      data: book,
    });
  } catch (error) {
    next(error);
  }
}

/**
 * ============================================================================
 * POST /books — CRIAR NOVO LIVRO
 * ============================================================================
 *
 * CORPO DA REQUISIÇÃO (JSON):
 *   {
 *     "title": "O Hobbit",
 *     "author": "J.R.R. Tolkien",
 *     "year": 1937,
 *     "genre": "Fantasia"
 *   }
 *
 * Campos opcionais: year, genre (se omitidos, ficam como undefined).
 * O ID é gerado automaticamente pelo servidor.
 *
 * COMANDO CURL:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Hobbit","author":"J.R.R. Tolkien","year":1937,"genre":"Fantasia"}'
 */
async function createBook(req, res, next) {
  try {
    const { title, author, year, genre } = req.body;

    // Valida os dados recebidos antes de criar o livro.
    const validationErrors = validateBook({ title, author, year, genre });
    if (validationErrors.length > 0) {
      throw new ValidationError('Validação falhou.', validationErrors);
    }

    // Cria o novo livro com ID automático e timestamp de criação.
    const newBook = {
      id: nextId++, // Incrementa o contador para o próximo ID.
      title,
      author,
      year: year || null, // Se não fornecido, armazena null em vez de undefined.
      genre: genre || null,
      createdAt: new Date(), // Timestamp do momento da criação.
    };

    // Adiciona ao array (operação O(1) no final).
    books.push(newBook);

    // Retorna 201 Created com o livro criado e localização no header Location.
    // A convenção REST exige que recursos criados tenham um URI único identificável.
    res.status(201).json({
      success: true,
      message: 'Livro criado com sucesso.',
      data: newBook,
      location: `/books/${newBook.id}`, // Header útil para clientes seguirem o link.
    });
  } catch (error) {
    next(error);
  }
}

/**
 * ============================================================================
 * PUT /books/:id — ATUALIZAR LIVRO EXISTENTE (SUBSTITUIÇÃO COMPLETA)
 * ============================================================================
 *
 * DIFERENÇA ENTRE PUT E PATCH:
 * ----------------------------
 * PUT = substituição completa: todos os campos fornecidos substituem os existentes.
 *      Campos não enviados são mantidos do original (implementação abaixo).
 * PATCH = atualização parcial: apenas os campos enviados são modificados.
 *
 * Neste exemplo, usamos PUT com comportamento de mesclagem (merge), que é mais
 * amigável para o usuário final. Em APIs estritamente RESTful, PUT deveria
 * exigir todos os campos — mas isso seria pouco prático.
 *
 * COMANDO CURL:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"O Senhor dos Anéis (Nova Edição)","year":2024}'
 */
async function updateBook(req, res, next) {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número inteiro válido.');
    }

    // Encontra o livro pelo ID.
    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError('Livro', id);
    }

    const { title, author, year, genre } = req.body;

    // Valida apenas os campos que estão sendo enviados.
    const validationErrors = validateBook({ title, author, year, genre });
    if (validationErrors.length > 0) {
      throw new ValidationError('Validação falhou.', validationErrors);
    }

    // Mescla os dados: campos novos sobrescrevem os antigos, campos não enviados são mantidos.
    books[bookIndex] = {
      ...books[bookIndex], // Mantém todos os campos existentes (id, createdAt, etc.).
      ...(title !== undefined && { title }),   // Só atualiza se o campo foi enviado.
      ...(author !== undefined && { author }),
      ...(year !== undefined && { year: year || null }),
      ...(genre !== undefined && { genre: genre || null }),
      updatedAt: new Date(), // Registra timestamp da atualização.
    };

    return res.status(200).json({
      success: true,
      message: 'Livro atualizado com sucesso.',
      data: books[bookIndex],
    });
  } catch (error) {
    next(error);
  }
}

/**
 * ============================================================================
 * DELETE /books/:id — EXCLUIR LIVRO
 * ============================================================================
 *
 * COMANDO CURL:
 *   curl -X DELETE http://localhost:3000/books/1
 */
async function deleteBook(req, res, next) {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('O parâmetro "id" deve ser um número inteiro válido.');
    }

    // findIndex retorna -1 se não encontrar.
    const bookIndex = books.findIndex((b) => b.id === id);

    if (bookIndex === -1) {
      throw new NotFoundError('Livro', id);
    }

    // splice remove o elemento do array e retorna um array com o elemento removido.
    const [removedBook] = books.splice(bookIndex, 1);

    return res.status(200).json({
      success: true,
      message: 'Livro excluído com sucesso.',
      data: removedBook, // Retorna o livro que foi excluído para confirmação.
    });
  } catch (error) {
    next(error);
  }
}

/**
 * ============================================================================
 * GET /stats — ESTATÍSTICAS DOS LIVROS
 * ============================================================================
 *
 * RETORNA:
 *   - totalBooks: quantidade total de livros
 *   - booksByGenre: distribuição por gênero
 *   - booksByAuthor: distribuição por autor
 *   - oldestBook: livro mais antigo (pelo ano)
 *   - newestBook: livro mais recente (pelo ano)
 *   - averageYear: média dos anos de publicação
 *
 * COMANDO CURL:
 *   curl http://localhost:3000/stats
 */
async function getStats(req, res, next) {
  try {
    if (books.length === 0) {
      return res.status(200).json({
        success: true,
        data: {
          totalBooks: 0,
          booksByGenre: {},
          booksByAuthor: {},
          oldestBook: null,
          newestBook: null,
          averageYear: null,
        },
      });
    }

    // Reduz o array para contar livros por gênero.
    const booksByGenre = books.reduce((acc, book) => {
      const genre = book.genre || 'Sem gênero';
      acc[genre] = (acc[genre] || 0) + 1;
      return acc;
    }, {});

    // Reduz o array para contar livros por autor.
    const booksByAuthor = books.reduce((acc, book) => {
      acc[book.author] = (acc[book.author] || 0) + 1;
      return acc;
    }, {});

    // Encontra o livro mais antigo e mais recente pelo ano de publicação.
    const oldestBook = books.reduce((min, book) =>
      (!min.year || book.year < min.year) ? book : min
    , null);

    const newestBook = books.reduce((max, book) =>
      (!max.year || book.year > max.year) ? book : max
    , null);

    // Calcula a média dos anos de publicação.
    const averageYear =
      books.filter((b) => b.year).length > 0
        ? Math.round(books.reduce((sum, b) => sum + b.year, 0) / books.filter((b) => b.year).length)
        : null;

    return res.status(200).json({
      success: true,
      data: {
        totalBooks: books.length,
        booksByGenre,
        booksByAuthor,
        oldestBook,
        newestBook,
        averageYear,
      },
    });
  } catch (error) {
    next(error);
  }
}

// Exporta todas as funções do controlador.
module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

