## Arquivo 5: `src/routes/booksRoutes.js`

```javascript
/**
 * ============================================================================
 * ROTAS DA API DE LIVROS
 * ============================================================================
 *
 * POR QUE ARQUIVO DE ROTAS SEPARADO?
 * -----------------------------------
 * Manter as rotas em um arquivo separado permite:
 *   1. Escalabilidade: quando a API cresce, as rotas não poluem o app.js.
 *   2. Reutilização: podemos montar múltiplos "routers" (ex: /api/v1/books).
 *   3. Legibilidade: cada arquivo tem uma responsabilidade única (Single Responsibility).
 *
 * CONVENÇÕES REST ADOTADAS:
 * -------------------------
 * | Método HTTP | URL              | Ação                    | Código de Resposta |
 * |-------------|------------------|-------------------------|--------------------|
 * | GET         | /books           | Listar todos            | 200 OK             |
 * | GET         | /books/:id       | Obter um                | 200 OK / 404       |
 * | POST        | /books           | Criar novo              | 201 Created        |
 * | PUT         | /books/:id       | Atualizar completo      | 200 OK / 404       |
 * | DELETE      | /books/:id       | Excluir                 | 200 OK / 404       |
 * | GET         | /stats           | Estatísticas            | 200 OK             |
 *
 * PADRÃO async/await NAS ROTAS:
 * ------------------------------
 * As rotas usam funções assíncronas porque os controladores podem, no futuro,
 * fazer operações I/O (banco de dados, APIs externas). Manter a assinatura
 * assíncrona desde o início evita refatoração posterior.
 */

const express = require('express');
const router = express.Router(); // Cria um roteador independente.

// Importa os controladores que contêm a lógica de negócio.
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
} = require('../controllers/booksController');

/**
 * ============================================================================
 * ROTAS PRINCIPAIS — /books
 * ============================================================================
 */

// GET /books — Listar todos os livros (com filtragem opcional via query params).
router.get('/books', getAllBooks);

// GET /books/:id — Obter um livro específico pelo ID.
// O Express captura ":id" como req.params.id automaticamente.
router.get('/books/:id', getBookById);

// POST /books — Criar um novo livro. O corpo da requisição (JSON) é parseado
// pelo middleware express.json() configurado no app.js.
router.post('/books', createBook);

// PUT /books/:id — Atualizar completamente um livro existente.
router.put('/books/:id', updateBook);

// DELETE /books/:id — Excluir um livro pelo ID.
router.delete('/books/:id', deleteBook);

/**
 * ============================================================================
 * ROTA DE ESTATÍSTICAS — /stats
 * ============================================================================
 * Colocada fora do grupo /books porque é uma rota de agregação, não de recurso.
 */
router.get('/stats', getStats);

// Exporta o roteador para ser usado no app.js.
module.exports = router;
```

