/**
 * ============================================================================
 * CONFIGURAÇÃO DO SERVIDOR EXPRESS
 * ============================================================================
 *
 * POR QUE SEPARAR app.js DO index.js?
 * ------------------------------------
 * app.js configura o servidor (middlewares, rotas, CORS).
 * index.js apenas inicia o servidor e ouve a porta.
 * Essa separação permite testar o app sem precisar iniciar o servidor HTTP.
 *
 * ORDEM DOS MIDDLEWARES — POR QUE IMPORTA?
 * -----------------------------------------
 * O Express executa middlewares na ordem em que são registrados. A ordem correta é:
 *   1. Middlewares globais (body-parser, CORS) → antes de qualquer rota.
 *   2. Rotas da API → para que as requisições sejam roteadas corretamente.
 *   3. Middleware de tratamento de erros → SEMPRE por último, para capturar erros
 *      de todas as rotas e middlewares anteriores.
 */

const express = require('express');
const cors = require('cors'); // Habilita CORS para permitir requisições cross-origin.
require('dotenv').config(); // Carrega variáveis do arquivo .env.

// Importa o roteador de livros e o middleware de erros.
const booksRoutes = require('./routes/booksRoutes');
const { errorHandler } = require('./middleware/errorMiddleware');

// Cria a instância do aplicativo Express.
const app = express();

/**
 * ============================================================================
 * MIDDLEWARES GLOBAIS
 * ============================================================================
 */

// CORS: permite que frontends de outras origens acessem esta API.
// Em produção, restrinja a origem específica (ex: { origin: 'https://meusite.com' }).
app.use(cors());

// express.json(): parseia o corpo de requisições com Content-Type: application/json.
// Sem este middleware, req.body seria undefined em requisições POST/PUT.
app.use(express.json());

// express.urlencoded(): parseia dados de formulários (application/x-www-form-urlencoded).
// Útil para APIs que também aceitam submissions de formulário.
app.use(express.urlencoded({ extended: true }));

/**
 * ============================================================================
 * LOG DE REQUISIÇÕES (DESENVOLVIMENTO)
 * ============================================================================
 * Middleware simples que loga método, URL e timestamp de cada requisição.
 * Em produção, considere usar um logger mais robusto (ex: winston, pino).
 */
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'development') {
    console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  }
  next(); // Passa o controle para o próximo middleware/rota.
});

/**
 * ============================================================================
 * ROTAS DA API
 * ============================================================================
 * Todas as rotas começam com /api/v1 para facilitar versionamento futuro.
 * Se precisarmos mudar a estrutura da API, mantemos a versão anterior funcionando.
 */
app.use('/api/v1', booksRoutes);

/**
 * ============================================================================
 * ROTA DE HEALTH CHECK — /health
 * ============================================================================
 * Usada por provedores de cloud (ex: AWS Auto Scaling) para verificar se o
 * servidor está respondendo. Retorna 200 com mensagem simples.
 */
app.get('/health', (req, res) => {
  res.status(200).json({
    success: true,
    message: 'Servidor OK',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(), // Tempo em segundos que o servidor está rodando.
  });
});

/**
 * ============================================================================
 * ROTA 404 PARA ROTAS NÃO ENCONTRADAS
 * ============================================================================
 * Se nenhuma rota corresponder, retornamos 404 com mensagem clara.
 * Isso evita que o Express retorne seu HTML de erro padrão (que vazaria info).
 */
app.use((req, res) => {
  res.status(404).json({
    success: false,
    statusCode: 404,
    message: `Rota ${req.method} ${req.url} não encontrada.`,
  });
});

/**
 * ============================================================================
 * MIDDLEWARE DE TRATAMENTO DE ERROS — SEMPRE O ÚLTIMO
 * ============================================================================
 * Deve ser registrado APÓS todas as rotas para capturar erros de qualquer lugar.
 */
app.use(errorHandler);

// Exporta a instância do app para uso em index.js e para testes.
module.exports = app;
```

