## File 2: `server.js`

```javascript
/**
 * ============================================================================
 * server.js — Application Entry Point
 * ============================================================================
 *
 * This file bootstraps the Express application, configures middleware,
 * mounts route handlers, and defines a global error-handling middleware.
 *
 * WHY THIS STRUCTURE?
 * -------------------
 * Keeping the entry point separate from route logic promotes separation of
 * concerns. The server.js file is responsible for "plumbing" (middleware,
 * listening on a port), while routes/books.js handles business logic. This
 * makes the codebase easier to navigate and scale as it grows.
 *
 * REST CONVENTION NOTE:
 * ---------------------
 * All book-related endpoints live under /books, which is the standard
 * pluralized resource name in REST APIs. The root (/) provides a simple
 * health-check endpoint.
 */

const express = require('express');
const bookRoutes = require('./routes/books');

// --------------------------------------------------------------------------
// Application Setup
// --------------------------------------------------------------------------

/**
 * Create an Express application instance.
 *
 * Express is a minimal, unopinionated web framework for Node.js. We choose it
 * here because it provides just enough structure without imposing rigid
 * architecture — ideal for educational purposes where we want to see the
 * mechanics clearly.
 */
const app = express();

/**
 * Port configuration.
 *
 * We default to 3000, a conventional port for local development servers.
 * In production you'd typically read this from an environment variable
 * (e.g., process.env.PORT) and fall back to 3000.
 */
const PORT = process.env.PORT || 3000;

// --------------------------------------------------------------------------
// Middleware Configuration
// --------------------------------------------------------------------------

/**
 * Body-parser middleware.
 *
 * Express does not parse request bodies by default (prior to v4.16+). We
 * explicitly enable JSON body parsing so that POST/PUT requests with JSON
 * payloads are available via req.body. Without this, req.body would be
 * undefined and we'd have to manually parse the raw request stream.
 *
 * limit: '10mb' prevents rejection of unusually large payloads (defensive).
 */
app.use(express.json({ limit: '10mb' }));

/**
 * Simple logging middleware for development visibility.
 *
 * This prints each incoming request's method, URL, and timestamp to the
 * console. In production you'd replace this with a proper logger like
 * Winston or Pino. For learning purposes, raw console output is perfectly
 * adequate and helps you trace request flow.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next(); // Pass control to the next middleware/route handler
});

// --------------------------------------------------------------------------
// Route Mounting
// --------------------------------------------------------------------------

/**
 * Mount book routes under the /books path.
 *
 * By using app.use('/books', bookRoutes), Express automatically prefixes
 * every route defined in books.js with '/books'. This is cleaner than
 * repeating '/books' in every route definition and makes it trivial to
 * change the base path later (e.g., if you restructure your API).
 */
app.use('/books', bookRoutes);

/**
 * Root health-check endpoint.
 *
 * A simple GET / that returns a JSON message confirming the server is
 * running. This is useful for load balancers, container orchestration
 * platforms (Kubernetes liveness probes), and quick manual verification.
 */
app.get('/', (req, res) => {
  res.json({
    message: 'Book Management API is running.',
    endpoints: {
      books: '/books',
      stats: '/stats'
    },
    documentation: 'See README.md for full endpoint details and examples.'
  });
});

// --------------------------------------------------------------------------
// Global Error-Handling Middleware
// --------------------------------------------------------------------------

/**
 * Catch-all error handler.
 *
 * Express treats any function with exactly FOUR parameters (err, req, res, next)
 * as an error-handling middleware. This middleware must be registered AFTER all
 * routes so it can catch errors thrown by route handlers.
 *
 * WHY CUSTOM ERROR CLASSES?
 * -------------------------
 * We define NotFoundError and ValidationError in routes/books.js. By checking
 * the error type here, we can return appropriate HTTP status codes:
 *   - 404 for not-found resources
 *   - 400 for client input errors
 *   - 500 for unexpected server errors
 *
 * This separation keeps route handlers focused on business logic while the
 * error handler focuses on response formatting.
 */
app.use((err, req, res, next) => {
  // Log the full stack trace for debugging (omit in production for security)
  console.error('Unhandled error:', err.stack);

  // Determine status code based on error type
  const statusCode = err.statusCode || 500;

  // Return a consistent JSON error response
  res.status(statusCode).json({
    success: false,
    error: {
      message: err.message,
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
      // In development we include the stack trace for easier debugging.
      // In production this is omitted to avoid leaking internal details.
    }
  });
});

// --------------------------------------------------------------------------
// Server Startup
// --------------------------------------------------------------------------

/**
 * Start the HTTP server and listen on the configured port.
 *
 * We wrap the listen call in a try/catch because if the port is already in
 * use, Node.js will throw an error that would otherwise crash the process
 * silently. Logging the error gives us immediate feedback.
 */
app.listen(PORT, () => {
  console.log(`========================================`);
  console.log(`  Book Management API running on port ${PORT}`);
  console.log(`  Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`  Base URL:    http://localhost:${PORT}`);
  console.log(`========================================`);
});

module.exports = app; // Export for testing purposes
```

