## File 3: `routes/books.js`

```javascript
/**
 * ============================================================================
 * routes/books.js — Book Management Routes
 * ============================================================================
 *
 * This module contains all RESTful endpoints for the /books resource.
 * It also defines custom error classes and an in-memory data store.
 *
 * DATA STRUCTURE CHOICE: In-Memory Array of Objects
 * -------------------------------------------------
 * We use a plain JavaScript array to simulate a database. Each element is
 * a Book instance (see below). This approach is chosen for educational
 * clarity — no external dependencies, no setup, and immediate visibility
 * into how CRUD operations manipulate data.
 *
 * In a real application you would replace this with a proper database
 * (PostgreSQL, MongoDB, etc.) and use an ORM or query builder. The route
 * logic here would remain largely the same; only the data-access layer
 * would change. This is known as the Repository Pattern.
 *
 * WHY A CLASS FOR BOOKS?
 * ----------------------
 * Using a class (Book) instead of plain objects provides:
 *   1. Encapsulation — validation logic lives inside the constructor.
 *   2. Type safety via JSDoc annotations for IDE support.
 *   3. A clear contract for what properties a book has.
 *   4. Easy extensibility (e.g., adding methods like .toJSON()).
 */

// --------------------------------------------------------------------------
// Custom Error Classes
// --------------------------------------------------------------------------

/**
 * NotFoundError — thrown when a requested resource does not exist.
 *
 * Extending the built-in Error class gives us proper stack traces and
 * instanceof checks. We add a statusCode property so the global error
 * handler can return 404 without hardcoding it in every route.
 */
class NotFoundError extends Error {
  /**
   * @param {string} message — Human-readable description of the error.
   */
  constructor(message) {
    super(message);
    this.name = 'NotFoundError';
    this.statusCode = 404;
  }
}

/**
 * ValidationError — thrown when client input fails validation.
 *
 * Similar to NotFoundError, we attach a statusCode (400 Bad Request) so
 * the error handler can distinguish client errors from server errors.
 */
class ValidationError extends Error {
  /**
   * @param {string} message — Description of what validation failed.
   */
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

// --------------------------------------------------------------------------
// In-Memory Data Store
// --------------------------------------------------------------------------

/**
 * Book class — represents a single book entity.
 *
 * The constructor validates required fields and assigns defaults. Using
 * a class ensures every book in our store has a consistent shape, which
 * prevents bugs from missing or malformed properties.
 */
class Book {
  /**
   * @param {object} data — Initial book data.
   * @param {string} data.title — The book's title (required).
   * @param {string} data.author — The author's name (required).
   * @param {string} [data.genre] — Genre/category (optional, defaults to 'Unknown').
   * @param {number} [data.year] — Publication year (optional).
   * @param {string} data.id — Unique identifier (required, generated externally).
   */
  constructor(data) {
    this.id = data.id;
    this.title = data.title;
    this.author = data.author;
    this.genre = data.genre || 'Unknown';
    this.year = data.year || null;
    this.createdAt = new Date().toISOString();
    this.updatedAt = new Date().toISOString();
  }

  /**
   * Update mutable fields on this book.
   *
   * We explicitly list which fields can be updated to prevent accidental
   * modification of immutable fields like id and createdAt. This is a
   * defensive programming practice.
   *
   * @param {object} updates — Fields to update.
   */
  update(updates) {
    if (updates.title !== undefined) this.title = updates.title;
    if (updates.author !== undefined) this.author = updates.author;
    if (updates.genre !== undefined) this.genre = updates.genre;
    if (updates.year !== undefined) this.year = updates.year;
    this.updatedAt = new Date().toISOString();
  }

  /**
   * Return a plain object representation suitable for JSON serialization.
   *
   * We exclude internal fields and ensure the output shape is consistent.
   * This method can be extended to include computed fields (e.g., age).
   *
   * @returns {object} Serializable book data.
   */
  toJSON() {
    return {
      id: this.id,
      title: this.title,
      author: this.author,
      genre: this.genre,
      year: this.year,
      createdAt: this.createdAt,
      updatedAt: this.updatedAt
    };
  }
}

/**
 * In-memory book storage.
 *
 * We seed the array with three sample books so the API is immediately
 * useful when you first start it. In a real app, this would be replaced
 * by database queries. The `let` keyword is used (rather than `const`)
 * because we may want to reassign the entire array in future extensions
 * (e.g., loading from a file on startup).
 */
let books = [
  new Book({
    id: '1',
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    year: 1925
  }),
  new Book({
    id: '2',
    title: 'Clean Code',
    author: 'Robert C. Martin',
    genre: 'Technology',
    year: 2008
  }),
  new Book({
    id: '3',
    title: 'Dune',
    author: 'Frank Herbert',
    genre: 'Science Fiction',
    year: 1965
  })
];

/**
 * Generate a simple unique ID.
 *
 * For production you would use a UUID library or database-generated IDs.
 * Here we use a timestamp-based approach for simplicity. In a concurrent
 * environment this could produce collisions, but for an educational example
 * it is sufficient and easy to understand.
 *
 * @returns {string} A unique identifier string.
 */
function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
}

// --------------------------------------------------------------------------
// Validation Helpers
// --------------------------------------------------------------------------

/**
 * Validate the required fields for creating a book.
 *
 * We validate before touching the data store to fail fast and provide
 * clear error messages. This is an example of input validation at the
 * boundary — never trust client input.
 *
 * @param {object} body — The request body from the client.
 * @throws {ValidationError} If any required field is missing or invalid.
 */
function validateCreateBook(body) {
  if (!body.title || typeof body.title !== 'string' || body.title.trim() === '') {
    throw new ValidationError('Title is required and must be a non-empty string.');
  }
  if (!body.author || typeof body.author !== 'string' || body.author.trim() === '') {
    throw new ValidationError('Author is required and must be a non-empty string.');
  }
  if (body.genre !== undefined && typeof body.genre !== 'string') {
    throw new ValidationError('Genre must be a string if provided.');
  }
  if (body.year !== undefined && (!Number.isInteger(body.year) || body.year < 0)) {
    throw new ValidationError('Year must be a positive integer if provided.');
  }
}

/**
 * Validate the fields for updating a book.
 *
 * Unlike create, update is partial — any subset of fields can be sent.
 * We only validate fields that are actually present in the request.
 *
 * @param {object} body — The request body from the client.
 * @throws {ValidationError} If any provided field is invalid.
 */
function validateUpdateBook(body) {
  if (body.title !== undefined && (typeof body.title !== 'string' || body.title.trim() === '')) {
    throw new ValidationError('Title must be a non-empty string if provided.');
  }
  if (body.author !== undefined && (typeof body.author !== 'string' || body.author.trim() === '')) {
    throw new ValidationError('Author must be a non-empty string if provided.');
  }
  if (body.genre !== undefined && typeof body.genre !== 'string') {
    throw new ValidationError('Genre must be a string if provided.');
  }
  if (body.year !== undefined && (!Number.isInteger(body.year) || body.year < 0)) {
    throw new ValidationError('Year must be a positive integer if provided.');
  }
}

// --------------------------------------------------------------------------
// Route Handlers
// --------------------------------------------------------------------------

const router = require('express').Router();

/**
 * GET /books — List all books with optional filtering.
 *
 * Supports query parameters for filtering:
 *   - author: Filter by author name (case-insensitive partial match)
 *   - genre:  Filter by genre (exact match, case-insensitive)
 *   - search: Search across title and author (case-insensitive)
 *
 * WHY QUERY PARAMETERS FOR FILTERING?
 * ------------------------------------
 * Using query parameters (e.g., ?genre=Fiction) is the RESTful way to
 * express optional filters. It keeps the URL structure clean and allows
 * clients to compose filters freely without needing multiple endpoints.
 *
 * EXAMPLES:
 *   curl http://localhost:3000/books
 *   curl "http://localhost:3000/books?genre=Fiction"
 *   curl "http://localhost:3000/books?author=fitzgerald"
 *   curl "http://localhost:3000/books?search=dune"
 */
router.get('/', (req, res) => {
  let result = books;

  // Filter by author (case-insensitive partial match)
  if (req.query.author) {
    const authorQuery = req.query.author.toLowerCase();
    result = result.filter(book => book.author.toLowerCase().includes(authorQuery));
  }

  // Filter by genre (exact, case-insensitive match)
  if (req.query.genre) {
    const genreQuery = req.query.genre.toLowerCase();
    result = result.filter(book => book.genre.toLowerCase() === genreQuery);
  }

  // Search across title and author
  if (req.query.search) {
    const searchQuery = req.query.search.toLowerCase();
    result = result.filter(book =>
      book.title.toLowerCase().includes(searchQuery) ||
      book.author.toLowerCase().includes(searchQuery)
    );
  }

  // Return the (possibly filtered) list as JSON.
  // We use .toJSON() on each book to ensure a consistent output shape.
  res.json({
    success: true,
    count: result.length,
    data: result.map(book => book.toJSON())
  });
});

/**
 * GET /books/:id — Retrieve a single book by its ID.
 *
 * We use findById to locate the book, and throw NotFoundError if it
 * doesn't exist. This keeps the response consistent — every endpoint
 * returns either success data or an error object.
 *
 * EXAMPLES:
 *   curl http://localhost:3000/books/1
 *   curl http://localhost:3000/books/999  → 404
 */
router.get('/:id', (req, res) => {
  const book = books.find(b => b.id === req.params.id);

  if (!book) {
    throw new NotFoundError(`Book with id '${req.params.id}' not found.`);
  }

  res.json({
    success: true,
    data: book.toJSON()
  });
});

/**
 * POST /books — Create a new book.
 *
 * The client sends a JSON body with title and author (required), plus
 * optional genre and year fields. We validate the input, create a new
 * Book instance, add it to our store, and return the created resource
 * with a 201 Created status code.
 *
 * WHY 201 CREATED?
 * ----------------
 * Per HTTP/1.1 specification (RFC 7231), 201 indicates that the request
 * resulted in the creation of a new resource. This is more informative
 * than 200 OK and helps clients understand what happened.
 *
 * EXAMPLES:
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","genre":"Dystopian","year":1949}'
 */
router.post('/', (req, res) => {
  // Validate input before processing
  validateCreateBook(req.body);

  const newBook = new Book({
    id: generateId(),
    title: req.body.title.trim(),
    author: req.body.author.trim(),
    genre: req.body.genre,
    year: req.body.year
  });

  books.push(newBook);

  res.status(201).json({
    success: true,
    message: 'Book created successfully.',
    data: newBook.toJSON()
  });
});

/**
 * PUT /books/:id — Fully update an existing book.
 *
 * PUT is a full-replacement operation: the client sends the complete
 * desired state, and we replace all mutable fields. This is different
 * from PATCH, which would only update provided fields.
 *
 * We validate the input, find the book, update it, and return the
 * updated resource with 200 OK.
 *
 * EXAMPLES:
 *   curl -X PUT http://localhost:3000/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby (Updated)","author":"F. Scott Fitzgerald"}'
 */
router.put('/:id', (req, res) => {
  const book = books.find(b => b.id === req.params.id);

  if (!book) {
    throw new NotFoundError(`Book with id '${req.params.id}' not found.`);
  }

  validateUpdateBook(req.body);

  book.update({
    title: req.body.title,
    author: req.body.author,
    genre: req.body.genre,
    year: req.body.year
  });

  res.json({
    success: true,
    message: 'Book updated successfully.',
    data: book.toJSON()
  });
});

/**
 * DELETE /books/:id — Delete a book by ID.
 *
 * We find the book, remove it from the array using splice (which is
 * O(n) but fine for small in-memory stores), and return 204 No Content
 * to indicate successful deletion with no response body.
 *
 * WHY 204 NO CONTENT?
 * -------------------
 * A 204 status tells the client the operation succeeded but there is
 * no content to return. This is the standard for DELETE operations and
 * avoids unnecessary payload transfer.
 *
 * EXAMPLES:
 *   curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/:id', (req, res) => {
  const index = books.findIndex(b => b.id === req.params.id);

  if (index === -1) {
    throw new NotFoundError(`Book with id '${req.params.id}' not found.`);
  }

  books.splice(index, 1);

  res.status(204).send();
});

// --------------------------------------------------------------------------
// Statistics Endpoint
// --------------------------------------------------------------------------

/**
 * GET /stats — Return aggregate statistics about the book collection.
 *
 * This endpoint computes:
 *   - totalBooks: Total number of books in the store.
 *   - averageYear: Average publication year (null if empty).
 *   - genres: A breakdown of books per genre with counts.
 *   - authors: A list of all unique author names.
 *
 * WHY SEPARATE ENDPOINT FOR STATS?
 * ---------------------------------
 * Statistics are a derived resource, not a direct manipulation of books.
 * Placing it at /stats (rather than embedding it in /books) follows the
 * REST principle that each endpoint should represent a single resource or
 * action. It also keeps the /books list response lightweight.
 *
 * EXAMPLES:
 *   curl http://localhost:3000/stats
 */
router.get('/stats', (req, res) => {
  const totalBooks = books.length;

  // Compute average publication year, handling the empty-case gracefully
  const years = books.map(b => b.year).filter(y => y !== null);
  const averageYear = years.length > 0
    ? years.reduce((sum, y) => sum + y, 0) / years.length
    : null;

  // Build a genre distribution map
  const genres = {};
  books.forEach(book => {
    genres[book.genre] = (genres[book.genre] || 0) + 1;
  });

  // Extract unique author names
  const authors = [...new Set(books.map(b => b.author))];

  res.json({
    success: true,
    data: {
      totalBooks,
      averageYear: averageYear ? Math.round(averageYear * 100) / 100 : null,
      genres,
      authors
    }
  });
});

// --------------------------------------------------------------------------
// Module Exports
// --------------------------------------------------------------------------

module.exports = router;
```

