## Arquivo 2: `src/utils/errors.js`

```javascript
/**
 * ============================================================
 * CLASSES DE ERRO PERSONALIZADAS
 * ============================================================
 *
 * POR QUE CRIAR CLASSES DE ERRO CUSTOMIZADAS?
 * --------------------------------------------
 * As classes de erro nativas do JavaScript (Error, TypeError, etc.)
 * são genéricas e não carregam informações contextuais úteis para
 * APIs REST. Ao criar subclasses como NotFoundError, ValidationError
 * e InternalServerError, podemos:
 *
 * 1. Identificar o TIPO de erro programaticamente (instanceof)
 * 2. Incluir campos extras como statusCode, message e details
 * 3. Padronizar a resposta de erro em toda a API
 * 4. Facilitar o tratamento no middleware de erros
 *
 * A hierarquia segue o padrão: Error -> CustomError -> Especifico
 */

/**
 * Classe base para todos os erros da aplicação.
 * Estende Error nativo e adiciona propriedades REST-friendly.
 */
class AppError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro
   * @param {number} statusCode - Código HTTP da resposta (4xx cliente, 5xx servidor)
   * @param {boolean} isOperational - Indica se o erro é esperado (true) ou bug (false)
   * @param {Object} [details] - Detalhes adicionais do erro
   */
  constructor(message, statusCode, isOperational = true, details = null) {
    super(message);
    // Mantém a stack trace correta mesmo com classes estendidas
    Object.setPrototypeOf(this, AppError.prototype);

    /**
     * Código HTTP que será retornado ao cliente.
     * Usamos statusCode em vez de status para evitar conflito
     * com propriedades internas do Node.js Error.
     */
    this.statusCode = statusCode;

    /**
     * Erros operacionais são esperados (ex: recurso não encontrado).
     * Erros não-operacionais indicam bugs e devem ser logados internamente.
     * Isso evita expor detalhes de falhas internas ao cliente.
     */
    this.isOperational = isOperational;

    /**
     * Detalhes opcionais para validação ou debugging.
     * Ex: lista de campos inválidos em um ValidationError.
     */
    this.details = details;

    /**
     * Timestamp do erro para logging e rastreamento.
     */
    this.timestamp = new Date().toISOString();
  }
}

/**
 * Erro 404 — Recurso não encontrado.
 * Usado quando um ID inválido é fornecido ou o recurso não existe.
 */
class NotFoundError extends AppError {
  constructor(resource = 'recurso', id = null) {
    const message = id
      ? `${resource} com ID ${id} não encontrado`
      : `${resource} não encontrado`;
    super(message, 404, true);
    this.name = 'NotFoundError';
  }
}

/**
 * Erro 400 — Validação falhou.
 * Usado quando dados de entrada não atendem aos requisitos.
 */
class ValidationError extends AppError {
  /**
   * @param {string} message - Mensagem geral do erro
   * @param {Object[]} fields - Array de campos com problemas
   * @example [{ field: 'title', message: 'é obrigatório' }]
   */
  constructor(message, fields = []) {
    super(message, 400, true, { fields });
    this.name = 'ValidationError';
  }
}

/**
 * Erro 500 — Erro interno do servidor.
 * Usado para falhas inesperadas que não devem expor detalhes ao cliente.
 */
class InternalError extends AppError {
  constructor(message = 'Erro interno do servidor', details = null) {
    super(message, 500, false, details);
    this.name = 'InternalError';
  }
}

module.exports = { AppError, NotFoundError, ValidationError, InternalError };
```

