## Arquivo 3: `src/models/book.js`

```javascript
/**
 * ============================================================
 * MODELO DE DADOS — Livro
 * ============================================================
 *
 * POR QUE USAR UM ARRAY EM MEMÓRIA?
 * ----------------------------------
 * Para este exemplo educacional, um array em memória é a escolha ideal porque:
 *
 * 1. SIMPLICIDADE: Não requer configuração de banco de dados (MongoDB, PostgreSQL, etc.)
 * 2. VELOCIDADE: Operações O(1) para push/pop e O(n) para busca linear são suficientes
 *    para um conjunto pequeno de dados (~10-100 livros)
 * 3. FOCALIZAÇÃO: Permite concentrar-se nos conceitos de REST, rotas e middleware
 *    sem distrações com camadas de abstração de banco de dados
 * 4. TRANSIÊNCIA: Os dados são perdidos ao reiniciar o servidor, o que é aceitável
 *    para um exemplo educacional
 *
 * POR QUE NÃO USAR UM OBJETO (MAP) EM VEZ DE ARRAY?
 * --------------------------------------------------
 * Um objeto { id: livro } permitiria busca O(1) por ID. No entanto:
 * - Arrays são mais familiares e legíveis para iniciantes
 * - A ordem de inserção é preservada (útil para listagem)
 * - Para n < 100, a diferença de performance é insignificante
 *
 * Em produção, recomenda-se usar um banco de dados com índices adequados.
 */

// Array em memória que armazena todos os livros da aplicação.
// Inicializado vazio; os dados são populados via POST /books.
const books = [];

/**
 * Gerador de IDs únicos simples.
 *
 * POR QUE NÃO USAR UUIDs?
 * -----------------------
 * Para este exemplo, incrementamos um contador numérico porque:
 * - É mais legível e fácil de entender para fins educacionais
 * - Não requer dependências externas (uuid, nanoid)
 * - IDs sequenciais são perfeitamente válidos em APIs REST
 *
 * Em produção, UUIDs v4 ou ULIDs são preferíveis por:
 * - Evitar enumeração de recursos (segurança)
 * - Permitir geração de IDs sem estado compartilhado
 */
let nextId = 1;

/**
 * Função auxiliar para gerar o próximo ID.
 * @returns {number} Próximo ID disponível
 */
function generateId() {
  return nextId++;
}

/**
 * ============================================================
 * OPERAÇÕES CRUD DO MODELO LIVRO
 * ============================================================
 *
 * Cada função opera diretamente sobre o array `books`.
 * Em uma aplicação real, estas funções seriam substituídas
 * por chamadas a um repositório ou service layer.
 */

/**
 * Retorna todos os livros armazenados.
 *
 * @returns {Array<Object>} Lista de todos os livros
 */
function findAll() {
  return [...books]; // Retorna cópia para evitar mutação externa direta
}

/**
 * Busca um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser buscado
 * @returns {Object|null} Livro encontrado ou null se não existir
 */
function findById(id) {
  return books.find((book) => book.id === id) || null;
}

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * @param {Object} data - Dados do novo livro
 * @param {string} data.title - Título do livro (obrigatório)
 * @param {string} data.author - Autor do livro (obrigatório)
 * @param {string} [data.genre] - Gênero literário
 * @param {number} [data.year] - Ano de publicação
 * @returns {Object} Livro criado com ID atribuído
 */
function create(data) {
  const newBook = {
    id: generateId(),
    title: data.title,
    author: data.author,
    genre: data.genre || null,
    year: data.year || null,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  books.push(newBook);
  return newBook;
}

/**
 * Atualiza um livro existente pelo ID.
 *
 * @param {number} id - ID do livro a ser atualizado
 * @param {Object} data - Campos a serem atualizados (partial update)
 * @returns {Object|null} Livro atualizado ou null se não encontrado
 */
function update(id, data) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return null;

  // Atualiza apenas os campos fornecidos (partial update / PATCH semantics)
  // Usamos Object.keys para iterar sobre campos explícitos do request
  const allowedFields = ['title', 'author', 'genre', 'year'];
  for (const field of allowedFields) {
    if (data[field] !== undefined) {
      books[index][field] = data[field];
    }
  }
  books[index].updatedAt = new Date().toISOString();
  return { ...books[index] }; // Retorna cópia para evitar referência direta
}

/**
 * Remove um livro pelo ID.
 *
 * @param {number} id - ID do livro a ser removido
 * @returns {boolean} True se removido, false se não encontrado
 */
function remove(id) {
  const index = books.findIndex((book) => book.id === id);
  if (index === -1) return false;
  books.splice(index, 1);
  return true;
}

/**
 * Calcula estatísticas agregadas sobre os livros.
 *
 * @returns {Object} Estatísticas: total, por gênero, média de anos, autores únicos
 */
function getStats() {
  const total = books.length;

  if (total === 0) {
    return {
      total,
      averageYear: null,
      genres: {},
      authors: [],
    };
  }

  // Agrupamento por gênero usando reduce — padrão funcional para agregação
  const genres = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Média de anos de publicação
  const averageYear =
    books.reduce((sum, book) => sum + (book.year || 0), 0) / total;

  // Lista de autores únicos
  const authors = [...new Set(books.map((book) => book.author))];

  return {
    total,
    averageYear: Math.round(averageYear * 100) / 100, // Arredonda para 2 casas decimais
    genres,
    authors,
  };
}

module.exports = { findAll, findById, create, update, remove, getStats };
```

