/**
 * ============================================================
 * MIDDLEWARE — Tratamento Centralizado de Erros
 * ============================================================
 *
 * POR QUE UM HANDLER DE ERROS CENTRALIZADO?
 * ------------------------------------------
 * Sem um middleware de erro, cada rota precisaria de try/catch
 * individual com respostas de erro duplicadas. O handler centralizado:
 *
 * 1. Centraliza a lógica de formatação de resposta de erro
 * 2. Diferencia erros operacionais (esperados) de bugs (inesperados)
 * 3. Evita vazamento de stack traces para clientes em produção
 * 4. Permite logging consistente de todos os erros
 *
 * NO EXPRESS, middlewares de erro têm 4 parâmetros: (err, req, res, next)
 * Eles são invocados automaticamente quando next(err) é chamado.
 */

const { AppError } = require('../utils/errors');

function errorHandler(err, req, res, next) {
  // Log do erro para fins de debugging/monitoramento
  console.error(`[ERROR] ${new Date().toISOString()}`, {
    name: err.name,
    message: err.message,
    statusCode: err.statusCode,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });

  // Se for um AppError customizado, usa seus campos; senão, trata como erro genérico
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      error: {
        status: err.statusCode,
        code: err.name,
        message: err.message,
        details: err.details || null,
        timestamp: err.timestamp || new Date().toISOString(),
      },
    });
  }

  // Erro não operacional (bug) — nunca expor detalhes ao cliente
  return res.status(500).json({
    error: {
      status: 500,
      code: 'INTERNAL_ERROR',
      message:
        process.env.NODE_ENV === 'production'
          ? 'Erro interno do servidor'
          : err.message,
      timestamp: new Date().toISOString(),
    },
  });
}

module.exports = errorHandler;
```

