/**
 * ============================================================
 * ROTAS — Gerenciamento de Livros
 * ============================================================
 *
 * POR QUE UM ARQUIVO DE ROTAS SEPARADO?
 * --------------------------------------
 * Separar rotas em arquivos distintos segue o princípio de
 * responsabilidade única e facilita a manutenção:
 *
 * 1. Cada arquivo de rota cuida apenas de um recurso (livros)
 * 2. A aplicação principal (app.js) permanece limpa e focada
 *    na configuração de middleware e roteamento
 * 3. Facilita testes unitários por recurso
 * 4. Permite escalar: novas rotas podem ser adicionadas sem
 *    modificar o arquivo da aplicação
 *
 * PADRÃO REST ADOTADO:
 * -------------------
 * | Método HTTP | Endpoint       | Ação                    | Código de Retorno |
 * |-------------|----------------|-------------------------|-------------------|
 * | GET         | /books         | Listar todos            | 200               |
 * | GET         | /books/:id     | Buscar por ID           | 200 / 404         |
 * | POST        | /books         | Criar novo              | 201               |
 * | PUT         | /books/:id     | Atualizar completo      | 200 / 404         |
 * | DELETE      | /books/:id     | Excluir                 | 204 / 404         |
 * | GET         | /stats         | Estatísticas            | 200               |
 *
 * EXEMPLOS DE CURL:
 * -----------------
 * # Listar todos os livros
 * curl http://localhost:3000/books
 *
 * # Filtrar por gênero
 * curl "http://localhost:3000/books?genre=Ficção Científica"
 *
 * # Buscar por ID
 * curl http://localhost:3000/books/1
 *
 * # Criar livro
 * curl -X POST http://localhost:3000/books \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Duna","author":"Frank Herbert","genre":"Ficção Científica","year":1965}'
 *
 * # Atualizar livro
 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Duna (Edição Ilustrada)"}'
 *
 * # Excluir livro
 * curl -X DELETE http://localhost:3000/books/1
 *
 * # Estatísticas
 * curl http://localhost:3000/stats
 */

const express = require('express');
const router = express.Router(); // Router é um middleware contido que gerencia suas próprias rotas

const { findAll, findById, create, update, remove, getStats } = require('../models/book');
const { NotFoundError, ValidationError } = require('../utils/errors');

// ============================================================
// GET /books — Listar todos os livros (com filtragem opcional)
// ============================================================

/**
 * @route   GET /books
 * @desc    Retorna lista de todos os livros
 * @access  Public
 * @query   {string} [genre] - Filtrar por gênero
 * @query   {string} [author] - Filtrar por autor (parcial)
 * @query   {number} [minYear] - Filtrar por ano mínimo
 * @query   {number} [maxYear] - Filtrar por ano máximo
 * @returns {Array<Object>} Lista de livros
 *
 * EXEMPLO:
 * curl "http://localhost:3000/books?genre=Ficção%20Científica"
 */
router.get('/books', (req, res, next) => {
  try {
    let result = findAll();

    // Filtragem por gênero (case-insensitive)
    if (req.query.genre) {
      const genreFilter = req.query.genre.toLowerCase();
      result = result.filter((book) =>
        book.genre?.toLowerCase().includes(genreFilter)
      );
    }

    // Filtragem por autor (busca parcial, case-insensitive)
    if (req.query.author) {
      const authorFilter = req.query.author.toLowerCase();
      result = result.filter((book) =>
        book.author?.toLowerCase().includes(authorFilter)
      );
    }

    // Filtragem por faixa de ano
    if (req.query.minYear) {
      const minYear = parseInt(req.query.minYear, 10);
      result = result.filter((book) => book.year >= minYear);
    }
    if (req.query.maxYear) {
      const maxYear = parseInt(req.query.maxYear, 10);
      result = result.filter((book) => book.year <= maxYear);
    }

    res.json({
      count: result.length,
      data: result,
      // Inclui metadados de filtragem para transparência
      filters: req.query.genre || req.query.author || req.query.minYear || req.query.maxYear
        ? { ...req.query }
        : null,
    });
  } catch (err) {
    next(err); // Encaminha erro ao middleware de tratamento
  }
});

// ============================================================
// GET /books/stats — Estatísticas agregadas
// ============================================================

/**
 * @route   GET /books/stats
 * @desc    Retorna estatísticas sobre o acervo de livros
 * @access  Public
 * @returns {Object} Estatísticas: total, média de anos, distribuição por gênero, autores únicos
 *
 * EXEMPLO DE RESPOSTA:
 * {
 *   "total": 5,
 *   "averageYear": 1987.4,
 *   "genres": { "Ficção Científica": 2, "Romance": 1, "Sem gênero": 2 },
 *   "authors": ["Frank Herbert", "J.K. Rowling", " Machado de Assis"]
 * }
 */
router.get('/books/stats', (req, res, next) => {
  try {
    const stats = getStats();
    res.json({ data: stats });
  } catch (err) {
    next(err);
  }
});

// ============================================================
// GET /books/:id — Buscar livro por ID
// ============================================================

/**
 * @route   GET /books/:id
 * @desc    Retorna um livro específico pelo ID
 * @access  Public
 * @param   {number} id - ID numérico do livro
 * @returns {Object} Livro encontrado
 * @throws  {NotFoundError} Se o livro não existir
 *
 * EXEMPLO:
 * curl http://localhost:3000/books/1
 */
router.get('/books/:id', (req, res, next) => {
  try {
    // Validação do parâmetro de rota
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('ID inválido. Deve ser um número inteiro.', [
        { field: 'id', message: 'deve ser um número válido' },
      ]);
    }

    const book = findById(id);
    if (!book) {
      // NotFoundError é uma classe customizada que carrega statusCode 404
      throw new NotFoundError('Livro', id);
    }

    res.json({ data: book });
  } catch (err) {
    next(err);
  }
});

// ============================================================
// POST /books — Criar novo livro
// ============================================================

/**
 * @route   POST /books
 * @desc    Cria um novo livro
 * @access  Public
 * @body    {Object} body - Dados do livro
 * @body    {string}  body.title - Título (obrigatório, mínimo 1 caractere)
 * @body    {string}  body.author - Autor (obrigatório, mínimo 1 caractere)
 * @body    {string}  [body.genre] - Gênero literário
 * @body    {number}  [body.year] - Ano de publicação (1000-2100)
 * @returns {Object} Livro criado com ID e timestamps
 * @throws  {ValidationError} Se os dados forem inválidos
 *
 * EXEMPLO DE CORPO:
 * {
 *   "title": "O Senhor dos Anéis",
 *   "author": "J.R.R. Tolkien",
 *   "genre": "Fantasia",
 *   "year": 1954
 * }
 *
 * EXEMPLO DE RESPOSTA (201 Created):
 * {
 *   "data": {
 *     "id": 6,
 *     "title": "O Senhor dos Anéis",
 *     "author": "J.R.R. Tolkien",
 *     "genre": "Fantasia",
 *     "year": 1954,
 *     "createdAt": "2024-01-15T10:30:00.000Z",
 *     "updatedAt": "2024-01-15T10:30:00.000Z"
 *   }
 * }
 */
router.post('/books', (req, res, next) => {
  try {
    const { title, author, genre, year } = req.body;

    // Validação dos campos obrigatórios
    const errors = [];
    if (!title || typeof title !== 'string' || title.trim().length === 0) {
      errors.push({ field: 'title', message: 'é obrigatório e deve ser uma string não vazia' });
    }
    if (!author || typeof author !== 'string' || author.trim().length === 0) {
      errors.push({ field: 'author', message: 'é obrigatório e deve ser uma string não vazia' });
    }
    if (year !== undefined && year !== null) {
      const yearNum = parseInt(year, 10);
      if (isNaN(yearNum) || yearNum < 1000 || yearNum > 2100) {
        errors.push({ field: 'year', message: 'deve ser um número entre 1000 e 2100' });
      }
    }

    if (errors.length > 0) {
      throw new ValidationError('Validação falhou. Verifique os campos destacados.', errors);
    }

    const newBook = create({
      title: title.trim(),
      author: author.trim(),
      genre: genre ? genre.trim() : null,
      year: year ? parseInt(year, 10) : null,
    });

    /**
     * 201 Created indica que o recurso foi criado com sucesso.
     * O corpo contém o livro criado; o header Location aponta para a URL do novo recurso.
     */
    res.status(201).json({ data: newBook });
  } catch (err) {
    next(err);
  }
});

// ============================================================
// PUT /books/:id — Atualizar livro existente
// ============================================================

/**
 * @route   PUT /books/:id
 * @desc    Atualiza completamente um livro existente
 * @access  Public
 * @param   {number} id - ID do livro a atualizar
 * @body    {Object} body - Dados completos do livro
 * @body    {string}  body.title - Título (obrigatório)
 * @body    {string}  body.author - Autor (obrigatório)
 * @body    {string}  [body.genre] - Gênero
 * @body    {number}  [body.year] - Ano de publicação
 * @returns {Object} Livro atualizado
 * @throws  {NotFoundError} Se o livro não existir
 * @throws  {ValidationError} Se os dados forem inválidos
