 * curl -X PUT http://localhost:3000/books/1 \
 *   -H "Content-Type: application/json" \
 *   -d '{"title":"Dom Casmurro","author":"Machado de Assis","genre":"Romance","year":1899}'
 */
router.put('/books/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('ID inválido.', [
        { field: 'id', message: 'deve ser um número válido' },
      ]);
    }

    // Verifica se o livro existe antes de atualizar
    const existing = findById(id);
    if (!existing) {
      throw new NotFoundError('Livro', id);
    }

    const { title, author, genre, year } = req.body;

    // Validação
    const errors = [];
    if (!title || typeof title !== 'string' || title.trim().length === 0) {
      errors.push({ field: 'title', message: 'é obrigatório' });
    }
    if (!author || typeof author !== 'string' || author.trim().length === 0) {
      errors.push({ field: 'author', message: 'é obrigatório' });
    }
    if (year !== undefined && year !== null) {
      const yearNum = parseInt(year, 10);
      if (isNaN(yearNum) || yearNum < 1000 || yearNum > 2100) {
        errors.push({ field: 'year', message: 'deve ser entre 1000 e 2100' });
      }
    }

    if (errors.length > 0) {
      throw new ValidationError('Validação falhou.', errors);
    }

    const updated = update(id, {
      title: title.trim(),
      author: author.trim(),
      genre: genre ? genre.trim() : null,
      year: year ? parseInt(year, 10) : null,
    });

    res.json({ data: updated });
  } catch (err) {
    next(err);
  }
});

// ============================================================
// DELETE /books/:id — Excluir livro
// ============================================================

/**
 * @route   DELETE /books/:id
 * @desc    Remove um livro pelo ID
 * @access  Public
 * @param   {number} id - ID do livro a excluir
 * @returns {null} 204 No Content em caso de sucesso
 * @throws  {NotFoundError} Se o livro não existir
 *
 * NOTA: DELETE retorna 204 (No Content) quando bem-sucedido,
 * conforme convenção REST. Não há corpo na resposta.
 *
 * EXEMPLO:
 * curl -X DELETE http://localhost:3000/books/1
 */
router.delete('/books/:id', (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      throw new ValidationError('ID inválido.', [
        { field: 'id', message: 'deve ser um número válido' },
      ]);
    }

    const deleted = remove(id);
    if (!deleted) {
      throw new NotFoundError('Livro', id);
    }

    /**
     * 204 No Content — A exclusão foi bem-sucedida e não há conteúdo
     * para retornar no corpo da resposta. Isso é a convenção REST padrão.
     */
    res.status(204).end();
  } catch (err) {
    next(err);
  }
});

module.exports = router;
