## Arquivo 7: `src/app.js`

```javascript
/**
 * ============================================================
 * CONFIGURAÇÃO DA APLICAÇÃO EXPRESS
 * ============================================================
 *
 * POR QUE SEPARAR app.js DO server.js?
 * -------------------------------------
 * - app.js configura o Express (middleware, rotas) sem iniciar o servidor
 * - server.js apenas importa app e chama .listen()
 * - Isso permite testar a aplicação sem precisar de um servidor rodando
 *
 * ORDEM DE REGISTRO DOS MIDDLEWARES É CRÍTICA:
 * ---------------------------------------------
 * 1. body-parser → parseia o corpo das requisições JSON
 * 2. Rotas → processa as requisições
 * 3. notFoundHandler → captura rotas não mapeadas (DEVE vir após as rotas)
 * 4. errorHandler → captura erros lançados por qualquer middleware anterior
 */

const express = require('express');
const booksRouter = require('./routes/books');
const notFoundHandler = require('./middleware/notFound');
const errorHandler = require('./middleware/errorHandler');

const app = express();

/**
 * Middleware para parsear JSON no corpo das requisições.
 * limit: '10kb' previne requisições excessivamente grandes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware de logging simples — registra método, URL e timestamp.
 * Em produção, substitua por um logger como winston ou pino.
 */
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.originalUrl}`);
  next();
});

/**
 * Registra as rotas de livros sob o prefixo /books.
 * Todas as rotas definidas em routes/books.js serão acessíveis
 * como /books/..., /books/stats, etc.
 */
app.use('/books', booksRouter);

/**
 * Middleware 404 — deve ser registrado APÓS todas as rotas.
 * Se nenhuma rota corresponder, esta função é invocada.
 */
app.use(notFoundHandler);

/**
 * Middleware de tratamento de erros — deve ser o ÚLTIMO middleware.
 * Captura erros lançados via next(err) em qualquer middleware anterior.
 * A assinatura com 4 parâmetros (err, req, res, next) é o que identifica
 * um middleware de erro no Express.
 */
app.use(errorHandler);

module.exports = app;
```

