## 📄 `server.js` — Application Entry Point

This file wires together Express, middleware, routes, and the global error handler. We keep it thin so that concerns are separated: routing lives in `routes/`, data logic in `data/`, and errors in `middleware/`.

```javascript
/**
 * server.js — Main entry point for the Book REST API.
 *
 * WHY this structure?
 * -------------------
 * Express apps follow a "middleware pipeline" pattern. Each middleware
 * function runs in order, giving us logging → parsing → routing → error handling.
 * By keeping route definitions out of this file, we maintain separation of concerns:
 *   - server.js  : app configuration & wiring
 *   - routes/    : business logic per endpoint
 *   - data/      : storage abstraction (could swap in a DB later)
 *   - middleware/ : cross-cutting concerns (errors, validation, logging)
 *
 * We use `express.json()` to parse incoming JSON request bodies. Without it,
 * POST/PUT payloads would be undefined when we try to read req.body.
 */

const express = require('express');
const bookRoutes = require('./routes/books');
const { errorHandler } = require('./middleware/errors');

// Create the Express application instance.
// `express()` returns a function that also acts as the HTTP request handler.
const app = express();

// ─── Middleware Registration (runs on EVERY request) ────────────────────────

/**
 * Why register middleware BEFORE routes?
 * Express executes middleware in the order it's registered. Logging and body
 * parsing must happen before routing so that:
 *   1. Every request is logged regardless of whether a route matches.
 *   2. req.body is populated before any route handler tries to read it.
 */

//morgan-style simple logger — logs method, URL, and response status code.
app.use((req, res, next) => {
  const start = Date.now();
  // `res.on('finish')` fires after the response is sent, giving us total time.
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(
      `[${new Date().toISOString()}] ${req.method} ${req.originalUrl} → ` +
      `${res.statusCode}  (${duration}ms)`
    );
  });
  next();
});

// Parse JSON request bodies up to 10kb (default is 100kb, but books are small).
app.use(express.json({ limit: '10kb' }));

// ─── Route Registration ─────────────────────────────────────────────────────

/**
 * WHY mount routes at '/api/v1'?
 * Versioning the API URL (e.g., /api/v1/) lets us evolve the schema without
 * breaking existing clients. If we later need a v2, we can add /api/v2/ alongside.
 */
app.use('/api/v1/books', bookRoutes);

// ─── 404 Fallback for Unmatched Routes ──────────────────────────────────────

/**
 * This middleware runs AFTER all route definitions. If no route matched the
 * URL, Express falls through to this handler and returns a 404.
 * Placing it here (not at the top) ensures actual routes take priority.
 */
app.use((req, res, next) => {
  const err = new Error(`Route ${req.method} ${req.originalUrl} not found`);
  err.statusCode = 404;
  next(err); // Pass to the global error handler below
});

// ─── Global Error-Handling Middleware ─────────────────────────────────────────

/**
 * Express recognizes error-handling middleware by its signature:
 *   (err, req, res, next) => ...
 * Any middleware that calls `next(err)` will land here. We respond with a
 * consistent JSON error shape so API consumers can parse errors uniformly.
 */
app.use(errorHandler);

// ─── Start the Server ────────────────────────────────────────────────────────

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`📚 Book API running on http://localhost:${PORT}`);
  console.log(`   Try: GET  http://localhost:${PORT}/api/v1/books`);
  console.log(`        POST http://localhost:${PORT}/api/v1/books`);
});

module.exports = app;
```

