## 📄 `data/books.js` — In-Memory Storage Layer

This module encapsulates all data operations. By isolating storage logic here, we can swap the in-memory array for a database later without touching route handlers.

```javascript
/**
 * data/books.js — In-memory book store with CRUD operations.
 *
 * WHY use an array instead of an object map?
 * -------------------------------------------
 * An array is simple and preserves insertion order (useful for pagination).
 * For a small educational dataset, lookup by scanning is acceptable.
 * In production, we'd use a Map or database for O(1) lookups by ID.
 *
 * WHY export functions instead of mutating directly in routes?
 * -------------------------------------------------------------
 * Keeping data logic in a dedicated module creates a single source of truth.
 * Routes call these functions rather than manipulating state themselves,
 * which makes testing and future refactoring (e.g., adding a DB) straightforward.
 */

// ─── Data Structure ──────────────────────────────────────────────────────────

/**
 * Each book object follows this shape:
 * {
 *   id: number          — auto-incremented unique identifier
 *   title: string       — book title (required)
 *   author: string      — primary author name (required)
 *   genre: string       — e.g., "Fiction", "Science" (optional)
 *   publishedYear: number — year of publication (optional)
 *   rating: number      — float between 0 and 5 (optional)
 * }
 */

/** @type {import('express').Request[]} */
let books = [
  {
    id: 1,
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    genre: 'Fiction',
    publishedYear: 1925,
    rating: 4.2,
  },
  {
    id: 2,
    title: 'A Brief History of Time',
    author: 'Stephen Hawking',
    genre: 'Science',
    publishedYear: 1988,
    rating: 4.6,
  },
  {
    id: 3,
    title: 'Dune',
    author: 'Frank Herbert',
    genre: 'Science Fiction',
    publishedYear: 1965,
    rating: 4.8,
  },
];

/** @type {number} Tracks the next ID to assign (prevents collisions). */
let nextId = 4;

// ─── Helper: Generate Unique ID ──────────────────────────────────────────────

/**
 * Returns an incrementing integer guaranteed to be unique within this session.
 * In a real app, we'd use UUIDs or let the database handle IDs.
 */
function generateId() {
  return nextId++;
}

// ─── GET All Books (with optional filtering) ─────────────────────────────────

/**
 * Retrieves all books, optionally filtered by query parameters.
 *
 * @param {object} [filters] — Optional filter criteria:
 *   @param {string}  [filters.genre]      — Exact genre match (case-insensitive)
 *   @param {string}  [filters.author]     — Substring match on author name
 *   @param {number}  [filters.minRating]  — Minimum rating threshold (0–5)
 *   @param {number}  [filters.publishedAfter] — Only books published after this year
 *
 * @returns {Array<object>} Filtered list of book objects.
 *
 * WHY return a new array instead of mutating `books`?
 * ---------------------------------------------------
 * We never mutate the source array during filtering; we create a filtered copy.
 * This prevents accidental side effects and keeps the original data intact.
 */
function getAllBooks(filters = {}) {
  let result = books;

  // Apply genre filter (case-insensitive exact match).
  if (filters.genre) {
    const normalizedGenre = filters.genre.toLowerCase();
    result = result.filter((book) => book.genre?.toLowerCase() === normalizedGenre);
  }

  // Apply author filter (substring, case-insensitive).
  if (filters.author) {
    const normalizedAuthor = filters.author.toLowerCase();
    result = result.filter((book) => book.author?.toLowerCase().includes(normalizedAuthor));
  }

  // Apply minimum rating filter.
  if (filters.minRating != null) {
    result = result.filter((book) => book.rating >= Number(filters.minRating));
  }

  // Apply published-after year filter.
  if (filters.publishedAfter != null) {
    result = result.filter((book) => book.publishedYear > Number(filters.publishedAfter));
  }

  return result;
}

// ─── GET Single Book by ID ───────────────────────────────────────────────────

/**
 * Finds a single book by its numeric ID.
 *
 * @param {number} id — The unique identifier of the book.
 * @returns {object|null} The book object, or null if not found.
 *
 * WHY return null instead of throwing?
 * ------------------------------------
 * "Not found" is a normal operational state (client may request a deleted item).
 * We let route handlers decide whether to throw a 404 or return null.
 */
function getBookById(id) {
  return books.find((book) => book.id === Number(id)) || null;
}

// ─── CREATE New Book ─────────────────────────────────────────────────────────

/**
 * Creates a new book and appends it to the in-memory store.
 *
 * @param {object} bookData — Partial or full book object (id is auto-generated).
 * @returns {object} The newly created book with its assigned ID.
 *
 * WHY spread `...bookData` and then override `id`?
 * -------------------------------------------------
 * This ensures the caller can pass any subset of fields, but we always control
 * the ID generation to guarantee uniqueness.
 */
function createBook(bookData) {
  const newBook = {
    id: generateId(),
    ...bookData,
    // Ensure rating is a number between 0 and 5 if provided.
    ...(bookData.rating != null ? { rating: Number(bookData.rating) } : {}),
  };
  books.push(newBook);
  return newBook;
}

// ─── UPDATE Existing Book (Full Replace via PUT) ─────────────────────────────

/**
 * Replaces an existing book entirely with the provided data.
 * The `id` field from `bookData` is ignored — we use the URL-provided ID.
 *
 * @param {number} id        — The ID of the book to update.
 * @param {object} bookData  — New book data (all fields replaced).
 * @returns {object|null}    — The updated book, or null if not found.
 *
 * WHY full replacement instead of partial merge?
 * -----------------------------------------------
 * PUT is defined by REST semantics as a full resource replacement.
 * For partial updates, clients should use PATCH (not implemented here for brevity).
 */
function updateBook(id, bookData) {
  const index = books.findIndex((book) => book.id === Number(id));
  if (index === -1) return null;

  // Preserve the original ID; replace all other fields.
  books[index] = {
    id: Number(id),
    ...bookData,
    ...(bookData.rating != null ? { rating: Number(bookData.rating) } : {}),
  };
  return books[index];
}

// ─── DELETE Book by ID ───────────────────────────────────────────────────────

/**
 * Removes a book from the store by its ID.
 *
 * @param {number} id — The unique identifier of the book to delete.
 * @returns {boolean}  — true if a book was removed, false if not found.
 *
 * WHY use `splice` instead of `filter`?
 * --------------------------------------
 * `splice` mutates in place and is O(n) but avoids creating a new array copy.
 * For small datasets this is negligible; for large ones we'd prefer filter + reassign.
 */
function deleteBook(id) {
  const index = books.findIndex((book) => book.id === Number(id));
  if (index === -1) return false;

  books.splice(index, 1);
  return true;
}

// ─── GET Statistics ──────────────────────────────────────────────────────────

/**
 * Computes aggregate statistics across all books.
 *
 * @returns {object} Statistics including:
 *   totalBooks       — count of all books
 *   averageRating    — mean rating (rounded to 2 decimals)
 *   genres           — object mapping genre → book count
 *   oldestPublication — earliest published year
 *   newestPublication — latest published year
 *
 * WHY compute stats on every request instead of caching?
 * -------------------------------------------------------
 * For an in-memory educational API, the dataset is tiny. Caching adds complexity
 * (invalidation logic) with no real benefit. In production, we'd cache and
 * invalidate on mutations.
 */
function getStats() {
  const totalBooks = books.length;

  if (totalBooks === 0) {
    return {
      totalBooks: 0,
      averageRating: null,
      genres: {},
      oldestPublication: null,
      newestPublication: null,
    };
  }

  // Reduce to compute sum of ratings.
  const totalRating = books.reduce((sum, book) => sum + (book.rating || 0), 0);
  const averageRating = Math.round((totalRating / totalBooks) * 100) / 100;

  // Group by genre using reduce for O(n) single-pass counting.
  const genres = books.reduce((acc, book) => {
    const genre = book.genre || 'Unknown';
    acc[genre] = (acc[genre] || 0) + 1;
    return acc;
  }, {});

  // Extract publication years (filter out nulls).
  const years = books.map((book) => book.publishedYear).filter(Boolean);
  const oldestPublication = years.length ? Math.min(...years) : null;
  const newestPublication = years.length ? Math.max(...years) : null;

  return {
    totalBooks,
    averageRating,
    genres,
    oldestPublication,
    newestPublication,
  };
}

// ─── Module Exports ──────────────────────────────────────────────────────────

module.exports = {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
};
```

