## 📄 `routes/books.js` — Route Handlers

This file defines every HTTP endpoint. Each handler validates input, calls the data layer, and returns a properly shaped JSON response.

```javascript
/**
 * routes/books.js — Express route handlers for book resources.
 *
 * WHY separate routes from data logic?
 * -------------------------------------
 * Routes handle HTTP concerns (status codes, headers, validation).
 * Data handles storage concerns (queries, mutations). This separation lets us:
 *   - Test routing logic independently of storage.
 *   - Swap the data layer without rewriting route handlers.
 *   - Keep each file focused and readable.
 *
 * WHY use async/await even though our data is synchronous?
 * ---------------------------------------------------------
 * Real APIs eventually connect to databases (MongoDB, PostgreSQL) which are async.
 * Writing routes with async/await now means zero refactor when we add a DB later.
 * It also lets us use try/catch for clean error handling.
 */

const express = require('express');
const router = express.Router();
const {
  getAllBooks,
  getBookById,
  createBook,
  updateBook,
  deleteBook,
  getStats,
} = require('../data/books');
const { NotFoundError, ValidationError } = require('../middleware/errors');

// ─── GET /api/v1/books — List All Books (with optional filters) ──────────────

/**
 * @route   GET /api/v1/books
 * @desc    Retrieve a list of all books, optionally filtered.
 * @access  Public
 *
 * Query Parameters (all optional):
 *   - genre        : Exact genre match (e.g., ?genre=Fiction)
 *   - author       : Substring search on author name (e.g., ?author=hawking)
 *   - minRating    : Minimum rating threshold 0–5 (e.g., ?minRating=4.0)
 *   - publishedAfter: Only books published after this year (e.g., ?publishedAfter=1960)
 *
 * @responseBody {Array<object>} List of book objects
 *
 * Example curl:
 *   curl http://localhost:3000/api/v1/books?genre=Fiction&minRating=4.0
 */
router.get('/', (req, res) => {
  try {
    // Destructure only the filter params we care about; ignore the rest.
    const { genre, author, minRating, publishedAfter } = req.query;

    /** @type {object} Build a filters object only including defined values. */
    const filters = {};
    if (genre) filters.genre = genre;
    if (author) filters.author = author;
    if (minRating) filters.minRating = minRating;
    if (publishedAfter) filters.publishedAfter = publishedAfter;

    const result = getAllBooks(filters);

    // 200 OK with the filtered book list.
    res.json({
      success: true,
      count: result.length,
      data: result,
    });
  } catch (error) {
    // Re-throw so the global error handler can format the response.
    next(error);
  }
});

// ─── GET /api/v1/books/:id — Get Single Book ─────────────────────────────────

/**
 * @route   GET /api/v1/books/:id
 * @desc    Retrieve a single book by its numeric ID.
 * @access  Public
 *
 * URL Parameters:
 *   - id : Integer book ID (e.g., /books/1)
 *
 * @responseBody {object} Single book object wrapped in success envelope
 *
 * Example curl:
 *   curl http://localhost:3000/api/v1/books/1
 */
router.get('/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    // Validate that the ID is a positive integer.
    if (isNaN(id) || id < 1) {
      throw new ValidationError('Invalid book ID: must be a positive integer');
    }

    const book = getBookById(id);
    if (!book) {
      throw new NotFoundError(`Book with id ${id} not found`);
    }

    res.json({
      success: true,
      data: book,
    });
  } catch (error) {
    next(error); // Pass to global error handler
  }
});

// ─── POST /api/v1/books — Create a New Book ──────────────────────────────────

/**
 * @route   POST /api/v1/books
 * @desc    Create a new book resource.
 * @access  Public
 *
 * Request Body (JSON):
 *   {
 *     "title": "String (required)",
 *     "author": "String (required)",
 *     "genre": "String (optional)",
 *     "publishedYear": Number (optional),
 *     "rating": Number 0-5 (optional)
 *   }
 *
 * @responseBody {object} The newly created book with assigned ID
 *
 * Example curl:
 *   curl -X POST http://localhost:3000/api/v1/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","genre":"Dystopian","publishedYear":1949,"rating":4.7}'
 */
router.post('/', (req, res, next) => {
  try {
    const { title, author, genre, publishedYear, rating } = req.body;

    // Validate required fields.
    if (!title || !author) {
      throw new ValidationError('Title and author are required fields');
    }

    /** @type {object} Build the book object, only including defined values. */
    const bookData = { title, author };
    if (genre) bookData.genre = genre;
    if (publishedYear) bookData.publishedYear = Number(publishedYear);
    if (rating != null) {
      const ratingNum = Number(rating);
      if (ratingNum < 0 || ratingNum > 5) {
        throw new ValidationError('Rating must be between 0 and 5');
      }
      bookData.rating = ratingNum;
    }

    const newBook = createBook(bookData);

    // 201 Created is the standard status for resource creation.
    res.status(201).json({
      success: true,
      data: newBook,
    });
  } catch (error) {
    next(error);
  }
});

// ─── PUT /api/v1/books/:id — Update an Existing Book ─────────────────────────

/**
 * @route   PUT /api/v1/books/:id
 * @desc    Fully replace an existing book's data.
 * @access  Public
 *
 * URL Parameters:
 *   - id : Integer book ID
 *
 * Request Body (JSON): Same shape as POST /books
 *
 * @responseBody {object} The updated book object
 *
 * Example curl:
 *   curl -X PUT http://localhost:3000/api/v1/books/1 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"The Great Gatsby (Updated)","author":"F. Scott Fitzgerald","rating":4.5}'
 */
router.put('/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('Invalid book ID: must be a positive integer');
    }

    const existingBook = getBookById(id);
    if (!existingBook) {
      throw new NotFoundError(`Book with id ${id} not found`);
    }

    // Validate rating if provided.
    if (req.body.rating != null) {
      const ratingNum = Number(req.body.rating);
      if (ratingNum < 0 || ratingNum > 5) {
        throw new ValidationError('Rating must be between 0 and 5');
      }
    }

    const updatedBook = updateBook(id, req.body);

    res.json({
      success: true,
      data: updatedBook,
    });
  } catch (error) {
    next(error);
  }
});

// ─── DELETE /api/v1/books/:id — Delete a Book ────────────────────────────────

/**
 * @route   DELETE /api/v1/books/:id
 * @desc    Remove a book by its ID.
 * @access  Public
 *
 * URL Parameters:
 *   - id : Integer book ID
 *
 * @responseBody {object} Confirmation message
 *
 * Example curl:
 *   curl -X DELETE http://localhost:3000/api/v1/books/2
 */
router.delete('/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    if (isNaN(id) || id < 1) {
      throw new ValidationError('Invalid book ID: must be a positive integer');
    }

    const deleted = deleteBook(id);
    if (!deleted) {
      throw new NotFoundError(`Book with id ${id} not found`);
    }

    // 200 OK with a confirmation message.
    res.json({
      success: true,
      message: `Book with id ${id} has been deleted`,
    });
  } catch (error) {
    next(error);
  }
});

// ─── GET /api/v1/books/stats — Aggregate Statistics ──────────────────────────

/**
 * @route   GET /api/v1/books/stats
 * @desc    Return aggregate statistics about the book collection.
 * @access  Public
 *
 * @responseBody {object} Statistics including totalBooks, averageRating,
 *                        genres breakdown, oldest/newest publication years
 *
 * Example curl:
 *   curl http://localhost:3000/api/v1/books/stats
 */
router.get('/stats', (req, res) => {
  try {
    const stats = getStats();

    res.json({
      success: true,
      data: stats,
    });
  } catch (error) {
    next(error);
  }
});

module.exports = router;
```

