## 📄 `middleware/errors.js` — Custom Error Classes & Global Handler

Centralized error handling ensures every API response follows the same shape, making it easy for clients to parse both success and error cases.

```javascript
/**
 * middleware/errors.js — Custom error classes and global error-handling middleware.
 *
 * WHY create custom error classes instead of using plain Error?
 * -------------------------------------------------------------
 * Custom classes let us attach a `statusCode` property, so the error handler
 * can automatically map errors to HTTP status codes without switch/if-else chains.
 * This is cleaner than checking error messages or types manually.
 *
 * WHY a single global error handler instead of try/catch in every route?
 * ----------------------------------------------------------------------
 * While we do use try/catch in routes, the global handler acts as a safety net
 * for any errors that slip through (e.g., unhandled rejections, middleware bugs).
 * It also guarantees a consistent JSON error shape across ALL error types.
 */

// ─── Custom Error Classes ─────────────────────────────────────────────────────

/**
 * Base class for all API errors. Attaches an HTTP status code so the handler
 * can respond with the correct status without hardcoding per-error-type logic.
 */
class ApiError extends Error {
  /**
   * @param {string} message — Human-readable error description.
   * @param {number} statusCode — HTTP status code (default 400).
   */
  constructor(message, statusCode = 400) {
    super(message);
    this.statusCode = statusCode;
    // Preserve stack trace for server logs.
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * Thrown when a requested resource does not exist.
 * Maps to HTTP 404 Not Found.
 */
class NotFoundError extends ApiError {
  constructor(message = 'Resource not found') {
    super(message, 404);
  }
}

/**
 * Thrown when client input fails validation.
 * Maps to HTTP 400 Bad Request.
 */
class ValidationError extends ApiError {
  constructor(message = 'Validation failed') {
    super(message, 400);
  }
}

// ─── Global Error-Handling Middleware ──────────────────────────────────────────

/**
 * Express error-handling middleware signature: (err, req, res, next).
 * This MUST be the last middleware registered; otherwise unmatched routes
 * would never reach it.
 *
 * @param {ApiError} err — Any Error instance (custom or built-in).
 * @param {express.Request} req — The Express request object.
 * @param {express.Response} res — The Express response object.
 * @param {function} next — Unused in error handlers (by convention).
 */
function errorHandler(err, req, res, next) {
  // Log the full error (including stack) for server-side debugging.
  console.error(`[ERROR] ${err.statusCode || 500} — ${err.message}`);
  if (process.env.NODE_ENV !== 'production') {
    console.error(err.stack);
  }

  // Default to 500 for unexpected errors; use err.statusCode for known ones.
  const statusCode = err.statusCode || 500;

  /**
   * Consistent JSON error shape:
   * { success: false, error: { message, statusCode } }
   * Clients can check `success` to distinguish errors from successes.
   */
  res.status(statusCode).json({
    success: false,
    error: {
      message: err.message,
      statusCode,
    },
  });
}

// ─── Module Exports ──────────────────────────────────────────────────────────

module.exports = {
  ApiError,
  NotFoundError,
  ValidationError,
  errorHandler,
};
```

