## Arquivo 2: `src/errors.js` — Classes de Erro Personalizadas

```javascript
/**
 * ============================================================
 * src/errors.js
 * ============================================================
 *
 * CLASSES DE ERRO PERSONALIZADAS
 *
 * Por que criar classes de erro personalizadas?
 * ----------------------------------------------
 * Em vez de simplesmente lançar strings ou objetos genéricos,
 * criamos uma hierarquia de classes que herda de Error. Isso nos
 * permite:
 *   1. Identificar o TIPO de erro com instanceof
 *   2. Incluir campos extras (como statusCode e details)
 *   3. Manter um stack trace limpo e útil para debugging
 *   4. Centralizar a lógica de resposta de erro no middleware
 *
 * Padrão adotado: A hierarquia segue o padrão "Error Hierarchy"
 * comum em frameworks como Django e Spring, onde erros específicos
 * herdam de um erro base mais genérico.
 */

/**
 * Classe base para todos os erros da API.
 *
 * Herda de Error nativo do Node.js para preservar o stack trace.
 * Adiciona statusCode (HTTP status) e details (informações extras).
 */
class ApiError extends Error {
  /**
   * @param {string} message - Mensagem descritiva do erro
   * @param {number} statusCode - Código HTTP de resposta (padrão: 500)
   * @param {object|null} details - Detalhes adicionais do erro (padrão: null)
   */
  constructor(message, statusCode = 500, details = null) {
    super(message); // Chama o construtor da classe Error nativa

    // Preservamos o nome da classe para identificação correta
    this.name = 'ApiError';

    // Definimos o código HTTP que será retornado ao cliente
    this.statusCode = statusCode;

    // Campos extras que podem ajudar no debugging ou na resposta
    this.details = details;

    // Capturamos o stack trace no momento da criação do erro.
    // Em Node.js, o Error.captureStackTrace otimiza o stack para
    // excluir frames internos do construtor, tornando-o mais limpo.
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, this.constructor);
    }
  }

  /**
   * Converte o erro em um objeto JSON padronizado para resposta da API.
   * Isso garante que todos os erros tenham a mesma estrutura na response.
   *
   * @returns {object} Objeto com message, statusCode e optionally details
   */
  toJSON() {
    const response = {
      error: this.name,       // Nome da classe de erro (ex: "NotFoundError")
      message: this.message,  // Mensagem legível para o cliente
      statusCode: this.statusCode
    };

    // Se houver detalhes extras, os incluímos na resposta
    if (this.details) {
      response.details = this.details;
    }

    return response;
  }
}

/**
 * Erro 400 — Bad Request.
 * Usado quando o cliente envia dados inválidos ou mal formatados.
 * Exemplo: ID não numérico, campos obrigatórios ausentes.
 */
class BadRequestError extends ApiError {
  constructor(message = 'Requisição inválida', details = null) {
    super(message, 400, details); // StatusCode 400 = Bad Request
    this.name = 'BadRequestError';
  }
}

/**
 * Erro 404 — Not Found.
 * Usado quando o recurso solicitado não existe.
 * Exemplo: Livro com ID inexistente.
 */
class NotFoundError extends ApiError {
  constructor(message = 'Recurso não encontrado') {
    super(message, 404, null); // StatusCode 404 = Not Found
    this.name = 'NotFoundError';
  }
}

/**
 * Erro 409 — Conflict.
 * Usado quando há conflito com o estado atual do servidor.
 * Exemplo: Tentar criar um livro com ID duplicado.
 */
class ConflictError extends ApiError {
  constructor(message = 'Conflito com recurso existente') {
    super(message, 409, null); // StatusCode 409 = Conflict
    this.name = 'ConflictError';
  }
}

/**
 * Erro 500 — Internal Server Error.
 * Usado para erros inesperados no servidor.
 * Em produção, nunca expomos detalhes internos ao cliente.
 */
class InternalServerError extends ApiError {
  constructor(message = 'Erro interno do servidor') {
    super(message, 500, null); // StatusCode 500 = Internal Server Error
    this.name = 'InternalServerError';
  }
}

// Exportamos todas as classes para uso nos módulos de rota e middleware
module.exports = {
  ApiError,
  BadRequestError,
  NotFoundError,
  ConflictError,
  InternalServerError
};
```

