## Arquivo 3: `src/middleware/errorHandler.js` — Middleware de Tratamento de Erros

```javascript
/**
 * ============================================================
 * src/middleware/errorHandler.js
 * ============================================================
 *
 * MIDDLEWARE DE TRATAMENTO DE ERROS
 *
 * Por que um middleware dedicado para erros?
 * -------------------------------------------
 * No Express, middlewares de erro são funções com 4 parâmetros:
 *   (error, req, res, next)
 *
 * O Express identifica automaticamente um middleware como handler
 * de erros quando ele tem exatamente 4 parâmetros. Isso nos permite
 * centralizar todo o tratamento de erros em UM único lugar, em vez
 * de repetir blocos try/catch em cada rota.
 *
 * Padrão adotado: "Centralized Error Handling" — todos os erros são
 * capturados e formatados consistentemente antes de serem enviados
 * ao cliente. Isso garante que a API tenha respostas de erro uniformes.
 */

const { ApiError } = require('../errors');

/**
 * Middleware principal de tratamento de erros.
 *
 * Este middleware é registrado APÓS todas as rotas no app.js.
 * Ele captura erros lançados por:
 *   - Erros síncronos (throw new Error(...))
 *   - Erros assíncronos capturados pelo wrapAsync()
 *   - Erros não tratados em middlewares anteriores
 *
 * @param {ApiError} error - Instância de ApiError ou Error genérico
 * @param {object} req - Objeto de requisição do Express
 * @param {object} res - Objeto de resposta do Express
 * @param {function} next - Função next do Express (não usada aqui)
 */
const errorHandler = (error, req, res, next) => {
  // Determinamos o statusCode: se for ApiError personalizado, usamos o dele;
  // caso contrário, assumimos 500 para erros genéricos não tratados.
  const statusCode = error.statusCode || 500;

  // Em desenvolvimento, incluímos o stack trace na resposta para facilitar debugging.
  // Em produção, isso seria um risco de segurança (exposição de caminhos internos).
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Construímos a resposta padronizada
  const response = {
    error: error.name || 'Error',
    message: error.message,
    statusCode
  };

  // Se o erro tiver detalhes extras (ex: validação falhou), incluímos
  if (error.details) {
    response.details = error.details;
  }

  // Em desenvolvimento, adicionamos o stack trace para debugging
  if (isDevelopment && error.stack) {
    response.stack = error.stack;
  }

  // Enviamos a resposta com o status HTTP apropriado e corpo JSON
  res.status(statusCode).json(response);
};

/**
 * Função wrapper para middlewares assíncronos.
 *
 * PROBLEMA: O Express NÃO captura automaticamente erros lançados
 * dentro de funções async. Se você fizer:
 *   router.get('/', async (req, res) => { throw new Error('ops'); })
 * O erro será um "UnhandledPromiseRejection" e o servidor pode crashar.
 *
 * SOLUÇÃO: Este wrapper captura erros assíncronos e os passa para
 * o next(error), que é capturado pelo middleware errorHandler.
 *
 * @param {function} fn - Função async do Express (req, res, next)
 * @returns {function} Função wrapper que captura erros assíncronos
 */
const wrapAsync = (fn) => {
  return (req, res, next) => {
    // Executamos a função original e capturamos rejeições de Promise
    Promise.resolve(fn(req, res, next)).catch(next);
    // O .catch(next) é equivalente a:
    //   .catch(error => next(error))
    // Isso passa o erro para o middleware errorHandler.
  };
};

module.exports = {
  errorHandler,
  wrapAsync
};
```

