## Arquivo 4: `src/data/books.js` — Armazenamento em Memória

```javascript
/**
 * ============================================================
 * src/data/books.js
 * ============================================================
 *
 * ARMAZENAMENTO EM MEMÓRIA (IN-MEMORY STORE)
 *
 * Por que usar um array em memória?
 * ----------------------------------
 * Para este exemplo educacional, usamos um array simples porque:
 *   1. Não requer configuração de banco de dados
 *   2. Facilita o entendimento dos conceitos de CRUD
 *   3. Permite focar na API REST sem distrações de infraestrutura
 *
 * Em produção, substituiríamos este módulo por um serviço que
 * conecta a um banco de dados (MongoDB, PostgreSQL, etc.).
 * A vantagem é que as rotas não precisam saber onde os dados
 * estão armazenados — apenas chamam funções deste módulo.
 *
 * Padrão adotado: "Repository Pattern" — isolamos a lógica de
 * acesso a dados em um módulo separado das rotas. Isso permite
 * trocar o storage (array → DB) sem alterar as rotas.
 */

// Array que armazena todos os livros em memória.
// Escolhemos array porque:
//   - A ordem de inserção é preservada (diferente de objetos)
//   - Métodos nativos como filter(), map(), findIndex() são intuitivos
//   - Para este exemplo didático, o tamanho é pequeno e não há necessidade
//     de índices complexos ou queries avançadas
const books = [];

/**
 * Gera um ID único simples para novos livros.
 *
 * Em produção, usaríamos UUIDs ou IDs do banco de dados.
 * Aqui usamos Date.now() que retorna milissegundos desde epoch,
 * garantindo unicidade para livros criados em momentos diferentes.
 *
 * @returns {number} ID único baseado no timestamp atual
 */
const generateId = () => Date.now();

/**
 * Cria um novo livro e o adiciona ao array.
 *
 * @param {object} bookData - Dados do livro a ser criado
 * @param {string} bookData.title - Título do livro (obrigatório)
 * @param {string} bookData.author - Autor do livro (obrigatório)
 * @param {string} [bookData.genre] - Gênero literário (opcional)
 * @param {number} [bookData.year] - Ano de publicação (opcional)
 * @returns {object} O livro criado com ID e timestamp adicionados
 */
const createBook = (bookData) => {
  const newBook = {
    id: generateId(),           // ID único gerado automaticamente
    title: bookData.title,
    author: bookData.author,
    genre: bookData.genre || null,   // Gênero é opcional; default null
    year: bookData.year || null,     // Ano é opcional; default null
    createdAt: new Date().toISOString() // Timestamp de criação em ISO 8601
  };

  books.push(newBook); // Adiciona ao final do array
  return newBook;      // Retorna o livro completo com ID
};

/**
 * Busca todos os livros no array.
 *
 * @returns {Array<object>} Lista de todos os livros
 */
const findAll = () => {
  return [...books]; // Retornamos uma cópia (spread) para evitar
                     // mutação externa direta do array original
};

/**
 * Busca um livro pelo ID.
 *
 * Usamos find() em vez de findIndex() porque:
 *   - find() retorna o objeto diretamente (mais legível)
 *   - É mais conciso e expressivo para busca por propriedade
 *
 * @param {number|string} id - ID do livro a ser buscado
 * @returns {object|null} O livro encontrado ou null se não existir
 */
const findById = (id) => {
  return books.find(book => book.id === id) || null;
};

/**
 * Atualiza um livro existente pelo ID.
 *
 * Usamos findIndex() aqui porque precisamos saber SE o livro existe
 * antes de atualizá-lo. Se não existir, retornamos null.
 *
 * @param {number|string} id - ID do livro a ser atualizado
 * @param {object} updates - Campos a serem atualizados (partial update)
 * @returns {object|null} O livro atualizado ou null se não existir
 */
const updateById = (id, updates) => {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return null; // Livro não encontrado
  }

  // Atualizamos apenas os campos fornecidos (partial update)
  // Isso permite atualizar título sem precisar enviar autor, etc.
  books[index] = {
    ...books[index],           // Mantém todos os campos existentes
    ...updates,                // Sobrescreve com os novos valores
    updatedAt: new Date().toISOString() // Timestamp de atualização
  };

  return books[index];
};

/**
 * Remove um livro pelo ID.
 *
 * @param {number|string} id - ID do livro a ser removido
 * @returns {boolean} true se removido, false se não encontrado
 */
const deleteById = (id) => {
  const index = books.findIndex(book => book.id === id);

  if (index === -1) {
    return false; // Livro não encontrado
  }

  books.splice(index, 1); // Remove exatamente 1 elemento no índice encontrado
  return true;
};

/**
 * Calcula estatísticas sobre os livros armazenados.
 *
 * Usamos reduce() para calcular múltiplas métricas em uma única
 * passagem pelo array — mais eficiente que fazer vários loops.
 *
 * @returns {object} Estatísticas: total, por gênero, média de anos, etc.
 */
const getStats = () => {
  const total = books.length;

  // Agrupamos livros por gênero usando reduce()
  // Isso cria um objeto onde cada chave é um gênero e o valor
  // é um array de livros daquele gênero
  const byGenre = books.reduce((acc, book) => {
    const genre = book.genre || 'Sem gênero'; // Livros sem gênero vão para "Sem gênero"

    if (!acc[genre]) {
      acc[genre] = [];
    }
    acc[genre].push(book);
    return acc;
  }, {});

  // Calculamos a média de anos de publicação (dos livros que têm ano)
  const booksWithYear = books.filter(b => b.year !== null && b.year !== undefined);
  const avgYear = booksWithYear.length > 0
    ? booksWithYear.reduce((sum, b) => sum + b.year, 0) / booksWithYear.length
    : null;

  // Contagem por gênero
  const genreCounts = {};
  for (const [genre, genreBooks] of Object.entries(byGenre)) {
    genreCounts[genre] = genreBooks.length;
  }

  return {
    total,
    byGenre: genreCounts,
    avgYear: avgYear ? Math.round(avgYear * 100) / 100 : null, // Arredondamos para 2 casas decimais
    booksWithYear: booksWithYear.length
  };
};

module.exports = {
  createBook,
  findAll,
  findById,
  updateById,
  deleteById,
  getStats
};
```

