## Arquivo 5: `src/routes/books.js` — Rotas de Livros

```javascript
/**
 * ============================================================
 * src/routes/books.js
 * ============================================================
 *
 * ROTAS DA API DE LIVROS
 *
 * Por que separar rotas em módulos?
 * ---------------------------------
 * O Express permite definir rotas em módulos separados usando
 * express.Router(). Isso oferece:
 *   1. Modularidade — cada recurso tem seu próprio arquivo
 *   2. Reusabilidade — o mesmo router pode ser montado em múltiplos paths
 *   3. Organização — facilita a manutenção e leitura do código
 *   4. Middleware específico — cada router pode ter seus próprios middlewares
 *
 * Convenções REST adotadas:
 *   - GET    /books       → Listar todos (com filtragem opcional)
 *   - GET    /books/:id   → Obter um livro pelo ID
 *   - POST   /books       → Criar novo livro
 *   - PUT    /books/:id   → Atualizar completamente um livro
 *   - DELETE /books/:id   → Remover um livro
 *
 * Padrão async/await: Usamos async/await em vez de .then() chains
 * porque é mais legível e se assemelha a código síncrono, facilitando
 * o entendimento do fluxo de execução. O wrapAsync() do middleware
 * cuida da captura de erros assíncronos.
 */

const express = require('express');
const router = express.Router(); // Cria um novo roteador Express

// Importamos as funções de dados e classes de erro
const { createBook, findAll, findById, updateById, deleteById } = require('../data/books');
const { BadRequestError, NotFoundError } = require('../errors');
const { wrapAsync } = require('../middleware/errorHandler');

/**
 * GET /books
 * Lista todos os livros com filtragem opcional.
 *
 * Parâmetros de query (opcionais):
 *   - genre: Filtra por gênero literário
 *   - author: Filtra por autor (busca parcial, case-insensitive)
 *   - minYear: Filtra livros publicados a partir deste ano
 *   - maxYear: Filtra livros publicados até este ano
 *
 * Exemplo de uso:
 *   curl http://localhost:3000/books?genre=Ficção&minYear=2000
 *
 * Resposta 200 OK (JSON):
 *   { "books": [...], "total": 10 }
 */
router.get('/', wrapAsync(async (req, res) => {
  // Obtemos todos os livros do storage
  let result = findAll();

  // FILTRAGEM POR GÊNERO
  // Se o parâmetro 'genre' foi fornecido na query string, filtramos.
  // Usamos === para comparação exata (case-sensitive).
  if (req.query.genre) {
    result = result.filter(book => book.genre === req.query.genre);
  }

  // FILTRAGEM POR AUTOR
  // Busca parcial e case-insensitive: "tolkien" encontra "J.R.R. Tolkien"
  if (req.query.author) {
    const authorSearch = req.query.author.toLowerCase();
    result = result.filter(book =>
      book.author.toLowerCase().includes(authorSearch)
    );
  }

  // FILTRAGEM POR ANO MÍNIMO
  if (req.query.minYear) {
    const minYear = parseInt(req.query.minYear, 10);
    if (isNaN(minYear)) {
      throw new BadRequestError('minYear deve ser um número válido');
    }
    result = result.filter(book => book.year && book.year >= minYear);
  }

  // FILTRAGEM POR ANO MÁXIMO
  if (req.query.maxYear) {
    const maxYear = parseInt(req.query.maxYear, 10);
    if (isNaN(maxYear)) {
      throw new BadRequestError('maxYear deve ser um número válido');
    }
    result = result.filter(book => book.year && book.year <= maxYear);
  }

  // Retornamos a lista com metadados de paginação
  res.json({
    books: result,
    total: result.length,
    // Informamos ao cliente quantos livros existem no total (sem filtros)
    totalAll: findAll().length
  });
}));

/**
 * GET /books/:id
 * Retorna um único livro pelo ID.
 *
 * Parâmetros de rota:
 *   - id: ID numérico do livro
 *
 * Exemplo de uso:
 *   curl http://localhost:3000/books/1700000000000
 *
 * Resposta 200 OK (JSON):
 *   { "id": 1700000000000, "title": "...", ... }
 *
 * Resposta 404 (JSON):
 *   { "error": "NotFoundError", "message": "Livro não encontrado" }
 */
router.get('/:id', wrapAsync(async (req, res) => {
  // VALIDAÇÃO: Verificamos se o ID é um número válido.
  // Como geramos IDs com Date.now(), esperamos números inteiros positivos.
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id <= 0) {
    throw new BadRequestError('ID deve ser um número inteiro positivo');
  }

  // Buscamos o livro pelo ID
  const book = findById(id);

  // Se não encontrado, lançamos NotFoundError (capturado pelo middleware)
  if (!book) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  // Retornamos o livro com status 200 OK
  res.json(book);
}));

/**
 * POST /books
 * Cria um novo livro.
 *
 * Corpo da requisição (JSON):
 *   {
 *     "title": "O Senhor dos Anéis",
 *     "author": "J.R.R. Tolkien",
 *     "genre": "Fantasia",
 *     "year": 1954
 *   }
 *
 * Campos obrigatórios: title, author
 * Campos opcionais: genre, year
 *
 * Exemplo de uso (curl):
 *   curl -X POST http://localhost:3000/books \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"1984","author":"George Orwell","genre":"Distopia","year":1949}'
 *
 * Resposta 201 Created (JSON):
 *   { "id": 1700000000000, "title": "...", ... }
 */
router.post('/', wrapAsync(async (req, res) => {
  // EXTRAÇÃO e VALIDAÇÃO dos dados do corpo da requisição
  const { title, author, genre, year } = req.body;

  // VALIDAÇÃO: Título é obrigatório
  if (!title || typeof title !== 'string' || title.trim() === '') {
    throw new BadRequestError(
      'O campo "title" é obrigatório e deve ser uma string não vazia',
      { field: 'title' }
    );
  }

  // VALIDAÇÃO: Autor é obrigatório
  if (!author || typeof author !== 'string' || author.trim() === '') {
    throw new BadRequestError(
      'O campo "author" é obrigatório e deve ser uma string não vazia',
      { field: 'author' }
    );
  }

  // VALIDAÇÃO: Ano, se fornecido, deve ser um número válido
  if (year !== undefined && year !== null) {
    const yearNum = parseInt(year, 10);
    if (isNaN(yearNum) || yearNum < 0 || yearNum > new Date().getFullYear() + 1) {
      throw new BadRequestError(
        'O campo "year" deve ser um número válido entre 0 e o ano atual + 1',
        { field: 'year' }
      );
    }
  }

  // VALIDAÇÃO: Gênero, se fornecido, deve ser uma string
  if (genre !== undefined && genre !== null && typeof genre !== 'string') {
    throw new BadRequestError(
      'O campo "genre" deve ser uma string',
      { field: 'genre' }
    );
  }

  // CRIAMOS o novo livro passando apenas os campos válidos
  const newBook = createBook({
    title: title.trim(),       // Removemos espaços em branco extras
    author: author.trim(),
    genre: genre ? genre.trim() : null,
    year: year !== undefined && year !== null ? parseInt(year, 10) : null
  });

  // Retornamos 201 Created (padrão REST para criação de recursos)
  // O corpo da resposta contém o recurso criado completo
  res.status(201).json(newBook);
}));

/**
 * PUT /books/:id
 * Atualiza completamente um livro existente.
 *
 * Diferença entre PUT e PATCH:
 *   - PUT substitui TODOS os campos (partial update não é padrão)
 *   - PATCH atualiza apenas os campos fornecidos
 *
 * Para este exemplo, usamos PUT com partial update (atualiza só o que veio),
 * pois é mais amigável para testes. Em APIs REST estritas, PUT deveria
 * exigir todos os campos.
 *
 * Exemplo de uso (curl):
 *   curl -X PUT http://localhost:3000/books/1700000000000 \
 *        -H "Content-Type: application/json" \
 *        -d '{"title":"Novo Título","author":"Novo Autor"}'
 *
 * Resposta 200 OK (JSON): Livro atualizado
 * Resposta 404 (JSON): Livro não encontrado
 */
router.put('/:id', wrapAsync(async (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id <= 0) {
    throw new BadRequestError('ID deve ser um número inteiro positivo');
  }

  // Verificamos se o livro existe ANTES de atualizar
  const existingBook = findById(id);
  if (!existingBook) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  // VALIDAÇÃO: Se title foi enviado, deve ser válido
  if (req.body.title !== undefined) {
    if (typeof req.body.title !== 'string' || req.body.title.trim() === '') {
      throw new BadRequestError('O campo "title" deve ser uma string não vazia');
    }
  }

  // VALIDAÇÃO: Se author foi enviado, deve ser válido
  if (req.body.author !== undefined) {
    if (typeof req.body.author !== 'string' || req.body.author.trim() === '') {
      throw new BadRequestError('O campo "author" deve ser uma string não vazia');
    }
  }

  // Atualizamos o livro com os campos fornecidos (partial update)
  const updatedBook = updateById(id, {
    title: req.body.title !== undefined ? req.body.title.trim() : undefined,
    author: req.body.author !== undefined ? req.body.author.trim() : undefined,
    genre: req.body.genre !== undefined ? (req.body.genre || null) : undefined,
    year: req.body.year !== undefined ? (req.body.year || null) : undefined
  });

  // Retornamos o livro atualizado
  res.json(updatedBook);
}));

/**
 * DELETE /books/:id
 * Remove um livro pelo ID.
 *
 * Exemplo de uso (curl):
 *   curl -X DELETE http://localhost:3000/books/1700000000000
 *
 * Resposta 200 OK (JSON): { "message": "Livro removido com sucesso" }
 * Resposta 404 (JSON): Livro não encontrado
 */
router.delete('/:id', wrapAsync(async (req, res) => {
  const id = parseInt(req.params.id, 10);

  if (isNaN(id) || id <= 0) {
    throw new BadRequestError('ID deve ser um número inteiro positivo');
  }

  // Verificamos se o livro existe antes de tentar remover
  const existingBook = findById(id);
  if (!existingBook) {
    throw new NotFoundError(`Livro com ID ${id} não encontrado`);
  }

  // Removemos o livro
  const deleted = deleteById(id);

  // Retornamos confirmação de sucesso
  res.json({
    message: 'Livro removido com sucesso',
    id: existingBook.id,
    title: existingBook.title
  });
}));

module.exports = router;
```

