```javascript
/**
 * ============================================================
 * src/routes/stats.js
 * ============================================================
 *
 * ROTAS DE ESTATÍSTICAS
 *
 * Endpoint dedicado para métricas sobre o acervo de livros.
 * Este é um endpoint de leitura (GET) que não modifica dados,
 * por isso não precisa de wrapAsync (as operações são síncronas).
 */

const express = require('express');
const router = express.Router();
const { getStats } = require('../data/books');

/**
 * GET /stats
 * Retorna estatísticas agregadas sobre os livros.
 *
 * Estatísticas retornadas:
 *   - total: Número total de livros
 *   - byGenre: Contagem de livros por gênero
 *   - avgYear: Média dos anos de publicação
 *   - booksWithYear: Quantos livros têm ano registrado
 *
 * Exemplo de uso (curl):
 *   curl http://localhost:3000/stats
 *
 * Resposta 200 OK (JSON):
 *   {
 *     "total": 5,
 *     "byGenre": { "Fantasia": 2, "Distopia": 1, "Sem gênero": 2 },
 *     "avgYear": 1984.5,
 *     "booksWithYear": 3
 *   }
 */
router.get('/', (req, res) => {
  const stats = getStats();
  res.json(stats);
});

module.exports = router;
