## Arquivo 7: `src/app.js` — Aplicação Principal

```javascript
/**
 * ============================================================
 * src/app.js
 * ============================================================
 *
 * APLICAÇÃO PRINCIPAL DO EXPRESS
 *
 * Estrutura de inicialização:
 *   1. Criar instância do Express
 *   2. Configurar middlewares globais (body-parser, JSON parsing)
 *   3. Registrar rotas
 *   4. Registrar middleware de tratamento de erros (SEMPRE por último)
 *   5. Iniciar o servidor na porta configurada
 *
 * Por que a ordem dos middlewares importa?
 * -----------------------------------------
 * No Express, middlewares são executados em ordem sequencial.
 * O middleware de erro DEVE ser registrado após todas as rotas,
 * caso contrário ele capturaria requisições normais como erros.
 *
 * Convenção REST: Usamos prefixo /api/v1 para futuras extensões
 * que possam adicionar novas versões da API sem quebrar clientes existentes.
 */

const express = require('express');
const path = require('path');

// Importamos os roteadores e o middleware de erro
const booksRouter = require('./routes/books');
const statsRouter = require('./routes/stats');
const { errorHandler } = require('./middleware/errorHandler');

// Criamos a instância do aplicativo Express
const app = express();

// ============================================================
// CONFIGURAÇÃO DE PORTA
// Usamos variável de ambiente com fallback para 3000.
// Isso permite rodar em diferentes ambientes (dev, staging, prod)
// sem alterar o código.
// ============================================================
const PORT = process.env.PORT || 3000;

// ============================================================
// MIDDLEWARES GLOBAIS
// ============================================================

/**
 * express.json() — Parser de corpo JSON.
 *
 * Este middleware analisa o corpo das requisições com Content-Type: application/json
 * e disponibiliza os dados em req.body. Sem ele, req.body seria undefined.
 *
 * limit: '10kb' — Limitamos o tamanho do body para evitar ataques de negação
 * de serviço (DoS) enviando payloads gigantes.
 */
app.use(express.json({ limit: '10kb' }));

/**
 * Middleware de logging simples.
 *
 * Registra na consola cada requisição com método, URL e timestamp.
 * Útil para debugging e monitoramento básico.
 * Em produção, substituiríamos por um logger profissional (Winston, Pino).
 */
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${req.method} ${req.url}`);
  next(); // Passa o controle para o próximo middleware/rota
});

// ============================================================
// REGISTRO DE ROTAS
// Montamos os roteadores nos paths correspondentes.
// Todas as rotas de livros ficam em /api/v1/books
// Todas as rotas de estatísticas ficam em /api/v1/stats
// ============================================================
app.use('/api/v1/books', booksRouter);
app.use('/api/v1/stats', statsRouter);

// ============================================================
// ROTA PARA RAIZ (documentação)
// ============================================================
app.get('/', (req, res) => {
  res.json({
    name: 'Livros API REST',
    version: '1.0.0',
    description: 'API REST para gerenciamento de livros — exemplo educacional',
    endpoints: {
      books: {
        list: 'GET    /api/v1/books',
        getById: 'GET    /api/v1/books/:id',
        create: 'POST   /api/v1/books',
        update: 'PUT    /api/v1/books/:id',
        delete: 'DELETE /api/v1/books/:id'
      },
      stats: {
        getStats: 'GET /api/v1/stats'
      }
    }
  });
});

// ============================================================
// ROTA 404 — Recurso não encontrado
// Qualquer path que não corresponda a uma rota registrada
// recebe esta resposta. Isso evita respostas genéricas do Express.
// ============================================================
app.use((req, res) => {
  res.status(404).json({
    error: 'NotFoundError',
    message: `Rota ${req.method} ${req.url} não encontrada`,
    statusCode: 404
  });
});

// ============================================================
// MIDDLEWARE DE TRATAMENTO DE ERROS
// SEMPRE registrado por último, após todas as rotas.
// Captura erros lançados por rotas e os formata consistentemente.
// ============================================================
app.use(errorHandler);

// ============================================================
// INICIALIZAÇÃO DO SERVIDOR
// ============================================================
app.listen(PORT, () => {
  console.log(`
╔══════════════════════════════════════════════════════════╗
║     API REST de Livros — Servidor Rodando!              ║
║                                                          ║
║   Porta: ${PORT}                                          ║
║   Base URL: http://localhost:${PORT}                      ║
║                                                          ║
║   Endpoints disponíveis:                                 ║
║     GET  /api/v1/books          — Listar livros         ║
║     GET  /api/v1/books/:id      — Obter livro por ID    ║
║     POST /api/v1/books          — Criar novo livro      ║
║     PUT  /api/v1/books/:id      — Atualizar livro       ║
║     DELETE /api/v1/books/:id    — Excluir livro         ║
║     GET  /api/v1/stats          — Estatísticas          ║
╚══════════════════════════════════════════════════════════╝
  `);
});

module.exports = app;
```

